async function supabaseRequestPasswordReset(email, redirectTo) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/recover`, {
    method: "POST",
    headers: { "Content-Type": "application/json", apikey: SUPABASE_KEY },
    body: JSON.stringify({ email, options: { redirect_to: redirectTo } }),
  });
  // Supabase répond 200 même si le courriel n'existe pas (pour ne pas révéler quels comptes existent).
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.msg || data.error_description || "Impossible d'envoyer le courriel pour le moment.");
  }
}
// Distingue un vrai rejet du serveur (jeton invalide/expiré — une réponse HTTP a bien été reçue,
// juste refusée) d'un simple problème réseau (l'appel fetch() lui-même échoue avant toute réponse —
// ex. le téléphone vient de se réveiller après avoir été mis en arrière-plan et le WiFi/les données
// mobiles n'ont pas encore eu le temps de se reconnecter). Ces erreurs réseau ont normalement le nom
// "TypeError" et un message du genre "Failed to fetch" / "NetworkError" / "Load failed" selon le
// navigateur — jamais une vraie réponse du serveur Supabase.
function isNetworkError(e) {
  if (!e) return false;
  const msg = String(e.message || e).toLowerCase();
  return e.name === "TypeError" || msg.includes("failed to fetch") || msg.includes("network") || msg.includes("load failed");
}
