/* ---------------- PARTAGE DE COMPTE AVEC UN·E PARTENAIRE (lecture seule, table "partner_links") ---------------- */
function generateInviteCode() {
  // Code court et facile à retaper (évite les caractères ambigus comme 0/O, 1/I).
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < 8; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}
async function supabaseGetOwnerLink(userId, accessToken) {
  // Le lien que CE compte a créé pour inviter quelqu'un (en tant que titulaire/maman).
  const res = await fetch(`${SUPABASE_URL}/rest/v1/partner_links?owner_user_id=eq.${userId}&select=*&order=created_at.desc&limit=1`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible de récupérer l'état du partage");
  return data[0] || null;
}
async function supabaseGetPartnerLink(userId, accessToken) {
  // Le lien où CE compte est le/la partenaire (lecture seule des données d'un autre compte).
  const res = await fetch(`${SUPABASE_URL}/rest/v1/partner_links?partner_user_id=eq.${userId}&status=eq.accepted&select=*&limit=1`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible de récupérer l'état du partage");
  return data[0] || null;
}
async function supabaseCreatePartnerInvite(userId, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/partner_links`, {
    method: "POST",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json", Prefer: "return=representation" },
    body: JSON.stringify({ owner_user_id: userId, invite_code: generateInviteCode(), status: "pending" }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible de créer l'invitation");
  return data[0];
}
async function supabaseRevokePartnerLink(id, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/partner_links?id=eq.${id}`, {
    method: "DELETE", headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  if (!res.ok) throw new Error("Impossible de retirer l'accès");
}
async function supabaseRedeemInviteCode(code, partnerUserId, accessToken) {
  // 1. Trouver l'invitation encore libre correspondant au code.
  const findRes = await fetch(`${SUPABASE_URL}/rest/v1/partner_links?invite_code=eq.${encodeURIComponent(code)}&status=eq.pending&partner_user_id=is.null&select=*`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  const found = await findRes.json();
  if (!findRes.ok) throw new Error("Impossible de vérifier ce code");
  if (!found[0]) throw new Error("CODE_INVALIDE");
  if (found[0].owner_user_id === partnerUserId) throw new Error("CODE_PROPRE_COMPTE");
  // 2. Le réclamer.
  const res = await fetch(`${SUPABASE_URL}/rest/v1/partner_links?id=eq.${found[0].id}`, {
    method: "PATCH",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json", Prefer: "return=representation" },
    body: JSON.stringify({ partner_user_id: partnerUserId, status: "accepted" }),
  });
  const data = await res.json();
  if (!res.ok || !data[0]) throw new Error("Impossible de rejoindre — ce code vient peut-être d'être utilisé.");
  return data[0];
}

