// ---------------- CONTENU DYNAMIQUE (table Supabase "app_content") ----------------
// Permet de charger le gros contenu texte des sections (grossesse, post-partum, etc.) uniquement
// quand la personne visite cette section, plutôt que de tout charger d'un coup au démarrage de l'app.
// Mise en cache mémoire (le temps de la session) pour éviter de re-télécharger à chaque changement d'onglet.
const _contentCache = {};
async function supabaseFetchContent(key) {
  if (_contentCache[key]) return _contentCache[key];
  const res = await fetch(`${SUPABASE_URL}/rest/v1/app_content?key=eq.${key}&select=data`, {
    headers: { apikey: SUPABASE_KEY },
  });
  const rows = await res.json();
  if (!res.ok) throw new Error(`Impossible de charger le contenu (${key})`);
  const data = rows?.[0]?.data || null;
  if (data) _contentCache[key] = data;
  return data;
}

async function supabaseUpdateProfile(userId, updates, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/profiles?id=eq.${userId}`, {
    method: "PATCH",
    headers: {
      apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json", Prefer: "return=minimal",
    },
    body: JSON.stringify(updates),
  });
  if (!res.ok) {
    const errText = await res.text().catch(() => "");
    throw new Error(`Impossible de mettre à jour le profil (${res.status}: ${errText || "réponse vide"})`);
  }
}

