async function supabaseUpdateDocument(id, updates, accessToken) {
  const body = {};
  if (updates.label !== undefined) body.label = updates.label;
  if (updates.note !== undefined) body.note = updates.note || null;
  if (updates.reminderDate !== undefined) body.reminder_date = updates.reminderDate || null;
  const res = await fetch(`${SUPABASE_URL}/rest/v1/documents?id=eq.${id}`, {
    method: "PATCH",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error("Impossible de modifier le document");
}
function mapDocumentRow(row) {
  return { id: row.id, label: row.label, category: row.category, note: row.note || "", reminderDate: row.reminder_date || "", photo: row.photo_data || "", date: new Date(row.created_at) };
}

/* ---------------- TÂCHES FAMILIALES (table Supabase "family_tasks") ---------------- */
async function supabaseFetchFamilyTasks(userId, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/family_tasks?user_id=eq.${userId}&select=*&order=created_at.asc`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible de récupérer les tâches");
  return data;
}
async function supabaseAddFamilyTask(task, userId, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/family_tasks`, {
    method: "POST",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json", Prefer: "return=representation" },
    body: JSON.stringify({ user_id: userId, task: task.task, person: task.person, done: false, done_month: null }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible d'ajouter la tâche");
  return data[0];
}
async function supabaseUpdateFamilyTask(id, doneMonth, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/family_tasks?id=eq.${id}`, {
    method: "PATCH",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify({ done_month: doneMonth, done: !!doneMonth }),
  });
  if (!res.ok) throw new Error("Impossible de mettre à jour la tâche");
}
async function supabaseDeleteFamilyTask(id, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/family_tasks?id=eq.${id}`, {
    method: "DELETE", headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  if (!res.ok) throw new Error("Impossible de retirer la tâche");
}
function mapFamilyTaskRow(row) {
  return { id: row.id, task: row.task, person: row.person, doneMonth: row.done_month || null, createdAt: row.created_at ? new Date(row.created_at) : new Date() };
}

/* ---------------- TRACKERS RAPIDES (table Supabase "tracker_entries", partagée par type) ---------------- */
async function supabaseFetchTrackerEntries(userId, type, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/tracker_entries?user_id=eq.${userId}&type=eq.${type}&select=*&order=created_at.asc`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible de récupérer l'historique");
  return data;
}
async function supabaseAddTrackerEntry(type, entry, userId, accessToken) {
  const body = {
    user_id: userId, type, label: entry.label, detail: entry.detail || null,
    entry_start: entry.start ? entry.start.toISOString() : null,
  };
  // Permet d'ajouter une entrée rétroactive pour une date précise (au lieu de toujours utiliser
  // l'heure actuelle) — utilisé quand on ajoute une entrée manuellement dans une date déjà ouverte.
  if (entry.createdAt) body.created_at = entry.createdAt.toISOString();
  const res = await fetch(`${SUPABASE_URL}/rest/v1/tracker_entries`, {
    method: "POST",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json", Prefer: "return=representation" },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Impossible d'ajouter l'entrée");
  return data[0];
}
async function supabaseDeleteTrackerEntry(id, accessToken) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/tracker_entries?id=eq.${id}`, {
    method: "DELETE",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}` },
  });
  if (!res.ok) throw new Error("Impossible de supprimer l'entrée");
}
async function supabaseUpdateTrackerEntry(id, updates, accessToken) {
  const body = {};
  if (updates.label !== undefined) body.label = updates.label;
  if (updates.detail !== undefined) body.detail = updates.detail || null;
  const res = await fetch(`${SUPABASE_URL}/rest/v1/tracker_entries?id=eq.${id}`, {
    method: "PATCH",
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error("Impossible de modifier l'entrée");
}
function mapTrackerEntryRow(row) {
  return { id: row.id, label: row.label, detail: row.detail || "", start: row.entry_start ? new Date(row.entry_start) : undefined, createdAt: row.created_at ? new Date(row.created_at) : new Date() };
}
// Ajoute une entrée immédiatement à l'écran (id temporaire) pendant que la sauvegarde Supabase se fait
// en arrière-plan, puis remplace l'entrée temporaire par la vraie ligne (avec son vrai id) une fois
// la réponse reçue — nécessaire pour que le bouton supprimer fonctionne tout de suite après l'ajout.
function makeOptimisticEntry(entry) {
  return { ...entry, id: `temp-${Date.now()}-${Math.random().toString(36).slice(2)}`, createdAt: entry.createdAt || new Date() };
}
async function persistTrackerEntry(type, entry, session, setLog, tempId) {
  if (!(session?.access_token && session?.user?.id)) return;
  try {
    const row = await supabaseAddTrackerEntry(type, entry, session.user.id, session.access_token);
    const real = mapTrackerEntryRow(row);
    setLog((l) => l.map((e) => (e.id === tempId ? real : e)));
  } catch { /* l'entrée reste visible localement (temporaire) même si la sauvegarde échoue */ }
}
function removeTrackerEntry(id, session, setLog) {
  setLog((l) => l.filter((e) => e.id !== id));
  if (session?.access_token && !String(id).startsWith("temp-")) {
    supabaseDeleteTrackerEntry(id, session.access_token).catch(() => {});
  }
}
function updateTrackerEntry(id, updates, session, setLog) {
  setLog((l) => l.map((e) => (e.id === id ? { ...e, ...updates } : e)));
  if (session?.access_token && !String(id).startsWith("temp-")) {
    supabaseUpdateTrackerEntry(id, updates, session.access_token).catch(() => {});
  }
}

// Rattacher une entrée de la table générique "tracker_entries" à un enfant précis du profil familial
// (sommeil, allaitement, couches) sans ajouter de colonne Supabase — l'id de l'enfant est encodé
// dans un tag caché à la fin du champ "detail" (ex. "14:32 · 120 ml [[child:abc123]]"), retiré avant
// l'affichage. Une entrée sans tag (créée avant cette fonctionnalité, ou famille à un seul enfant)
// reste visible peu importe l'enfant sélectionné, pour ne jamais faire disparaître une donnée existante.
const CHILD_TAG_RE = /\s*\[\[child:([^\]]+)\]\]\s*$/;
function encodeChildTag(detail, childId) {
  const base = (detail || "").replace(CHILD_TAG_RE, "");
  return childId ? `${base} [[child:${childId}]]` : base;
}
function decodeChildId(detail) {
  const m = typeof detail === "string" ? detail.match(CHILD_TAG_RE) : null;
  return m ? m[1] : null;
}
function stripChildTag(detail) {
  return typeof detail === "string" ? detail.replace(CHILD_TAG_RE, "") : detail;
}
function filterLogByChild(log, selectedChildId) {
  if (!selectedChildId) return log;
  return log.filter((e) => {
    const cid = decodeChildId(e.detail);
    return cid == null || cid === selectedChildId;
  });
}
function stripChildTagFromLog(log) {
  return log.map((e) => ({ ...e, detail: stripChildTag(e.detail) }));
}

// Encode la durée et l'intervalle (en ms) d'une contraction dans une balise cachée à la fin du
// champ "detail" — même technique que le tag [[child:...]] ci-dessus — pour pouvoir retracer un
// graphique fidèle plus tard, sans avoir besoin d'une nouvelle colonne Supabase. Les entrées créées
// avant cet ajout n'ont simplement pas cette balise et n'apparaissent pas dans le graphique.
const CONTRACTION_DATA_RE = /\s*\[\[c:(\d+):(\d*)\]\]\s*$/;
function encodeContractionData(detail, durationMs, intervalMs) {
  const base = (detail || "").replace(CONTRACTION_DATA_RE, "");
  return `${base} [[c:${Math.round(durationMs)}:${intervalMs != null ? Math.round(intervalMs) : ""}]]`;
}
function decodeContractionData(detail) {
  const m = typeof detail === "string" ? detail.match(CONTRACTION_DATA_RE) : null;
  if (!m) return null;
  return { durationMs: Number(m[1]), intervalMs: m[2] ? Number(m[2]) : null };
}
function stripContractionTag(detail) {
  return typeof detail === "string" ? detail.replace(CONTRACTION_DATA_RE, "") : detail;
}
function stripContractionTagFromLog(log) {
  return log.map((e) => ({ ...e, detail: stripContractionTag(e.detail) }));
}
// Petite rangée de pastilles pour choisir l'enfant concerné — mêmes enfants que le profil familial
// (children/kids), masquée automatiquement s'il n'y en a qu'un seul ou aucun.
function ChildSelectorPills({ kids, selectedChildId, onSelect, color, label }) {
  if (!kids || kids.length < 2) return null;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
      {label && <span style={{ fontSize: 12, color: COLORS.muted, fontWeight: 700 }}>{label}</span>}
      {kids.map((ch) => (
        <button key={ch.id} onClick={() => onSelect(ch.id)} style={{
          padding: "6px 13px", borderRadius: 999, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
          border: `1px solid ${selectedChildId === ch.id ? color : COLORS.line}`,
          background: selectedChildId === ch.id ? color : "#fff",
          color: selectedChildId === ch.id ? "#fff" : COLORS.text,
        }}>{ch.name}</button>
      ))}
    </div>
  );
}

// Même principe que le tag caché pour les trackers, mais pour "Mes documents" — la personne
// concernée peut être un enfant du profil OU "maman" elle-même (beaucoup de documents à gérer pour
// elle aussi). Stocké dans le champ "note" de la table "documents" (inutilisé ailleurs dans cet
// outil), pas dans "category" qui sert déjà à distinguer les documents de l'album souvenir.
const OWNER_TAG_RE = /\s*\[\[owner:([^\]]+)\]\]\s*$/;
function encodeOwnerTag(text, ownerId) {
  const base = (text || "").replace(OWNER_TAG_RE, "");
  return ownerId ? `${base} [[owner:${ownerId}]]`.trim() : base.trim();
}
function decodeOwnerId(text) {
  const m = typeof text === "string" ? text.match(OWNER_TAG_RE) : null;
  return m ? m[1] : null;
}
function OwnerSelectorPills({ kids, selectedOwnerId, onSelect, color, label, momLabel }) {
  if (!kids || kids.length === 0) return null;
  const options = [{ id: "maman", name: momLabel }, ...kids];
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
      {label && <span style={{ fontSize: 12, color: COLORS.muted, fontWeight: 700 }}>{label}</span>}
      {options.map((ch) => (
        <button key={ch.id} onClick={() => onSelect(ch.id)} style={{
          padding: "6px 13px", borderRadius: 999, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
          border: `1px solid ${selectedOwnerId === ch.id ? color : COLORS.line}`,
          background: selectedOwnerId === ch.id ? color : "#fff",
          color: selectedOwnerId === ch.id ? "#fff" : COLORS.text,
        }}>{ch.name}</button>
      ))}
    </div>
  );
}

/* ---------------- PHOTOS (Supabase Storage, bucket "photos") ---------------- */
// CONFIRMÉ par test réel : le plantage mémoire vient bien de createImageBitmap/canvas eux-mêmes sur
// ce téléphone précis (probablement un bug ou une limite du décodage accéléré GPU de ce navigateur),
// pas de canvas.toDataURL() spécifiquement comme on le pensait à l'étape précédente. La version qui
// a fonctionné sans plantage est celle qui n'utilise AUCUNE de ces API : on envoie le fichier original
// tel quel et on génère un aperçu ultra-léger avec URL.createObjectURL (aucun décodage de pixels par
// notre code — seul le navigateur décode, au moment de l'affichage, de façon optimisée en interne).
// Contrepartie : les photos ne sont plus compressées avant l'envoi (fichiers plus lourds, upload un
// peu plus lent), mais c'est nettement préférable à un plantage qui perd les données de la personne.
//
// GARDE-FOU SUPPLÉMENTAIRE (comme la plupart des grandes apps — WhatsApp, Instagram, etc.) : on refuse
// carrément les photos trop volumineuses AVANT de tenter quoi que ce soit avec elles, plutôt que de
// risquer un plantage. Le seuil est plus bas si l'appareil signale peu de mémoire disponible
// (navigator.deviceMemory, seulement disponible sur Chrome/Android). On ne peut jamais garantir à 100 %
// qu'Android ne tuera pas la page par manque de mémoire — mais on élimine ainsi la cause la plus fréquente.
async function resizeImageForUpload(file, maxDim = 640, quality = 0.75) {
  if (!file || !file.type?.startsWith("image/")) return { dataUrl: null, file, tooLarge: false };

  const deviceMemoryGB = (typeof navigator !== "undefined" && navigator.deviceMemory) || null;
  const maxBytes = deviceMemoryGB && deviceMemoryGB <= 2 ? 6 * 1024 * 1024 : 14 * 1024 * 1024;
  if (file.size > maxBytes) {
    return { dataUrl: null, file: null, tooLarge: true };
  }

  try {
    return { dataUrl: URL.createObjectURL(file), file, tooLarge: false };
  } catch (e) {
    return { dataUrl: null, file, tooLarge: false };
  }
}

async function supabaseUploadPhoto(file, userId, accessToken) {
  const ext = (file.name.split(".").pop() || "jpg").toLowerCase();
  const path = `${userId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
  const res = await fetch(`${SUPABASE_URL}/storage/v1/object/photos/${path}`, {
    method: "POST",
    headers: {
      apikey: SUPABASE_KEY, Authorization: `Bearer ${accessToken}`,
      "Content-Type": file.type || "application/octet-stream",
    },
    body: file,
  });
  if (!res.ok) {
    const errText = await res.text().catch(() => "");
    throw new Error(`Impossible de téléverser la photo (${res.status}: ${errText || "réponse vide"})`);
  }
  return `${SUPABASE_URL}/storage/v1/object/public/photos/${path}`;
}

// Stocke la session localement pour rester connecté d'une visite à l'autre.
function saveLocalSession(session) {
  try { localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session)); } catch (e) { /* stockage indisponible */ }
}
function loadLocalSession() {
  try {
    const raw = localStorage.getItem(SESSION_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}
function clearLocalSession() {
  try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch (e) { /* rien à faire */ }
}

// Envoie un courriel transactionnel via la fonction serverless /api/send-email (qui relaie vers
// Resend en gardant la vraie clé API côté serveur — voir api/send-email.js).
async function sendAppEmail(to, subject, html, attachments) {
  const res = await fetch("/api/send-email", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ to, subject, html, attachments }),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data?.error || "Échec de l'envoi du courriel.");
  }
  return true;
}

function escapeHtml(str) {
  return String(str ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

// slot ("breakfast"/"lunch"/"dinner"/"snack", toujours en anglais — voir MENU_JSON_SYSTEM_PROMPT) ->
// libellé affiché + couleurs, pour que chaque repas soit visuellement distinct dans le courriel
// (fond pâle + couleur d'accent), plutôt qu'un bloc de texte uniforme difficile à parcourir.
// "snack" est utilisé quand la personne a choisi une structure de repas avec collations ou petits
// repas multiples (voir MEALS_STRUCTURE_PLAN) — plusieurs collations dans la même journée partagent
// ce même style, ce qui est voulu.
const MENU_SLOT_META = {
  breakfast: { fr: "Déjeuner", en: "Breakfast", es: "Desayuno", icon: "🌅", bg: "#FBF3E4", accent: "#C98A2E" },
  lunch: { fr: "Dîner", en: "Lunch", es: "Almuerzo", icon: "🥗", bg: "#E4EFDF", accent: "#5B8A5A" },
  dinner: { fr: "Souper", en: "Dinner", es: "Cena", icon: "🍽️", bg: "#EAF2F8", accent: "#2F7A93" },
  snack: { fr: "Collation", en: "Snack", es: "Merienda", icon: "🍎", bg: "#F3ECE0", accent: "#9A7444" },
};

// Construit le courriel HTML coloré à partir du menu structuré (menuData, voir
// MENU_JSON_SYSTEM_PROMPT) — un bloc distinct par repas avec sa propre couleur, les ingrédients et
// les étapes clairement séparés. Si le JSON n'a pas pu être analysé (rawText), on retombe sur un
// rendu texte simple plutôt que de ne rien envoyer.
async function sendPersonalizedMenuEmail(email, menuData, rawText, lang) {
  const subject = lang === "fr" ? "Votre menu personnalisé Me My Baby 🍽️" : lang === "es" ? "Tu menú personalizado de Me My Baby 🍽️" : "Your personalized Me My Baby menu 🍽️";
  const signoff = lang === "fr" ? "Bon appétit !" : lang === "es" ? "¡Buen provecho!" : "Enjoy your meals!";
  const closing = lang === "fr"
    ? "Envie d'un nouveau menu ou de modifier vos choix ? Connectez-vous à Me My Baby et rendez-vous à la page Léa, notre diététicienne virtuelle."
    : lang === "es"
    ? "¿Quieres un nuevo menú o modificar tus opciones? Inicia sesión en Me My Baby y ve a la página de Léa, nuestra nutricionista virtual."
    : "Want a new menu or to change your choices? Log in to Me My Baby and head to the Léa page, our virtual dietitian.";
  const cta = lang === "fr" ? "Aller à Léa" : lang === "es" ? "Ir a Léa" : "Go to Léa";
  const prepWord = lang === "fr" ? "Prép." : lang === "es" ? "Prep." : "Prep";
  const cookWord = lang === "fr" ? "Cuisson" : lang === "es" ? "Cocción" : "Cook";
  const minWord = lang === "fr" ? "min" : lang === "es" ? "min" : "min";

  let bodyHtml;
  if (menuData && Array.isArray(menuData.days) && menuData.days.length > 0) {
    // Décrit le nombre réel de repas/jour à partir des données reçues (pas d'un texte fixe qui
    // dirait toujours "déjeuner, dîner et souper" même quand des collations ont été demandées).
    const firstDayMealCount = (menuData.days[0]?.meals || []).length;
    const hasSnacks = menuData.days.some((d) => (d.meals || []).some((m) => m.slot === "snack"));
    const mealsPerDayText = lang === "fr"
      ? (hasSnacks ? `${firstDayMealCount} repas par jour (dont des collations)` : "3 repas par jour (déjeuner, dîner et souper)")
      : lang === "es"
      ? (hasSnacks ? `${firstDayMealCount} comidas al día (incluyendo meriendas)` : "3 comidas al día (desayuno, almuerzo y cena)")
      : (hasSnacks ? `${firstDayMealCount} meals per day (including snacks)` : "3 meals per day (breakfast, lunch and dinner)");
    const introText = lang === "fr"
      ? `Ce courriel contient un seul envoi : votre menu personnalisé, qui couvre les ${menuData.days.length} prochains jours. Chacun de ces ${menuData.days.length} jours comprend ${mealsPerDayText}.`
      : lang === "es"
      ? `Este correo contiene un solo envío: tu menú personalizado, que cubre los próximos ${menuData.days.length} días. Cada uno de esos ${menuData.days.length} días incluye ${mealsPerDayText}.`
      : `This is a single email: your personalized menu, covering the next ${menuData.days.length} days. Each of those ${menuData.days.length} days includes ${mealsPerDayText}.`;
    const introHtml = `<p style="margin:0 0 16px;font-size:13.5px;color:#3A3833;">${escapeHtml(introText)}</p>`;
    const tipsHtml = Array.isArray(menuData.tips) && menuData.tips.length > 0
      ? `<div style="background:#FBF6ED;border-radius:14px;padding:14px 18px;margin:0 0 22px;">
          <ul style="margin:0;padding-left:18px;color:#5A5548;font-size:13px;line-height:1.6;">
            ${menuData.tips.map((t) => `<li>${escapeHtml(t)}</li>`).join("")}
          </ul>
        </div>`
      : "";
    const daysHtml = menuData.days.map((day) => {
      const mealsHtml = (day.meals || []).map((meal) => {
        const meta = MENU_SLOT_META[meal.slot] || MENU_SLOT_META.dinner;
        const timeParts = [];
        if (meal.prep) timeParts.push(`${prepWord} ${meal.prep} ${minWord}`);
        if (meal.cook) timeParts.push(`${cookWord} ${meal.cook} ${minWord}`);
        const ingredientsHtml = (meal.ingredients || []).map((i) => `<li style="margin-bottom:3px;">${escapeHtml(i)}</li>`).join("");
        const stepsHtml = (meal.steps || []).map((s) => `<li style="margin-bottom:5px;">${escapeHtml(s)}</li>`).join("");
        return `<div style="background:${meta.bg};border-radius:14px;padding:14px 16px;margin-bottom:12px;">
          <div style="font-weight:700;font-size:14px;color:${meta.accent};margin-bottom:2px;">${meta.icon} ${escapeHtml(meta[lang] || meta.en)} — ${escapeHtml(meal.title || "")}</div>
          ${timeParts.length ? `<div style="font-size:11.5px;color:#7A7364;margin-bottom:8px;">${timeParts.join(" · ")}</div>` : ""}
          <div style="font-size:13px;color:#3A3833;font-weight:700;margin-bottom:2px;">${lang === "fr" ? "Ingrédients" : lang === "es" ? "Ingredientes" : "Ingredients"}</div>
          <ul style="margin:0 0 10px;padding-left:18px;font-size:13px;color:#3A3833;">${ingredientsHtml}</ul>
          <div style="font-size:13px;color:#3A3833;font-weight:700;margin-bottom:2px;">${lang === "fr" ? "Préparation" : lang === "es" ? "Preparación" : "Steps"}</div>
          <ol style="margin:0;padding-left:18px;font-size:13px;color:#3A3833;">${stepsHtml}</ol>
        </div>`;
      }).join("");
      return `<div style="margin-bottom:22px;">
        <div style="background:#5B3A24;color:#fff;font-weight:700;font-size:13.5px;padding:8px 14px;border-radius:10px;margin-bottom:10px;">${escapeHtml(day.date || "")}</div>
        ${mealsHtml}
      </div>`;
    }).join("");
    bodyHtml = introHtml + tipsHtml + daysHtml;
  } else {
    // Repli : le JSON n'a pas pu être analysé — on affiche quand même le texte reçu plutôt que de
    // bloquer l'envoi, dans une mise en page simple.
    bodyHtml = `<div style="white-space:pre-wrap;">${escapeHtml(rawText || "")}</div>`;
  }

  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:560px;margin:0 auto;line-height:1.6;">
    ${bodyHtml}
    <p style="margin-top:6px;">${signoff}<br>— Léa</p>
    <div style="background:#FBF6ED;border-radius:14px;padding:16px 18px;margin:24px 0 0;">
      <p style="margin:0;font-size:13px;color:#7A7364;">${closing}</p>
    </div>
    <div style="text-align:center;margin:20px 0 0;">
      <a href="https://me-my-baby.vercel.app" style="background:#D4A54A;color:#fff;text-decoration:none;padding:12px 26px;border-radius:999px;font-weight:700;display:inline-block;">${cta}</a>
    </div>
  </div>`;
  return sendAppEmail(email, subject, html);
}



