// Repère fruit/légume + poids le plus proche de la semaine de grossesse donnée — PREGNANCY_WEEKS
// n'a une entrée que toutes les 4 semaines, donc on prend la plus proche plutôt que d'exiger une
// correspondance exacte (utilisé pour les petits badges "comparaison" un peu partout dans l'app).
function getClosestPregnancyWeek(weeks) {
  if (weeks == null) return null;
  let closest = PREGNANCY_WEEKS[0];
  let bestDiff = Math.abs(weeks - closest.w);
  for (const entry of PREGNANCY_WEEKS) {
    const diff = Math.abs(weeks - entry.w);
    if (diff < bestDiff) { closest = entry; bestDiff = diff; }
  }
  return closest;
}

