// Reusable wallpaper pattern generator (deterministic)
function makeWallpaperPattern(emojis, count = 24) {
  return Array.from({ length: count }).map((_, idx) => {
    const row = Math.floor(idx / 6);
    const col = idx % 6;
    return {
      emoji: emojis[idx % emojis.length],
      top: `${row * 22 + (col % 2 === 0 ? 2 : 9)}%`,
      left: `${col * 17 + (row % 2 === 0 ? 2 : 6)}%`,
      rotate: ((idx * 37) % 40) - 20,
      size: 18 + (idx % 3) * 4,
    };
  });
}

function SectionHero({ sectionKey, lang }) {
  const meta = SECTION_META[sectionKey];
  if (!meta) return null;
  const Icon = meta.icon;
  const compact = !!meta.compact;
  const hasWallpaper = !!meta.wallpaper;
  const pattern = hasWallpaper ? makeWallpaperPattern(meta.wallpaper) : null;
  // Version plus élégante/soignée : dégradé doux (au lieu d'un aplat de couleur), badge d'icône
  // en dégradé avec ombre portée dans la couleur de la section, et une bulle décorative floutée
  // — le même langage visuel que l'accueil et les pages plein écran des outils, pour que
  // l'appli se sente comme UN seul système cohérent plutôt qu'un collage de styles.
  // Bulle de titre centrée : le titre en haut, la photo réelle juste en dessous, puis le texte —
  // tout empilé et centré, plutôt qu'en rangée (titre/texte à côté de l'image).
  const imageSize = compact ? 88 : 108;
  return (
    <div style={{
      position: "relative", overflow: "hidden", textAlign: "center",
      background: `linear-gradient(135deg, ${meta.color}22 0%, ${COLORS.cream} 58%, ${meta.color}14 100%)`,
      border: `1px solid ${meta.color}30`,
      borderRadius: 22, padding: compact ? "20px 20px" : "28px 26px",
      marginBottom: 22, boxShadow: `0 12px 30px ${meta.color}26`,
    }}>
      <div style={{ position: "absolute", top: -34, right: -22, width: 130, height: 130, borderRadius: "50%", background: meta.color, opacity: 0.1, pointerEvents: "none" }} />
      {hasWallpaper && (
        <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 0 }}>
          {pattern.map((it, idx) => (
            <span
              key={idx}
              style={{
                position: "absolute", top: it.top, left: it.left, fontSize: it.size,
                opacity: 0.16, transform: `rotate(${it.rotate}deg)`,
              }}
            >
              {it.emoji}
            </span>
          ))}
        </div>
      )}
      <div style={{
        position: "relative", zIndex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 12,
        background: hasWallpaper ? "#fff" : "transparent",
        borderRadius: hasWallpaper ? 16 : 0,
        padding: hasWallpaper ? "18px 18px 20px" : 0,
        boxShadow: hasWallpaper ? "0 6px 18px rgba(91,58,36,0.10)" : "none",
      }}>
        <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: compact ? 21 : 26, color: COLORS.teal, letterSpacing: "-0.01em" }}>{meta.title[lang]}</h2>
        <div style={{
          position: "relative", overflow: "hidden",
          width: imageSize, height: imageSize, borderRadius: compact ? 20 : 24,
          background: `linear-gradient(135deg, ${meta.color} 0%, ${meta.color}CC 100%)`,
          display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
          boxShadow: `0 8px 18px ${meta.color}45`,
        }}>
          {meta.image ? (
            <img
              src={meta.image.url} alt={meta.image.alt[lang]} loading="lazy"
              style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
            />
          ) : meta.customIcon ? (
            <Illustration type={meta.customIcon} size={compact ? 40 : 50} />
          ) : meta.emojiIcon ? (
            <span style={{ fontSize: compact ? 34 : 42, lineHeight: 1 }}>{meta.emojiIcon}</span>
          ) : (
            <Icon size={compact ? 30 : 36} color="#fff" />
          )}
        </div>
        {/* Crédit photo affiché sous l'image, en petit gris pâle — plus jamais superposé sur la
            photo elle-même (texte blanc sur fond sombre), comme demandé. */}
        {meta.image && (
          <p style={{ margin: "-6px 0 0", fontSize: 9.5, color: COLORS.muted, opacity: 0.7, letterSpacing: "0.02em" }}>
            {meta.image.credit}
          </p>
        )}
        <p style={{ margin: 0, color: COLORS.text, opacity: 0.82, fontSize: compact ? 13 : 14.5, lineHeight: 1.55, maxWidth: 440 }}>{meta.desc[lang]}</p>
      </div>
    </div>
  );
}

