function LegalModal({ lang, doc, onClose }) {
  const titles = {
    privacy: { fr: "Politique de confidentialité", en: "Privacy Policy", es: "Política de privacidad" },
    terms: { fr: "Conditions d'utilisation", en: "Terms of Use", es: "Condiciones de uso" },
  };
  const closeLabel = lang === "fr" ? "Fermer" : lang === "es" ? "Cerrar" : "Close";
  return (
    <div onClick={onClose} style={{
      position: "fixed", inset: 0, zIndex: 200, background: "rgba(91,58,36,0.45)",
      display: "flex", alignItems: "center", justifyContent: "center", padding: 16,
    }}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: "#fff", borderRadius: 18, maxWidth: 560, width: "100%", maxHeight: "82vh",
        display: "flex", flexDirection: "column", overflow: "hidden", boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
      }}>
        <div style={{ padding: "16px 20px", borderBottom: `1px solid ${COLORS.line}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 17, margin: 0, color: COLORS.teal }}>{titles[doc][lang]}</h3>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.muted, fontSize: 20, lineHeight: 1 }}>✕</button>
        </div>
        <div style={{ padding: "18px 20px", overflowY: "auto", fontSize: 12.5, lineHeight: 1.6, color: COLORS.text, whiteSpace: "pre-wrap" }}>
          {LEGAL_TEXT[doc][lang]}
        </div>
        <div style={{ padding: "12px 20px", borderTop: `1px solid ${COLORS.line}`, textAlign: "right" }}>
          <button onClick={onClose} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "9px 18px", borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{closeLabel}</button>
        </div>
      </div>
    </div>
  );
}

// Avis préventif lié à la batterie, affiché près des sections où plusieurs photos sont ajoutées d'affilée.
// La détection réelle du niveau de batterie (Battery Status API) a été retirée de la plupart des
// navigateurs récents (dont Chrome) pour des raisons de vie privée — elle ne fonctionnera donc que sur
// certains appareils. Un message préventif générique s'affiche dans tous les cas, en complément.
function BatteryNotice({ lang }) {
  const [level, setLevel] = useState(null); // 0-1, ou null si l'API n'est pas disponible
  const [charging, setCharging] = useState(null);

  useEffect(() => {
    let battery;
    let mounted = true;
    if (typeof navigator !== "undefined" && typeof navigator.getBattery === "function") {
      navigator.getBattery().then((b) => {
        if (!mounted) return;
        battery = b;
        setLevel(b.level);
        setCharging(b.charging);
        const update = () => { setLevel(b.level); setCharging(b.charging); };
        b.addEventListener("levelchange", update);
        b.addEventListener("chargingchange", update);
      }).catch(() => { /* API indisponible ou refusée : on garde le message générique */ });
    }
    return () => { mounted = false; };
  }, []);

  const L = lang === "fr"
    ? { lowBattery: (pct) => `🔋 Votre batterie est à ${pct}%. Sur certains téléphones, une batterie faible peut causer des ralentissements ou des plantages lors de l'ajout de plusieurs photos — nous vous recommandons de brancher votre téléphone avant de continuer.` }
    : lang === "es"
    ? { lowBattery: (pct) => `🔋 Tu batería está al ${pct}%. En algunos teléfonos, una batería baja puede causar lentitud o fallos al agregar varias fotos — te recomendamos conectar tu teléfono antes de continuar.` }
    : { lowBattery: (pct) => `🔋 Your battery is at ${pct}%. On some phones, low battery can cause slowdowns or crashes when adding several photos — we recommend plugging in your phone before continuing.` };

  const showLowBatteryWarning = level !== null && level < 0.3 && !charging;
  if (!showLowBatteryWarning) return null; // rien à afficher si la batterie n'est pas d\u00e9tect\u00e9e comme basse

  return (
    <div style={{
      display: "flex", gap: 8, alignItems: "flex-start", background: "#FDEDEA",
      borderRadius: 12, padding: "10px 12px", marginBottom: 14, fontSize: 12, color: COLORS.text, lineHeight: 1.5,
    }}>
      <span>{L.lowBattery(Math.round(level * 100))}</span>
    </div>
  );
}

function Card({ children, style, onClick }) {
  return (
    <div onClick={onClick} style={{ background: COLORS.card, border: `1px solid ${COLORS.line}`, borderRadius: 18, padding: "22px 24px", boxShadow: "0 2px 14px rgba(91,58,36,0.06)", ...style }}>
      {children}
    </div>
  );
}

/* ---------------- SÉLECTEUR D'HEURE (remplace la roue native du téléphone) ---------------- */
function TimeSelect({ value, onChange, style }) {
  // value/onChange utilisent le format 24h "HH:MM" (compatible avec <input type="time">) pour ne rien
  // casser côté sauvegarde — seul l'affichage change (deux menus déroulants au lieu de la roue native).
  const [h24, m] = (value || "").split(":");
  const hourNum = h24 !== undefined && h24 !== "" ? Number(h24) : null;
  const minuteNum = m !== undefined && m !== "" ? Number(m) : 0;
  const period = hourNum === null ? "AM" : hourNum >= 12 ? "PM" : "AM";
  const hour12 = hourNum === null ? "" : (hourNum % 12 === 0 ? 12 : hourNum % 12);

  const commit = (h12, min, per) => {
    let h = Number(h12) % 12;
    if (per === "PM") h += 12;
    onChange(`${String(h).padStart(2, "0")}:${String(min).padStart(2, "0")}`);
  };

  const selectStyle = { padding: "10px 8px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, background: "#fff", ...style };

  return (
    <div style={{ display: "flex", gap: 6 }}>
      <select value={hour12 || ""} onChange={(e) => commit(e.target.value || 12, minuteNum, period)} style={{ ...selectStyle, flex: 1 }}>
        <option value="">--</option>
        {Array.from({ length: 12 }, (_, i) => i + 1).map((h) => <option key={h} value={h}>{h}</option>)}
      </select>
      <select value={minuteNum} onChange={(e) => commit(hour12 || 12, e.target.value, period)} style={{ ...selectStyle, flex: 1 }}>
        {Array.from({ length: 12 }, (_, i) => i * 5).map((min) => <option key={min} value={min}>{String(min).padStart(2, "0")}</option>)}
      </select>
      <select value={period} onChange={(e) => commit(hour12 || 12, minuteNum, e.target.value)} style={{ ...selectStyle, flex: 1 }}>
        <option value="AM">AM</option>
        <option value="PM">PM</option>
      </select>
    </div>
  );
}

/* ---------------- LOCKED CONTENT (paywall teaser) ---------------- */
