      {data.note && (
        <p style={{ marginTop: 14, padding: "10px 14px", background: COLORS.cream, borderRadius: 10, fontSize: 14, color: COLORS.muted, borderLeft: `3px solid ${COLORS.ochre}` }}>
          {data.note[lang]}
        </p>
      )}
