// Belle page de présentation affichée sur la page de l'onglet lui-même (avant de choisir un
// sous-onglet précis) pour les sections qui n'ont pas de contenu autonome dédié (contrairement à
// "Ma grossesse" avec son calculateur, ou "Conception" avec son calculateur d'ovulation).
// IMPORTANT : cette page ne doit contenir AUCUN lien ni bouton menant vers un sous-onglet — les
// sous-onglets ne sont accessibles que depuis le menu déroulant de navigation. Les cartes ci-dessous
// sont donc purement informatives (non cliquables), pour donner un aperçu du contenu de la section
// sans jamais permettre d'y naviguer directement depuis cette page.
function SectionOverviewGrid({ sectionKey, ids, dataObj, lang, accent = COLORS.sage }) {
  if (!ids || !ids.length) return null;
  const L = lang === "fr" ? "Dans cette section" : lang === "es" ? "En esta sección" : "In this section";
  const hint = lang === "fr"
    ? "Utilisez le menu déroulant en haut pour ouvrir l'un de ces sujets."
    : lang === "es"
    ? "Usa el menú desplegable de arriba para abrir uno de estos temas."
    : "Use the dropdown menu above to open one of these topics.";
  return (
    <div>
      <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 19, fontWeight: 700, color: COLORS.teal, margin: "0 0 6px" }}>{L}</h2>
      <p style={{ fontSize: 12.5, color: COLORS.muted, margin: "0 0 14px", fontStyle: "italic" }}>{hint}</p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(210px, 1fr))", gap: 14 }}>
        {ids.map((id) => {
          const d = dataObj[id];
          if (!d) return null;
          return (
            <div
              key={id}
              style={{
                display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 10, textAlign: "left",
                background: COLORS.card, border: `1px solid ${accent}30`, borderRadius: 18,
                padding: "16px 16px 14px", boxShadow: "0 3px 10px rgba(91,58,36,0.06)",
              }}
            >
              <div style={{
                width: 42, height: 42, borderRadius: 13, background: accent,
                display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
              }}>
                {d.titleIcon ? <Illustration type={d.titleIcon} size={26} /> : null}
              </div>
              <span style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 16, fontWeight: 700, color: COLORS.teal, lineHeight: 1.25 }}>
                {d.title[lang]}
              </span>
              {d.intro && (
                <span style={{
                  fontSize: 12.5, color: COLORS.muted, lineHeight: 1.5, display: "-webkit-box",
                  WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden",
                }}>
                  {d.intro[lang]}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

