// Composant générique de "planning imprimable" — pensé pour être réutilisé par d'autres plannings
// familiaux plus tard (il suffira de lui passer une structure de jours différente). Affiche une
// grille de jours à cocher à l'écran (interactif), plus un bouton d'export PDF qui réutilise
// exactement le même mécanisme d'impression que les autres outils PDF de l'appli (portail +
// @media print), avec une mise en page dédiée façon planning papier.
function FamilyWeeklyPlanner({ lang, printId, title, subtitle, days, dailyTasks, icon: HeaderIcon, headerColor }) {
  const [checked, setChecked] = useState({});
  const toggle = (id) => setChecked((c) => ({ ...c, [id]: !c[id] }));
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";
  const printedOn = new Date().toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" });
  const L = lang === "fr"
    ? { daily: "Tâches quotidiennes", notForget: "À ne pas oublier", notes: "Notes", btn: "📄 Télécharger en PDF", hint: "Sur mobile, choisissez « Enregistrer en PDF » comme imprimante — le document peut ensuite être partagé ou imprimé comme n'importe quel PDF.", generatedOn: "Généré le" }
    : lang === "es"
    ? { daily: "Tareas diarias", notForget: "No olvidar", notes: "Notas", btn: "📄 Descargar en PDF", hint: "En el celular, elige «Guardar como PDF» como impresora — el documento se puede compartir o imprimir como cualquier PDF.", generatedOn: "Generado el" }
    : { daily: "Daily tasks", notForget: "Don't forget", notes: "Notes", btn: "📄 Download as PDF", hint: "On mobile, choose \"Save as PDF\" as the printer — the document can then be shared or printed like any PDF.", generatedOn: "Generated on" };

  const CheckRow = ({ id, label }) => (
    <label style={{ display: "flex", alignItems: "flex-start", gap: 8, cursor: "pointer", marginBottom: 7 }}>
      <input type="checkbox" checked={!!checked[id]} onChange={() => toggle(id)} style={{ marginTop: 2, width: 15, height: 15, flexShrink: 0, accentColor: headerColor }} />
      <span style={{ fontSize: 12.5, color: COLORS.text, lineHeight: 1.4, textDecoration: checked[id] ? "line-through" : "none", opacity: checked[id] ? 0.55 : 1 }}>{label}</span>
    </label>
  );

  return (
    <Card style={{ marginTop: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 4 }}>
        <div style={{ width: 44, height: 44, borderRadius: 14, background: headerColor, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <HeaderIcon size={22} color="#fff" />
        </div>
        <div>
          <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 18, fontWeight: 700, color: COLORS.teal, margin: 0 }}>{title}</h3>
          <p style={{ fontSize: 12, color: COLORS.muted, margin: "2px 0 0" }}>{subtitle}</p>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(230px, 1fr))", gap: 12, marginTop: 16 }}>
        {days.map((d) => (
          <div key={d.key} style={{ background: `${d.color}0F`, border: `1px solid ${d.color}30`, borderRadius: 14, padding: "12px 14px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 8 }}>
              <d.icon size={15} color={d.color} />
              <span style={{ fontSize: 13, fontWeight: 800, color: d.color }}>{d.day[lang]}</span>
              {d.theme?.[lang] && <span style={{ fontSize: 11.5, color: COLORS.muted }}>— {d.theme[lang]}</span>}
            </div>
            {d.tasks[lang].map((t, i) => <CheckRow key={i} id={`${d.key}-${i}`} label={t} />)}
          </div>
        ))}
      </div>

      {dailyTasks && (
        <div style={{ marginTop: 12, background: `${COLORS.sand}14`, border: `1px solid ${COLORS.sand}30`, borderRadius: 14, padding: "12px 14px" }}>
          <span style={{ fontSize: 13, fontWeight: 800, color: COLORS.teal }}>{L.daily}</span>
          <div style={{ marginTop: 8 }}>
            {dailyTasks[lang].map((t, i) => <CheckRow key={i} id={`daily-${i}`} label={t} />)}
          </div>
        </div>
      )}

      <button onClick={() => window.print()} style={{
        width: "100%", padding: "13px", borderRadius: 12, border: "none", background: headerColor,
        color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 16,
      }}>{L.btn}</button>
      <p style={{ fontSize: 11, color: COLORS.muted, textAlign: "center", marginTop: 8 }}>{L.hint}</p>

      <style>{`
        @page { size: letter; margin: 0.4in; }
        @media print {
          html, body { margin: 0 !important; padding: 0 !important; }
          body > *:not(#${printId}) { display: none !important; }
          #${printId} { display: block !important; position: absolute; top: 0; left: 0; }
        }
        @media screen { #${printId} { display: none; } }
      `}</style>
      {createPortal(
        <div id={printId} style={{ width: "7.7in", padding: "0.2in", fontFamily: "Georgia, serif", color: "#222" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
            <div style={{ width: 34, height: 34, borderRadius: 10, background: headerColor, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <HeaderIcon size={18} color="#fff" />
            </div>
            <h1 style={{ fontSize: 19, margin: 0, color: "#222" }}>{title}</h1>
          </div>
          <p style={{ fontSize: 10.5, color: "#666", margin: "2px 0 12px" }}>{L.generatedOn} {printedOn}</p>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "0.14in" }}>
            {days.map((d) => (
              <div key={d.key} style={{ border: `1.5px solid ${d.color}`, borderRadius: 8, padding: "0.1in", breakInside: "avoid" }}>
                <div style={{ background: d.color, color: "#fff", borderRadius: 5, padding: "3px 7px", fontSize: 11.5, fontWeight: 700, marginBottom: 6 }}>
                  {d.day[lang]}{d.theme?.[lang] ? ` — ${d.theme[lang]}` : ""}
                </div>
                {d.tasks[lang].map((t, i) => (
                  <div key={i} style={{ display: "flex", gap: 6, fontSize: 10, marginBottom: 4, alignItems: "flex-start" }}>
                    <span style={{ display: "inline-block", width: 9, height: 9, border: "1.3px solid #999", borderRadius: 2, flexShrink: 0, marginTop: 1.5 }} />
                    <span>{t}</span>
                  </div>
                ))}
              </div>
            ))}
          </div>
          {dailyTasks && (
            <div style={{ marginTop: "0.14in", border: "1.5px solid #C9A876", borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.daily}</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 16px" }}>
                {dailyTasks[lang].map((t, i) => (
                  <div key={i} style={{ display: "flex", gap: 6, fontSize: 10, alignItems: "flex-start", minWidth: "45%" }}>
                    <span style={{ display: "inline-block", width: 9, height: 9, border: "1.3px solid #999", borderRadius: 2, flexShrink: 0, marginTop: 1.5 }} />
                    <span>{t}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.14in", marginTop: "0.14in" }}>
            <div style={{ border: "1.5px solid #D98BA4", borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 8, color: "#222" }}>{L.notForget}</div>
              {[0, 1, 2].map((i) => (
                <div key={i} style={{ borderBottom: "1px solid #ccc", height: "0.22in", marginBottom: 4 }} />
              ))}
            </div>
            <div style={{ border: "1.5px solid #6E9BC0", borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 8, color: "#222" }}>{L.notes}</div>
              {[0, 1, 2].map((i) => (
                <div key={i} style={{ borderBottom: "1px solid #ccc", height: "0.22in", marginBottom: 4 }} />
              ))}
            </div>
          </div>
        </div>,
        document.body
      )}
    </Card>
  );
}

