// Troisième planning : une page hebdomadaire vierge à imprimer, façon agenda papier — semaine à
// écrire à la main, menu de la semaine, préparation, notes, tâches à faire et un petit suivi de
// bonnes habitudes. Contrairement aux deux plannings ci-dessus (déjà remplis de tâches), celui-ci
// est pensé comme un GABARIT VIERGE qu'on remplit à la main une fois imprimé — donc pas de contenu
// interactif à l'écran, juste un aperçu et le téléchargement PDF.
function WeeklyOrganizerPlanner({ lang }) {
  const printId = "print-weekly-organizer";
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";
  const printedOn = new Date().toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" });
  const WEEK_DAYS = lang === "fr"
    ? ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"]
    : lang === "es"
    ? ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"]
    : ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const HABITS = lang === "fr"
    ? ["Boire de l'eau", "Bouger 10 minutes", "Un moment pour moi"]
    : lang === "es"
    ? ["Beber agua", "Moverme 10 minutos", "Un momento para mí"]
    : ["Drink water", "Move for 10 minutes", "A moment for myself"];
  const L = lang === "fr"
    ? { title: "Ma semaine — planning simplifié", subtitle: "Une page à imprimer pour organiser la semaine à la main : menu, tâches, notes et petites habitudes.", weekOf: "Ma semaine :", menu: "Menu de la semaine", prep: "Préparation", notes: "Notes", todo: "À faire", habits: "Mes bonnes habitudes", btn: "📄 Télécharger en PDF", hint: "Sur mobile, choisissez « Enregistrer en PDF » comme imprimante — le document peut ensuite être partagé ou imprimé comme n'importe quel PDF.", generatedOn: "Généré le", preview: "Contient : une grille des 7 jours, un menu de la semaine, un espace préparation, des notes libres, une liste à faire et un suivi de bonnes habitudes — tout sur une seule page, à remplir à la main une fois imprimée." }
    : lang === "es"
    ? { title: "Mi semana — planning simplificado", subtitle: "Una página para imprimir y organizar la semana a mano: menú, tareas, notas y pequeños hábitos.", weekOf: "Mi semana:", menu: "Menú de la semana", prep: "Preparación", notes: "Notas", todo: "Por hacer", habits: "Mis buenos hábitos", btn: "📄 Descargar en PDF", hint: "En el celular, elige «Guardar como PDF» como impresora — el documento se puede compartir o imprimir como cualquier PDF.", generatedOn: "Generado el", preview: "Incluye: una cuadrícula de los 7 días, un menú semanal, un espacio de preparación, notas libres, una lista de tareas y un seguimiento de buenos hábitos — todo en una sola página, para llenar a mano una vez impresa." }
    : { title: "My week — simple planner", subtitle: "A page to print and organize the week by hand: menu, to-dos, notes and small habits.", weekOf: "My week:", menu: "Weekly menu", prep: "Preparation", notes: "Notes", todo: "To do", habits: "My good habits", btn: "📄 Download as PDF", hint: "On mobile, choose \"Save as PDF\" as the printer — the document can then be shared or printed like any PDF.", generatedOn: "Generated on", preview: "Includes: a 7-day grid, a weekly menu, a preparation space, free notes, a to-do list and a habit tracker — all on one page, to fill in by hand once printed." };

  const LinedBox = ({ lines = 6 }) => (
    <div>
      {Array.from({ length: lines }).map((_, i) => (
        <div key={i} style={{ borderBottom: "1px solid #ccc", height: "0.2in" }} />
      ))}
    </div>
  );

  return (
    <Card style={{ marginTop: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 4 }}>
        <div style={{ width: 44, height: 44, borderRadius: 14, background: COLORS.blue, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Calendar size={22} color="#fff" />
        </div>
        <div>
          <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 18, fontWeight: 700, color: COLORS.teal, margin: 0 }}>{L.title}</h3>
          <p style={{ fontSize: 12, color: COLORS.muted, margin: "2px 0 0" }}>{L.subtitle}</p>
        </div>
      </div>
      <p style={{ fontSize: 12.5, color: COLORS.text, lineHeight: 1.6, background: `${COLORS.blue}0F`, border: `1px solid ${COLORS.blue}30`, borderRadius: 12, padding: "10px 13px", marginTop: 14 }}>{L.preview}</p>

      <button onClick={() => window.print()} style={{
        width: "100%", padding: "13px", borderRadius: 12, border: "none", background: COLORS.blue,
        color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 14,
      }}>{L.btn}</button>
      <p style={{ fontSize: 11, color: COLORS.muted, textAlign: "center", marginTop: 8 }}>{L.hint}</p>

      <style>{`
        @page { size: letter; margin: 0.4in; }
        @media print {
          html, body { margin: 0 !important; padding: 0 !important; }
          body > *:not(#${printId}) { display: none !important; }
          #${printId} { display: block !important; position: absolute; top: 0; left: 0; }
        }
        @media screen { #${printId} { display: none; } }
      `}</style>
      {createPortal(
        <div id={printId} style={{ width: "7.7in", padding: "0.2in", fontFamily: "Georgia, serif", color: "#222" }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 2 }}>
            <h1 style={{ fontSize: 20, margin: 0, color: "#222" }}>{L.weekOf}</h1>
            <div style={{ flex: 1, borderBottom: "1px solid #999", height: "0.2in" }} />
          </div>
          <p style={{ fontSize: 10, color: "#666", margin: "2px 0 10px" }}>{L.generatedOn} {printedOn}</p>

          {/* Bande des 7 jours de la semaine */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", marginBottom: "0.14in" }}>
            {WEEK_DAYS.map((d, i) => (
              <div key={i} style={{ border: "1.5px solid " + COLORS.blue, borderRight: i < 6 ? "none" : undefined, textAlign: "center", padding: "4px 0" }}>
                <div style={{ fontSize: 10, fontWeight: 700, background: COLORS.blue, color: "#fff", padding: "2px 0" }}>{d}</div>
                <div style={{ height: "0.3in" }} />
              </div>
            ))}
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.14in" }}>
            <div style={{ border: `1.5px solid ${COLORS.lavender}`, borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.menu}</div>
              {WEEK_DAYS.map((d, i) => (
                <div key={i} style={{ display: "flex", gap: 6, alignItems: "baseline", marginBottom: 5 }}>
                  <span style={{ fontSize: 9.5, fontWeight: 700, width: 24 }}>{d[0]}</span>
                  <div style={{ flex: 1, borderBottom: "1px solid #ccc", height: "0.16in" }} />
                </div>
              ))}
            </div>
            <div style={{ border: `1.5px solid ${COLORS.sky}`, borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.prep}</div>
              <LinedBox lines={7} />
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0.14in", marginTop: "0.14in" }}>
            <div style={{ border: `1.5px solid ${COLORS.ochre}`, borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.notes}</div>
              <LinedBox lines={7} />
            </div>
            <div style={{ border: `1.5px solid ${COLORS.sage}`, borderRadius: 8, padding: "0.1in" }}>
              <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.todo}</div>
              {Array.from({ length: 7 }).map((_, i) => (
                <div key={i} style={{ display: "flex", gap: 6, alignItems: "flex-start", marginBottom: 5 }}>
                  <span style={{ display: "inline-block", width: 9, height: 9, border: "1.3px solid #999", borderRadius: 2, flexShrink: 0, marginTop: 2 }} />
                  <div style={{ flex: 1, borderBottom: "1px solid #ccc", height: "0.16in" }} />
                </div>
              ))}
            </div>
          </div>

          <div style={{ marginTop: "0.14in", border: `1.5px solid ${COLORS.pink}`, borderRadius: 8, padding: "0.1in" }}>
            <div style={{ fontSize: 11.5, fontWeight: 700, marginBottom: 6, color: "#222" }}>{L.habits}</div>
            <div style={{ display: "grid", gridTemplateColumns: "1.4fr repeat(7, 1fr)", gap: 4, alignItems: "center" }}>
              <div />
              {WEEK_DAYS.map((d, i) => <div key={i} style={{ fontSize: 9, fontWeight: 700, textAlign: "center" }}>{d}</div>)}
              {HABITS.map((h, hi) => (
                <React.Fragment key={hi}>
                  <div style={{ fontSize: 10 }}>{h}</div>
                  {WEEK_DAYS.map((_, di) => (
                    <div key={di} style={{ display: "flex", justifyContent: "center" }}>
                      <span style={{ display: "inline-block", width: 9, height: 9, border: "1.3px solid #999", borderRadius: 2 }} />
                    </div>
                  ))}
                </React.Fragment>
              ))}
            </div>
          </div>
        </div>,
        document.body
      )}
    </Card>
  );
}

// Petit composant partagé — une zone de lignes vides pour écrire à la main une fois imprimé,
// réutilisé par plusieurs plannings (routine, budget, liste de courses, semaine simplifiée).
function PlannerLinedBox({ lines = 6, height = "0.2in" }) {
  return (
    <div>
      {Array.from({ length: lines }).map((_, i) => (
        <div key={i} style={{ borderBottom: "1px solid #ccc", height }} />
      ))}
    </div>
  );
}

