// Point d'entrée affiché dans "Vie de famille" > "Sauver du temps au quotidien" — un petit
// sélecteur permet de passer d'un planning imprimable à l'autre. D'autres modèles pourront
// s'ajouter ici plus tard.
function HouseholdPlannersCard({ lang }) {
  const [active, setActive] = useState("weeklyCleaning");
  const L = lang === "fr"
    ? { pickerLabel: "Choisir un planning :", weeklyCleaning: "Ménage — semaine", deepClean: "Ménage — en profondeur", weeklyOrganizer: "Ma semaine", routine: "Ma routine", grocery: "Liste de courses" }
    : lang === "es"
    ? { pickerLabel: "Elegir un planning:", weeklyCleaning: "Limpieza — semana", deepClean: "Limpieza — a fondo", weeklyOrganizer: "Mi semana", routine: "Mi rutina", grocery: "Lista de compras" }
    : { pickerLabel: "Choose a planner:", weeklyCleaning: "Cleaning — week", deepClean: "Cleaning — deep", weeklyOrganizer: "My week", routine: "My routine", grocery: "Grocery list" };

  const cleaningTitle = lang === "fr" ? "Calendrier de ménage hebdomadaire" : lang === "es" ? "Calendario de limpieza semanal" : "Weekly cleaning calendar";
  const cleaningSubtitle = lang === "fr" ? "Un focus différent chaque jour — pour que le ménage reste simple et réaliste." : lang === "es" ? "Un enfoque diferente cada día — para que la limpieza siga siendo simple y realista." : "A different focus each day — to keep cleaning simple and realistic.";
  const deepTitle = lang === "fr" ? "Ménage en profondeur, par pièce" : lang === "es" ? "Limpieza a fondo, por habitación" : "Deep clean, room by room";
  const deepSubtitle = lang === "fr" ? "Pour un grand nettoyage occasionnel — toute la maison, pièce par pièce." : lang === "es" ? "Para una limpieza a fondo ocasional — toda la casa, habitación por habitación." : "For an occasional deep clean — the whole house, room by room.";

  const options = [
    { key: "weeklyCleaning", label: L.weeklyCleaning, color: COLORS.sage },
    { key: "deepClean", label: L.deepClean, color: COLORS.blue },
    { key: "weeklyOrganizer", label: L.weeklyOrganizer, color: COLORS.pink },
    { key: "routine", label: L.routine, color: COLORS.ochre },
    { key: "grocery", label: L.grocery, color: COLORS.coral },
  ];

  return (
    <div style={{ marginTop: 16 }}>
      <p style={{ fontSize: 12, fontWeight: 700, color: COLORS.muted, margin: "0 0 8px" }}>{L.pickerLabel}</p>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {options.map((o) => (
          <button key={o.key} onClick={() => setActive(o.key)} style={{
            padding: "7px 14px", borderRadius: 999, border: `1.5px solid ${active === o.key ? o.color : COLORS.line}`,
            background: active === o.key ? o.color : "#fff", color: active === o.key ? "#fff" : COLORS.text,
            fontSize: 12.5, fontWeight: 700, cursor: "pointer",
          }}>{o.label}</button>
        ))}
      </div>

      {active === "weeklyCleaning" && (
        <FamilyWeeklyPlanner lang={lang} printId="print-cleaning-planner" title={cleaningTitle} subtitle={cleaningSubtitle} days={CLEANING_PLANNER_DAYS} dailyTasks={CLEANING_PLANNER_DAILY} icon={ClipboardList} headerColor={COLORS.sage} />
      )}
      {active === "deepClean" && (
        <FamilyWeeklyPlanner lang={lang} printId="print-deep-clean-planner" title={deepTitle} subtitle={deepSubtitle} days={DEEP_CLEAN_ROOMS} dailyTasks={null} icon={Sparkles} headerColor={COLORS.blue} />
      )}
      {active === "weeklyOrganizer" && <WeeklyOrganizerPlanner lang={lang} />}
      {active === "routine" && <DailyRoutinePlanner lang={lang} />}
      {active === "grocery" && <GroceryListPlanner lang={lang} />}
    </div>
  );
}

// Table (clé Supabase) associée à chaque sectionKey — le dev01 a besoin de deux tables combinées.
const GENERIC_SECTION_CONTENT_KEYS = {
  postpartum: ["POSTPARTUM"],
  dev01: ["DEV01", "DEV15"],
  alimentation: ["FEEDING"],
  soins: ["CARE"],
  sante: ["HEALTH"],
  famille: ["FAMILYLIFE"],
};

// Ordre volontaire des sous-onglets par section — Supabase (jsonb) ne garantit pas l'ordre des clés
// d'un objet JSON, donc on le fixe explicitement ici plutôt que de se fier à Object.keys().
const GENERIC_SECTION_TAB_ORDER = {
  postpartum: ["retourCouches", "emotions", "allaitement", "biberon", "sommeilNaissance", "couple", "recuperation", "exercicesPostpartum"],
  dev01: ["m03", "m46", "m79", "m1012", "a12", "a23", "a34", "a45", "proprete", "jeu"],
  alimentation: ["intro", "allergenes", "menu612", "menu15"],
  soins: ["bain", "peau", "oreillesNez", "change", "sommeilSecuritaire", "habillement"],
  sante: ["fievre", "rhume", "gastro", "otite", "eruptions", "urgence", "vaccination"],
  famille: ["plusieursEnfants", "travailFamille", "sauverDuTemps", "coupleFamille", "lacherPrise", "solutionsPratiques"],
};

function GenericSection({ sectionKey, lang, isMember, goTo, initialSub, children: kids, session }) {
  // Le contenu texte de chaque section est chargé depuis Supabase (table app_content) uniquement si
  // la personne visite réellement cette section — plutôt que d'être codé en dur et chargé d'un coup
  // au démarrage de l'app pour TOUTES les sections, peu importe si elles sont consultées ou non.
  const [dataObj, setDataObj] = useState(null);
  const [loadError, setLoadError] = useState(false);
  useEffect(() => {
    let mounted = true;
    const keys = GENERIC_SECTION_CONTENT_KEYS[sectionKey] || [];
    Promise.all(keys.map((k) => supabaseFetchContent(k)))
      .then((parts) => { if (mounted) setDataObj(Object.assign({}, ...parts)); })
      .catch(() => { if (mounted) setLoadError(true); });
    return () => { mounted = false; };
  }, [sectionKey]);

  // Même mécanique que "Ma grossesse" / "Conception" : le sous-onglet précis à afficher vient du
  // menu de navigation déplié (jamais d'un sélecteur affiché sur la page elle-même), et on se
  // resynchronise si on choisit un autre sous-onglet alors que le composant est déjà monté.
  const [activeSub, setActiveSub] = useState(initialSub || null);
  const meta = SECTION_META[sectionKey];

  useEffect(() => {
    setActiveSub(initialSub || null);
  }, [initialSub]);

  if (!dataObj) {
    return (
      <div style={{ padding: "60px 20px", textAlign: "center", color: COLORS.muted }}>
        {loadError
          ? (lang === "fr" ? "Impossible de charger le contenu pour le moment. Vérifiez votre connexion et réessayez." : lang === "es" ? "No se pudo cargar el contenido por ahora. Verifica tu conexión e inténtalo de nuevo." : "Couldn't load the content right now. Check your connection and try again.")
          : (lang === "fr" ? "Chargement…" : lang === "es" ? "Cargando…" : "Loading…")}
      </div>
    );
  }

  const ids = (GENERIC_SECTION_TAB_ORDER[sectionKey] || Object.keys(dataObj)).filter((id) => dataObj[id]);
  // La page de l'onglet lui-même (sans sous-onglet choisi) ne retombe plus automatiquement sur le
  // premier sous-onglet — elle affiche sa propre page de présentation (voir plus bas).
  const currentSub = activeSub && dataObj[activeSub] ? activeSub : null;
  const milestoneRows = sectionKey === "dev01" && currentSub
    ? (DEV_MILESTONE_MAP[currentSub]
        ? DEV_MILESTONE_MAP[currentSub].map((i) => DEV_MILESTONES[i])
        : DEV15_MILESTONE_MAP[currentSub]
          ? DEV15_MILESTONE_MAP[currentSub].map((i) => DEV15_MILESTONES[i])
          : null)
    : null;
  // La section "Vie de famille" vient de Supabase avec une couleur de carte sombre (presque noire) qui
  // détonne avec le reste de l'app — on la remplace ici par des tons chaleureux et vifs, sans toucher
  // au contenu texte ni aux autres sections. COLORS.teal n'est PLUS dans cette liste : c'est maintenant
  // la couleur de marque (brun très sombre), donc une carte sur 5 apparaissait presque noire.
  const FAMILY_PALETTE = [COLORS.pink, COLORS.coral, COLORS.ochre, COLORS.sage, COLORS.blue];
  const subtabData = currentSub && sectionKey === "famille" && dataObj[currentSub]?.groups
    ? { ...dataObj[currentSub], groups: dataObj[currentSub].groups.map((g, i) => ({ ...g, color: FAMILY_PALETTE[i % FAMILY_PALETTE.length] })) }
    : (currentSub ? dataObj[currentSub] : null);
  return (
    <div>
      <SectionHero sectionKey={sectionKey} lang={lang} />
      <ToyDivider />
      {currentSub ? (
        <>
          {isMember && milestoneRows && <DevMilestonesTable lang={lang} rows={milestoneRows} />}
          <SubtabBody data={subtabData} lang={lang} accent={meta?.color} Icon={meta?.icon} isMember={isMember} goTo={goTo} />
          {isMember && sectionKey === "sante" && currentSub === "vaccination" && <VaccineCalendar lang={lang} />}
          {isMember && sectionKey === "sante" && currentSub === "urgence" && <HealthEmergencySheet lang={lang} />}
          {isMember && sectionKey === "alimentation" && currentSub === "intro" && <RecipesByAgeCard lang={lang} />}
          {isMember && sectionKey === "alimentation" && currentSub === "intro" && <FoodIntroductionTracker lang={lang} />}
          {isMember && sectionKey === "alimentation" && currentSub === "menu612" && (
            <MealScheduleCard lang={lang} rows={MENU612_SCHEDULE} color={COLORS.blue} colHeaders={lang === "fr" ? ["6-8 mois", "9-12 mois"] : lang === "es" ? ["6-8 meses", "9-12 meses"] : ["6-8 months", "9-12 months"]} title={lang === "fr" ? "Horaire d'une journée type — 6 à 12 mois" : lang === "es" ? "Horario de un día tipo — 6 a 12 meses" : "Sample day schedule — 6 to 12 months"} />
          )}
          {isMember && sectionKey === "alimentation" && currentSub === "menu15" && (
            <MealScheduleCard lang={lang} rows={MENU15_SCHEDULE} color={COLORS.pink} colHeaders={lang === "fr" ? ["1-3 ans", "3-5 ans"] : lang === "es" ? ["1-3 años", "3-5 años"] : ["1-3 years", "3-5 years"]} title={lang === "fr" ? "Horaire d'une journée type — 1 à 5 ans" : lang === "es" ? "Horario de un día tipo — 1 a 5 años" : "Sample day schedule — 1 to 5 years"} />
          )}
          {isMember && sectionKey === "postpartum" && currentSub === "allaitement" && <NursingScheduleCard lang={lang} />}
          {isMember && sectionKey === "postpartum" && currentSub === "biberon" && <MilkChartCard lang={lang} />}
          {isMember && sectionKey === "postpartum" && currentSub === "sommeilNaissance" && <SleepMilestonesCard lang={lang} />}
          {isMember && sectionKey === "postpartum" && currentSub === "allaitement" && <BreastmilkTipsCard lang={lang} />}
          {isMember && sectionKey === "postpartum" && currentSub === "exercicesPostpartum" && <PostpartumExerciseTables lang={lang} />}
          {isMember && sectionKey === "postpartum" && currentSub === "emotions" && <MoodCheckIn lang={lang} />}
          {isMember && sectionKey === "soins" && currentSub === "habillement" && <TempClothingTable lang={lang} />}
          {isMember && sectionKey === "soins" && currentSub === "bain" && <BathFrequencyTable lang={lang} />}
          {isMember && sectionKey === "famille" && currentSub === "sauverDuTemps" && <HouseholdPlannersCard lang={lang} />}
          {isMember && sectionKey === "famille" && currentSub === "solutionsPratiques" && <MonthlyBudgetPlanner lang={lang} />}
        </>
      ) : (
        <>
          {isMember && sectionKey === "dev01" && <MilestoneChartCard lang={lang} />}
          <SectionOverviewGrid sectionKey={sectionKey} ids={ids} dataObj={dataObj} lang={lang} accent={meta?.color} />
        </>
      )}
      <ToyDivider />
    </div>
  );
}

/* ---------------- FREE-TOOL BADGE ---------------- */
// Petit badge à poser sur les outils accessibles à tout le monde (pas seulement aux membres),
// pour que ce soit visuellement évident dès un coup d'œil — plutôt que la personne le découvre
// seulement en essayant de cliquer.
function FreeToolBadge({ lang }) {
  const label = lang === "fr" ? "Offert à tous — gratuit" : lang === "es" ? "Para todas — gratis" : "Free for everyone";
  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: "linear-gradient(135deg, #FBF1E3 0%, #F3E4CC 100%)",
      color: COLORS.teal, border: `1px solid ${COLORS.ochre}`,
      borderRadius: 999, padding: "5px 12px 5px 10px",
      fontSize: 11.5, fontWeight: 800, letterSpacing: "0.01em", whiteSpace: "nowrap",
      boxShadow: "0 2px 6px rgba(91,58,36,0.12)",
    }}>
      <Gift size={13} strokeWidth={2.4} color={COLORS.teal} />
      {label}
    </span>
  );
}

/* ---------------- OVULATION CALCULATOR ---------------- */
function OvulationCalculator({ lang }) {
  const [lmp, setLmp] = useState("");
  const [cycleLength, setCycleLength] = useState(28);

  const result = useMemo(() => {
    if (!lmp) return null;
    const start = new Date(lmp + "T00:00:00");
    if (isNaN(start.getTime())) return null;
    const ovulationDay = new Date(start);
    ovulationDay.setDate(start.getDate() + (Number(cycleLength) - 14));
    const fertileStart = new Date(ovulationDay);
    fertileStart.setDate(ovulationDay.getDate() - 5);
    const fertileEnd = new Date(ovulationDay);
    fertileEnd.setDate(ovulationDay.getDate() + 1);
    const nextPeriod = new Date(start);
    nextPeriod.setDate(start.getDate() + Number(cycleLength));
    return { ovulationDay, fertileStart, fertileEnd, nextPeriod };
  }, [lmp, cycleLength]);

  const fmt = (d) => d.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "long", year: "numeric" });

  const L = lang === "fr"
    ? { title: "Calculateur d'ovulation", lmpLabel: "1er jour de vos dernières règles", cycleLabel: "Longueur habituelle du cycle (jours)", ov: "Jour d'ovulation estimé", fw: "Fenêtre fertile", np: "Prochaines règles prévues", disclaimer: "Estimation basée sur un cycle régulier. Les cycles irréguliers rendent cette estimation moins précise." }
    : lang === "es"
    ? { title: "Calculadora de ovulación", lmpLabel: "1er día de tu última menstruación", cycleLabel: "Duración habitual del ciclo (días)", ov: "Día de ovulación estimado", fw: "Ventana fértil", np: "Próxima menstruación esperada", disclaimer: "Estimación basada en un ciclo regular. Los ciclos irregulares hacen esta estimación menos precisa." }
    : { title: "Ovulation calculator", lmpLabel: "First day of your last period", cycleLabel: "Usual cycle length (days)", ov: "Estimated ovulation day", fw: "Fertile window", np: "Next period expected", disclaimer: "Estimate based on a regular cycle. Irregular cycles make this estimate less precise." };

  return (
    <Card style={{ marginBottom: 28, borderTop: `4px solid ${COLORS.blue}`, background: "#EEF5FA" }}>
      <div style={{ marginBottom: 10 }}>
        <FreeToolBadge lang={lang} />
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10, flexWrap: "wrap" }}>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: COLORS.blue, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Calculator size={18} color="#fff" />
        </div>
        <h3 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, flex: 1, minWidth: 0 }}>{L.title}</h3>
      </div>
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", marginBottom: 16 }}>
        <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: COLORS.muted, fontWeight: 600 }}>
          {L.lmpLabel}
          <input type="date" value={lmp} onChange={(e) => setLmp(e.target.value)}
            style={{ padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14 }} />
        </label>
        <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: COLORS.muted, fontWeight: 600 }}>
          {L.cycleLabel}
          <input type="number" min={21} max={35} value={cycleLength} onChange={(e) => setCycleLength(e.target.value)}
            style={{ padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, width: 100 }} />
        </label>
      </div>
      {result && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12 }}>
          <div style={{ background: "linear-gradient(135deg, #D8E9F2 0%, #C2DCE9 100%)", borderRadius: 12, padding: "12px 14px" }}>
            <div style={{ fontSize: 12, color: "#3D6E8F", fontWeight: 700, textTransform: "uppercase" }}>{L.ov}</div>
            <div style={{ fontSize: 17, color: COLORS.teal, fontWeight: 800, marginTop: 4 }}>{fmt(result.ovulationDay)}</div>
          </div>
          <div style={{ background: "linear-gradient(135deg, #D8E9F2 0%, #C2DCE9 100%)", borderRadius: 12, padding: "12px 14px" }}>
            <div style={{ fontSize: 12, color: "#3D6E8F", fontWeight: 700, textTransform: "uppercase" }}>{L.fw}</div>
            <div style={{ fontSize: 15, color: COLORS.teal, fontWeight: 800, marginTop: 4 }}>{fmt(result.fertileStart)} – {fmt(result.fertileEnd)}</div>
          </div>
          <div style={{ background: "linear-gradient(135deg, #D8E9F2 0%, #C2DCE9 100%)", borderRadius: 12, padding: "12px 14px" }}>
            <div style={{ fontSize: 12, color: "#3D6E8F", fontWeight: 700, textTransform: "uppercase" }}>{L.np}</div>
            <div style={{ fontSize: 17, color: COLORS.teal, fontWeight: 800, marginTop: 4 }}>{fmt(result.nextPeriod)}</div>
          </div>
        </div>
      )}
      <p style={{ fontSize: 12.5, color: COLORS.muted, marginTop: 14, marginBottom: 0 }}>{L.disclaimer}</p>
    </Card>
  );
}

/* ---------------- CYCLE TRACKER (personal journal) ---------------- */
function CycleTracker({ lang, session }) {
  const [entries, setEntries] = useState([]);
  const [date, setDate] = useState("");
  const [loading, setLoading] = useState(true);

  // Charge l'historique déjà enregistré au montage — avant, ce suivi était perdu à chaque
  // fermeture de l'app puisqu'il ne vivait qu'en mémoire locale (useState) sans jamais être
  // sauvegardé dans Supabase.
  useEffect(() => {
    if (!(session?.access_token && session?.user?.id)) { setLoading(false); return; }
    let cancelled = false;
    supabaseFetchTrackerEntries(session.user.id, "cycle", session.access_token)
      .then((rows) => {
        if (cancelled) return;
        const mapped = rows.map(mapTrackerEntryRow).sort((a, b) => (a.start || a.createdAt) - (b.start || b.createdAt));
        setEntries(mapped);
      })
      .catch(() => { /* l'historique reste vide si le chargement échoue, la personne peut réessayer en rouvrant */ })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [session?.access_token, session?.user?.id]);

  const L = lang === "fr"
    ? {
        title: "Mon suivi de cycle", subtitle: "Notez le premier jour de vos règles chaque mois — l'application calcule la durée de chaque cycle pour vous.",
        dateLabel: "Premier jour des règles", add: "Ajouter",
        empty: "Aucune date pour l'instant — ajoutez le premier jour de vos dernières règles ci-dessus.",
        colDate: "Date", colLength: "Durée du cycle", firstCycle: "Premier cycle enregistré",
        days: (n) => `${n} jour${n > 1 ? "s" : ""}`,
        remove: "Retirer",
      }
    : lang === "es"
    ? {
        title: "Mi seguimiento de ciclo", subtitle: "Registra el primer día de tu menstruación cada mes — la aplicación calcula la duración de cada ciclo por ti.",
        dateLabel: "Primer día de la menstruación", add: "Agregar",
        empty: "Aún no hay fechas — agrega el primer día de tu última menstruación arriba.",
        colDate: "Fecha", colLength: "Duración del ciclo", firstCycle: "Primer ciclo registrado",
        days: (n) => `${n} día${n > 1 ? "s" : ""}`,
        remove: "Quitar",
      }
    : {
        title: "My cycle tracker", subtitle: "Log the first day of your period each month — the app calculates each cycle's length for you.",
        dateLabel: "First day of period", add: "Add",
        empty: "No dates yet — add the first day of your last period above.",
        colDate: "Date", colLength: "Cycle length", firstCycle: "First cycle logged",
        days: (n) => `${n} day${n > 1 ? "s" : ""}`,
        remove: "Remove",
      };

  const inputStyle = { padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13.5, fontFamily: "inherit" };

  const toDateStr = (d) => (d instanceof Date ? d.toISOString().slice(0, 10) : "");

  const addEntry = () => {
    if (!date || entries.some((en) => toDateStr(en.start) === date)) return;
    const startDate = new Date(date + "T00:00:00");
    const optimistic = makeOptimisticEntry({ start: startDate, label: date });
    setEntries((prev) => [...prev, optimistic].sort((a, b) => a.start - b.start));
    if (session?.access_token && session?.user?.id) {
      persistTrackerEntry("cycle", { start: startDate, label: date }, session, setEntries, optimistic.id);
    }
    setDate("");
  };

  const removeEntry = (id) => removeTrackerEntry(id, session, setEntries);

  const fmt = (d) => d.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "long", year: "numeric" });
  const dayDiff = (a, b) => Math.round((b - a) / 86400000);

  const rows = [...entries].reverse().map((en, i, arr) => {
    const prev = arr[i + 1];
    const length = prev ? dayDiff(prev.start, en.start) : null;
    return { ...en, length };
  });
  const dayWord = lang === "fr" ? "date" : lang === "es" ? "fecha" : "date";
  const daysWord = lang === "fr" ? "dates" : lang === "es" ? "fechas" : "dates";

  return (
    <Card style={{ marginBottom: 28, borderTop: `4px solid ${COLORS.sage}`, background: "#EAF1E8" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: COLORS.sage, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <BookOpen size={17} color="#fff" />
        </div>
        <h3 style={{ margin: 0, fontSize: 14, fontWeight: 800, letterSpacing: "0.03em", textTransform: "uppercase", color: COLORS.teal }}>{L.title}</h3>
      </div>
      <p style={{ fontSize: 13, color: COLORS.muted, margin: "0 0 14px" }}>{L.subtitle}</p>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 16, alignItems: "flex-end" }}>
        <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 12.5, color: COLORS.muted, fontWeight: 600 }}>
          {L.dateLabel}
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") addEntry(); }}
            style={inputStyle}
          />
        </label>
        <button type="button" onClick={addEntry} style={{
          background: COLORS.sage, color: "#fff", border: "none", padding: "9px 18px",
          borderRadius: 10, fontWeight: 700, fontSize: 13.5, cursor: "pointer",
        }}>{L.add}</button>
      </div>

      {loading ? (
        <p style={{ fontSize: 13, color: COLORS.muted, fontStyle: "italic" }}>…</p>
      ) : rows.length === 0 ? (
        <p style={{ fontSize: 13, color: COLORS.muted, fontStyle: "italic" }}>{L.empty}</p>
      ) : (
        <DateGroupedList
          items={rows}
          getDate={(row) => row.start}
          getId={(row) => row.id}
          loaded={!loading}
          emptyLabel={L.empty}
          countLabel={(n) => `${n} ${n > 1 ? daysWord : dayWord}`}
          lang={lang}
          renderItem={(row) => (
            <div key={row.id} style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              background: COLORS.cream, borderRadius: 10, padding: "9px 13px", fontSize: 13, gap: 8,
            }}>
              <span style={{ color: COLORS.teal, fontWeight: 700 }}>{fmt(row.start)}</span>
              <span style={{ color: COLORS.text, flex: 1, textAlign: "right" }}>
                {row.length ? L.days(row.length) : <span style={{ color: COLORS.muted, fontStyle: "italic" }}>{L.firstCycle}</span>}
              </span>
              <button onClick={() => removeEntry(row.id)} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 11, cursor: "pointer", textDecoration: "underline", flexShrink: 0 }}>{L.remove}</button>
            </div>
          )}
        />
      )}
      <TrackerPdfExport
        lang={lang} printId="cycle-print-view" title={L.title}
        entries={rows.map((row) => ({ date: row.start, label: fmt(row.start), detail: row.length ? L.days(row.length) : L.firstCycle }))}
      />
    </Card>
  );
}

