function BirthPlanTool({ lang, userProfile, session }) {
  const L = lang === "fr"
    ? { title: "Plan de naissance", subtitle: "Vos souhaits pour l'accouchement, remplis à votre rythme et téléchargeables en PDF à apporter à l'hôpital.", printBtn: "📄 Télécharger en PDF", printHint: "S'ouvre dans la fenêtre d'impression — choisissez « Enregistrer en PDF ».", dueLabel: "Date prévue", weekLabel: (w) => `Semaine ${w}`, printedOnLabel: "Imprimé le", disclaimer: "Ce plan de naissance reflète vos souhaits — l'équipe médicale pourra devoir s'en écarter selon la situation le jour même. Discutez-en avec votre professionnel de la santé.", noAnswer: "—" }
    : lang === "es"
    ? { title: "Plan de nacimiento", subtitle: "Tus deseos para el parto, completados a tu ritmo y descargables en PDF para llevar al hospital.", printBtn: "📄 Descargar en PDF", printHint: "Se abre en la ventana de impresión — elige «Guardar como PDF».", dueLabel: "Fecha prevista", weekLabel: (w) => `Semana ${w}`, printedOnLabel: "Impreso el", disclaimer: "Este plan de nacimiento refleja tus deseos — el equipo médico podría necesitar desviarse según la situación del día. Coméntalo con tu profesional de la salud.", noAnswer: "—" }
    : { title: "Birth plan", subtitle: "Your wishes for the birth, filled in at your own pace and downloadable as a PDF to bring to the hospital.", printBtn: "📄 Download as PDF", printHint: "Opens the print window — choose \"Save as PDF\".", dueLabel: "Due date", weekLabel: (w) => `Week ${w}`, printedOnLabel: "Printed on", disclaimer: "This birth plan reflects your wishes — the medical team may need to depart from it depending on the situation on the day. Discuss it with your healthcare provider.", noAnswer: "—" };

  const STORAGE_KEY = mmbScopedKey("mmb_birth_plan_v1", session);
  const [answers, setAnswers] = useState({});
  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      setAnswers(raw ? JSON.parse(raw) : {});
    } catch { setAnswers({}); }
  }, [STORAGE_KEY]);
  const setAnswer = (key, value) => {
    setAnswers((prev) => {
      const next = { ...prev, [key]: value };
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(next)); } catch {}
      return next;
    });
  };

  const pregnancy = userProfile?.dueDate ? getPregnancyInfo(userProfile.dueDate, lang) : null;
  const printedOn = new Date().toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-ES" : "en-US", { year: "numeric", month: "long", day: "numeric" });

  const inputStyle = { width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13, boxSizing: "border-box", fontFamily: "inherit", resize: "vertical" };

  const pillLabelFor = (item, id) => item.options.find((o) => o.id === id)?.label[lang] || item.options.find((o) => o.id === id)?.label.fr || "";

  return (
    <Card style={{ marginBottom: 18 }}>
      <h4 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 17, color: COLORS.teal }}>{L.title}</h4>
      <p style={{ margin: "0 0 4px", fontSize: 12.5, color: COLORS.muted }}>{L.subtitle}</p>
      {pregnancy && (
        <p style={{ margin: "0 0 14px", fontSize: 12.5, fontWeight: 700, color: COLORS.teal }}>
          {L.weekLabel(pregnancy.weeks)}{pregnancy.fmtDue ? ` — ${L.dueLabel} ${pregnancy.fmtDue}` : ""}
        </p>
      )}

      {BIRTH_PLAN_FIELDS.map((sec, si) => (
        <div key={si} style={{ marginBottom: 18 }}>
          <p style={{ fontSize: 11.5, fontWeight: 800, color: COLORS.ochre, textTransform: "uppercase", letterSpacing: "0.03em", margin: "0 0 10px" }}>{sec.section[lang] || sec.section.fr}</p>
          {sec.items.map((item) => (
            <div key={item.key} style={{ marginBottom: 14 }}>
              <label style={{ display: "block", fontSize: 12.5, fontWeight: 600, color: COLORS.text, marginBottom: 6 }}>{item.q[lang] || item.q.fr}</label>
              {item.type === "pills" ? (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {item.options.map((o) => {
                    const selected = answers[item.key] === o.id;
                    return (
                      <button key={o.id} onClick={() => setAnswer(item.key, o.id)} style={{
                        padding: "7px 13px", borderRadius: 999, border: `1.5px solid ${selected ? COLORS.teal : COLORS.line}`,
                        background: selected ? COLORS.teal : "#fff", color: selected ? "#fff" : COLORS.text,
                        fontSize: 12.5, fontWeight: 600, cursor: "pointer",
                      }}>{o.label[lang] || o.label.fr}</button>
                    );
                  })}
                </div>
              ) : (
                <textarea rows={2} style={inputStyle} value={answers[item.key] || ""} onChange={(e) => setAnswer(item.key, e.target.value)} />
              )}
            </div>
          ))}
        </div>
      ))}

      <button onClick={() => window.print()} style={{
        width: "100%", padding: "14px", borderRadius: 12, border: "none", background: COLORS.teal,
        color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer",
      }}>{L.printBtn}</button>
      <p style={{ fontSize: 11, color: COLORS.muted, textAlign: "center", marginTop: 8 }}>{L.printHint}</p>

      <style>{`
        @page { size: letter; margin: 0.5in; }
        @media print {
          html, body { margin: 0 !important; padding: 0 !important; }
          body > *:not(#birth-plan-print-view) { display: none !important; }
          #birth-plan-print-view { display: block !important; position: absolute; top: 0; left: 0; }
        }
        @media screen { #birth-plan-print-view { display: none; } }
      `}</style>
      {createPortal(
        <div id="birth-plan-print-view" style={{ width: "7.5in", padding: "0.2in", fontFamily: "Georgia, serif", color: "#222" }}>
          <h1 style={{ fontSize: 22, margin: "0 0 4px" }}>{L.title}</h1>
          <p style={{ fontSize: 11, color: "#666", margin: "0 0 4px" }}>{L.printedOnLabel} {printedOn}</p>
          {pregnancy && (
            <p style={{ fontSize: 13, fontWeight: 700, margin: "0 0 16px" }}>
              {L.weekLabel(pregnancy.weeks)}{pregnancy.fmtDue ? ` — ${L.dueLabel} ${pregnancy.fmtDue}` : ""}
            </p>
          )}
          {BIRTH_PLAN_FIELDS.map((sec, si) => (
            <div key={si}>
              <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{sec.section[lang] || sec.section.fr}</h2>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                <tbody>
                  {sec.items.map((item) => (
                    <tr key={item.key} style={{ borderBottom: "1px solid #ddd" }}>
                      <td style={{ padding: "6px 10px 6px 0", verticalAlign: "top", width: "45%", fontWeight: 700 }}>{item.q[lang] || item.q.fr}</td>
                      <td style={{ padding: "6px 0", verticalAlign: "top" }}>
                        {item.type === "pills"
                          ? (answers[item.key] ? pillLabelFor(item, answers[item.key]) : L.noAnswer)
                          : (answers[item.key] && answers[item.key].trim() ? answers[item.key] : L.noAnswer)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ))}
          <p style={{ fontSize: 10, color: "#888", marginTop: 24, lineHeight: 1.5 }}>{L.disclaimer}</p>
        </div>,
        document.body
      )}
    </Card>
  );
}

