// Illustration originale (créée par Claude, pas une photo) d'un bébé recroquevillé, en 10 étapes
// de développement (une par tranche de 4 semaines) — style illustré doux et arrondi, construit
// uniquement à partir de cercles/ellipses pour rester lisse et mignon à chaque étape.
const FETUS_RING = "#FDEDE3";
const FETUS_WOMB_1 = "#F6C9D2";
const FETUS_WOMB_2 = "#E9A3B7";
const FETUS_SKIN_HI = "#FFF9F2";
const FETUS_SKIN = "#FCE3CB";
const FETUS_SKIN_SHADE = "#F6C89C";
const FETUS_CORD = "#E9AFC0";
const FETUS_LINE = "#C98A6E";

function fetusStageMarkup(stageNum, id) {
  const i = Math.max(0, Math.min(9, stageNum));
  const t = i / 9;
  let svg = "";
  if (i === 0) {
    svg = `
      <circle cx="50" cy="52" r="10" fill="url(#${id}-skin)"/>
      <circle cx="50" cy="52" r="10" fill="none" stroke="${FETUS_SKIN_HI}" stroke-width="1.2" opacity="0.7"/>
    `;
    return svg;
  }
  const headR = 12 + t * 7 - (i >= 6 ? (i - 5) * 0.6 : 0);
  const headCx = 46 + t * 4;
  const headCy = 38 - t * 4;
  const bodyRx = 10 + t * 11;
  const bodyRy = 13 + t * 13;
  const bodyCx = headCx + 2 + t * 5;
  const bodyCy = headCy + headR + bodyRy * 0.72;
  const legR = 5 + t * 6.5;
  const legCx = bodyCx - bodyRx * 0.35;
  const legCy = bodyCy + bodyRy * 0.55;
  const armRx = 4 + t * 3.4;
  const armRy = 3 + t * 2.6;

  if (i === 1) {
    svg += `<path d="M${bodyCx - bodyRx * 0.2} ${bodyCy + bodyRy * 0.7} q -8 6 -3 14" stroke="url(#${id}-shade)" stroke-width="5" fill="none" stroke-linecap="round"/>`;
  }
  svg += `<ellipse cx="${bodyCx}" cy="${bodyCy}" rx="${bodyRx}" ry="${bodyRy}" fill="url(#${id}-skin)" transform="rotate(18 ${bodyCx} ${bodyCy})"/>`;
  if (i >= 2) {
    svg += `<circle cx="${legCx}" cy="${legCy}" r="${legR}" fill="url(#${id}-shade)"/>`;
  }
  if (i >= 3) {
    const armCx = headCx - headR * 0.55;
    const armCy = headCy + headR * 0.75;
    svg += `<ellipse cx="${armCx}" cy="${armCy}" rx="${armRx}" ry="${armRy}" fill="url(#${id}-shade)" transform="rotate(-35 ${armCx} ${armCy})"/>`;
  }
  if (i >= 4) {
    svg += `<path d="M${bodyCx + bodyRx * 0.6} ${bodyCy - bodyRy * 0.1} q 14 -4 20 6" stroke="${FETUS_CORD}" stroke-width="2.4" fill="none" stroke-linecap="round"/>`;
  }
  svg += `<circle cx="${headCx}" cy="${headCy}" r="${headR}" fill="url(#${id}-skin)"/>`;
  if (i >= 4) {
    svg += `<circle cx="${headCx + headR * 0.82}" cy="${headCy + headR * 0.15}" r="${headR * 0.22}" fill="url(#${id}-shade)"/>`;
  }
  if (i >= 5) {
    const ex = headCx + headR * 0.12;
    const ey = headCy + headR * 0.12;
    svg += `<path d="M${ex - headR * 0.22} ${ey} q ${headR * 0.22} ${headR * 0.16} ${headR * 0.44} 0" stroke="${FETUS_LINE}" stroke-width="1.3" fill="none" stroke-linecap="round" opacity="0.55"/>`;
    const tx = headCx - headR * 0.55;
    const ty = headCy + headR * 0.55;
    svg += `<circle cx="${tx}" cy="${ty}" r="${2.4 + t * 1.2}" fill="url(#${id}-shade)"/>`;
  }
  if (i === 9) {
    svg += `<circle cx="${bodyCx + bodyRx + 10}" cy="${bodyCy - bodyRy * 0.6}" r="9" fill="${FETUS_WOMB_1}" opacity="0.6"/>`;
    svg += `<path d="M${bodyCx + bodyRx * 0.6} ${bodyCy - bodyRy * 0.1} q 16 -8 ${bodyCx + bodyRx + 4} ${bodyCy - bodyRy * 0.5}" stroke="${FETUS_CORD}" stroke-width="2" fill="none" stroke-linecap="round"/>`;
  }
  return svg;
}

function FetusStageIllustration({ stage, size = 40 }) {
  const id = "fetus";
  const inner = fetusStageMarkup(stage, id);
  const svgMarkup = `
    <svg viewBox="0 0 100 100" width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <radialGradient id="${id}-womb" cx="34%" cy="28%" r="78%">
          <stop offset="0%" stop-color="${FETUS_WOMB_1}"/>
          <stop offset="100%" stop-color="${FETUS_WOMB_2}"/>
        </radialGradient>
        <radialGradient id="${id}-skin" cx="30%" cy="20%" r="90%">
          <stop offset="0%" stop-color="${FETUS_SKIN_HI}"/>
          <stop offset="100%" stop-color="${FETUS_SKIN}"/>
        </radialGradient>
        <radialGradient id="${id}-shade" cx="30%" cy="20%" r="90%">
          <stop offset="0%" stop-color="${FETUS_SKIN}"/>
          <stop offset="100%" stop-color="${FETUS_SKIN_SHADE}"/>
        </radialGradient>
      </defs>
      <circle cx="50" cy="50" r="47" fill="${FETUS_RING}"/>
      <circle cx="50" cy="51" r="39" fill="url(#${id}-womb)"/>
      <g>${inner}</g>
    </svg>`;
  return <span style={{ display: "inline-flex", lineHeight: 0 }} dangerouslySetInnerHTML={{ __html: svgMarkup }} />;
}


// 10 étapes de 4 semaines chacune (1-4, 5-8, ..., 37-40), réparties dans les 3 trimestres — un
// petit tableau explicatif plus court est affiché dans chaque onglet de trimestre plutôt qu'un seul
// grand tableau de 40 lignes.
// Les descriptions décrivent ce qui se voit réellement dans chaque illustration (taille, forme,
// membres visibles, placenta...) plutôt que des faits génériques déconnectés de l'image, pour que le
// texte et la photo se correspondent bien à chaque étape.
const FETUS_STAGE_GROUPS = [
  { from: 1, to: 4, trimester: 1, fr: "Tout début : un tout petit amas de cellules vient de s'implanter dans l'utérus — trop petit pour être vu autrement qu'en très gros plan.", es: "Todo comienza: un pequeño grupo de células acaba de implantarse en el útero — demasiado pequeño para verse salvo de muy cerca.", en: "Very beginning: a tiny cluster of cells has just implanted in the uterus — too small to see except in extreme close-up." },
  { from: 5, to: 8, trimester: 1, fr: "L'embryon prend la forme d'une petite virgule recourbée, relié par le cordon — le cœur vient tout juste de commencer à battre.", es: "El embrión toma la forma de una pequeña coma curva, conectado por el cordón — el corazón acaba de comenzar a latir.", en: "The embryo takes the shape of a small curved comma, connected by the cord — the heart has just started beating." },
  { from: 9, to: 12, trimester: 1, fr: "La tête est encore proportionnellement grande et le corps se recourbe — les tout premiers mouvements commencent, même si vous ne les sentez pas encore.", es: "La cabeza sigue siendo proporcionalmente grande y el cuerpo se curva — comienzan los primeros movimientos, aunque todavía no los sientas.", en: "The head is still proportionally large and the body curls inward — the very first movements begin, even though you can't feel them yet." },
  { from: 13, to: 16, trimester: 2, fr: "Le petit corps continue de s'allonger et de se préciser à l'intérieur de l'utérus.", es: "El pequeño cuerpo sigue alargándose y definiéndose dentro del útero.", en: "The little body keeps lengthening and becoming more defined inside the uterus." },
  { from: 17, to: 20, trimester: 2, fr: "On distingue maintenant clairement les bras et les jambes — c'est souvent vers cette période que vous pourriez sentir les premiers mouvements.", es: "Ahora se distinguen claramente los brazos y las piernas — a menudo es en este período cuando podrías sentir los primeros movimientos.", en: "The arms and legs are now clearly visible — this is often around when you might start feeling the first movements." },
  { from: 21, to: 24, trimester: 2, fr: "Bébé est bien recroquevillé et commence déjà à porter le pouce près de la bouche — un réflexe de succion qui se met en place.", es: "El bebé está bien acurrucado y ya empieza a llevarse el pulgar cerca de la boca — un reflejo de succión que se está formando.", en: "Baby is snugly curled up and already starts bringing a thumb near the mouth — a sucking reflex taking shape." },
  { from: 25, to: 28, trimester: 2, fr: "Le corps devient plus potelé et les petits traits du visage commencent à se préciser.", es: "El cuerpo se vuelve más rechoncho y los pequeños rasgos del rostro empiezan a definirse.", en: "The body becomes plumper and the little facial features start to take shape." },
  { from: 29, to: 32, trimester: 3, fr: "Bébé est bien recroquevillé dans un espace qui devient plus restreint, et continue de prendre du poids.", es: "El bebé está bien acurrucado en un espacio más reducido, y sigue ganando peso.", en: "Baby is snugly curled up in the more limited space, and keeps gaining weight." },
  { from: 33, to: 36, trimester: 3, fr: "Bébé remplit maintenant beaucoup plus d'espace et commence à se positionner pour la naissance.", es: "El bebé ahora ocupa mucho más espacio y comienza a posicionarse para el nacimiento.", en: "Baby now fills much more space and starts positioning for birth." },
  { from: 37, to: 40, trimester: 3, fr: "Le placenta et le cordon sont bien visibles autour de bébé, qui est maintenant considéré à terme et prêt à vous rencontrer.", es: "La placenta y el cordón son claramente visibles alrededor del bebé, que ahora se considera a término y listo para conocerte.", en: "The placenta and cord are clearly visible around baby, who is now considered full term and ready to meet you." },
];

// Refait sous forme de vrai tableau (comme celui des fruits de la grossesse) plutôt qu'une simple
// liste de blocs empilés — plus élégant et plus cohérent visuellement avec le reste de l'appli.
function TrimesterFetusTable({ lang, trimester }) {
  const L = lang === "fr"
    ? { title: "Ce qui se passe ce trimestre", subtitle: "Un aperçu rapide du développement de bébé.", weeks: "Semaines", dev: "Développement" }
    : lang === "es"
    ? { title: "Lo que sucede este trimestre", subtitle: "Un vistazo rápido al desarrollo del bebé.", weeks: "Semanas", dev: "Desarrollo" }
    : { title: "What's happening this trimester", subtitle: "A quick look at baby's development.", weeks: "Weeks", dev: "Development" };

  const palette = [COLORS.pink, COLORS.ochre, COLORS.sage, COLORS.blue];
  const rows = FETUS_STAGE_GROUPS
    .map((g, i) => ({ ...g, stageIndex: i }))
    .filter((g) => g.trimester === trimester);

  return (
    <Card style={{ marginBottom: 18, borderTop: `4px solid ${COLORS.blue}`, background: "#FDFEFF" }}>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, fontWeight: 700, color: COLORS.teal }}>{L.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12.5, color: COLORS.muted }}>{L.subtitle}</p>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ textAlign: "left", padding: "6px 8px", fontSize: 10.5, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>{L.weeks}</th>
            <th style={{ textAlign: "center", padding: "6px 8px", fontSize: 10.5, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}></th>
            <th style={{ textAlign: "left", padding: "6px 8px", fontSize: 10.5, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.03em" }}>{L.dev}</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => {
            const c = palette[i % palette.length];
            return (
              <tr key={row.from} style={{ background: i % 2 ? `${c}14` : "transparent" }}>
                <td style={{ padding: "10px 8px", borderRadius: "10px 0 0 10px", verticalAlign: "top" }}>
                  <span style={{
                    display: "inline-flex", alignItems: "center", justifyContent: "center",
                    minWidth: 30, height: 24, borderRadius: 8, background: c, color: "#fff",
                    fontSize: 11.5, fontWeight: 800, padding: "0 8px", whiteSpace: "nowrap",
                  }}>{row.from}-{row.to}</span>
                </td>
                <td style={{ padding: "10px 4px", verticalAlign: "top" }}>
                  <div style={{
                    width: 42, height: 42, borderRadius: 12, flexShrink: 0, background: "#fff",
                    boxShadow: "0 2px 6px rgba(91,58,36,0.1)", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden",
                  }}>
                    <FetusStageIllustration stage={row.stageIndex} size={34} />
                  </div>
                </td>
                <td style={{ padding: "10px 8px 10px 4px", borderRadius: "0 10px 10px 0", fontSize: 12.5, color: COLORS.text, lineHeight: 1.4 }}>
                  {row[lang] || row.fr}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </Card>
  );
}

// Court texte selon le trimestre — partagé entre la bulle d'accueil ("Bonjour, ...") et la bulle
// de profil ("Félicitations...") pour que les deux bulles personnalisées soient cohérentes.
const TRIMESTER_SUMMARY = {
  1: {
    fr: "Le premier trimestre est marqué par les grands changements hormonaux : fatigue, nausées possibles, seins sensibles — pendant que les organes essentiels de bébé se forment.",
    en: "The first trimester brings big hormonal shifts: fatigue, possible nausea, tender breasts — while baby's essential organs are forming.",
    es: "El primer trimestre trae grandes cambios hormonales: fatiga, posibles náuseas, senos sensibles — mientras se forman los órganos esenciales del bebé.",
  },
  2: {
    fr: "Le deuxième trimestre est souvent le plus confortable : l'énergie revient, le ventre s'arrondit, et vous sentirez bientôt (ou déjà) les premiers mouvements de bébé.",
    en: "The second trimester is often the most comfortable: energy returns, the belly rounds out, and you'll soon feel (or already are feeling) baby's first movements.",
    es: "El segundo trimestre suele ser el más cómodo: la energía regresa, el vientre se redondea, y pronto sentirás (o ya sientes) los primeros movimientos del bebé.",
  },
  3: {
    fr: "Le troisième trimestre est la dernière ligne droite : bébé prend du poids rapidement et se prépare à la naissance — bon moment pour préparer votre valise de maternité.",
    en: "The third trimester is the home stretch: baby is gaining weight quickly and getting ready for birth — a good time to pack your hospital bag.",
    es: "El tercer trimestre es la recta final: el bebé aumenta de peso rápidamente y se prepara para nacer — buen momento para preparar tu maleta de maternidad.",
  },
};

// Petit badge réutilisable "bébé a la taille de..." avec illustration + poids, affiché dans la
// bulle d'accueil (statut membre), la bulle de profil (visible même en statut non-membre) et le
// résumé de grossesse — toujours basé sur la même donnée (PREGNANCY_WEEKS) pour rester cohérent.
// Émoji réels (pas nos illustrations vectorielles) pour chaque fruit/légume de comparaison —
// demandé explicitement pour que ça ressemble à une vraie photo de fruit plutôt qu'à un dessin.
const PREGNANCY_FRUIT_EMOJI = {
  // Aucun emoji Unicode "graine de pavot" / "prune" n'existe — on utilise le meilleur équivalent
  // visuel réel qui reste un VRAI emoji illustré (pas un rond de couleur uni) : le texte de
  // comparaison à la semaine 8 a été changé pour « une fraise » afin de pouvoir utiliser le vrai
  // emoji fraise (🍓) plutôt qu'une cerise; pour la prune (semaine 12), le bleuet (🫐) est le fruit
  // réel le plus proche visuellement (petit, rond, violet) — aucun emoji « prune » n'existe encore
  // dans le standard Unicode. La graine de pavot reste un petit rond brun, affiché en plus petit
  // (voir PREGNANCY_FRUIT_EMOJI_SCALE), aucun emoji réel n'existant à cette échelle.
  poppySeed: "🟤", raspberryFruit: "🍓", plumFruit: "🫐", avocado: "🥑", bananaFruit: "🍌",
  cornCob: "🌽", eggplantFruit: "🍆", coconutFruit: "🥥", lettuceLeaf: "🥬", watermelonFruit: "🍉",
};
// Certains émoji de remplacement (voir ci-dessus) doivent être affichés plus petits que les
// autres pour rester visuellement fidèles à ce qu'ils représentent (une graine de pavot est
// minuscule, pas de la taille d'une bille).
const PREGNANCY_FRUIT_EMOJI_SCALE = { poppySeed: 0.42 };

function PregnancyFruitBadge({ weeks, lang, tone = "light", size = "normal" }) {
  const match = getClosestPregnancyWeek(weeks);
  if (!match) return null;
  const L = lang === "fr" ? { compareTo: "Bébé a à peu près la taille de", and: "et" } : lang === "es" ? { compareTo: "Tu bebé es aproximadamente del tamaño de", and: "y" } : { compareTo: "Baby is about the size of", and: "and" };
  const light = tone === "light";
  const big = size === "large";
  const emoji = PREGNANCY_FRUIT_EMOJI[match.icon] || "🌱";
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: big ? 18 : 14,
      background: light ? `linear-gradient(135deg, ${COLORS.pink}12 0%, ${COLORS.cream} 60%, ${COLORS.ochre}10 100%)` : "rgba(255,255,255,0.16)",
      border: light ? `1px solid ${COLORS.pink}22` : "none",
      borderRadius: big ? 20 : 18, padding: big ? "16px 20px" : "12px 16px",
    }}>
      <span style={{ fontSize: (big ? 56 : 40) * (PREGNANCY_FRUIT_EMOJI_SCALE[match.icon] || 1), lineHeight: 1, flexShrink: 0 }}>{emoji}</span>
      <div style={{ minWidth: 0 }}>
        <p style={{ margin: 0, fontSize: big ? 12.5 : 11.5, fontWeight: 600, color: light ? COLORS.muted : "#fff", opacity: light ? 1 : 0.9, fontStyle: "italic" }}>{L.compareTo}</p>
        <p style={{ margin: "1px 0 3px", fontSize: big ? 18 : 15.5, fontWeight: 700, color: light ? COLORS.teal : "#fff", fontFamily: "Fraunces, Georgia, serif" }}>{match.compare[lang]}</p>
        <p style={{ margin: 0, fontSize: big ? 13.5 : 12, fontWeight: 600, color: light ? COLORS.ochre : "#fff", opacity: light ? 1 : 0.95 }}>
          {match.length[lang]} · {match.weight[lang]}
        </p>
      </div>
    </div>
  );
}

// Ligne du temps discrète et féminine : un simple trait fin en dégradé blush→doré avec un petit
// point qui avance semaine après semaine, sans gros badges ni pictogramme — juste assez pour
// donner envie de revenir voir le repère progresser, sans alourdir la bulle personnalisée.
function PregnancyTimeline({ weeks, days, daysRemaining, lang, tone = "light" }) {
  const TOTAL_WEEKS = 40;
  const preciseWeeks = weeks + (days || 0) / 7;
  const pct = Math.max(1.5, Math.min(100, (preciseWeeks / TOTAL_WEEKS) * 100));
  const weeksRemaining = Math.floor((daysRemaining || 0) / 7);
  const extraDays = (daysRemaining || 0) % 7;
  const light = tone === "light";

  const L = lang === "fr"
    ? {
        remaining: () => weeksRemaining > 0
          ? `encore ${weeksRemaining} semaine${weeksRemaining > 1 ? "s" : ""}${extraDays > 0 ? ` et ${extraDays} j.` : ""}`
          : `encore ${extraDays} jour${extraDays > 1 ? "s" : ""}`,
      }
    : lang === "es"
    ? {
        remaining: () => weeksRemaining > 0
          ? `quedan ${weeksRemaining} semana${weeksRemaining > 1 ? "s" : ""}${extraDays > 0 ? ` y ${extraDays} d.` : ""}`
          : `quedan ${extraDays} día${extraDays > 1 ? "s" : ""}`,
      }
    : {
        remaining: () => weeksRemaining > 0
          ? `${weeksRemaining} week${weeksRemaining > 1 ? "s" : ""}${extraDays > 0 ? ` ${extraDays}d` : ""} to go`
          : `${extraDays} day${extraDays > 1 ? "s" : ""} to go`,
      };

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
      <div style={{ position: "relative", flex: 1, height: 4, borderRadius: 999, background: light ? `${COLORS.pink}20` : "rgba(255,255,255,0.25)" }}>
        <div style={{
          position: "absolute", left: 0, top: 0, bottom: 0, borderRadius: 999, width: `${pct}%`,
          background: `linear-gradient(90deg, ${COLORS.pink}90 0%, ${COLORS.ochre}90 100%)`,
          transition: "width 0.5s ease",
        }} />
        <div style={{
          position: "absolute", left: `${pct}%`, top: "50%", transform: "translate(-50%, -50%)",
          width: 8, height: 8, borderRadius: "50%", background: light ? COLORS.pink : "#fff",
          border: `1.5px solid ${light ? "#fff" : COLORS.pink}`, boxShadow: "0 1px 3px rgba(91,58,36,0.25)",
        }} />
      </div>
      <span style={{
        fontSize: 11, fontStyle: "italic", fontWeight: 600, whiteSpace: "nowrap",
        color: light ? COLORS.muted : "#fff", opacity: light ? 1 : 0.85, fontFamily: "Fraunces, Georgia, serif",
      }}>
        {L.remaining()}
      </span>
    </div>
  );
}

/* ---------------- DAILY TRACKER (feeding, sleep, diaper, kicks, contractions) ---------------- */
function formatDuration(ms, lang) {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}
function formatClock(date, lang) {
  return date.toLocaleTimeString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { hour: "2-digit", minute: "2-digit" });
}

// Les outils qui gardent des données dans le navigateur (localStorage) plutôt que dans Supabase
// (questions au médecin, plan de naissance, album bedaine, etc.) doivent inclure l'identifiant du
// compte connecté dans la clé — sinon, sur le même appareil/navigateur, un nouveau compte verrait
// les données laissées par un compte précédent. "guest" est utilisé quand personne n'est connecté.
function mmbScopedKey(base, session) {
  const uid = session?.user?.id || "guest";
  return `${base}__u${uid}`;
}

/* ---------------- REGROUPEMENT GÉNÉRIQUE PAR DATE (jour → mois → année) ----------------
   Utilisé partout où on affiche une liste d'éléments datés (trackers, cycle, journal,
   documents, rendez-vous) pour éviter d'avoir une liste interminable au fil des mois/années :
   - Le mois en cours reste affiché à plat, par jour (comme avant).
   - Un mois déjà passé (mais dans l'année en cours) se replie sous un en-tête de mois — on clique
     dessus pour voir ses dates, puis sur une date pour voir ses éléments.
   - Une année déjà passée se replie sous un en-tête d'année — on clique dessus pour voir ses mois,
     puis un mois pour voir ses dates, puis une date pour voir ses éléments.
   Tout est replié par défaut; seul l'ajout d'un nouvel élément pendant l'utilisation en cours
   ouvre automatiquement la chaîne (année/mois/date) qui le contient, pour qu'on le voie tout de
   suite sans avoir à cliquer. */
function DateGroupedList({ items, getDate, getId, renderItem, renderDateAdd, emptyLabel, countLabel, loaded = true, lang }) {
  const dateKey = (d) => d.toISOString().slice(0, 10);
  const monthKey = (d) => d.toISOString().slice(0, 7); // "AAAA-MM"
  const yearKey = (d) => String(d.getFullYear());
  const now = new Date();
  const currentMonthKey = monthKey(now);
  const currentYearKey = yearKey(now);

  const [openDates, setOpenDates] = useState(() => new Set());
  const [openMonths, setOpenMonths] = useState(() => new Set());
  const [openYears, setOpenYears] = useState(() => new Set());
  const toggleIn = (setFn) => (key) => setFn((s) => {
    const next = new Set(s);
    if (next.has(key)) next.delete(key); else next.add(key);
    return next;
  });
  const toggleDate = toggleIn(setOpenDates);
  const toggleMonth = toggleIn(setOpenMonths);
  const toggleYear = toggleIn(setOpenYears);

  // Ouvre automatiquement la date (et son mois/année s'ils sont repliés) d'un élément qui vient
  // d'être ajouté pendant cette utilisation de l'outil — jamais au chargement initial de
  // l'historique. Comme ce chargement (Supabase) est asynchrone, la liste démarre toujours vide
  // puis se remplit un instant après le montage : on attend que `loaded` devienne vrai avant de
  // commencer à comparer, sinon ce remplissage serait pris à tort pour un ajout en direct.
  const prevItemsRef = useRef(null);
  const baselineSetRef = useRef(false);
  useEffect(() => {
    if (!loaded) return;
    if (!baselineSetRef.current) {
      baselineSetRef.current = true;
      prevItemsRef.current = items;
      return;
    }
    const prev = prevItemsRef.current;
    if (items.length > prev.length) {
      const prevIds = new Set(prev.map((it) => getId(it)));
      const added = items.filter((it) => !prevIds.has(getId(it)));
      if (added.length > 0) {
        setOpenDates((s) => { const next = new Set(s); added.forEach((it) => next.add(dateKey(getDate(it)))); return next; });
        setOpenMonths((s) => { const next = new Set(s); added.forEach((it) => next.add(monthKey(getDate(it)))); return next; });
        setOpenYears((s) => { const next = new Set(s); added.forEach((it) => next.add(yearKey(getDate(it)))); return next; });
      }
    }
    prevItemsRef.current = items;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, loaded]);

  if (items.length === 0) return (
    <div style={{
      textAlign: "center", padding: "16px 12px", marginTop: 14, borderRadius: 12,
      border: `1px dashed ${COLORS.line}`, background: COLORS.cream,
    }}>
      <p style={{ fontSize: 12.5, color: COLORS.muted, fontStyle: "italic", margin: 0 }}>{emptyLabel}</p>
    </div>
  );

  const todayLabel = lang === "fr" ? "Aujourd'hui" : lang === "es" ? "Hoy" : "Today";
  const yesterdayLabel = lang === "fr" ? "Hier" : lang === "es" ? "Ayer" : "Yesterday";
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";
  const todayKeyStr = dateKey(now);
  const yesterdayKeyStr = dateKey(new Date(Date.now() - 86400000));
  const dateHeading = (d) => {
    const key = dateKey(d);
    if (key === todayKeyStr) return todayLabel;
    if (key === yesterdayKeyStr) return yesterdayLabel;
    return d.toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  };
  const monthHeading = (d) => d.toLocaleDateString(locale, { month: "long", year: "numeric" });

  const headerRowStyle = {
    width: "100%", display: "flex", justifyContent: "space-between", alignItems: "center",
    background: "none", border: "none", cursor: "pointer", padding: "6px 2px",
    borderBottom: `1px solid ${COLORS.line}`, textAlign: "left",
  };
  const chevron = (isOpen) => (
    <ChevronRight size={15} style={{ transform: isOpen ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.15s" }} />
  );

  // Regroupe d'abord par jour civil, du plus récent au plus ancien.
  const sorted = items.slice().sort((a, b) => (getDate(b) || 0) - (getDate(a) || 0));
  const dateGroups = [];
  for (const it of sorted) {
    const d = getDate(it) || new Date();
    const key = dateKey(d);
    let g = dateGroups.find((g) => g.key === key);
    if (!g) g = { key, date: d, items: [] }, dateGroups.push(g);
    g.items.push(it);
  }

  const renderDateGroup = (g) => {
    const isOpen = openDates.has(g.key);
    return (
      <div key={g.key} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleDate(g.key)} style={headerRowStyle}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: COLORS.text, textTransform: "uppercase", letterSpacing: 0.3 }}>
            {dateHeading(g.date)}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(g.items.length)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 8 }}>
            {g.items.map((it) => renderItem(it))}
            {/* L'ajout rétroactif ne s'affiche que pour les jours passés — pour aujourd'hui, le
                formulaire principal en haut de l'outil sert déjà à ça, et l'afficher deux fois
                (une fois en haut, une fois ici) créait un doublon visuel confus. */}
            {renderDateAdd && g.key !== todayKeyStr && renderDateAdd(g.date)}
          </div>
        )}
      </div>
    );
  };

  // Sépare : mois en cours (affiché à plat par date) / mois passés de l'année en cours (repliés par
  // mois) / années passées (repliées par année, puis par mois à l'intérieur).
  const currentMonthGroups = [];
  const monthBuckets = new Map(); // monthKey -> { date, groups: [dateGroup] } — pour les mois passés de l'année en cours
  const yearBuckets = new Map();  // yearKey -> Map(monthKey -> { date, groups }) — pour les années passées

  for (const g of dateGroups) {
    const mKey = monthKey(g.date);
    const yKey = yearKey(g.date);
    if (mKey === currentMonthKey) {
      currentMonthGroups.push(g);
    } else if (yKey === currentYearKey) {
      if (!monthBuckets.has(mKey)) monthBuckets.set(mKey, { date: g.date, groups: [] });
      monthBuckets.get(mKey).groups.push(g);
    } else {
      if (!yearBuckets.has(yKey)) yearBuckets.set(yKey, new Map());
      const yearMonths = yearBuckets.get(yKey);
      if (!yearMonths.has(mKey)) yearMonths.set(mKey, { date: g.date, groups: [] });
      yearMonths.get(mKey).groups.push(g);
    }
  }

  const renderMonthBucket = (mKey, bucket) => {
    const isOpen = openMonths.has(mKey);
    const total = bucket.groups.reduce((n, g) => n + g.items.length, 0);
    return (
      <div key={mKey} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleMonth(mKey)} style={headerRowStyle}>
          <span style={{ fontSize: 12.5, fontWeight: 800, color: COLORS.text, textTransform: "capitalize", letterSpacing: 0.3 }}>
            {monthHeading(bucket.date)}
          </span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(total)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ marginTop: 8, paddingLeft: 10 }}>
            {bucket.groups.map((g) => renderDateGroup(g))}
          </div>
        )}
      </div>
    );
  };

  const renderYearBucket = (yKey, yearMonths) => {
    const isOpen = openYears.has(yKey);
    const monthEntries = Array.from(yearMonths.entries()).sort((a, b) => b[0].localeCompare(a[0]));
    const total = monthEntries.reduce((n, [, bucket]) => n + bucket.groups.reduce((m, g) => m + g.items.length, 0), 0);
    return (
      <div key={yKey} style={{ marginBottom: 8 }}>
        <button onClick={() => toggleYear(yKey)} style={headerRowStyle}>
          <span style={{ fontSize: 13, fontWeight: 800, color: COLORS.text, letterSpacing: 0.3 }}>{yKey}</span>
          <span style={{ display: "flex", alignItems: "center", gap: 6, color: COLORS.muted, fontSize: 12 }}>
            {countLabel(total)}
            {chevron(isOpen)}
          </span>
        </button>
        {isOpen && (
          <div style={{ marginTop: 8, paddingLeft: 10 }}>
            {monthEntries.map(([mKey, bucket]) => renderMonthBucket(mKey, bucket))}
          </div>
        )}
      </div>
    );
  };

  const sortedMonthKeys = Array.from(monthBuckets.keys()).sort((a, b) => b.localeCompare(a));
  const sortedYearKeys = Array.from(yearBuckets.keys()).sort((a, b) => b.localeCompare(a));

  return (
    <div style={{ marginTop: 14 }}>
      {currentMonthGroups.map((g) => renderDateGroup(g))}
      {sortedMonthKeys.map((mKey) => renderMonthBucket(mKey, monthBuckets.get(mKey)))}
      {sortedYearKeys.map((yKey) => renderYearBucket(yKey, yearBuckets.get(yKey)))}
    </div>
  );
}

// Bouton + document imprimable/PDF générique pour n'importe quel tracker (une seule page qui
// s'allonge, triée du plus ancien au plus récent). `printId` doit être unique par outil monté à
// l'écran (même mécanisme que les autres exports PDF de l'appli : BirthPlanTool, BumpAlbumTool,
// PregnancyQuestionsQuickTool) pour que deux portails imprimables ne se marchent pas dessus.
function TrackerPdfExport({ lang, printId, title, entries }) {
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";
  const L = lang === "fr"
    ? { btn: "📄 Télécharger en PDF", hint: "Sur mobile, choisissez « Enregistrer en PDF » comme imprimante — le document peut ensuite être partagé ou imprimé comme n'importe quel PDF.", generatedOn: "Généré le" }
    : lang === "es"
    ? { btn: "📄 Descargar en PDF", hint: "En el celular, elige «Guardar como PDF» como impresora — el documento se puede compartir o imprimir como cualquier PDF.", generatedOn: "Generado el" }
    : { btn: "📄 Download as PDF", hint: "On mobile, choose \"Save as PDF\" as the printer — the document can then be shared or printed like any PDF.", generatedOn: "Generated on" };
  if (!entries || entries.length === 0) return null;
  const sorted = [...entries].sort((a, b) => (a.date || 0) - (b.date || 0));
  const printedOn = new Date().toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" });
  return (
    <>
      <button onClick={() => window.print()} style={{
        width: "100%", padding: "13px", borderRadius: 12, border: "none", background: COLORS.teal,
        color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer", marginTop: 14,
      }}>{L.btn}</button>
      <p style={{ fontSize: 11, color: COLORS.muted, textAlign: "center", marginTop: 8 }}>{L.hint}</p>
      <style>{`
        @page { size: letter; margin: 0.5in; }
        @media print {
          html, body { margin: 0 !important; padding: 0 !important; }
          body > *:not(#${printId}) { display: none !important; }
          #${printId} { display: block !important; position: absolute; top: 0; left: 0; }
        }
        @media screen { #${printId} { display: none; } }
      `}</style>
      {createPortal(
        <div id={printId} style={{ width: "7.5in", padding: "0.3in", fontFamily: "Georgia, serif", color: "#222" }}>
          <h1 style={{ fontSize: 20, margin: "0 0 4px" }}>{title}</h1>
          <p style={{ fontSize: 11, color: "#666", margin: "0 0 14px" }}>{L.generatedOn} {printedOn}</p>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
            <tbody>
              {sorted.map((e, i) => (
                <tr key={i} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ padding: "5px 6px 5px 0", whiteSpace: "nowrap", verticalAlign: "top" }}>
                    {(e.date || new Date()).toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" })}
                  </td>
                  <td style={{ padding: "5px 6px 5px 0", fontWeight: 700, whiteSpace: "nowrap", verticalAlign: "top" }}>{e.label}</td>
                  <td style={{ padding: "5px 0", color: "#555", verticalAlign: "top" }}>{e.detail}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>,
        document.body
      )}
    </>
  );
}

function TrackerLogList({ entries, emptyLabel, onDelete, renderDateAdd, loaded, lang }) {
  const entryWord = lang === "fr" ? "entrée" : lang === "es" ? "entrada" : "entry";
  const entriesWord = lang === "fr" ? "entrées" : lang === "es" ? "entradas" : "entries";
  return (
    <DateGroupedList
      items={entries}
      getDate={(e) => e.createdAt || new Date()}
      getId={(e) => e.id}
      emptyLabel={emptyLabel}
      countLabel={(n) => `${n} ${n > 1 ? entriesWord : entryWord}`}
      loaded={loaded}
      lang={lang}
      renderDateAdd={renderDateAdd}
      renderItem={(e) => (
        <div key={e.id} style={{
          display: "flex", justifyContent: "space-between", alignItems: "center",
          background: COLORS.cream, borderRadius: 10, padding: "9px 13px", fontSize: 13, gap: 8,
        }}>
          <span style={{ color: COLORS.text, fontWeight: 600 }}>{e.label}</span>
          <span style={{ color: COLORS.muted, flex: 1, textAlign: "right" }}>{e.detail}</span>
          {onDelete && (
            <button
              onClick={() => onDelete(e.id)}
              aria-label={lang === "fr" ? "Supprimer" : lang === "es" ? "Eliminar" : "Delete"}
              style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.muted, padding: 2, display: "flex", flexShrink: 0 }}
            >
              <X size={15} />
            </button>
          )}
        </div>
      )}
    />
  );
}

function FeedingTracker({ lang, session, children: kids, isReadOnlyPartner }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [trackSession, setTrackSession] = useState(null); // { side, start }
  const [log, setLog] = useState([]);
  const [selectedChildId, setSelectedChildId] = useState(kids?.[0]?.id ?? null);
  const forChildLabel = lang === "fr" ? "Pour :" : lang === "es" ? "Para:" : "For:";
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr"
    ? {
        left: "Sein gauche", right: "Sein droit", bottle: "Biberon", pump: "Tire-lait", stop: "Arrêter", inProgress: "En cours",
        qtyPh: "Quantité", ml: "ml", oz: "oz", save: "Enregistrer", cancel: "Annuler",
        todayTotal: (v, u) => `Aujourd'hui : ${v} ${u} au total (biberon + tire-lait)`,
      }
    : lang === "es"
    ? {
        left: "Seno izquierdo", right: "Seno derecho", bottle: "Biberón", pump: "Extractor de leche", stop: "Detener", inProgress: "En curso",
        qtyPh: "Cantidad", ml: "ml", oz: "oz", save: "Guardar", cancel: "Cancelar",
        todayTotal: (v, u) => `Hoy: ${v} ${u} en total (biberón + extractor)`,
      }
    : {
        left: "Left breast", right: "Right breast", bottle: "Bottle", pump: "Pumping", stop: "Stop", inProgress: "In progress",
        qtyPh: "Quantity", ml: "ml", oz: "oz", save: "Save", cancel: "Cancel",
        todayTotal: (v, u) => `Today: ${v} ${u} total (bottle + pumping)`,
      };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "feeding", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const persist = (type, entry, tempId) => persistTrackerEntry(type, entry, session, setLog, tempId);

  const start = (side) => setTrackSession({ side, start: new Date() });
  const stop = () => {
    if (!trackSession) return;
    const durationMs = new Date() - trackSession.start;
    const entry = { label: trackSession.side, detail: encodeChildTag(`${formatClock(trackSession.start, lang)} · ${formatDuration(durationMs, lang)}`, selectedChildId) };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setTrackSession(null);
  };
  // Quantité (ml/oz) au biberon et au tire-lait — encodée directement dans le texte du "detail"
  // (ex. "14:32 · 120 ml"), comme le poids de grossesse, plutôt que d'ajouter une colonne structurée
  // dans la table générique tracker_entries. Un total du jour est calculé en reparsant ce texte.
  const [qtyUnit, setQtyUnit] = useState(lang === "en" ? "oz" : "ml");
  const mlPerOz = 29.5735;
  const [bottlePending, setBottlePending] = useState(false);
  const [bottleQty, setBottleQty] = useState("");
  const logBottle = () => {
    const qty = Number(bottleQty);
    const detail = encodeChildTag(qty > 0 ? `${formatClock(new Date(), lang)} · ${qty} ${qtyUnit}` : formatClock(new Date(), lang), selectedChildId);
    const entry = { label: M.bottle, detail };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setBottlePending(false);
    setBottleQty("");
  };
  const [pumpPending, setPumpPending] = useState(false);
  const [pumpQty, setPumpQty] = useState("");
  const logPump = () => {
    const qty = Number(pumpQty);
    const detail = encodeChildTag(qty > 0 ? `${formatClock(new Date(), lang)} · ${qty} ${qtyUnit}` : formatClock(new Date(), lang), selectedChildId);
    const entry = { label: M.pump, detail };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setPumpPending(false);
    setPumpQty("");
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Total du jour, tous les biberons + séances de tire-lait confondus (converti dans l'unité choisie).
  const todayKey = new Date().toDateString();
  const parseQtyMl = (detail) => {
    const m = detail && detail.match(/([\d.]+)\s?(ml|oz)/i);
    if (!m) return 0;
    const val = parseFloat(m[1]);
    return /oz/i.test(m[2]) ? val * mlPerOz : val;
  };
  const todayTotalMl = filterLogByChild(log, selectedChildId)
    .filter((e) => (e.label === M.bottle || e.label === M.pump) && (e.start || e.createdAt) && (e.start || e.createdAt).toDateString() === todayKey)
    .reduce((sum, e) => sum + parseQtyMl(e.detail), 0);
  const todayTotalDisplay = qtyUnit === "ml" ? Math.round(todayTotalMl) : Math.round((todayTotalMl / mlPerOz) * 10) / 10;
  const saveWord = lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save";
  // Ajout rétroactif pour une date passée — seul le biberon est proposé ici via ce mécanisme (l'ajout
  // manuel avec heures de début/fin, juste en dessous, couvre maintenant l'allaitement au sein pour
  // les personnes qui préfèrent noter après coup plutôt que garder un chrono en direct).
  const addBottleForDate = (date) => {
    const entry = { label: M.bottle, detail: encodeChildTag(formatClock(date, lang), selectedChildId), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
  };
  const renderDateAdd = (date) => (
    <button onClick={() => addBottleForDate(date)} style={{
      marginTop: 8, width: "100%", padding: "9px", borderRadius: 10, border: `1px dashed ${COLORS.line}`,
      background: "#fff", color: COLORS.pink, fontWeight: 700, fontSize: 12.5, cursor: "pointer",
    }}>+ {M.bottle}</button>
  );

  // Ajout manuel d'une tétée (début → fin) sans chronomètre en direct — pour les personnes qui
  // préfèrent noter à la fin de la journée plutôt que de garder l'appli ouverte pendant la tétée.
  const ME = lang === "fr"
    ? { manualToggle: "Entrer une tétée manuellement", startLabel: "Début", endLabel: "Fin", add: "Ajouter", cancel: "Annuler" }
    : lang === "es"
    ? { manualToggle: "Ingresar una toma manualmente", startLabel: "Inicio", endLabel: "Fin", add: "Agregar", cancel: "Cancelar" }
    : { manualToggle: "Enter a feeding manually", startLabel: "Start", endLabel: "End", add: "Add", cancel: "Cancel" };
  const [manualOpen, setManualOpen] = useState(false);
  const [manualSide, setManualSide] = useState(M.left);
  const [manualStart, setManualStart] = useState("");
  const [manualEnd, setManualEnd] = useState("");
  useEffect(() => { setManualSide(M.left); }, [lang]); // suit la langue si elle change pendant que le formulaire est ouvert
  const timeStrToDate = (timeStr) => {
    const [h, m] = timeStr.split(":").map(Number);
    const d = new Date();
    d.setHours(h, m, 0, 0);
    return d;
  };
  const addManualFeed = () => {
    if (!manualStart || !manualEnd) return;
    const start = timeStrToDate(manualStart);
    let end = timeStrToDate(manualEnd);
    if (end <= start) end = new Date(end.getTime() + 24 * 60 * 60 * 1000); // plage qui traverse minuit
    const entry = { label: manualSide, detail: encodeChildTag(`${formatClock(start, lang)} · ${formatDuration(end - start, lang)}`, selectedChildId), createdAt: start };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persist("feeding", entry, optimistic.id);
    setManualStart("");
    setManualEnd("");
  };

  return (
    <Card>
      <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <FeedingHeroIllu size={130} />
      </div>
      <ChildSelectorPills kids={kids} selectedChildId={selectedChildId} onSelect={setSelectedChildId} color={COLORS.pink} label={forChildLabel} />
      {!isReadOnlyPartner && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 4 }}>
          {[M.left, M.right].map((side) => (
            <button key={side} onClick={() => (trackSession?.side === side ? stop() : start(side))} style={{
              flex: 1, minWidth: 130, padding: "14px 10px", borderRadius: 14, border: "none", cursor: "pointer",
              background: trackSession?.side === side ? COLORS.pink : "#FDF0F3", color: trackSession?.side === side ? "#fff" : COLORS.pink,
              fontWeight: 700, fontSize: 14,
            }}>
              {side}{trackSession?.side === side ? ` · ${formatDuration(new Date() - trackSession.start, lang)} — ${saveWord}` : ""}
            </button>
          ))}
        </div>
      )}
      {todayTotalMl > 0 && (
        <p style={{ margin: "10px 0 0", fontSize: 12, fontWeight: 700, color: COLORS.pink, background: "#FDF0F3", borderRadius: 10, padding: "8px 12px", textAlign: "center" }}>
          {M.todayTotal(todayTotalDisplay, qtyUnit)}
        </p>
      )}

      {!isReadOnlyPartner && (
      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        <button onClick={() => { setBottlePending((v) => !v); setPumpPending(false); }} style={{
          flex: 1, padding: "12px", borderRadius: 12, cursor: "pointer",
          border: `2px solid ${bottlePending ? COLORS.pink : COLORS.line}`, background: "#fff",
          color: COLORS.teal, fontWeight: 700, fontSize: 13.5,
        }}>+ {M.bottle}</button>
        <button onClick={() => { setPumpPending((v) => !v); setBottlePending(false); }} style={{
          flex: 1, padding: "12px", borderRadius: 12, cursor: "pointer",
          border: `2px solid ${pumpPending ? COLORS.pink : COLORS.line}`, background: "#fff",
          color: COLORS.teal, fontWeight: 700, fontSize: 13.5,
        }}>+ {M.pump}</button>
      </div>
      )}

      {!isReadOnlyPartner && (bottlePending || pumpPending) && (
        <div style={{ marginTop: 8, background: "#FDF0F3", borderRadius: 12, padding: 12 }}>
          <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
            <input
              type="number" step="1" min="0" placeholder={M.qtyPh}
              value={bottlePending ? bottleQty : pumpQty}
              onChange={(e) => (bottlePending ? setBottleQty(e.target.value) : setPumpQty(e.target.value))}
              style={{ flex: 1, padding: "9px 11px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box" }}
            />
            <div style={{ display: "flex", gap: 4 }}>
              {["ml", "oz"].map((u) => (
                <button key={u} onClick={() => setQtyUnit(u)} style={{
                  padding: "9px 12px", borderRadius: 10, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
                  border: `1px solid ${qtyUnit === u ? COLORS.pink : COLORS.line}`,
                  background: qtyUnit === u ? COLORS.pink : "#fff", color: qtyUnit === u ? "#fff" : COLORS.muted,
                }}>{u === "ml" ? M.ml : M.oz}</button>
              ))}
            </div>
          </div>
          <button onClick={bottlePending ? logBottle : logPump} style={{
            width: "100%", padding: "12px", borderRadius: 12, border: "none", background: COLORS.pink, color: "#fff",
            fontWeight: 800, fontSize: 13.5, cursor: "pointer",
          }}>{saveWord}</button>
        </div>
      )}
      {!isReadOnlyPartner && !trackSession && (
        <div style={{ marginTop: 10 }}>
          <button onClick={() => setManualOpen((v) => !v)} style={{
            background: "none", border: "none", color: COLORS.pink, fontSize: 12.5, fontWeight: 700,
            textDecoration: "underline", cursor: "pointer", padding: "4px 0",
          }}>{manualOpen ? ME.cancel : ME.manualToggle}</button>
          {manualOpen && (
            <div style={{ marginTop: 8, background: "#FDF0F3", borderRadius: 12, padding: 12 }}>
              <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                {[M.left, M.right].map((side) => (
                  <button key={side} onClick={() => setManualSide(side)} style={{
                    flex: 1, padding: "9px 6px", borderRadius: 10, cursor: "pointer",
                    border: `2px solid ${manualSide === side ? COLORS.pink : "transparent"}`,
                    background: "#fff", color: COLORS.pink, fontWeight: 700, fontSize: 12.5,
                  }}>{side}</button>
                ))}
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.startLabel}
                  <input type="time" value={manualStart} onChange={(e) => setManualStart(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
                <label style={{ flex: 1, fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.endLabel}
                  <input type="time" value={manualEnd} onChange={(e) => setManualEnd(e.target.value)} style={{
                    display: "block", width: "100%", marginTop: 4, padding: "8px 10px", borderRadius: 8,
                    border: `1px solid ${COLORS.line}`, fontSize: 14, boxSizing: "border-box",
                  }} />
                </label>
              </div>
              <button onClick={addManualFeed} disabled={!manualStart || !manualEnd} style={{
                width: "100%", padding: "10px", borderRadius: 10, border: "none",
                cursor: manualStart && manualEnd ? "pointer" : "default",
                background: manualStart && manualEnd ? COLORS.pink : COLORS.line,
                color: manualStart && manualEnd ? "#fff" : COLORS.muted,
                fontWeight: 800, fontSize: 13,
              }}>{ME.add}</button>
            </div>
          )}
        </div>
      )}
      <TrackerLogList entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId))} emptyLabel={emptyLabel} onDelete={isReadOnlyPartner ? undefined : removeEntry} renderDateAdd={isReadOnlyPartner ? undefined : renderDateAdd} loaded={loaded} lang={lang} />
      <TrackerPdfExport
        lang={lang} printId="feeding-print-view"
        title={lang === "fr" ? "Allaitement" : lang === "es" ? "Lactancia" : "Feeding"}
        entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId)).map((e) => ({ date: e.start || e.createdAt, label: e.label, detail: e.detail }))}
      />
    </Card>
  );
}

/* ---------------- SONS POUR LA SIESTE (berceuses + sons apaisants) ----------------
   Tout est généré directement dans le navigateur avec l'API Web Audio (oscillateurs + bruit
   filtré) — aucun fichier audio à héberger ni à téléverser, donc ça fonctionne immédiatement
   partout où l'appli est déployée, sans dépendre d'un lien externe qui pourrait un jour se briser. */
const NOTE_FREQ = {
  G3: 196.0, A3: 220.0, B3: 246.94, C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392.0,
  A4: 440.0, B4: 493.88, C5: 523.25, D5: 587.33, E5: 659.25, F5: 698.46, G5: 783.99,
};

// Trois VRAIES berceuses connues et universellement reconnues (mélodies traditionnelles du domaine
// public, jamais des compositions maison) plutôt que des mélodies originales — jouées très
// lentement, notes tenues longtemps, pour une vraie ambiance de sommeil plutôt qu'une comptine
// enjouée. Chacune boucle sur elle-même tant que la lecture continue.
const LULLABY_MELODIES = {
  // "Twinkle Twinkle Little Star" / "Ah! vous dirai-je maman" / "Estrellita dónde estás" — la
  // berceuse la plus reconnue au monde, dans les trois langues de l'appli.
  twinkle: [
    ["C4", 0.55], ["C4", 0.55], ["G4", 0.55], ["G4", 0.55], ["A4", 0.55], ["A4", 0.55], ["G4", 1.4],
    ["F4", 0.55], ["F4", 0.55], ["E4", 0.55], ["E4", 0.55], ["D4", 0.55], ["D4", 0.55], ["C4", 1.4],
    ["G4", 0.55], ["G4", 0.55], ["F4", 0.55], ["F4", 0.55], ["E4", 0.55], ["E4", 0.55], ["D4", 1.4],
    ["G4", 0.55], ["G4", 0.55], ["F4", 0.55], ["F4", 0.55], ["E4", 0.55], ["E4", 0.55], ["D4", 1.4],
    ["C4", 0.55], ["C4", 0.55], ["G4", 0.55], ["G4", 0.55], ["A4", 0.55], ["A4", 0.55], ["G4", 1.4],
    ["F4", 0.55], ["F4", 0.55], ["E4", 0.55], ["E4", 0.55], ["D4", 0.55], ["D4", 0.55], ["C4", 1.8],
  ],
  // "Frère Jacques" / "Are You Sleeping?" / "Fray Felipe" — littéralement une chanson sur le
  // sommeil ("dormez-vous, dormez-vous?"), connue dans les trois langues.
  frereJacques: [
    ["C4", 0.55], ["D4", 0.55], ["E4", 0.55], ["C4", 0.55],
    ["C4", 0.55], ["D4", 0.55], ["E4", 0.55], ["C4", 0.55],
    ["E4", 0.55], ["F4", 0.55], ["G4", 1.2],
    ["E4", 0.55], ["F4", 0.55], ["G4", 1.2],
    ["G4", 0.4], ["A4", 0.4], ["G4", 0.4], ["F4", 0.4], ["E4", 0.55], ["C4", 0.9],
    ["G4", 0.4], ["A4", 0.4], ["G4", 0.4], ["F4", 0.4], ["E4", 0.55], ["C4", 0.9],
    ["C4", 0.55], ["G3", 0.55], ["C4", 1.3],
    ["C4", 0.55], ["G3", 0.55], ["C4", 1.8],
  ],
  // "Berceuse de Brahms" (Wiegenlied) — LA berceuse de référence demandée, mélodie du domaine
  // public (Brahms, 1868), transposée en do majeur pour rester lente et douce sur ces instruments.
  brahms: [
    ["G4", 0.55], ["G4", 0.55], ["A4", 0.55], ["G4", 0.55], ["C5", 0.55], ["B4", 1.1],
    ["A4", 0.55], ["G4", 0.55], ["A4", 0.55], ["B4", 0.55], ["C5", 1.6],
    ["G4", 0.55], ["G4", 0.55], ["A4", 0.55], ["G4", 0.55], ["C5", 0.55], ["B4", 1.1],
    ["A4", 0.55], ["G4", 0.55], ["F4", 0.55], ["E4", 0.55], ["D4", 2.2],
  ],
};

// Bruit blanc simple (utilisé nulle part directement ici, mais gardé pour référence/tests).
function createWhiteNoiseBuffer(ctx, seconds = 3) {
  const bufferSize = Math.floor(ctx.sampleRate * seconds);
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
  return buffer;
}

// Bruit ROSE (algorithme de Paul Kellet) — beaucoup plus doux et « rond » que le bruit blanc brut,
// qui sonnait comme un grésillement de radio. C'est ce qui donne le vrai son feutré de la pluie,
// des vagues et du souffle utérin, plutôt qu'un chuintement agressif.
function createPinkNoiseBuffer(ctx, seconds = 3) {
  const bufferSize = Math.floor(ctx.sampleRate * seconds);
  const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
  for (let i = 0; i < bufferSize; i++) {
    const white = Math.random() * 2 - 1;
    b0 = 0.99886 * b0 + white * 0.0555179;
    b1 = 0.99332 * b1 + white * 0.0750759;
    b2 = 0.96900 * b2 + white * 0.1538520;
    b3 = 0.86650 * b3 + white * 0.3104856;
    b4 = 0.55000 * b4 + white * 0.5329522;
    b5 = -0.7616 * b5 - white * 0.0168980;
    const pink = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
    b6 = white * 0.115926;
    data[i] = pink * 0.11;
  }
  return buffer;
}

// Une note jouée avec l'un de 3 « instruments » bien distincts — entièrement revus pour sonner
// doux et calme (vraie berceuse pour endormir un bébé), plutôt que clinquant ou brillant :
//  - "musicbox" (Berceuse douce) : sinus filtré + harmonique très discrète, attaque légèrement
//    adoucie (jamais un clic sec) et décroissance longue et enveloppante.
//  - "pluck" (Berceuse étoilée) : corde pincée (guitare/harpe) mais en onde triangle (jamais de
//    dents de scie brute, trop agressive) à travers un filtre qui reste sombre dès l'attaque.
//  - "flute" (Berceuse océane) : timbre soufflé, chaud et soutenu (sinus + triangle très discrète,
//    vibrato léger), attaque et relâchement lents, comme un fredonnement plutôt qu'un instrument.
function playInstrumentNote(ctx, masterGain, freq, t, dur, instrument, nodesOut) {
  if (instrument === "musicbox") {
    const decay = Math.min(dur * 1.15, 1.7);
    const osc = ctx.createOscillator(); osc.type = "sine"; osc.frequency.value = freq;
    const filter = ctx.createBiquadFilter(); filter.type = "lowpass"; filter.frequency.value = 2100; filter.Q.value = 0.3;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.32, t + 0.05); // attaque adoucie, plus jamais instantanée
    g.gain.exponentialRampToValueAtTime(0.0006, t + decay);
    osc.connect(filter); filter.connect(g); g.connect(masterGain);
    osc.start(t); osc.stop(t + decay + 0.05);
    const osc2 = ctx.createOscillator(); osc2.type = "sine"; osc2.frequency.value = freq * 2;
    const g2 = ctx.createGain();
    g2.gain.setValueAtTime(0.0001, t);
    g2.gain.exponentialRampToValueAtTime(0.08, t + 0.05); // harmonique à peine perceptible, juste la couleur
    g2.gain.exponentialRampToValueAtTime(0.0004, t + decay * 0.55);
    osc2.connect(g2); g2.connect(masterGain);
    osc2.start(t); osc2.stop(t + decay + 0.05);
    nodesOut.push(osc, filter, g, osc2, g2);
  } else if (instrument === "pluck") {
    const decay = Math.min(dur * 1.15, 1.9);
    const osc = ctx.createOscillator(); osc.type = "triangle"; osc.frequency.value = freq;
    const filter = ctx.createBiquadFilter(); filter.type = "lowpass"; filter.Q.value = 0.5;
    filter.frequency.setValueAtTime(Math.min(3200, freq * 5), t); // beaucoup moins brillant qu'avant
    filter.frequency.exponentialRampToValueAtTime(Math.max(200, freq * 1.1), t + decay);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.32, t + 0.03);
    g.gain.exponentialRampToValueAtTime(0.0006, t + decay);
    osc.connect(filter); filter.connect(g); g.connect(masterGain);
    osc.start(t); osc.stop(t + decay + 0.05);
    nodesOut.push(osc, filter, g);
  } else {
    // "flute" — mélange sinus (majoritaire) + un soupçon de triangle, vibrato très léger, attaque
    // et relâchement longs, pour un rendu proche d'un fredonnement chaud plutôt qu'un instrument.
    const hold = Math.max(0.15, dur - 0.4);
    const osc = ctx.createOscillator(); osc.type = "sine"; osc.frequency.value = freq;
    const osc2 = ctx.createOscillator(); osc2.type = "triangle"; osc2.frequency.value = freq;
    const vibrato = ctx.createOscillator(); vibrato.type = "sine"; vibrato.frequency.value = 3.2;
    const vibratoGain = ctx.createGain(); vibratoGain.gain.value = 2;
    vibrato.connect(vibratoGain); vibratoGain.connect(osc.frequency); vibratoGain.connect(osc2.frequency);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.26, t + 0.25);
    g.gain.setValueAtTime(0.26, t + hold);
    g.gain.linearRampToValueAtTime(0.0001, t + dur);
    const g2 = ctx.createGain(); g2.gain.value = 0.35;
    osc.connect(g); osc2.connect(g2); g2.connect(g); g.connect(masterGain);
    osc.start(t); osc.stop(t + dur + 0.05);
    osc2.start(t); osc2.stop(t + dur + 0.05);
    vibrato.start(t); vibrato.stop(t + dur + 0.05);
    nodesOut.push(osc, osc2, g, g2, vibrato, vibratoGain);
  }
}

// Nappe continue de bruit rose, utilisée en fond pour le cœur/utérus et pour la baleine/océan.
function buildNoiseBed(ctx, masterGain, { lowpassFreq, gain }) {
  const noise = ctx.createBufferSource();
  noise.buffer = createPinkNoiseBuffer(ctx, 3);
  noise.loop = true;
  const lowpass = ctx.createBiquadFilter();
  lowpass.type = "lowpass";
  lowpass.frequency.value = lowpassFreq;
  const noiseGain = ctx.createGain();
  noiseGain.gain.value = gain;
  noise.connect(lowpass); lowpass.connect(noiseGain); noiseGain.connect(masterGain);
  noise.start();
  return { nodes: [noise, lowpass, noiseGain], noiseGain };
}

// Refait une nouvelle fois : le "whoosh + thump" façon doppler sonnait trop comme un tambour,
// agressif. Ici : une nappe de fond CONTINUE, douce et feutrée (le calme du ventre), plus un léger
// bip électronique ponctuel façon moniteur cardiaque d'hôpital — jamais un tambour/impact.

// La nappe de fond, calme et continue — le "calme dans le ventre" demandé, toujours présente en
// arrière-plan, avec une très légère respiration de volume.
function buildWombAmbience(ctx, masterGain) {
  const noise = ctx.createBufferSource();
  noise.buffer = createPinkNoiseBuffer(ctx, 4);
  noise.loop = true;
  const lowpass = ctx.createBiquadFilter();
  lowpass.type = "lowpass";
  lowpass.frequency.value = 320;
  const gain = ctx.createGain();
  gain.gain.value = 0.14;
  noise.connect(lowpass); lowpass.connect(gain); gain.connect(masterGain);
  const lfo = ctx.createOscillator(); lfo.type = "sine"; lfo.frequency.value = 1 / 4.5;
  const lfoDepth = ctx.createGain(); lfoDepth.gain.value = 0.03;
  lfo.connect(lfoDepth); lfoDepth.connect(gain.gain);
  noise.start(); lfo.start();
  return [noise, lowpass, gain, lfo, lfoDepth];
}

// Le battement lui-même : un bip sinusoïdal court et léger, comme celui d'un moniteur cardiaque —
// pas de basse ni d'impact, juste une petite tonalité claire qui marque le rythme.
function playMonitorBeep(ctx, masterGain, t, nodesOut) {
  const osc = ctx.createOscillator(); osc.type = "sine"; osc.frequency.value = 880;
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(0.16, t + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0004, t + 0.14);
  osc.connect(g); g.connect(masterGain);
  osc.start(t); osc.stop(t + 0.18);
  nodesOut.push(osc, g);
}

// Un « chant » de baleine ponctuel — une plainte grave qui glisse lentement vers le haut puis
// redescend, avec vibrato ET une harmonique discrète une octave plus haute (un vrai chant de
// baleine n'est jamais un sinus pur), PLUS un écho/réverbération léger qui donne cette sensation
// d'immensité océanique typique des enregistrements de baleines qu'on entend partout — le son
// "balai" signalé venait surtout de la nappe de bruit de fond continue, retirée (voir plus bas).
function playWhaleCall(ctx, masterGain, t, callDur, nodesOut) {
  const startFreq = 80 + Math.random() * 25;
  const peakFreq = startFreq + 130 + Math.random() * 90;
  const endFreq = startFreq * 0.8;
  const osc = ctx.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(startFreq, t);
  osc.frequency.linearRampToValueAtTime(peakFreq, t + callDur * 0.4);
  osc.frequency.linearRampToValueAtTime(endFreq, t + callDur);
  const osc2 = ctx.createOscillator();
  osc2.type = "sine";
  osc2.frequency.setValueAtTime(startFreq * 2, t);
  osc2.frequency.linearRampToValueAtTime(peakFreq * 2, t + callDur * 0.4);
  osc2.frequency.linearRampToValueAtTime(endFreq * 2, t + callDur);
  const vibrato = ctx.createOscillator();
  vibrato.type = "sine";
  vibrato.frequency.value = 3;
  const vibratoGain = ctx.createGain();
  vibratoGain.gain.value = 7;
  vibrato.connect(vibratoGain); vibratoGain.connect(osc.frequency); vibratoGain.connect(osc2.frequency);
  const filter = ctx.createBiquadFilter();
  filter.type = "lowpass";
  filter.frequency.value = 550; // sombre/sous-marin
  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(0.65, t + callDur * 0.25);
  g.gain.linearRampToValueAtTime(0.58, t + callDur * 0.7);
  g.gain.linearRampToValueAtTime(0.0001, t + callDur);
  const g2 = ctx.createGain(); g2.gain.value = 0.25; // harmonique discrète, juste pour la texture
  // Écho court avec réinjection légère — donne la profondeur/l'immensité de l'océan.
  const delay = ctx.createDelay(1.0); delay.delayTime.value = 0.38;
  const feedback = ctx.createGain(); feedback.gain.value = 0.32;
  const delayWet = ctx.createGain(); delayWet.gain.value = 0.5;
  delay.connect(feedback); feedback.connect(delay);
  osc.connect(filter); osc2.connect(g2); g2.connect(filter); filter.connect(g); g.connect(masterGain);
  g.connect(delay); delay.connect(delayWet); delayWet.connect(masterGain);
  osc.start(t); osc2.start(t); vibrato.start(t);
  osc.stop(t + callDur + 0.1); osc2.stop(t + callDur + 0.1); vibrato.stop(t + callDur + 0.1);
  nodesOut.push(osc, osc2, g2, vibrato, vibratoGain, filter, g, delay, feedback, delayWet);
}

// « Pluie douce » — entièrement refaite : plus AUCUN highpass (c'était lui qui donnait le côté
// « brillant »/qui grince), un double filtre passe-bas très fermé pour ne garder qu'un doux
// murmure grave et feutré, et une ondulation beaucoup plus lente et discrète (période ~11 s au
// lieu de 6,5 s, profondeur réduite) — une pluie lente entendue à travers une fenêtre, jamais une
// pluie battante et aiguë.
function buildSoftRain(ctx, masterGain) {
  const noise = ctx.createBufferSource();
  noise.buffer = createPinkNoiseBuffer(ctx, 4);
  noise.loop = true;
  const lowpass = ctx.createBiquadFilter();
  lowpass.type = "lowpass";
  lowpass.frequency.value = 750;
  const lowpass2 = ctx.createBiquadFilter();
  lowpass2.type = "lowpass";
  lowpass2.frequency.value = 900;
  const noiseGain = ctx.createGain();
  noiseGain.gain.value = 0.22;
  noise.connect(lowpass); lowpass.connect(lowpass2); lowpass2.connect(noiseGain); noiseGain.connect(masterGain);
  const waveLfo = ctx.createOscillator();
  waveLfo.type = "sine";
  waveLfo.frequency.value = 1 / 11;
  const waveDepth = ctx.createGain();
  waveDepth.gain.value = 0.05;
  waveLfo.connect(waveDepth); waveDepth.connect(noiseGain.gain);

  noise.start(); waveLfo.start();
  return [noise, lowpass, lowpass2, noiseGain, waveLfo, waveDepth];
}

// Trois VRAIS fichiers audio (mp3 libres de droits fournis par Marilyne) plutôt que des berceuses
// synthétisées — servis tels quels depuis /public/sounds, chacun en boucle. Les melodies
// synthétisées (LULLABY_MELODIES) restent définies plus haut mais ne sont plus utilisées ici.
const LULLABY_OPTIONS = [
  { id: "dream", kind: "audio", src: "/lullaby-dream.mp3", emoji: "🎵", color: COLORS.pink, label: { fr: "Berceuse douce (rêverie)", en: "Soft lullaby (dream)", es: "Canción de cuna suave (ensueño)" } },
  { id: "musicbox", kind: "audio", src: "/lullaby-musicbox.mp3", emoji: "⭐", color: COLORS.lavender, label: { fr: "Berceuse boîte à musique", en: "Music box lullaby", es: "Canción de cuna de caja de música" } },
  { id: "soft", kind: "audio", src: "/lullaby-soft.mp3", emoji: "🔔", color: COLORS.blue, label: { fr: "Berceuse apaisante", en: "Soothing lullaby", es: "Canción de cuna relajante" } },
];
const WOMB_SOUND_OPTIONS = [
  // Vrais fichiers audio (mp3 libres de droits fournis par Marilyne) plutôt que des sons
  // synthétisés — servis tels quels depuis /public. Le battement de cœur est maintenant lui aussi
  // un vrai fichier : un mélange (fond doux + battement audible) préparé pour reproduire l'effet
  // « dans le ventre », après plusieurs essais de synthèse qui ne convenaient pas.
  { id: "heartbeat", kind: "audio", src: "/heartbeat-womb.mp3", emoji: "❤️", color: COLORS.coral, label: { fr: "Cœur & flux (comme dans l'utérus)", en: "Heartbeat & flow (like in the womb)", es: "Corazón y flujo (como en el útero)" } },
  { id: "waves", kind: "audio", src: "/ocean-waves.mp3", emoji: "🌊", color: COLORS.sky, label: { fr: "Vagues de l'océan", en: "Ocean waves", es: "Olas del océano" } },
  { id: "rain", kind: "audio", src: "/rain.mp3", emoji: "🌧️", color: COLORS.sage, label: { fr: "Pluie douce et apaisante", en: "Soft, calming rain", es: "Lluvia suave y relajante" } },
];
const SLEEP_SOUND_MAX_MS = 2 * 60 * 60 * 1000; // 2 h maximum, pour ne pas laisser le son jouer indéfiniment

// Affiche m:ss (ou h:mm:ss après 1 h) — l'ancien affichage arrondissait aux minutes, donc restait
// bloqué à « 0 min » tant qu'une minute complète ne s'était pas écoulée.
function formatElapsedClock(ms) {
  const totalSec = Math.floor(ms / 1000);
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}

function SleepSoundPlayer({ lang }) {
  const ctxRef = useRef(null);
  const activeNodesRef = useRef([]);
  const audioRef = useRef(null); // instance <audio> pour les sons fournis en vrai fichier (ex. pluie)
  const tokenRef = useRef(0);
  const timersRef = useRef([]);
  const startTimeRef = useRef(null);
  const [playingId, setPlayingId] = useState(null);
  const [elapsedMs, setElapsedMs] = useState(0);

  const clearTimers = () => {
    timersRef.current.forEach((id) => clearTimeout(id));
    timersRef.current = [];
  };

  const stopAll = () => {
    tokenRef.current += 1;
    clearTimers();
    activeNodesRef.current.forEach((n) => {
      try { n.stop && n.stop(); } catch {}
      try { n.disconnect && n.disconnect(); } catch {}
    });
    activeNodesRef.current = [];
    if (audioRef.current) {
      try { audioRef.current.pause(); audioRef.current.currentTime = 0; } catch {}
      audioRef.current = null;
    }
    startTimeRef.current = null;
    setPlayingId(null);
    setElapsedMs(0);
  };

  useEffect(() => () => stopAll(), []); // arrête tout si on quitte l'outil sommeil

  // Minuteur d'affichage — coché toutes les 500 ms pour un compteur fluide (au lieu d'1 seconde).
  useEffect(() => {
    if (!playingId) return;
    const interval = setInterval(() => {
      if (startTimeRef.current) setElapsedMs(Date.now() - startTimeRef.current);
    }, 500);
    return () => clearInterval(interval);
  }, [playingId]);

  const scheduleMelodyLoop = (ctx, masterGain, melody, instrument, myToken) => {
    if (tokenRef.current !== myToken) return;
    const now = ctx.currentTime + 0.05;
    let t = now;
    melody.forEach(([note, dur]) => {
      playInstrumentNote(ctx, masterGain, NOTE_FREQ[note], t, dur, instrument, activeNodesRef.current);
      t += dur;
    });
    const loopMs = (t - now) * 1000;
    const id = setTimeout(() => scheduleMelodyLoop(ctx, masterGain, melody, instrument, myToken), Math.max(300, loopMs - 100));
    timersRef.current.push(id);
  };

  const scheduleHeartbeatLoop = (ctx, masterGain, myToken) => {
    if (tokenRef.current !== myToken) return;
    const now = ctx.currentTime + 0.05;
    playMonitorBeep(ctx, masterGain, now, activeNodesRef.current);
    const period = 60 / 68; // ~68 battements/minute
    const id = setTimeout(() => scheduleHeartbeatLoop(ctx, masterGain, myToken), period * 1000);
    timersRef.current.push(id);
  };

  const scheduleWhaleLoop = (ctx, masterGain, myToken) => {
    if (tokenRef.current !== myToken) return;
    const now = ctx.currentTime + 0.1;
    const callDur = 4.5 + Math.random() * 2.5;
    playWhaleCall(ctx, masterGain, now, callDur, activeNodesRef.current);
    const silence = 3 + Math.random() * 3.5;
    const id = setTimeout(() => scheduleWhaleLoop(ctx, masterGain, myToken), (callDur + silence) * 1000);
    timersRef.current.push(id);
  };

  const play = (option) => {
    stopAll();

    if (option.kind === "audio") {
      // Vrai fichier audio (mp3) au lieu d'une synthèse Web Audio — lecture directe en boucle via
      // un élément <audio>, complètement indépendant du reste de la chaîne Web Audio ci-dessous.
      const audio = new Audio(option.src);
      audio.loop = true;
      audio.volume = 0.9;
      audio.play().catch(() => {});
      audioRef.current = audio;
      startTimeRef.current = Date.now();
      setPlayingId(option.id);
      setElapsedMs(0);
      const stopTimerId = setTimeout(stopAll, SLEEP_SOUND_MAX_MS);
      timersRef.current.push(stopTimerId);
      return;
    }

    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    if (!ctxRef.current) ctxRef.current = new AC();
    const ctx = ctxRef.current;
    if (ctx.state === "suspended") ctx.resume();

    // Chaîne de sortie simplifiée : plus de compresseur — c'est lui, en réagissant aux rafales de
    // bruit + battements superposés, qui provoquait l'effet de grésillement signalé. Une seule
    // gain node directe vers la sortie, avec des niveaux réglés individuellement par son.
    const masterGain = ctx.createGain();
    masterGain.gain.value = 0.9;
    masterGain.connect(ctx.destination);
    activeNodesRef.current = [masterGain];

    const myToken = tokenRef.current;
    if (option.kind === "melody") {
      scheduleMelodyLoop(ctx, masterGain, option.melody, option.instrument, myToken);
    } else if (option.kind === "heartbeat") {
      // Nappe de fond continue et douce (le calme du ventre) + un léger bip électronique par
      // battement (façon moniteur d'hôpital) — plus de "whoosh" en rafale ni de thump, qui
      // sonnaient trop comme un tambour.
      const nodes = buildWombAmbience(ctx, masterGain);
      activeNodesRef.current.push(...nodes);
      scheduleHeartbeatLoop(ctx, masterGain, myToken);
    } else if (option.kind === "whale") {
      // Plus de nappe de bruit continue en fond non plus — c'était elle qui donnait ce son de
      // « balai »/sweeping signalé. Le chant de baleine porte maintenant tout le son à lui seul.
      scheduleWhaleLoop(ctx, masterGain, myToken);
    } else {
      const nodes = option.builder(ctx, masterGain);
      activeNodesRef.current.push(...nodes);
    }
    startTimeRef.current = Date.now();
    setPlayingId(option.id);
    setElapsedMs(0);
    const stopTimerId = setTimeout(stopAll, SLEEP_SOUND_MAX_MS);
    timersRef.current.push(stopTimerId);
  };

  const L = lang === "fr"
    ? { lullabies: "Berceuses", sounds: "Sons apaisants (comme dans l'utérus)", stop: "Arrêter", playing: "En cours", max: "max 2 h" }
    : lang === "es"
    ? { lullabies: "Canciones de cuna", sounds: "Sonidos relajantes (como en el útero)", stop: "Detener", playing: "Reproduciendo", max: "máx. 2 h" }
    : { lullabies: "Lullabies", sounds: "Soothing sounds (like in the womb)", stop: "Stop", playing: "Playing", max: "max 2h" };

  // Même format que les tuiles de la grille d'outils de l'accueil : icône dans un carré arrondi
  // coloré au-dessus, étiquette en dessous — au lieu des anciennes bulles en forme de pilule,
  // pour que les deux endroits de l'appli se ressemblent visuellement.
  const renderRow = (options) => (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10 }}>
      {options.map((opt) => {
        const isActive = playingId === opt.id;
        return (
          <button
            key={opt.id}
            type="button"
            onClick={() => (isActive ? stopAll() : play(opt))}
            style={{
              display: "flex", flexDirection: "column", alignItems: "center", gap: 6,
              background: "none", border: "none", cursor: "pointer", minWidth: 0, padding: "2px 0",
            }}
          >
            <div style={{
              width: 48, height: 48, borderRadius: 16,
              background: isActive ? opt.color : `${opt.color}1F`,
              display: "flex", alignItems: "center", justifyContent: "center",
              boxShadow: isActive ? `0 4px 12px ${opt.color}55` : "none",
              transition: "background 0.2s ease, box-shadow 0.2s ease",
            }}>
              <span style={{ fontSize: 21, lineHeight: 1 }}>{opt.emoji}</span>
            </div>
            <span style={{ fontSize: 11, color: COLORS.text, fontWeight: 700, textAlign: "center" }}>{opt.label[lang]}</span>
          </button>
        );
      })}
    </div>
  );

  return (
    <div style={{ background: "#EAF2F8", borderRadius: 16, padding: "14px 16px", marginTop: 12 }}>
      <p style={{ margin: "0 0 8px", fontSize: 11.5, fontWeight: 800, color: COLORS.blue, textTransform: "uppercase", letterSpacing: "0.03em" }}>{L.lullabies}</p>
      {renderRow(LULLABY_OPTIONS)}
      <p style={{ margin: "14px 0 8px", fontSize: 11.5, fontWeight: 800, color: COLORS.blue, textTransform: "uppercase", letterSpacing: "0.03em" }}>{L.sounds}</p>
      {renderRow(WOMB_SOUND_OPTIONS)}
      {playingId && (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, marginTop: 12, paddingTop: 10, borderTop: `1px solid ${COLORS.blue}25` }}>
          <span style={{ fontSize: 12, color: COLORS.muted, fontWeight: 600 }}>
            {L.playing} · {formatElapsedClock(elapsedMs)} <span style={{ opacity: 0.7 }}>({L.max})</span>
          </span>
          <button
            type="button"
            onClick={stopAll}
            style={{ background: "none", border: "none", color: "#B3261E", fontSize: 12, fontWeight: 700, textDecoration: "underline", cursor: "pointer" }}
          >
            {L.stop}
          </button>
        </div>
      )}
    </div>
  );
}

function SleepTracker({ lang, session, children: kids, isReadOnlyPartner }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [trackSession, setTrackSession] = useState(null);
  const [log, setLog] = useState([]);
  const [selectedChildId, setSelectedChildId] = useState(kids?.[0]?.id ?? null);
  const forChildLabel = lang === "fr" ? "Pour :" : lang === "es" ? "Para:" : "For:";
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr" ? { start: "Bébé s'endort", stop: "Bébé se réveille" } : lang === "es" ? { start: "El bebé se duerme", stop: "El bebé se despierta" } : { start: "Baby falls asleep", stop: "Baby wakes up" };
  // Pour les personnes qui préfèrent noter les périodes de sommeil après coup plutôt que de garder
  // l'appli ouverte avec un chronomètre en direct (ex. en fin de journée, plusieurs siestes d'un coup).
  const ME = lang === "fr"
    ? { manualToggle: "Entrer une plage manuellement", startLabel: "Début", endLabel: "Fin", add: "Ajouter", cancel: "Annuler" }
    : lang === "es"
    ? { manualToggle: "Ingresar un rango manualmente", startLabel: "Inicio", endLabel: "Fin", add: "Agregar", cancel: "Cancelar" }
    : { manualToggle: "Enter a time range manually", startLabel: "Start", endLabel: "End", add: "Add", cancel: "Cancel" };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "sleep", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const toggle = () => {
    if (trackSession) {
      const durationMs = new Date() - trackSession.start;
      const entry = { label: formatClock(trackSession.start, lang), detail: encodeChildTag(formatDuration(durationMs, lang), selectedChildId) };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("sleep", entry, session, setLog, optimistic.id);
      setTrackSession(null);
    } else {
      setTrackSession({ start: new Date() });
    }
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Ajout manuel d'une plage (début → fin), sans chronomètre en direct.
  const [manualOpen, setManualOpen] = useState(false);
  const [manualStart, setManualStart] = useState("");
  const [manualEnd, setManualEnd] = useState("");
  const timeStrToDate = (timeStr) => {
    const [h, m] = timeStr.split(":").map(Number);
    const d = new Date();
    d.setHours(h, m, 0, 0);
    return d;
  };
  const addManual = () => {
    if (!manualStart || !manualEnd) return;
    const start = timeStrToDate(manualStart);
    let end = timeStrToDate(manualEnd);
    if (end <= start) end = new Date(end.getTime() + 24 * 60 * 60 * 1000); // plage qui traverse minuit
    const entry = { label: formatClock(start, lang), detail: encodeChildTag(formatDuration(end - start, lang), selectedChildId), createdAt: start };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("sleep", entry, session, setLog, optimistic.id);
    setManualStart("");
    setManualEnd("");
  };

  return (
    <Card>
      <div style={{ background: "#EAF2F8", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <SleepHeroIllu size={130} />
      </div>
      <ChildSelectorPills kids={kids} selectedChildId={selectedChildId} onSelect={setSelectedChildId} color={COLORS.blue} label={forChildLabel} />
      {!isReadOnlyPartner && (
      <button onClick={toggle} style={{
        width: "100%", padding: "18px", borderRadius: 16, border: "none", cursor: "pointer",
        background: trackSession ? COLORS.blue : "#EAF2F8", color: trackSession ? "#fff" : COLORS.blue,
        fontWeight: 800, fontSize: 15,
      }}>
        {trackSession ? `${lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save"} · ${formatDuration(new Date() - trackSession.start, lang)}` : M.start}
      </button>
      )}
      {!isReadOnlyPartner && <SleepSoundPlayer lang={lang} />}
      {!isReadOnlyPartner && !trackSession && (
        <div style={{ marginTop: 10 }}>
          <button onClick={() => setManualOpen((v) => !v)} style={{
            background: "none", border: "none", color: COLORS.blue, fontSize: 12.5, fontWeight: 700,
            textDecoration: "underline", cursor: "pointer", padding: "4px 0",
          }}>{manualOpen ? ME.cancel : ME.manualToggle}</button>
          {manualOpen && (
            <div style={{ marginTop: 8, background: "#EAF2F8", borderRadius: 12, padding: 12 }}>
              {/* Début et fin l'un sous l'autre plutôt que côte à côte — plus de place pour que
                  les menus déroulants heure/minute/AM-PM ne soient jamais compressés. */}
              <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 8 }}>
                <label style={{ fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.startLabel}
                  <div style={{ marginTop: 4 }}>
                    <TimeSelect value={manualStart} onChange={setManualStart} />
                  </div>
                </label>
                <label style={{ fontSize: 11.5, color: COLORS.muted, fontWeight: 700 }}>
                  {ME.endLabel}
                  <div style={{ marginTop: 4 }}>
                    <TimeSelect value={manualEnd} onChange={setManualEnd} />
                  </div>
                </label>
              </div>
              <button onClick={addManual} disabled={!manualStart || !manualEnd} style={{
                width: "100%", padding: "10px", borderRadius: 10, border: "none",
                cursor: manualStart && manualEnd ? "pointer" : "default",
                background: manualStart && manualEnd ? COLORS.blue : COLORS.line,
                color: manualStart && manualEnd ? "#fff" : COLORS.muted,
                fontWeight: 800, fontSize: 13,
              }}>{ME.add}</button>
            </div>
          )}
        </div>
      )}
      <TrackerLogList entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId))} emptyLabel={emptyLabel} onDelete={isReadOnlyPartner ? undefined : removeEntry} loaded={loaded} lang={lang} />
      <TrackerPdfExport
        lang={lang} printId="sleep-print-view"
        title={lang === "fr" ? "Sommeil" : lang === "es" ? "Sueño" : "Sleep"}
        entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId)).map((e) => ({ date: e.start || e.createdAt, label: e.label, detail: e.detail }))}
      />
    </Card>
  );
}

function DiaperTracker({ lang, session, children: kids, isReadOnlyPartner }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [log, setLog] = useState([]);
  const [selectedChildId, setSelectedChildId] = useState(kids?.[0]?.id ?? null);
  const forChildLabel = lang === "fr" ? "Pour :" : lang === "es" ? "Para:" : "For:";
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr" ? { pee: "Pipi", poop: "Selle", both: "Les deux" } : lang === "es" ? { pee: "Pipí", poop: "Popó", both: "Ambos" } : { pee: "Wet", poop: "Dirty", both: "Both" };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "diaper", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const [selectedType, setSelectedType] = useState(null);
  const saveLabel = lang === "fr" ? "Sauvegarder" : lang === "es" ? "Guardar" : "Save";
  const add = () => {
    if (!selectedType) return;
    const entry = { label: selectedType, detail: encodeChildTag(formatClock(new Date(), lang), selectedChildId) };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("diaper", entry, session, setLog, optimistic.id);
    setSelectedType(null);
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);
  // Ajout rétroactif pour une date passée (ex. « j'ai oublié d'entrer une couche d'hier ») —
  // toujours via les mêmes boutons de type, jamais de texte à écrire.
  const dateKeyOf = (d) => d.toISOString().slice(0, 10);
  const [addTypeByDate, setAddTypeByDate] = useState({}); // { [dateKey]: type }
  const addForDate = (date) => {
    const key = dateKeyOf(date);
    const type = addTypeByDate[key];
    if (!type) return;
    const entry = { label: type, detail: encodeChildTag(formatClock(date, lang), selectedChildId), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("diaper", entry, session, setLog, optimistic.id);
    setAddTypeByDate((prev) => { const next = { ...prev }; delete next[key]; return next; });
  };
  const renderDateAdd = (date) => {
    const key = dateKeyOf(date);
    const selected = addTypeByDate[key];
    return (
      <div style={{ marginTop: 8 }}>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 6 }}>
          {[M.pee, M.poop, M.both].map((type) => (
            <button key={type} onClick={() => setAddTypeByDate((prev) => ({ ...prev, [key]: type }))} style={{
              flex: 1, minWidth: 80, padding: "9px 6px", borderRadius: 10, cursor: "pointer",
              border: `2px solid ${selected === type ? COLORS.sage : "transparent"}`,
              background: "#F0F5EC", color: COLORS.sage, fontWeight: 700, fontSize: 12,
            }}>{type}</button>
          ))}
        </div>
        <button onClick={() => addForDate(date)} disabled={!selected} style={{
          width: "100%", padding: "9px", borderRadius: 10, border: "none", cursor: selected ? "pointer" : "default",
          background: selected ? COLORS.sage : COLORS.line, color: selected ? "#fff" : COLORS.muted,
          fontWeight: 800, fontSize: 12.5,
        }}>{saveLabel}</button>
      </div>
    );
  };

  return (
    <Card>
      <div style={{ background: "#F0F5EC", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <DiaperHeroIllu size={130} />
      </div>
      <ChildSelectorPills kids={kids} selectedChildId={selectedChildId} onSelect={setSelectedChildId} color={COLORS.sage} label={forChildLabel} />
      {!isReadOnlyPartner && (
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 12 }}>
        {[M.pee, M.poop, M.both].map((type) => (
          <button key={type} onClick={() => setSelectedType(type)} style={{
            flex: 1, minWidth: 100, padding: "16px 10px", borderRadius: 14, cursor: "pointer",
            border: `2px solid ${selectedType === type ? COLORS.sage : "transparent"}`,
            background: "#F0F5EC", color: COLORS.sage, fontWeight: 700, fontSize: 14,
          }}>{type}</button>
        ))}
      </div>
      )}
      {!isReadOnlyPartner && (
      <button onClick={add} disabled={!selectedType} style={{
        width: "100%", padding: "14px", borderRadius: 14, border: "none", cursor: selectedType ? "pointer" : "default",
        background: selectedType ? COLORS.sage : COLORS.line, color: selectedType ? "#fff" : COLORS.muted,
        fontWeight: 800, fontSize: 14.5,
      }}>{saveLabel}</button>
      )}
      <TrackerLogList entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId))} emptyLabel={emptyLabel} onDelete={isReadOnlyPartner ? undefined : removeEntry} renderDateAdd={isReadOnlyPartner ? undefined : renderDateAdd} loaded={loaded} lang={lang} />
      <TrackerPdfExport
        lang={lang} printId="diaper-print-view"
        title={lang === "fr" ? "Couches" : lang === "es" ? "Pañales" : "Diapers"}
        entries={stripChildTagFromLog(filterLogByChild(log, selectedChildId)).map((e) => ({ date: e.start || e.createdAt, label: e.label, detail: e.detail }))}
      />
    </Card>
  );
}

function KickTracker({ lang, session, isReadOnlyPartner }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [count, setCount] = useState(0);
  const [sessionStart, setSessionStart] = useState(null);
  const [log, setLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const M = lang === "fr"
    ? { title: "Compte-coups de bébé", subtitle: "Chaque fois que vous sentez bébé bouger ou donner un coup, touchez le bouton — ça compte les mouvements pour surveiller sa forme.", add: "+1 coup", reset: "Sauvegarder", tip: "Le repère habituel est d'environ 10 coups en moins de 2 heures. Si vous en sentez beaucoup moins que d'habitude, contactez votre professionnel de la santé." }
    : lang === "es"
    ? { title: "Contador de movimientos del bebé", subtitle: "Cada vez que sientas al bebé moverse o dar una patada, toca el botón — esto cuenta los movimientos para vigilar su bienestar.", add: "+1 movimiento", reset: "Guardar", tip: "La referencia habitual es de unos 10 movimientos en menos de 2 horas. Si sientes muchos menos de lo habitual, contacta a tu profesional de la salud." }
    : { title: "Baby kick counter", subtitle: "Every time you feel baby move or kick, tap the button — this counts baby's movements to help monitor their wellbeing.", add: "+1 kick", reset: "Save", tip: "A common guideline is about 10 kicks in under 2 hours. If you notice far fewer than usual, contact your healthcare provider." };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "kick", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const add = () => { if (!sessionStart) setSessionStart(new Date()); setCount((c) => c + 1); };
  const reset = () => {
    if (sessionStart) {
      const entry = { label: `${count} ${lang === "fr" ? "coups" : lang === "es" ? "movimientos" : "kicks"}`, detail: `${formatClock(sessionStart, lang)} → ${formatClock(new Date(), lang)}` };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("kick", entry, session, setLog, optimistic.id);
    }
    setCount(0); setSessionStart(null);
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);
  // Ajout rétroactif pour une date passée (ex. « j'ai oublié d'entrer un coup d'hier ») — même
  // bouton « +1 coup », juste appliqué à la date choisie au lieu de maintenant.
  const dateKeyOf = (d) => d.toISOString().slice(0, 10);
  const [countByDate, setCountByDate] = useState({}); // { [dateKey]: count }
  const addForDate = (date) => {
    const key = dateKeyOf(date);
    const c = countByDate[key] || 0;
    if (c <= 0) return;
    const entry = { label: `${c} ${lang === "fr" ? "coups" : lang === "es" ? "movimientos" : "kicks"}`, detail: formatClock(date, lang), createdAt: date };
    const optimistic = makeOptimisticEntry(entry);
    setLog((l) => [...l, optimistic]);
    persistTrackerEntry("kick", entry, session, setLog, optimistic.id);
    setCountByDate((prev) => { const next = { ...prev }; delete next[key]; return next; });
  };
  const renderDateAdd = (date) => {
    const key = dateKeyOf(date);
    const c = countByDate[key] || 0;
    return (
      <div style={{ marginTop: 8, display: "flex", gap: 8 }}>
        <button onClick={() => setCountByDate((prev) => ({ ...prev, [key]: (prev[key] || 0) + 1 }))} style={{
          flex: 1, padding: "9px", borderRadius: 10, border: "none", background: COLORS.ochre, color: "#fff",
          fontWeight: 800, fontSize: 12.5, cursor: "pointer",
        }}>{M.add}{c > 0 ? ` (${c})` : ""}</button>
        <button onClick={() => addForDate(date)} disabled={c === 0} style={{
          padding: "9px 14px", borderRadius: 10, border: `1px solid ${COLORS.line}`, background: "#fff",
          color: COLORS.muted, fontWeight: 700, fontSize: 12, cursor: c > 0 ? "pointer" : "default", opacity: c > 0 ? 1 : 0.5,
        }}>{M.reset}</button>
      </div>
    );
  };

  return (
    <Card>
      <div style={{ background: "#FBF3E4", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <KickHeroIllu size={130} />
      </div>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 17, color: COLORS.teal }}>{M.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.5 }}>{M.subtitle}</p>
      <div style={{ textAlign: "center", marginBottom: 14 }}>
        <div style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 48, color: COLORS.ochre, fontWeight: 700 }}>{count}</div>
        {sessionStart && <div style={{ fontSize: 12.5, color: COLORS.muted }}>{lang === "fr" ? "Depuis" : lang === "es" ? "Desde" : "Since"} {formatClock(sessionStart, lang)}</div>}
      </div>
      {!isReadOnlyPartner && (
      <div style={{ display: "flex", gap: 10 }}>
        <button onClick={add} style={{ flex: 1, padding: "16px", borderRadius: 14, border: "none", background: COLORS.ochre, color: "#fff", fontWeight: 800, fontSize: 15, cursor: "pointer" }}>{M.add}</button>
        <button onClick={reset} disabled={!sessionStart} style={{ padding: "16px 18px", borderRadius: 14, border: `1px solid ${COLORS.line}`, background: "#fff", color: COLORS.muted, fontWeight: 700, fontSize: 13, cursor: sessionStart ? "pointer" : "default", opacity: sessionStart ? 1 : 0.5 }}>{M.reset}</button>
      </div>
      )}
      <p style={{ fontSize: 12, color: COLORS.muted, lineHeight: 1.5, marginTop: 12 }}>{M.tip}</p>
      <TrackerLogList entries={log} emptyLabel={emptyLabel} onDelete={isReadOnlyPartner ? undefined : removeEntry} renderDateAdd={isReadOnlyPartner ? undefined : renderDateAdd} loaded={loaded} lang={lang} />
      <TrackerPdfExport
        lang={lang} printId="kick-print-view" title={M.title}
        entries={log.map((e) => ({ date: e.start || e.createdAt, label: e.label, detail: e.detail }))}
      />
    </Card>
  );
}

// Petit graphique à barres groupées — durée de la contraction (rose) vs. pause avant celle-ci
// (ardoise) — pour visualiser d'un coup d'œil si les contractions se rapprochent et s'allongent,
// plutôt que de devoir lire chaque ligne de texte une par une. Ne montre que les entrées récentes
// qui ont la donnée numérique encodée (les entrées créées avant cet ajout n'en ont pas).
function ContractionChart({ points, lang }) {
  const L = lang === "fr"
    ? { title: "Aperçu visuel", duration: "Durée", interval: "Pause avant", empty: "Le graphique apparaîtra ici dès que vous aurez enregistré quelques contractions." }
    : lang === "es"
    ? { title: "Vista visual", duration: "Duración", interval: "Pausa antes", empty: "El gráfico aparecerá aquí en cuanto registres algunas contracciones." }
    : { title: "Visual overview", duration: "Duration", interval: "Pause before", empty: "The chart will appear here once you've logged a few contractions." };

  if (!points || points.length === 0) {
    return <p style={{ fontSize: 12, color: COLORS.muted, textAlign: "center", padding: "10px 0" }}>{L.empty}</p>;
  }

  const recent = points.slice(-8); // les 8 dernières, pour rester lisible sur un téléphone
  const maxMs = Math.max(...recent.map((p) => Math.max(p.durationMs, p.intervalMs || 0)), 1000);
  const chartH = 120;
  const barMaxH = 84;
  const groupW = 40;
  const barW = 12;
  const chartW = recent.length * groupW;

  const fmtMin = (ms) => {
    const totalSec = Math.round(ms / 1000);
    const m = Math.floor(totalSec / 60);
    const s = totalSec % 60;
    return `${m}:${String(s).padStart(2, "0")}`;
  };

  return (
    <div style={{ marginTop: 4, marginBottom: 4 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
        <p style={{ fontSize: 11.5, color: COLORS.muted, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.03em", margin: 0 }}>{L.title}</p>
        <div style={{ display: "flex", gap: 12, fontSize: 11, color: COLORS.muted }}>
          <span style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 9, height: 9, borderRadius: 3, background: COLORS.pink, display: "inline-block" }} /> {L.duration}</span>
          <span style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 9, height: 9, borderRadius: 3, background: COLORS.slate, display: "inline-block" }} /> {L.interval}</span>
        </div>
      </div>
      <div style={{ overflowX: "auto" }}>
        <svg viewBox={`0 0 ${chartW} ${chartH}`} width={Math.max(chartW, 240)} height={chartH} style={{ display: "block" }}>
          {recent.map((p, i) => {
            const durH = Math.max(3, (p.durationMs / maxMs) * barMaxH);
            const intH = p.intervalMs ? Math.max(3, (p.intervalMs / maxMs) * barMaxH) : 0;
            const gx = i * groupW;
            return (
              <g key={i}>
                <rect x={gx + groupW / 2 - barW - 2} y={barMaxH - durH + 4} width={barW} height={durH} rx={3} fill={COLORS.pink} />
                {p.intervalMs != null && (
                  <rect x={gx + groupW / 2 + 2} y={barMaxH - intH + 4} width={barW} height={intH} rx={3} fill={COLORS.slate} />
                )}
                <text x={gx + groupW / 2} y={barMaxH + 20} textAnchor="middle" fontSize="8" fill={COLORS.muted}>{fmtMin(p.durationMs)}</text>
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

function ContractionTracker({ lang, session, isReadOnlyPartner }) {
  const emptyLabel = lang === "fr" ? "Aucune entrée pour l'instant." : lang === "es" ? "Aún no hay entradas." : "No entries yet.";
  const [active, setActive] = useState(null);
  const [log, setLog] = useState([]);
  // Historique numérique (durée/intervalle en ms) de la session en cours, utilisé pour détecter
  // le motif "5-1-1" en temps réel — distinct de `log` (texte affiché + Supabase) qui ne garde
  // pas ces valeurs sous forme exploitable.
  const [sessionLog, setSessionLog] = useState([]);
  const hasSession = !!(session?.access_token && session?.user?.id);
  const [tick, setTick] = useState(0); // force le re-rendu chaque seconde pour un minuteur "en direct"
  const [notifStatus, setNotifStatus] = useState(
    typeof Notification !== "undefined" ? Notification.permission : "unsupported"
  );
  const notifiedRef = useRef(false);
  const M = lang === "fr"
    ? { start: "Début de contraction", stop: "Fin de contraction", duration: "Durée", interval: "Depuis la précédente",
        tip: "La règle du 5-1-1 (contractions aux 5 minutes, durant 1 minute, depuis 1 heure) est souvent utilisée comme repère pour se rendre à l'hôpital — validez toujours avec votre professionnel de la santé.",
        save: "Sauvegarder", inProgress: "Contraction en cours",
        alertTitle: "Motif 5-1-1 détecté", alertBody: "Vos dernières contractions suivent le rythme du 5-1-1 (environ aux 5 minutes, d'une durée d'environ 1 minute, depuis environ 1 heure). C'est souvent le moment recommandé de contacter votre professionnel de la santé ou de vous rendre à l'hôpital.",
        enableNotif: "Activer les notifications 5-1-1", notifOn: "Notifications activées ✓", notifBlocked: "Notifications bloquées dans le navigateur",
        notifTitle: "Motif 5-1-1 détecté", notifBody: "Vos contractions suivent le rythme du 5-1-1 — envisagez de contacter votre professionnel de la santé.",
      }
    : lang === "es"
    ? { start: "Inicio de contracción", stop: "Fin de contracción", duration: "Duración", interval: "Desde la anterior",
        tip: "La regla del 5-1-1 (contracciones cada 5 minutos, con duración de 1 minuto, durante 1 hora) se usa a menudo como referencia para ir al hospital — confirma siempre con tu profesional de la salud.",
        save: "Guardar", inProgress: "Contracción en curso",
        alertTitle: "Patrón 5-1-1 detectado", alertBody: "Tus últimas contracciones siguen el ritmo del 5-1-1 (cada 5 minutos aprox., de 1 minuto de duración aprox., desde hace 1 hora aprox.). Suele ser el momento recomendado para contactar a tu profesional de la salud o ir al hospital.",
        enableNotif: "Activar notificaciones 5-1-1", notifOn: "Notificaciones activadas ✓", notifBlocked: "Notificaciones bloqueadas en el navegador",
        notifTitle: "Patrón 5-1-1 detectado", notifBody: "Tus contracciones siguen el ritmo del 5-1-1 — considera contactar a tu profesional de la salud.",
      }
    : { start: "Start contraction", stop: "End contraction", duration: "Duration", interval: "Since previous",
        tip: "The 5-1-1 rule (contractions every 5 minutes, lasting 1 minute, for 1 hour) is often used as a guideline for heading to the hospital — always confirm with your healthcare provider.",
        save: "Save", inProgress: "Contraction in progress",
        alertTitle: "5-1-1 pattern detected", alertBody: "Your recent contractions are following the 5-1-1 rhythm (about every 5 minutes, lasting about 1 minute, for about 1 hour). This is often the recommended time to contact your healthcare provider or head to the hospital.",
        enableNotif: "Turn on 5-1-1 notifications", notifOn: "Notifications on ✓", notifBlocked: "Notifications blocked in the browser",
        notifTitle: "5-1-1 pattern detected", notifBody: "Your contractions are following the 5-1-1 rhythm — consider contacting your healthcare provider.",
      };

  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "contraction", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  // Minuteur en direct : re-rend chaque seconde tant qu'une contraction est en cours
  useEffect(() => {
    if (!active) return;
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [active]);

  const toggle = () => {
    if (active) {
      const stopTime = new Date();
      const durationMs = stopTime - active.start;
      const prevStart = log.length > 0 ? log[log.length - 1].start : null;
      const intervalMs = prevStart ? active.start - prevStart : null;
      const entry = {
        start: active.start,
        label: formatClock(active.start, lang),
        detail: encodeContractionData(
          `${M.duration} ${formatDuration(durationMs, lang)}${intervalMs ? ` · ${M.interval} ${formatDuration(intervalMs, lang)}` : ""}`,
          durationMs, intervalMs
        ),
      };
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      persistTrackerEntry("contraction", entry, session, setLog, optimistic.id);
      setSessionLog((s) => [...s, { start: active.start, durationMs, intervalMs }]);
      setActive(null);
    } else {
      setActive({ start: new Date() });
    }
  };
  const removeEntry = (id) => removeTrackerEntry(id, session, setLog);

  // Détection approximative du motif "5-1-1" : contractions ~aux 5 min, durant ~1 min chacune,
  // observées sur une fenêtre d'au moins ~1 heure. Approximation informationnelle uniquement —
  // ne remplace jamais l'avis d'un professionnel de la santé.
  const five11 = useMemo(() => {
    if (sessionLog.length < 4) return false;
    const recent = sessionLog.slice(-8);
    const withInterval = recent.filter((e) => e.intervalMs != null);
    if (withInterval.length < 3) return false;
    const spanMs = recent[recent.length - 1].start - recent[0].start;
    if (spanMs < 50 * 60 * 1000) return false; // au moins ~50 min de suivi continu
    const intervalsOk = withInterval.every((e) => e.intervalMs <= 5.5 * 60 * 1000);
    const durationsOk = recent.every((e) => e.durationMs >= 50 * 1000);
    return intervalsOk && durationsOk;
  }, [sessionLog]);

  useEffect(() => {
    if (five11 && notifStatus === "granted" && !notifiedRef.current) {
      try { new Notification(M.notifTitle, { body: M.notifBody }); } catch {}
      notifiedRef.current = true;
    }
    if (!five11) notifiedRef.current = false;
  }, [five11, notifStatus]);

  const requestNotif = () => {
    if (typeof Notification === "undefined") return;
    Notification.requestPermission().then((p) => setNotifStatus(p));
  };

  return (
    <Card>
      <div style={{ background: "#FDF0F3", borderRadius: 18, padding: "16px", textAlign: "center", marginBottom: 16 }}>
        <ContractionHeroIllu size={130} />
      </div>

      {five11 && (
        <div style={{
          display: "flex", gap: 10, alignItems: "flex-start", background: "#FDECEA", border: "1.5px solid #E8A79A",
          borderRadius: 14, padding: "12px 14px", marginBottom: 14,
        }}>
          <ShieldAlert size={20} color="#B3261E" style={{ flexShrink: 0, marginTop: 1 }} />
          <div>
            <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 800, color: "#B3261E" }}>{M.alertTitle}</p>
            <p style={{ margin: 0, fontSize: 12.5, color: COLORS.text, lineHeight: 1.5 }}>{M.alertBody}</p>
          </div>
        </div>
      )}

      {active && (
        <div style={{ textAlign: "center", marginBottom: 10 }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, color: COLORS.pink, marginBottom: 4 }}>
            <Clock size={14} /> {M.inProgress}
          </div>
          <div style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 30, fontWeight: 800, color: COLORS.pink, letterSpacing: 0.5 }}>
            {formatDuration(new Date() - active.start, lang)}
          </div>
        </div>
      )}

      {!isReadOnlyPartner && (
      <button onClick={toggle} style={{
        width: "100%", padding: "18px", borderRadius: 16, border: "none", cursor: "pointer",
        background: active ? COLORS.pink : "#FDF0F3", color: active ? "#fff" : COLORS.pink,
        fontWeight: 800, fontSize: 15,
      }}>
        {active ? M.save : M.start}
      </button>
      )}

      {notifStatus !== "unsupported" && notifStatus !== "granted" && (
        <button onClick={requestNotif} disabled={notifStatus === "denied"} style={{
          width: "100%", marginTop: 10, padding: "11px", borderRadius: 12, cursor: notifStatus === "denied" ? "default" : "pointer",
          border: `1.5px solid ${COLORS.teal}`, background: "#fff", color: notifStatus === "denied" ? COLORS.muted : COLORS.teal,
          fontWeight: 700, fontSize: 12.5, display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
        }}>
          <BellRing size={15} /> {notifStatus === "denied" ? M.notifBlocked : M.enableNotif}
        </button>
      )}
      {notifStatus === "granted" && (
        <p style={{ fontSize: 11.5, color: COLORS.muted, textAlign: "center", marginTop: 8, display: "flex", alignItems: "center", justifyContent: "center", gap: 5 }}>
          <Bell size={13} /> {M.notifOn}
        </p>
      )}

      <p style={{ fontSize: 12, color: COLORS.muted, lineHeight: 1.5, marginTop: 12 }}>{M.tip}</p>

      <ContractionChart
        points={log.map((e) => decodeContractionData(e.detail)).filter(Boolean)}
        lang={lang}
      />

      <TrackerLogList entries={stripContractionTagFromLog(log)} emptyLabel={emptyLabel} onDelete={isReadOnlyPartner ? undefined : removeEntry} loaded={loaded} lang={lang} />
      <TrackerPdfExport
        lang={lang} printId="contraction-print-view"
        title={lang === "fr" ? "Contractions" : lang === "es" ? "Contracciones" : "Contractions"}
        entries={stripContractionTagFromLog(log).map((e) => ({ date: e.start || e.createdAt, label: e.label, detail: e.detail }))}
      />
    </Card>
  );
}

