function DailyTip({ lang, userProfile, goTo }) {
  const pregnancy = getPregnancyInfo(userProfile?.dueDate, lang);
  const childAges = userProfile?.childrenAgesArr;

  // Choisit une astuce en fonction du jour de l'année pour les conseils liés à l'âge de l'enfant
  // (change chaque jour), mais en fonction de la SEMAINE de grossesse pour les conseils de grossesse
  // (reste stable toute la semaine, change automatiquement quand la grossesse avance d'une semaine).
  const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);

  let tip = null;
  let context = null;
  let label = null;
  let extraNotes = []; // { text, subtab }

  const LN = lang === "fr"
    ? { standard: "Grossesse standard : découvrez le calendrier de suivi habituel et à quoi vous attendre.",
        s3540: "Grossesse 35 à 40 ans : consultez la section dédiée dans Ma grossesse pour voir ce qui change et ce qui reste pareil.",
        s40plus: "Grossesse 40 ans et plus : consultez la section dédiée dans Ma grossesse pour un suivi adapté à votre situation.",
        risque: "Grossesse à risque : consultez la section dédiée dans Ma grossesse pour comprendre à quoi vous attendre et quand consulter rapidement." }
    : lang === "es"
    ? { standard: "Embarazo estándar: descubre el calendario de seguimiento habitual y qué esperar.",
        s3540: "Embarazo de 35 a 40 años: consulta la sección dedicada en Mi embarazo para ver qué cambia y qué sigue igual.",
        s40plus: "Embarazo de 40 años o más: consulta la sección dedicada en Mi embarazo para un seguimiento adaptado a tu situación.",
        risque: "Embarazo de riesgo: consulta la sección dedicada en Mi embarazo para entender qué esperar y cuándo consultar rápidamente." }
    : { standard: "Standard pregnancy: discover the usual follow-up schedule and what to expect.",
        s3540: "Pregnancy 35 to 40: check the dedicated section under My Pregnancy to see what changes and what stays the same.",
        s40plus: "Pregnancy 40 and older: check the dedicated section under My Pregnancy for guidance adapted to your situation.",
        risque: "High-risk pregnancy: check the dedicated section under My Pregnancy to understand what to expect and when to seek care promptly." };

  if (pregnancy) {
    const tierTips = PREGNANCY_TIPS[lang][pregnancy.trimester - 1];
    tip = tierTips[pregnancy.weeks % tierTips.length]; // lié à la semaine de grossesse, pas au jour du calendrier
    context = lang === "fr" ? `Semaine ${pregnancy.weeks} de grossesse` : `Week ${pregnancy.weeks} of pregnancy`;
    label = lang === "fr" ? "💡 Conseil de la semaine" : lang === "es" ? "💡 Consejo de la semana" : "💡 Tip of the week";
    const profile = userProfile?.pregnancyProfile || [];
    if (profile.includes("standard")) extraNotes.push({ text: LN.standard, subtab: "grossesseStandard" });
    if (profile.includes("35to40")) extraNotes.push({ text: LN.s3540, subtab: "grossesse35plus" });
    if (profile.includes("40plus")) extraNotes.push({ text: LN.s40plus, subtab: "grossesse40plus" });
    if (profile.includes("risque")) extraNotes.push({ text: LN.risque, subtab: "grossesseRisque" });
  } else if (childAges && childAges.length > 0 && childAges[0]) {
    const ageYears = Number(childAges[0]);
    const bucket = ageYears < 0.25 ? 0 : ageYears < 0.5 ? 1 : ageYears < 1 ? 2 : ageYears < 2 ? 3 : 4;
    const tierTips = CHILD_TIPS[lang][bucket];
    tip = tierTips[dayOfYear % tierTips.length];
    context = lang === "fr" ? "Astuce du jour" : "Tip of the day";
    label = lang === "fr" ? "💡 Conseil du jour" : lang === "es" ? "💡 Consejo del día" : "💡 Tip of the day";
  }

  if (!tip) return null;

  return (
    <div style={{
      background: `linear-gradient(135deg, #FBF3E4 0%, #FDF0F3 100%)`, borderRadius: 18,
      padding: "16px 18px", marginBottom: 4, border: `1px solid ${COLORS.line}`,
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6, flexWrap: "wrap" }}>
        <span style={{ fontSize: 11.5, fontWeight: 800, color: COLORS.ochre, textTransform: "uppercase", letterSpacing: "0.03em" }}>{label}</span>
        {context && <span style={{ fontSize: 11, color: COLORS.muted, fontWeight: 600 }}>· {context}</span>}
      </div>
      <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.55 }}>{tip.info}</p>
      <p style={{ margin: "8px 0 0", fontSize: 13, color: COLORS.teal, lineHeight: 1.5, fontWeight: 600 }}>
        <span style={{ color: COLORS.sage }}>{lang === "fr" ? "→ À essayer : " : lang === "es" ? "→ Para intentar: " : "→ Try this: "}</span>{tip.tip}
      </p>
      {extraNotes.map((note, i) => (
        <button
          key={i} onClick={() => goTo && goTo("grossesse", note.subtab)}
          style={{
            display: "block", textAlign: "left", background: "none", border: "none", padding: 0, cursor: "pointer",
            margin: "8px 0 0", fontSize: 12, color: COLORS.blue, fontWeight: 600, lineHeight: 1.5, textDecoration: "underline",
          }}
        >{note.text}</button>
      ))}
    </div>
  );
}

/* ---------------- SUGGESTED DOCTOR QUESTIONS (by trimester) ---------------- */
const DOCTOR_QUESTIONS = {
  fr: {
    1: ["Quels suppléments me recommandez-vous ?", "Quels sont les signes qui doivent m'inquiéter à ce stade ?", "Quels aliments dois-je éviter ?", "À quelle fréquence aurai-je des rendez-vous ?"],
    2: ["Quand aurai-je mon échographie morphologique ?", "Est-ce normal de ressentir [tel symptôme] ?", "Devrais-je envisager un dépistage du diabète gestationnel ?", "Quelle activité physique est sécuritaire pour moi ?"],
    3: ["Quels sont les signes de travail que je dois surveiller ?", "Quel est votre protocole pour le dépassement de terme ?", "Quand devrais-je me rendre à l'hôpital ?", "Pouvons-nous discuter de mon plan de naissance ?"],
  },
  en: {
    1: ["What supplements do you recommend?", "What signs should concern me at this stage?", "What foods should I avoid?", "How often will I have appointments?"],
    2: ["When will I have my anatomy ultrasound?", "Is it normal to feel [symptom]?", "Should I consider gestational diabetes screening?", "What physical activity is safe for me?"],
    3: ["What labor signs should I watch for?", "What's your protocol for going past the due date?", "When should I head to the hospital?", "Can we discuss my birth plan?"],
  },
  es: {
    1: ["¿Qué suplementos me recomienda?", "¿Qué señales deben preocuparme en esta etapa?", "¿Qué alimentos debo evitar?", "¿Con qué frecuencia tendré citas?"],
    2: ["¿Cuándo tendré mi ecografía morfológica?", "¿Es normal sentir [tal síntoma]?", "¿Debería considerar el cribado de diabetes gestacional?", "¿Qué actividad física es segura para mí?"],
    3: ["¿Qué señales de trabajo de parto debo vigilar?", "¿Cuál es su protocolo si se pasa la fecha de parto?", "¿Cuándo debería ir al hospital?", "¿Podemos hablar de mi plan de parto?"],
  },
};

// Questions post-accouchement — même forme que DOCTOR_QUESTIONS mais indexées par période (1 = 0-2
// semaines, 2 = 3-6 semaines, 3 = 7 semaines et plus) plutôt que par trimestre.
const POSTPARTUM_QUESTIONS = {
  fr: {
    1: ["Quels sont les signes de complication à surveiller (saignements, fièvre, douleur) ?", "Comment prendre soin de ma cicatrice / mon périnée ?", "Est-ce normal de me sentir aussi fatiguée ou émotive ?", "Quand pourrai-je reprendre mes activités habituelles ?"],
    2: ["Puis-je reprendre une activité physique légère ?", "Mon allaitement se déroule-t-il normalement ?", "Quand aurai-je ma visite postnatale ?", "Quels moyens de contraception me recommandez-vous ?"],
    3: ["Est-ce normal de ressentir [tel symptôme] à ce stade ?", "Quand puis-je reprendre le travail en toute sécurité ?", "Comment savoir si c'est plus que le baby blues ?", "Avez-vous des ressources pour la santé mentale postnatale ?"],
  },
  en: {
    1: ["What complication signs should I watch for (bleeding, fever, pain)?", "How do I care for my incision / perineum?", "Is it normal to feel this tired or emotional?", "When can I resume my usual activities?"],
    2: ["Can I start light physical activity?", "Is my breastfeeding going normally?", "When is my postnatal check-up?", "What contraception options do you recommend?"],
    3: ["Is it normal to feel [symptom] at this stage?", "When can I safely return to work?", "How do I know if it's more than the baby blues?", "Do you have resources for postpartum mental health?"],
  },
  es: {
    1: ["¿Qué señales de complicación debo vigilar (sangrado, fiebre, dolor)?", "¿Cómo debo cuidar mi incisión / periné?", "¿Es normal sentirme tan cansada o emotiva?", "¿Cuándo podré retomar mis actividades habituales?"],
    2: ["¿Puedo comenzar actividad física ligera?", "¿Mi lactancia va normalmente?", "¿Cuándo es mi revisión posparto?", "¿Qué método anticonceptivo me recomienda?"],
    3: ["¿Es normal sentir [tal síntoma] en esta etapa?", "¿Cuándo puedo volver al trabajo con seguridad?", "¿Cómo sé si es más que el baby blues?", "¿Tiene recursos sobre salud mental posparto?"],
  },
};

function DoctorQuestions({ lang, trimester, session }) {
  const L = lang === "fr"
    ? { title: "Questions à poser à votre prochain rendez-vous", subtitle: "Une liste suggérée selon votre trimestre — cochez celles que vous voulez poser." }
    : lang === "es"
    ? { title: "Preguntas para hacer en tu próxima cita", subtitle: "Una lista sugerida según tu trimestre — marca las que quieras preguntar." }
    : { title: "Questions to ask at your next appointment", subtitle: "A suggested list based on your trimester — check off the ones you want to ask." };
  // Les cases cochées sont gardées dans le navigateur (par trimestre, indépendant de la langue
  // puisque les listes de questions sont alignées 1-pour-1 entre fr/es/en) — ça permet au « Résumé
  // pour mon rendez-vous » de reprendre les mêmes questions cochées ici, plutôt que d'avoir deux
  // listes séparées qui se dédoublent.
  const storageKey = mmbScopedKey(`mmb_doctor_q_checked_t${trimester}`, session);
  const [checked, setChecked] = useState({});
  useEffect(() => {
    try {
      const raw = localStorage.getItem(storageKey);
      if (raw) setChecked(JSON.parse(raw));
    } catch {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [trimester]);
  const toggleQuestion = (i) => {
    setChecked((c) => {
      const next = { ...c, [i]: !c[i] };
      try { localStorage.setItem(storageKey, JSON.stringify(next)); } catch {}
      return next;
    });
  };
  const questions = DOCTOR_QUESTIONS[lang][trimester] || DOCTOR_QUESTIONS[lang][1];
  const checkedCount = Object.values(checked).filter(Boolean).length;

  return (
    <Card style={{ marginBottom: 18, borderTop: `4px solid ${COLORS.blue}`, background: "#EAF2F8" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: COLORS.blue, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Stethoscope size={17} color="#fff" />
        </div>
        <h3 style={{ margin: 0, fontSize: 14, fontWeight: 800, letterSpacing: "0.03em", textTransform: "uppercase", color: COLORS.teal }}>{L.title}</h3>
      </div>
      <p style={{ fontSize: 13, color: COLORS.muted, margin: "0 0 16px" }}>{L.subtitle}</p>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {questions.map((q, i) => (
          <label key={i} style={{
            display: "flex", alignItems: "flex-start", gap: 10, background: checked[i] ? "#F0F5EC" : "#fff",
            borderRadius: 12, padding: "11px 14px", cursor: "pointer", boxShadow: "0 1px 4px rgba(91,58,36,0.06)",
          }}>
            <div style={{
              width: 18, height: 18, borderRadius: 6, flexShrink: 0, marginTop: 1,
              border: `2px solid ${checked[i] ? COLORS.sage : COLORS.line}`, background: checked[i] ? COLORS.sage : "#fff",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              {checked[i] && <Check size={12} color="#fff" strokeWidth={3} />}
              <input type="checkbox" checked={!!checked[i]} onChange={() => toggleQuestion(i)} style={{ position: "absolute", opacity: 0, width: 18, height: 18, cursor: "pointer" }} />
            </div>
            <span style={{ fontSize: 13, color: COLORS.text, lineHeight: 1.45, textDecoration: checked[i] ? "line-through" : "none", opacity: checked[i] ? 0.65 : 1 }}>{q}</span>
          </label>
        ))}
      </div>
      {checkedCount > 0 && (
        <p style={{ fontSize: 11.5, color: COLORS.blue, fontWeight: 700, marginTop: 12, marginBottom: 0 }}>
          {checkedCount} / {questions.length}
        </p>
      )}
    </Card>
  );
}

