// Outil unique « Questions au médecin », accessible directement depuis l'accès rapide de la page
// d'accueil — regroupe en un seul outil (par onglets) ce qui était auparavant 3 outils séparés :
// les questions à poser par trimestre, le suivi poids/symptômes, et le résumé imprimable de
// rendez-vous. Détecte le trimestre automatiquement à partir de la date prévue du profil.
// Outil unique et harmonisé « Questions au médecin » — pas d'onglets séparés : le trimestre et la
// date prévue viennent automatiquement du profil, puis tout se fait sur une seule page qui
// s'allonge : questions (suggérées + ajout manuel, repliable), poids, symptômes (repliable), et un
// bouton pour tout télécharger en un seul PDF partageable/imprimable avec les données saisies.
function PregnancyQuestionsQuickTool({ lang, userProfile, session, children: kids }) {
  const hasSession = !!(session?.access_token && session?.user?.id);
  const pregnancy = getPregnancyInfo(userProfile?.dueDate, lang);
  const trimester = pregnancy?.trimester || 1;
  const locale = lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA";

  // Onglet Grossesse / Post-accouchement — le même outil sert aux deux, seule la source de données
  // change (trimestre vs période postpartum, calculée à partir de la date de naissance du dernier
  // enfant enregistré au profil familial).
  const [mode, setMode] = useState("pregnancy");
  const isPost = mode === "postpartum";
  const latestChild = useMemo(() => {
    if (!kids || kids.length === 0) return null;
    const withBirthdate = kids.filter((c) => c.birthdate);
    if (withBirthdate.length === 0) return null;
    return [...withBirthdate].sort((a, b) => new Date(b.birthdate) - new Date(a.birthdate))[0];
  }, [kids]);
  const weeksPostpartum = latestChild?.birthdate
    ? Math.max(0, Math.floor((Date.now() - new Date(latestChild.birthdate + "T12:00:00").getTime()) / (7 * 24 * 3600 * 1000)))
    : null;
  const postpartumPeriod = weeksPostpartum == null ? 1 : weeksPostpartum <= 2 ? 1 : weeksPostpartum <= 6 ? 2 : 3;
  const period = isPost ? postpartumPeriod : trimester;

  const [questionsOpen, setQuestionsOpen] = useState(false);
  const [symptomsOpen, setSymptomsOpen] = useState(false);
  const [moodOpen, setMoodOpen] = useState(false);

  // Questions suggérées — mêmes cases cochées que partout ailleurs dans l'appli (par trimestre,
  // indépendant de la langue). Les questions ajoutées manuellement sont gardées séparément, elles
  // aussi par trimestre, pour ne pas mélanger les deux listes.
  const checkedKey = mmbScopedKey(isPost ? `mmb_post_q_checked_p${period}` : `mmb_doctor_q_checked_t${period}`, session);
  const customKey = mmbScopedKey(isPost ? `mmb_post_q_custom_p${period}` : `mmb_doctor_q_custom_t${period}`, session);
  const [checked, setChecked] = useState({});
  const [customQuestions, setCustomQuestions] = useState([]);
  const [newQuestion, setNewQuestion] = useState("");
  useEffect(() => {
    try { const raw = localStorage.getItem(checkedKey); setChecked(raw ? JSON.parse(raw) : {}); } catch { setChecked({}); }
    try { const raw = localStorage.getItem(customKey); setCustomQuestions(raw ? JSON.parse(raw) : []); } catch { setCustomQuestions([]); }
  }, [checkedKey, customKey]);
  const toggleQuestion = (i) => {
    setChecked((c) => {
      const next = { ...c, [i]: !c[i] };
      try { localStorage.setItem(checkedKey, JSON.stringify(next)); } catch {}
      return next;
    });
  };
  const addCustomQuestion = () => {
    const q = newQuestion.trim();
    if (!q) return;
    setCustomQuestions((list) => {
      const next = [...list, q];
      try { localStorage.setItem(customKey, JSON.stringify(next)); } catch {}
      return next;
    });
    setNewQuestion("");
  };
  const removeCustomQuestion = (i) => {
    setCustomQuestions((list) => {
      const next = list.filter((_, idx) => idx !== i);
      try { localStorage.setItem(customKey, JSON.stringify(next)); } catch {}
      return next;
    });
  };
  const suggestedQuestions = isPost
    ? (POSTPARTUM_QUESTIONS[lang][period] || POSTPARTUM_QUESTIONS[lang][1])
    : (DOCTOR_QUESTIONS[lang][period] || DOCTOR_QUESTIONS[lang][1]);
  const includedSuggested = suggestedQuestions.filter((_, i) => checked[i]);
  const allIncludedQuestions = [...includedSuggested, ...customQuestions];

  // Poids — même table/même mécanisme que les autres trackers rapides (tracker_entries), avec deux
  // types distincts selon l'onglet : "pregWeight"/"pregSymptom" pour la grossesse, "postWeight"/
  // "postSymptom" pour le post-accouchement — pour ne jamais mélanger les deux périodes.
  const todayStr = new Date().toISOString().slice(0, 10);
  const [pregWeightLog, setPregWeightLog] = useState([]);
  const [postWeightLog, setPostWeightLog] = useState([]);
  const [weightForm, setWeightForm] = useState({ date: todayStr, weight: "" });
  const [savingW, setSavingW] = useState(false);
  const [units, setUnits] = useState(lang === "en" ? "imperial" : "metric");

  const [pregSymptomLog, setPregSymptomLog] = useState([]);
  const [postSymptomLog, setPostSymptomLog] = useState([]);
  const [symptomForm, setSymptomForm] = useState({ date: todayStr, symptoms: [], note: "" });
  const [savingS, setSavingS] = useState(false);

  // Humeur (post-accouchement seulement) — même mécanisme (tracker_entries, type "postMood").
  const [postMoodLog, setPostMoodLog] = useState([]);
  const [moodForm, setMoodForm] = useState({ date: todayStr, mood: null, feelings: [], note: "" });
  const [savingM, setSavingM] = useState(false);

  const weightLog = isPost ? postWeightLog : pregWeightLog;
  const setWeightLog = isPost ? setPostWeightLog : setPregWeightLog;
  const symptomLog = isPost ? postSymptomLog : pregSymptomLog;
  const setSymptomLog = isPost ? setPostSymptomLog : setPregSymptomLog;
  const weightTrackerType = isPost ? "postWeight" : "pregWeight";
  const symptomTrackerType = isPost ? "postSymptom" : "pregSymptom";

  // Rendez-vous à venir — inclus automatiquement dans le PDF, sans rien à saisir ici (déjà entrés
  // dans l'outil « Mes rendez-vous »).
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    if (!hasSession) return;
    supabaseFetchTrackerEntries(session.user.id, "pregWeight", session.access_token)
      .then((rows) => setPregWeightLog(rows.map(mapTrackerEntryRow))).catch(() => {});
    supabaseFetchTrackerEntries(session.user.id, "pregSymptom", session.access_token)
      .then((rows) => setPregSymptomLog(rows.map(mapTrackerEntryRow))).catch(() => {});
    supabaseFetchTrackerEntries(session.user.id, "postWeight", session.access_token)
      .then((rows) => setPostWeightLog(rows.map(mapTrackerEntryRow))).catch(() => {});
    supabaseFetchTrackerEntries(session.user.id, "postSymptom", session.access_token)
      .then((rows) => setPostSymptomLog(rows.map(mapTrackerEntryRow))).catch(() => {});
    supabaseFetchTrackerEntries(session.user.id, "postMood", session.access_token)
      .then((rows) => setPostMoodLog(rows.map(mapTrackerEntryRow))).catch(() => {});
    supabaseFetchAppointments(session.user.id, session.access_token)
      .then((rows) => setAppointments(rows.map(mapAppointmentRow))).catch(() => {});
  }, [hasSession, session?.user?.id]);

  const L = lang === "fr"
    ? {
        title: "Questions au médecin", subtitle: "Tout ce qu'il vous faut pour votre prochain rendez-vous — vos questions, votre poids et vos symptômes — réunis en un seul document.",
        postTitle: "Suivi post-accouchement", postSubtitle: "Tout ce qu'il vous faut pour votre visite postnatale — vos questions, votre poids et vos symptômes — réunis en un seul document.",
        tabPregnancy: "Grossesse", tabPostpartum: "Post-accouchement",
        periodLabel: (p) => `${p === 1 ? "0 à 2" : p === 2 ? "3 à 6" : "7 semaines et plus"} — période ${p}`,
        weekPostLabel: (w) => w == null ? "" : `${w} semaine${w > 1 ? "s" : ""} après l'accouchement`,
        noChild: "Ajoutez la date de naissance de bébé dans votre profil familial pour un suivi post-accouchement personnalisé — en attendant, la période 1 (0 à 2 semaines) est affichée par défaut.",
        trimesterLabel: (t) => `${t === 1 ? "1er" : `${t}e`} trimestre`, weekLabel: (w) => `semaine ${w}`, dueLabel: "Accouchement prévu le",
        questionsHeading: "Questions à poser", questionsCount: (n, tot) => `${n} / ${tot}`,
        addQuestionPh: "Ajouter une question personnelle…", addBtn: "Ajouter",
        weightHeading: "Poids", weightLabel: units === "metric" ? "Poids (kg)" : "Poids (lb)", metric: "kg", imperial: "lb",
        symptomsHeading: "Symptômes", noteLabel: "Note (optionnel)", notePh: "Ex. surtout en soirée, s'améliore avec du repos...",
        add: "Ajouter", date: "Date",
        emptyWeight: "Aucune pesée enregistrée.", emptySymptoms: "Aucun symptôme noté.",
        moodHeading: "Comment vous sentez-vous ?", moodQuestion: "Aujourd'hui, dans l'ensemble :",
        feelingsLabel: "Est-ce que ça vous arrive, ces temps-ci ?", moodNotePh: "Un mot sur ce que vous vivez (optionnel)",
        emptyMood: "Aucun suivi d'humeur noté.", moodHistHeading: "Suivi de l'humeur",
        moodDisclaimer: "Ce suivi est un aide-mémoire personnel, pas un outil de diagnostic — s'il ne se sent pas comme vous depuis plus de deux semaines, en parler à un professionnel de la santé est une bonne étape.",
        crisisTitle: "Vous n'êtes pas seule", crisisBody: "Si vous avez des pensées de vous faire du mal ou de faire du mal à votre bébé, parlez-en tout de suite à quelqu'un en qui vous avez confiance ou contactez une ressource d'aide — c'est disponible jour et nuit, gratuitement et confidentiellement.",
        crisisResources: "📞 988 — ligne de crise (Canada et États-Unis, jour et nuit) · ailleurs, contactez la ligne d'aide ou le numéro d'urgence de votre région",
        printBtn: "📄 Télécharger en PDF", printHint: "Sur mobile, choisissez « Enregistrer en PDF » comme imprimante — le document peut ensuite être partagé ou imprimé comme n'importe quel PDF.",
        printedOnLabel: "Généré le", apptsHeading: "Prochains rendez-vous", weightHistHeading: "Historique de poids", symptomsHistHeading: "Symptômes récents",
        disclaimer: "Document généré à partir des données saisies dans l'application « Me My Baby », à titre indicatif seulement — ne remplace pas un dossier médical officiel.",
      }
    : lang === "es"
    ? {
        title: "Preguntas al médico", subtitle: "Todo lo que necesitas para tu próxima cita — tus preguntas, tu peso y tus síntomas — reunidos en un solo documento.",
        postTitle: "Seguimiento posparto", postSubtitle: "Todo lo que necesitas para tu revisión posparto — tus preguntas, tu peso y tus síntomas — reunidos en un solo documento.",
        tabPregnancy: "Embarazo", tabPostpartum: "Posparto",
        periodLabel: (p) => `${p === 1 ? "0 a 2" : p === 2 ? "3 a 6" : "7 semanas o más"} — período ${p}`,
        weekPostLabel: (w) => w == null ? "" : `${w} semana${w > 1 ? "s" : ""} después del parto`,
        noChild: "Agrega la fecha de nacimiento del bebé en tu perfil familiar para un seguimiento posparto personalizado — mientras tanto, se muestra el período 1 (0 a 2 semanas) por defecto.",
        trimesterLabel: (t) => `${t}${t === 1 ? "er" : "do"} trimestre`, weekLabel: (w) => `semana ${w}`, dueLabel: "Parto previsto el",
        questionsHeading: "Preguntas para hacer", questionsCount: (n, tot) => `${n} / ${tot}`,
        addQuestionPh: "Agregar una pregunta personal…", addBtn: "Agregar",
        weightHeading: "Peso", weightLabel: units === "metric" ? "Peso (kg)" : "Peso (lb)", metric: "kg", imperial: "lb",
        symptomsHeading: "Síntomas", noteLabel: "Nota (opcional)", notePh: "Ej. sobre todo en la noche, mejora con descanso...",
        add: "Agregar", date: "Fecha",
        emptyWeight: "No hay pesajes registrados.", emptySymptoms: "No hay síntomas registrados.",
        moodHeading: "¿Cómo te sientes?", moodQuestion: "Hoy, en general:",
        feelingsLabel: "¿Te pasa esto últimamente?", moodNotePh: "Unas palabras sobre lo que sientes (opcional)",
        emptyMood: "No hay seguimiento de ánimo registrado.", moodHistHeading: "Seguimiento del ánimo",
        moodDisclaimer: "Este seguimiento es una nota personal, no una herramienta de diagnóstico — si no te sientes tú misma desde hace más de dos semanas, hablar con un profesional de la salud es un buen paso.",
        crisisTitle: "No estás sola", crisisBody: "Si tienes pensamientos de hacerte daño o de hacerle daño a tu bebé, habla de inmediato con alguien de confianza o contacta un recurso de ayuda — está disponible día y noche, gratis y confidencial.",
        crisisResources: "📞 988 — línea de crisis (Canadá y Estados Unidos, día y noche) · en otros países, contacta la línea de ayuda o el número de emergencias de tu localidad",
        printBtn: "📄 Descargar en PDF", printHint: "En el celular, elige «Guardar como PDF» como impresora — el documento se puede compartir o imprimir como cualquier PDF.",
        printedOnLabel: "Generado el", apptsHeading: "Próximas citas", weightHistHeading: "Historial de peso", symptomsHistHeading: "Síntomas recientes",
        disclaimer: "Documento generado a partir de los datos ingresados en la aplicación «Me My Baby», solo a título indicativo — no reemplaza un expediente médico oficial.",
      }
    : {
        title: "Doctor questions", subtitle: "Everything you need for your next appointment — your questions, your weight and your symptoms — brought together in one document.",
        postTitle: "Postpartum check-up", postSubtitle: "Everything you need for your postnatal visit — your questions, your weight and your symptoms — brought together in one document.",
        tabPregnancy: "Pregnancy", tabPostpartum: "Postpartum",
        periodLabel: (p) => `${p === 1 ? "0 to 2" : p === 2 ? "3 to 6" : "7 weeks and up"} — period ${p}`,
        weekPostLabel: (w) => w == null ? "" : `${w} week${w > 1 ? "s" : ""} after birth`,
        noChild: "Add your baby's birth date in your family profile for a personalized postpartum tracker — in the meantime, period 1 (0 to 2 weeks) is shown by default.",
        trimesterLabel: (t) => `${t === 1 ? "1st" : t === 2 ? "2nd" : "3rd"} trimester`, weekLabel: (w) => `week ${w}`, dueLabel: "Due date",
        questionsHeading: "Questions to ask", questionsCount: (n, tot) => `${n} / ${tot}`,
        addQuestionPh: "Add a personal question…", addBtn: "Add",
        weightHeading: "Weight", weightLabel: units === "metric" ? "Weight (kg)" : "Weight (lb)", metric: "kg", imperial: "lb",
        symptomsHeading: "Symptoms", noteLabel: "Note (optional)", notePh: "E.g. mostly in the evening, better with rest...",
        add: "Add", date: "Date",
        emptyWeight: "No weigh-ins logged.", emptySymptoms: "No symptoms logged.",
        moodHeading: "How are you feeling?", moodQuestion: "Overall, today:",
        feelingsLabel: "Has this been happening lately?", moodNotePh: "A word about how you're doing (optional)",
        emptyMood: "No mood check-ins logged.", moodHistHeading: "Mood check-ins",
        moodDisclaimer: "This check-in is a personal note, not a diagnostic tool — if you haven't felt like yourself for more than two weeks, talking to a healthcare provider is a good step.",
        crisisTitle: "You're not alone", crisisBody: "If you're having thoughts of hurting yourself or your baby, talk to someone you trust right away or reach out to a support line — it's free, confidential, and available day and night.",
        crisisResources: "📞 988 — Suicide Crisis Helpline (Canada and the US, 24/7) · elsewhere, contact your local helpline or emergency number",
        printBtn: "📄 Download as PDF", printHint: "On mobile, choose \"Save as PDF\" as the printer — the document can then be shared or printed like any PDF.",
        printedOnLabel: "Generated on", apptsHeading: "Upcoming appointments", weightHistHeading: "Weight history", symptomsHistHeading: "Recent symptoms",
        disclaimer: "Document generated from data entered in the \"Me My Baby\" app, for information only — does not replace an official medical record.",
      };

  const dateLabelFmt = (d) => d.toLocaleDateString(locale, { day: "numeric", month: "short", year: "numeric" });

  const lbToKg = (lb) => lb / 2.20462;
  const addWeight = async () => {
    if (!weightForm.date || !weightForm.weight) return;
    const val = Number(weightForm.weight);
    if (!val || val <= 0) return;
    const dateObj = new Date(weightForm.date + "T12:00:00");
    const entry = { start: dateObj, createdAt: dateObj, label: `${val.toFixed(1)} ${units === "metric" ? "kg" : "lb"}`, detail: dateLabelFmt(dateObj) };
    setSavingW(true);
    if (hasSession) {
      const optimistic = makeOptimisticEntry(entry);
      setWeightLog((l) => [...l, optimistic]);
      await persistTrackerEntry(weightTrackerType, entry, session, setWeightLog, optimistic.id);
    } else {
      setWeightLog((l) => [...l, { ...entry, id: `local-${Date.now()}` }]);
    }
    setWeightForm({ date: todayStr, weight: "" });
    setSavingW(false);
  };
  const removeWeight = (id) => removeTrackerEntry(id, session, setWeightLog);

  const toggleSymptom = (id) => {
    setSymptomForm((f) => ({ ...f, symptoms: f.symptoms.includes(id) ? f.symptoms.filter((s) => s !== id) : [...f.symptoms, id] }));
  };
  const addSymptoms = async () => {
    if (symptomForm.symptoms.length === 0 && !symptomForm.note.trim()) return;
    const opts = isPost ? (POSTPARTUM_SYMPTOM_OPTIONS[lang] || POSTPARTUM_SYMPTOM_OPTIONS.fr) : (PREG_SYMPTOM_OPTIONS[lang] || PREG_SYMPTOM_OPTIONS.fr);
    const labels = symptomForm.symptoms.map((id) => opts.find((o) => o.id === id)?.label).filter(Boolean);
    const dateObj = new Date(symptomForm.date + "T12:00:00");
    const entry = { start: dateObj, createdAt: dateObj, label: labels.length ? labels.join(", ") : dateLabelFmt(dateObj), detail: symptomForm.note.trim() };
    setSavingS(true);
    if (hasSession) {
      const optimistic = makeOptimisticEntry(entry);
      setSymptomLog((l) => [...l, optimistic]);
      await persistTrackerEntry(symptomTrackerType, entry, session, setSymptomLog, optimistic.id);
    } else {
      setSymptomLog((l) => [...l, { ...entry, id: `local-${Date.now()}` }]);
    }
    setSymptomForm({ date: todayStr, symptoms: [], note: "" });
    setSavingS(false);
  };
  const removeSymptom = (id) => removeTrackerEntry(id, session, setSymptomLog);

  const moodFeelingOptions = MOOD_FEELINGS_OPTIONS[lang] || MOOD_FEELINGS_OPTIONS.fr;
  const toggleMoodFeeling = (id) => {
    setMoodForm((f) => ({ ...f, feelings: f.feelings.includes(id) ? f.feelings.filter((s) => s !== id) : [...f.feelings, id] }));
  };
  const moodSelfHarmFlagged = moodForm.feelings.includes("selfHarm");
  const addMood = async () => {
    if (!moodForm.mood && moodForm.feelings.length === 0 && !moodForm.note.trim()) return;
    const feelingLabels = moodForm.feelings.map((id) => moodFeelingOptions.find((o) => o.id === id)?.label).filter(Boolean);
    const moodPoint = MOOD_SCALE.find((m) => m.v === moodForm.mood);
    const dateObj = new Date(moodForm.date + "T12:00:00");
    const label = moodPoint ? `${moodPoint.emoji} ${moodPoint[lang] || moodPoint.fr}` : (feelingLabels[0] || dateLabelFmt(dateObj));
    const detail = [feelingLabels.join(", "), moodForm.note.trim()].filter(Boolean).join(" — ");
    const entry = { start: dateObj, createdAt: dateObj, label, detail };
    setSavingM(true);
    if (hasSession) {
      const optimistic = makeOptimisticEntry(entry);
      setPostMoodLog((l) => [...l, optimistic]);
      await persistTrackerEntry("postMood", entry, session, setPostMoodLog, optimistic.id);
    } else {
      setPostMoodLog((l) => [...l, { ...entry, id: `local-${Date.now()}` }]);
    }
    setMoodForm({ date: todayStr, mood: null, feelings: [], note: "" });
    setSavingM(false);
  };
  const removeMood = (id) => removeTrackerEntry(id, session, setPostMoodLog);

  const upcomingAppts = appointments.filter((a) => a.date >= todayStr).sort((a, b) => a.date < b.date ? -1 : 1).slice(0, 6);
  const recentWeights = [...weightLog].sort((a, b) => (a.start || a.createdAt) - (b.start || b.createdAt));
  const recentSymptoms = [...symptomLog].sort((a, b) => (b.start || b.createdAt) - (a.start || a.createdAt));
  const recentMoods = [...postMoodLog].sort((a, b) => (b.start || b.createdAt) - (a.start || a.createdAt));
  const printedOn = new Date().toLocaleDateString(locale, { day: "numeric", month: "long", year: "numeric" });

  const inputStyle = { padding: "9px 11px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 13, boxSizing: "border-box" };

  // Chevron rond bien visible (au lieu d'un simple "+"/"−" discret) pour que ce soit clair au
  // premier coup d'œil que la carte se déplie — avec un petit texte d'invite tant qu'elle n'a
  // jamais été ouverte, plutôt que de compter sur l'icône seule pour communiquer "cliquable".
  const collapsibleHeader = (open, setOpen, label, countBadge) => (
    <button onClick={() => setOpen((o) => !o)} style={{
      width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8,
      background: "#EAF2F8", border: `1.5px solid ${COLORS.blue}45`, borderRadius: 12, padding: "13px 15px",
      cursor: "pointer", marginBottom: open ? 10 : 0,
    }}>
      <span style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 2 }}>
        <span style={{ fontSize: 14, fontWeight: 800, color: COLORS.teal, display: "flex", alignItems: "center", gap: 8 }}>
          {label}
          {countBadge != null && (
            <span style={{ fontSize: 11, fontWeight: 800, color: "#fff", background: COLORS.blue, borderRadius: 999, padding: "2px 8px" }}>{countBadge}</span>
          )}
        </span>
        {!open && (
          <span style={{ fontSize: 11, fontWeight: 600, color: COLORS.blue }}>
            {lang === "fr" ? "Touchez pour ouvrir" : lang === "es" ? "Toca para abrir" : "Tap to open"}
          </span>
        )}
      </span>
      <span style={{
        width: 28, height: 28, borderRadius: "50%", background: COLORS.blue, flexShrink: 0,
        display: "flex", alignItems: "center", justifyContent: "center",
      }}>
        <ChevronDown size={17} color="#fff" strokeWidth={2.6} style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform 0.2s ease" }} />
      </span>
    </button>
  );

  return (
    <Card style={{ marginBottom: 18 }}>
      <div style={{ background: "#EAF2F8", borderRadius: 18, padding: "18px 16px", textAlign: "center", marginBottom: 16 }}>
        <div style={{ width: 72, height: 72, borderRadius: "50%", background: COLORS.blue, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto" }}>
          <Stethoscope size={34} color="#fff" />
        </div>
      </div>
      <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal }}>{isPost ? L.postTitle : L.title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: COLORS.muted, lineHeight: 1.5 }}>{isPost ? L.postSubtitle : L.subtitle}</p>

      {/* ---- Onglet Grossesse / Post-accouchement ---- */}
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        {[["pregnancy", L.tabPregnancy], ["postpartum", L.tabPostpartum]].map(([m, label]) => (
          <button key={m} onClick={() => setMode(m)} style={{
            flex: 1, padding: "9px 10px", borderRadius: 10, fontSize: 12.5, fontWeight: 700, cursor: "pointer",
            border: `1.5px solid ${mode === m ? COLORS.blue : COLORS.line}`,
            background: mode === m ? COLORS.blue : "#fff", color: mode === m ? "#fff" : COLORS.text,
          }}>{label}</button>
        ))}
      </div>

      {/* ---- Trimestre / période post-accouchement + date prévue, tirés automatiquement du profil ---- */}
      {!isPost && pregnancy && (
        <p style={{ margin: "0 0 18px", fontSize: 13, fontWeight: 700, color: COLORS.blue, background: "#EAF2F8", borderRadius: 10, padding: "10px 13px", textAlign: "center", lineHeight: 1.5 }}>
          {L.trimesterLabel(pregnancy.trimester)} — {L.weekLabel(pregnancy.weeks)}
          {pregnancy.fmtDue && <><br />{L.dueLabel} {pregnancy.fmtDue}</>}
        </p>
      )}
      {isPost && (
        <p style={{ margin: "0 0 18px", fontSize: 13, fontWeight: 700, color: COLORS.blue, background: "#EAF2F8", borderRadius: 10, padding: "10px 13px", textAlign: "center", lineHeight: 1.5 }}>
          {L.periodLabel(postpartumPeriod)}
          {weeksPostpartum != null && <><br />{L.weekPostLabel(weeksPostpartum)}</>}
          {weeksPostpartum == null && <><br /><span style={{ fontWeight: 500, fontSize: 12 }}>{L.noChild}</span></>}
        </p>
      )}

      {/* ---- Questions (repliable) ---- */}
      {collapsibleHeader(questionsOpen, setQuestionsOpen, L.questionsHeading, L.questionsCount(allIncludedQuestions.length, suggestedQuestions.length + customQuestions.length))}
      {questionsOpen && (
        <div style={{ marginBottom: 18 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 12 }}>
            {suggestedQuestions.map((q, i) => (
              <label key={i} style={{
                display: "flex", alignItems: "flex-start", gap: 10, background: checked[i] ? "#F0F5EC" : "#fff",
                borderRadius: 12, padding: "11px 14px", cursor: "pointer", boxShadow: "0 1px 4px rgba(91,58,36,0.06)",
              }}>
                <div style={{
                  width: 18, height: 18, borderRadius: 6, flexShrink: 0, marginTop: 1,
                  border: `2px solid ${checked[i] ? COLORS.sage : COLORS.line}`, background: checked[i] ? COLORS.sage : "#fff",
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  {checked[i] && <Check size={12} color="#fff" strokeWidth={3} />}
                  <input type="checkbox" checked={!!checked[i]} onChange={() => toggleQuestion(i)} style={{ position: "absolute", opacity: 0, width: 18, height: 18, cursor: "pointer" }} />
                </div>
                <span style={{ fontSize: 13, color: COLORS.text, lineHeight: 1.45, textDecoration: checked[i] ? "line-through" : "none", opacity: checked[i] ? 0.65 : 1 }}>{q}</span>
              </label>
            ))}
            {customQuestions.map((q, i) => (
              <div key={`c${i}`} style={{
                display: "flex", alignItems: "flex-start", gap: 10, background: "#FBF3E4",
                borderRadius: 12, padding: "11px 14px", boxShadow: "0 1px 4px rgba(91,58,36,0.06)",
              }}>
                <span style={{ fontSize: 13, color: COLORS.text, lineHeight: 1.45, flex: 1 }}>{q}</span>
                <button onClick={() => removeCustomQuestion(i)} aria-label="×" style={{ background: "none", border: "none", color: COLORS.muted, cursor: "pointer", padding: 0, flexShrink: 0 }}><X size={15} /></button>
              </div>
            ))}
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <input
              value={newQuestion} onChange={(e) => setNewQuestion(e.target.value)} placeholder={L.addQuestionPh}
              onKeyDown={(e) => { if (e.key === "Enter") addCustomQuestion(); }}
              style={{ ...inputStyle, flex: 1 }}
            />
            <button onClick={addCustomQuestion} style={{
              padding: "9px 16px", borderRadius: 10, border: "none", background: COLORS.blue, color: "#fff",
              fontWeight: 700, fontSize: 13, cursor: "pointer", whiteSpace: "nowrap",
            }}>{L.addBtn}</button>
          </div>
        </div>
      )}

      {/* ---- Poids (toujours visible) ---- */}
      <div style={{ background: "#EAF2F8", borderRadius: 14, padding: "14px 15px", marginBottom: 18 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
          <span style={{ fontSize: 14, fontWeight: 800, color: COLORS.teal }}>{L.weightHeading}</span>
          <div style={{ display: "flex", gap: 6 }}>
            {["metric", "imperial"].map((u) => (
              <button key={u} onClick={() => setUnits(u)} style={{
                padding: "4px 10px", borderRadius: 999, fontSize: 11, fontWeight: 700, cursor: "pointer",
                border: `1px solid ${units === u ? COLORS.blue : COLORS.line}`,
                background: units === u ? COLORS.blue : "#fff", color: units === u ? "#fff" : COLORS.muted,
              }}>{u === "metric" ? L.metric : L.imperial}</button>
            ))}
          </div>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: recentWeights.length ? 10 : 0 }}>
          <input type="date" style={{ ...inputStyle, flex: "1 1 130px", minWidth: 0, boxSizing: "border-box" }} value={weightForm.date} onChange={(e) => setWeightForm({ ...weightForm, date: e.target.value })} />
          <input type="number" step="0.1" placeholder={L.weightLabel} style={{ ...inputStyle, flex: "1 1 100px", minWidth: 0, boxSizing: "border-box" }} value={weightForm.weight} onChange={(e) => setWeightForm({ ...weightForm, weight: e.target.value })} />
          <button onClick={addWeight} disabled={savingW} style={{
            padding: "9px 16px", borderRadius: 10, border: "none", background: COLORS.blue, color: "#fff",
            fontWeight: 700, fontSize: 13, cursor: savingW ? "default" : "pointer", opacity: savingW ? 0.7 : 1, whiteSpace: "nowrap", flexShrink: 0,
          }}>{savingW ? "…" : L.add}</button>
        </div>
        {recentWeights.length > 0 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {[...recentWeights].reverse().slice(0, 4).map((e) => (
              <div key={e.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", fontSize: 12.5, background: "#fff", borderRadius: 8, padding: "6px 10px" }}>
                <span style={{ color: COLORS.muted }}>{dateLabelFmt(e.start || e.createdAt)}</span>
                <span style={{ fontWeight: 700, color: COLORS.text }}>{e.label}</span>
                <button onClick={() => removeWeight(e.id)} style={{ background: "none", border: "none", color: COLORS.muted, cursor: "pointer", padding: 0 }}><X size={13} /></button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ---- Comment vous sentez-vous ? (repliable, post-accouchement seulement) ---- */}
      {isPost && (
        <>
          {collapsibleHeader(moodOpen, setMoodOpen, L.moodHeading, recentMoods.length || null)}
          {moodOpen && (
            <div style={{ marginBottom: 12 }}>
              <p style={{ fontSize: 12.5, fontWeight: 700, color: COLORS.text, marginBottom: 8 }}>{L.moodQuestion}</p>
              <div style={{ display: "flex", gap: 6, marginBottom: 14 }}>
                {MOOD_SCALE.map((m) => (
                  <button key={m.v} onClick={() => setMoodForm((f) => ({ ...f, mood: m.v }))} title={m[lang] || m.fr} style={{
                    flex: 1, padding: "10px 4px", borderRadius: 10, fontSize: 20, cursor: "pointer",
                    border: `1.5px solid ${moodForm.mood === m.v ? COLORS.blue : COLORS.line}`,
                    background: moodForm.mood === m.v ? "#EAF2F8" : "#fff",
                  }}>{m.emoji}</button>
                ))}
              </div>
              <p style={{ fontSize: 12.5, fontWeight: 700, color: COLORS.text, marginBottom: 8 }}>{L.feelingsLabel}</p>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginBottom: 10 }}>
                {moodFeelingOptions.map((f) => {
                  const isOn = moodForm.feelings.includes(f.id);
                  return (
                    <button key={f.id} onClick={() => toggleMoodFeeling(f.id)} style={{
                      padding: "7px 12px", borderRadius: 999, fontSize: 12, fontWeight: 700, cursor: "pointer",
                      border: `1.5px solid ${isOn ? (f.critical ? "#B3261E" : COLORS.blue) : COLORS.line}`,
                      background: isOn ? (f.critical ? "#B3261E" : COLORS.blue) : "#fff",
                      color: isOn ? "#fff" : (f.critical ? "#B3261E" : COLORS.text),
                    }}>{f.label}</button>
                  );
                })}
              </div>
              {moodSelfHarmFlagged && (
                <div style={{ background: "#FDEBEA", border: "1.5px solid #B3261E", borderRadius: 12, padding: "13px 14px", marginBottom: 12 }}>
                  <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 800, color: "#B3261E" }}>{L.crisisTitle}</p>
                  <p style={{ margin: "0 0 8px", fontSize: 12.5, color: "#7A1F1B", lineHeight: 1.5 }}>{L.crisisBody}</p>
                  <p style={{ margin: 0, fontSize: 12.5, fontWeight: 700, color: "#7A1F1B" }}>{L.crisisResources}</p>
                </div>
              )}
              <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 12.5, color: COLORS.muted, fontWeight: 600, marginBottom: 10 }}>
                <textarea rows={2} placeholder={L.moodNotePh} style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit" }} value={moodForm.note} onChange={(e) => setMoodForm((f) => ({ ...f, note: e.target.value }))} />
              </label>
              <button onClick={addMood} disabled={savingM || (!moodForm.mood && moodForm.feelings.length === 0 && !moodForm.note.trim())} style={{
                width: "100%", padding: "11px", borderRadius: 10, border: "none", background: COLORS.blue, color: "#fff",
                fontWeight: 700, fontSize: 13.5, cursor: "pointer", opacity: (savingM || (!moodForm.mood && moodForm.feelings.length === 0 && !moodForm.note.trim())) ? 0.55 : 1, marginBottom: 10,
              }}>{savingM ? "…" : L.add}</button>
              <p style={{ fontSize: 10.5, color: COLORS.muted, lineHeight: 1.5, margin: "0 0 12px" }}>{L.moodDisclaimer}</p>
              {recentMoods.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                  {recentMoods.slice(0, 4).map((e) => (
                    <div key={e.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, fontSize: 12.5, background: "#fff", borderRadius: 8, padding: "7px 10px" }}>
                      <div>
                        <div style={{ color: COLORS.muted, fontSize: 11 }}>{dateLabelFmt(e.start || e.createdAt)}</div>
                        <div style={{ fontWeight: 700, color: COLORS.text }}>{e.label}</div>
                        {e.detail && <div style={{ color: COLORS.muted }}>{e.detail}</div>}
                      </div>
                      <button onClick={() => removeMood(e.id)} style={{ background: "none", border: "none", color: COLORS.muted, cursor: "pointer", padding: 0, flexShrink: 0 }}><X size={13} /></button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </>
      )}

      {/* ---- Symptômes (repliable) ---- */}
      {collapsibleHeader(symptomsOpen, setSymptomsOpen, L.symptomsHeading, recentSymptoms.length || null)}
      {symptomsOpen && (
        <div style={{ marginBottom: 18 }}>
          <input type="date" style={{ ...inputStyle, width: "100%", marginBottom: 10 }} value={symptomForm.date} onChange={(e) => setSymptomForm({ ...symptomForm, date: e.target.value })} />
          <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginBottom: 10 }}>
            {(isPost ? (POSTPARTUM_SYMPTOM_OPTIONS[lang] || POSTPARTUM_SYMPTOM_OPTIONS.fr) : (PREG_SYMPTOM_OPTIONS[lang] || PREG_SYMPTOM_OPTIONS.fr)).map((s) => {
              const isOn = symptomForm.symptoms.includes(s.id);
              return (
                <button key={s.id} onClick={() => toggleSymptom(s.id)} style={{
                  padding: "7px 12px", borderRadius: 999, fontSize: 12, fontWeight: 700, cursor: "pointer",
                  border: `1px solid ${isOn ? COLORS.sage : COLORS.line}`,
                  background: isOn ? COLORS.sage : "#fff", color: isOn ? "#fff" : COLORS.text,
                }}>{s.emoji} {s.label}</button>
              );
            })}
          </div>
          <label style={{ display: "flex", flexDirection: "column", gap: 6, fontSize: 12.5, color: COLORS.muted, fontWeight: 600, marginBottom: 10 }}>
            {L.noteLabel}
            <textarea rows={2} placeholder={L.notePh} style={{ ...inputStyle, resize: "vertical", fontFamily: "inherit" }} value={symptomForm.note} onChange={(e) => setSymptomForm({ ...symptomForm, note: e.target.value })} />
          </label>
          <button onClick={addSymptoms} disabled={savingS || (symptomForm.symptoms.length === 0 && !symptomForm.note.trim())} style={{
            width: "100%", padding: "11px", borderRadius: 10, border: "none", background: COLORS.sage, color: "#fff",
            fontWeight: 700, fontSize: 13.5, cursor: "pointer", opacity: (savingS || (symptomForm.symptoms.length === 0 && !symptomForm.note.trim())) ? 0.55 : 1, marginBottom: recentSymptoms.length ? 12 : 0,
          }}>{savingS ? "…" : L.add}</button>
          {recentSymptoms.length > 0 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {recentSymptoms.slice(0, 4).map((e) => (
                <div key={e.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, fontSize: 12.5, background: "#fff", borderRadius: 8, padding: "7px 10px" }}>
                  <div>
                    <div style={{ color: COLORS.muted, fontSize: 11 }}>{dateLabelFmt(e.start || e.createdAt)}</div>
                    <div style={{ fontWeight: 700, color: COLORS.text }}>{e.label}</div>
                    {e.detail && <div style={{ color: COLORS.muted }}>{e.detail}</div>}
                  </div>
                  <button onClick={() => removeSymptom(e.id)} style={{ background: "none", border: "none", color: COLORS.muted, cursor: "pointer", padding: 0, flexShrink: 0 }}><X size={13} /></button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ---- Un seul bouton pour tout télécharger en PDF ---- */}
      <button onClick={() => window.print()} style={{
        width: "100%", padding: "14px", borderRadius: 12, border: "none", background: COLORS.teal,
        color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer",
      }}>{L.printBtn}</button>
      <p style={{ fontSize: 11, color: COLORS.muted, textAlign: "center", marginTop: 8 }}>{L.printHint}</p>

      {/* ---- Document imprimable / PDF unique, avec toutes les données saisies ---- */}
      <style>{`
        @page { size: letter; margin: 0.5in; }
        @media print {
          html, body { margin: 0 !important; padding: 0 !important; }
          body > *:not(#doctor-questions-print-view) { display: none !important; }
          #doctor-questions-print-view { display: block !important; position: absolute; top: 0; left: 0; }
        }
        @media screen { #doctor-questions-print-view { display: none; } }
      `}</style>
      {createPortal(
        <div id="doctor-questions-print-view" style={{ width: "7.5in", padding: "0.2in", fontFamily: "Georgia, serif", color: "#222" }}>
          <h1 style={{ fontSize: 22, margin: "0 0 4px" }}>{isPost ? L.postTitle : L.title}</h1>
          <p style={{ fontSize: 11, color: "#666", margin: "0 0 4px" }}>{L.printedOnLabel} {printedOn}</p>
          {!isPost && pregnancy && (
            <p style={{ fontSize: 13, fontWeight: 700, margin: "0 0 16px" }}>
              {L.trimesterLabel(pregnancy.trimester)} — {L.weekLabel(pregnancy.weeks)}{pregnancy.fmtDue ? ` — ${L.dueLabel} ${pregnancy.fmtDue}` : ""}
            </p>
          )}
          {isPost && (
            <p style={{ fontSize: 13, fontWeight: 700, margin: "0 0 16px" }}>
              {L.periodLabel(postpartumPeriod)}{weeksPostpartum != null ? ` — ${L.weekPostLabel(weeksPostpartum)}` : ""}
            </p>
          )}

          {upcomingAppts.length > 0 && (
            <>
              <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{L.apptsHeading}</h2>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                <tbody>
                  {upcomingAppts.map((a) => (
                    <tr key={a.id} style={{ borderBottom: "1px solid #ddd" }}>
                      <td style={{ padding: "5px 6px 5px 0", whiteSpace: "nowrap" }}>{dateLabelFmt(new Date(a.date + "T12:00:00"))}</td>
                      <td style={{ padding: "5px 6px" }}>{a.title}</td>
                      <td style={{ padding: "5px 0", color: "#555" }}>{a.location}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {allIncludedQuestions.length > 0 && (
            <>
              <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{L.questionsHeading}</h2>
              <ul style={{ fontSize: 12, margin: "6px 0 0", paddingLeft: 18, lineHeight: 1.7 }}>
                {allIncludedQuestions.map((q, i) => <li key={i}>☐ {q}</li>)}
              </ul>
            </>
          )}

          <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{L.weightHistHeading}</h2>
          {recentWeights.length === 0 ? (
            <p style={{ fontSize: 12, color: "#666" }}>{L.emptyWeight}</p>
          ) : (
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
              <tbody>
                {recentWeights.map((e) => (
                  <tr key={e.id} style={{ borderBottom: "1px solid #ddd" }}>
                    <td style={{ padding: "5px 6px 5px 0", whiteSpace: "nowrap" }}>{dateLabelFmt(e.start || e.createdAt)}</td>
                    <td style={{ padding: "5px 0", fontWeight: 700 }}>{e.label}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{L.symptomsHistHeading}</h2>
          {recentSymptoms.length === 0 ? (
            <p style={{ fontSize: 12, color: "#666" }}>{L.emptySymptoms}</p>
          ) : (
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
              <tbody>
                {recentSymptoms.map((e) => (
                  <tr key={e.id} style={{ borderBottom: "1px solid #ddd" }}>
                    <td style={{ padding: "5px 6px 5px 0", whiteSpace: "nowrap", verticalAlign: "top" }}>{dateLabelFmt(e.start || e.createdAt)}</td>
                    <td style={{ padding: "5px 0" }}>
                      <span style={{ fontWeight: 700 }}>{e.label}</span>
                      {e.detail && <div style={{ color: "#555" }}>{e.detail}</div>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {isPost && recentMoods.length > 0 && (
            <>
              <h2 style={{ fontSize: 15, borderBottom: "1.5px solid #999", paddingBottom: 4, marginTop: 18 }}>{L.moodHistHeading}</h2>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                <tbody>
                  {recentMoods.map((e) => (
                    <tr key={e.id} style={{ borderBottom: "1px solid #ddd" }}>
                      <td style={{ padding: "5px 6px 5px 0", whiteSpace: "nowrap", verticalAlign: "top" }}>{dateLabelFmt(e.start || e.createdAt)}</td>
                      <td style={{ padding: "5px 0" }}>
                        <span style={{ fontWeight: 700 }}>{e.label}</span>
                        {e.detail && <div style={{ color: "#555" }}>{e.detail}</div>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          <p style={{ fontSize: 10, color: "#888", marginTop: 24, lineHeight: 1.5 }}>{L.disclaimer}</p>
        </div>,
        document.body
      )}
    </Card>
  );
}

/* ---------------- IDÉES DE PRÉNOMS (liste partagée maman/papa, table "tracker_entries" type "babyNameIdea") ----------------
   Même table générique que les autres suivis rapides — le sexe et la personne qui a proposé le prénom
   (maman/papa) sont encodés dans le champ "detail" (ex. "fille|papa|0") plutôt que d'ajouter des
   colonnes Supabase. partnerAllowed: true dans QuickTrackerLinks (plus bas) fait que le·la partenaire
   invité·e (qui écrit avec le même effectiveSession que le compte principal) peut ajouter ses propres
   idées — c'est ce qui inclut cet outil dans le partage de compte. */
const BABY_NAME_SEX_OPTIONS = [
  { id: "fille", label: { fr: "Fille", en: "Girl", es: "Niña" } },
  { id: "garcon", label: { fr: "Garçon", en: "Boy", es: "Niño" } },
  { id: "neutre", label: { fr: "Neutre", en: "Either", es: "Neutro" } },
];
const BABY_NAME_BY_OPTIONS = [
  { id: "maman", label: { fr: "Maman", en: "Mom", es: "Mamá" } },
  { id: "papa", label: { fr: "Papa", en: "Dad", es: "Papá" } },
];

function BabyNameIdeasTool({ lang, session, isReadOnlyPartner }) {
  const hasSession = !!(session?.access_token && session?.user?.id);
  const [log, setLog] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [nameInput, setNameInput] = useState("");
  const [sexChoice, setSexChoice] = useState("neutre");
  const [byChoice, setByChoice] = useState(isReadOnlyPartner ? "papa" : "maman");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!hasSession) { setLoaded(true); return; }
    supabaseFetchTrackerEntries(session.user.id, "babyNameIdea", session.access_token)
      .then((rows) => setLog(rows.map(mapTrackerEntryRow)))
      .catch(() => {})
      .finally(() => setLoaded(true));
  }, [hasSession, session?.user?.id]);

  const L = lang === "fr"
    ? {
        title: "Idées de prénoms", subtitle: "Chacun propose ses idées — maman d'un côté, papa de l'autre — et vous les comparez ensemble.",
        namePh: "Ajouter un prénom…", sexLabel: "Sexe", byLabel: "Proposé par", add: "Ajouter",
        mamanHeading: "Idées de maman", papaHeading: "Idées de papa",
        empty: "Aucun prénom proposé pour l'instant.", deleteBtn: "Supprimer",
      }
    : lang === "es"
    ? {
        title: "Ideas de nombres", subtitle: "Cada quien propone sus ideas — mamá por un lado, papá por el otro — y las comparan juntos.",
        namePh: "Agregar un nombre…", sexLabel: "Sexo", byLabel: "Propuesto por", add: "Agregar",
        mamanHeading: "Ideas de mamá", papaHeading: "Ideas de papá",
        empty: "Aún no hay nombres propuestos.", deleteBtn: "Eliminar",
      }
    : {
        title: "Baby name ideas", subtitle: "Everyone adds their own ideas — mom on one side, dad on the other — and you compare together.",
        namePh: "Add a name…", sexLabel: "Sex", byLabel: "Suggested by", add: "Add",
        mamanHeading: "Mom's ideas", papaHeading: "Dad's ideas",
        empty: "No names suggested yet.", deleteBtn: "Delete",
      };

  const encodeDetail = (sexId, byId, fav) => `${sexId}|${byId}|${fav ? 1 : 0}`;
  const decodeDetail = (detail) => {
    const parts = (detail || "").split("|");
    return { sexId: parts[0] || "neutre", byId: parts[1] || "maman", fav: parts[2] === "1" };
  };

  const addName = async () => {
    const name = nameInput.trim();
    if (!name || saving) return;
    setSaving(true);
    const entry = { label: name, detail: encodeDetail(sexChoice, byChoice, false), createdAt: new Date() };
    if (hasSession) {
      const optimistic = makeOptimisticEntry(entry);
      setLog((l) => [...l, optimistic]);
      await persistTrackerEntry("babyNameIdea", entry, session, setLog, optimistic.id);
    } else {
      setLog((l) => [...l, { ...entry, id: `local-${Date.now()}` }]);
    }
    setNameInput("");
    setSaving(false);
  };
  const toggleFav = (e) => {
    const { sexId, byId, fav } = decodeDetail(e.detail);
    updateTrackerEntry(e.id, { detail: encodeDetail(sexId, byId, !fav) }, session, setLog);
  };
  const removeName = (id) => removeTrackerEntry(id, session, setLog);

  const decorated = log.map((e) => ({ ...e, ...decodeDetail(e.detail) }));
  const sortFn = (a, b) => (b.fav - a.fav) || a.label.localeCompare(b.label);
  const mamanList = decorated.filter((e) => e.byId === "maman").sort(sortFn);
  const papaList = decorated.filter((e) => e.byId === "papa").sort(sortFn);

  const sexIcon = (sexId) => (sexId === "fille" ? "🎀" : sexId === "garcon" ? "💙" : "✨");

  // Rangées en carte élégante avec liseré de couleur et prénom en serif — la liste est maintenant
  // le point focal de l'outil, pas juste une liste brute sous le formulaire.
  const nameColumn = (heading, list, accentColor) => (
    <div style={{ flex: 1, minWidth: 140 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 10 }}>
        <div style={{ width: 5, height: 5, borderRadius: "50%", background: accentColor }} />
        <p style={{ margin: 0, fontSize: 12, fontWeight: 800, color: accentColor, textTransform: "uppercase", letterSpacing: "0.04em" }}>{heading}</p>
      </div>
      {list.length === 0 ? (
        <p style={{ fontSize: 12, color: COLORS.muted, fontStyle: "italic" }}>{L.empty}</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {list.map((e) => (
            <div key={e.id} style={{
              display: "flex", alignItems: "center", gap: 9, background: "#fff", borderRadius: 12,
              padding: "11px 13px", borderLeft: `3px solid ${accentColor}`,
              boxShadow: "0 2px 9px rgba(91,58,36,0.07)",
            }}>
              <span style={{ fontSize: 14 }}>{sexIcon(e.sexId)}</span>
              <span style={{ flex: 1, fontFamily: "Fraunces, Georgia, serif", fontSize: 15.5, fontWeight: 700, color: COLORS.teal, minWidth: 0, wordBreak: "break-word" }}>{e.label}</span>
              <button onClick={() => toggleFav(e)} aria-label="♥" style={{ background: "none", border: "none", padding: 2, cursor: "pointer", color: e.fav ? COLORS.pink : COLORS.line, flexShrink: 0 }}>
                <Heart size={16} fill={e.fav ? COLORS.pink : "none"} />
              </button>
              <button onClick={() => removeName(e.id)} aria-label={L.deleteBtn} style={{ background: "none", border: "none", padding: 2, cursor: "pointer", color: COLORS.muted, flexShrink: 0 }}>
                <X size={15} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  return (
    <Card style={{ marginBottom: 18 }}>
      <div style={{ textAlign: "center", marginBottom: 14 }}>
        <div style={{
          width: 52, height: 52, borderRadius: "50%",
          background: `linear-gradient(135deg, ${COLORS.ochre} 0%, ${COLORS.ochre}CC 100%)`,
          display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 10px",
          boxShadow: `0 6px 16px ${COLORS.ochre}45`,
        }}>
          <Sparkles size={24} color="#fff" />
        </div>
        <h3 style={{ margin: "0 0 4px", fontFamily: "Fraunces, Georgia, serif", fontSize: 19, color: COLORS.teal }}>{L.title}</h3>
        <p style={{ margin: "0 auto", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.5, maxWidth: 320 }}>{L.subtitle}</p>
      </div>

      {/* ---- Ajout d'un prénom : volontairement discret et compact, pour laisser toute la place
          à la liste ci-dessous (le vrai point d'intérêt de cet outil). ---- */}
      <div style={{ background: COLORS.cream, border: `1px solid ${COLORS.line}`, borderRadius: 14, padding: "10px 12px", marginBottom: 20 }}>
        <input
          value={nameInput} onChange={(e) => setNameInput(e.target.value)} placeholder={L.namePh}
          onKeyDown={(e) => { if (e.key === "Enter") addName(); }}
          style={{ width: "100%", padding: "8px 10px", borderRadius: 8, border: `1px solid ${COLORS.line}`, fontSize: 12.5, boxSizing: "border-box", marginBottom: 8 }}
        />
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          <div style={{ display: "flex", gap: 4 }}>
            {BABY_NAME_SEX_OPTIONS.map((o) => (
              <button key={o.id} onClick={() => setSexChoice(o.id)} style={{
                padding: "4px 9px", borderRadius: 999, fontSize: 10, fontWeight: 700, cursor: "pointer",
                border: `1px solid ${sexChoice === o.id ? COLORS.ochre : COLORS.line}`,
                background: sexChoice === o.id ? COLORS.ochre : "#fff", color: sexChoice === o.id ? "#fff" : COLORS.muted,
              }}>{o.label[lang]}</button>
            ))}
          </div>
          <div style={{ width: 1, height: 16, background: COLORS.line }} />
          <div style={{ display: "flex", gap: 4 }}>
            {BABY_NAME_BY_OPTIONS.map((o) => (
              <button key={o.id} onClick={() => setByChoice(o.id)} style={{
                padding: "4px 9px", borderRadius: 999, fontSize: 10, fontWeight: 700, cursor: "pointer",
                border: `1px solid ${byChoice === o.id ? COLORS.teal : COLORS.line}`,
                background: byChoice === o.id ? COLORS.teal : "#fff", color: byChoice === o.id ? "#fff" : COLORS.muted,
              }}>{o.label[lang]}</button>
            ))}
          </div>
          <button onClick={addName} disabled={saving || !nameInput.trim()} style={{
            marginLeft: "auto", padding: "6px 16px", borderRadius: 8, border: "none", background: COLORS.ochre, color: "#fff",
            fontWeight: 700, fontSize: 11.5, cursor: "pointer", opacity: (saving || !nameInput.trim()) ? 0.55 : 1,
          }}>{saving ? "…" : L.add}</button>
        </div>
      </div>

      {/* ---- La liste, mise en valeur : grand encadré élégant dans les tons chauds du logo
          (crème/doré), avec les deux colonnes maman/papa. ---- */}
      <div style={{
        background: `linear-gradient(160deg, #FBF3E4 0%, ${COLORS.cream} 100%)`,
        border: `1px solid ${COLORS.ochre}30`, borderRadius: 18, padding: "18px 16px",
        boxShadow: `0 10px 28px ${COLORS.ochre}1A`,
      }}>
        <div style={{ display: "flex", gap: 18, flexWrap: "wrap" }}>
          {nameColumn(L.mamanHeading, mamanList, COLORS.pink)}
          {nameColumn(L.papaHeading, papaList, COLORS.blue)}
        </div>
      </div>
    </Card>
  );
}

// Ordre volontaire des onglets de "Ma grossesse" : d'abord les types de grossesse (même ordre que la
// sélection au formulaire de profil), puis un fil chronologique/pratique logique.
const PREGNANCY_TAB_ORDER = [
  "grossesseStandard", "grossesse35plus", "grossesse40plus", "grossesseRisque", "jumeaux",
  "t1", "t2", "t3", "suivis", "symptomes", "alimentation", "planchePelvien", "trousse",
];

function PregnancySection({ lang, isMember, goTo, initialSub, userProfile, session }) {
  // Le contenu (13 sous-sections) est chargé depuis Supabase au lieu d'être codé en dur dans ce
  // fichier — il n'est téléchargé et gardé en mémoire que si la personne visite réellement cette
  // section, plutôt que dès l'ouverture de l'app.
  const [content, setContent] = useState(null); // null tant que le chargement n'est pas terminé
  const [loadError, setLoadError] = useState(false);
  useEffect(() => {
    let mounted = true;
    supabaseFetchContent("PREGNANCY")
      .then((data) => { if (mounted) setContent(data); })
      .catch(() => { if (mounted) setLoadError(true); });
    return () => { mounted = false; };
  }, []);

  // Permet d'arriver directement sur un sous-onglet précis (ex. depuis un lien "en savoir plus"
  // dans le conseil du jour), plutôt que de toujours retomber sur le premier onglet par défaut.
  const [activeSub, setActiveSub] = useState(initialSub || null);
  const meta = SECTION_META.grossesse;

  // Le composant reste monté quand on navigue d'un sous-onglet à l'autre (ou de l'aperçu vers un
  // sous-onglet) depuis le menu déroulant : on ne repart donc jamais d'un nouveau montage, et
  // useState(initialSub) seul ne verrait jamais ces changements. Sans cet effet, cliquer un
  // sous-onglet alors qu'on est déjà sur "Grossesse" ne faisait donc rien.
  useEffect(() => {
    setActiveSub(initialSub || null);
  }, [initialSub]);

  if (!content) {
    return (
      <div style={{ padding: "60px 20px", textAlign: "center", color: COLORS.muted }}>
        {loadError
          ? (lang === "fr" ? "Impossible de charger le contenu pour le moment. Vérifiez votre connexion et réessayez." : lang === "es" ? "No se pudo cargar el contenido por ahora. Verifica tu conexión e inténtalo de nuevo." : "Couldn't load the content right now. Check your connection and try again.")
          : (lang === "fr" ? "Chargement…" : lang === "es" ? "Cargando…" : "Loading…")}
      </div>
    );
  }

  // « Ma grossesse » (l'onglet lui-même, sans sous-onglet choisi) a maintenant sa propre page
  // d'aperçu — elle ne reprend plus automatiquement le contenu du premier sous-onglet. Cliquer un
  // sous-onglet précis depuis le menu de navigation (qui se déplie) affiche ensuite sa page à lui.
  const currentSub = activeSub && content[activeSub] ? activeSub : null;

  return (
    <div>
      <SectionHero sectionKey="grossesse" lang={lang} />
      <ToyDivider />
      {currentSub ? (
        <>
          <SubtabBody data={content[currentSub]} lang={lang} accent={meta.color} Icon={meta.icon} isMember={isMember} goTo={goTo} />
          {isMember && currentSub === "trousse" && (
            <>
              <MomBagCard lang={lang} />
              <BabyBagCard lang={lang} />
              <HospitalListDownload lang={lang} />
              <BirthPlanTool lang={lang} userProfile={userProfile} session={session} />
            </>
          )}
          {isMember && currentSub === "planchePelvien" && <PelvicFloorPrepTables lang={lang} />}
          {isMember && currentSub === "alimentation" && <FoodMedSafetyChecker lang={lang} />}
          {isMember && currentSub === "alimentation" && <FoodsToFavorCard lang={lang} />}
          {isMember && currentSub === "alimentation" && <FoodsToAvoidCard lang={lang} />}
          {isMember && currentSub === "t1" && <TrimesterFetusTable lang={lang} trimester={1} />}
          {isMember && currentSub === "t1" && <DoctorQuestions lang={lang} trimester={1} session={session} />}
          {isMember && currentSub === "t2" && <TrimesterFetusTable lang={lang} trimester={2} />}
          {isMember && currentSub === "t2" && <DoctorQuestions lang={lang} trimester={2} session={session} />}
          {isMember && currentSub === "t3" && <TrimesterFetusTable lang={lang} trimester={3} />}
          {isMember && currentSub === "t3" && <DoctorQuestions lang={lang} trimester={3} session={session} />}
        </>
      ) : (
        <>
          {/* Espace supplémentaire entre la bande décorative (ours/blocs) juste au-dessus et le
              calculateur, pour qu'ils ne se touchent pas visuellement. */}
          <div style={{ marginTop: 18 }}>
            <PregnancyCalculator lang={lang} />
          </div>
          <WeekStrip lang={lang} />
        </>
      )}
      <ToyDivider />
    </div>
  );
}

// Ordre volontaire des sous-onglets de "Conception" (Supabase ne garantit pas l'ordre des clés).
const CONCEPTION_TAB_ORDER = ["cycle", "fenetre", "prepCorps", "fertilite"];

function ConceptionSection({ lang, isMember, goTo, initialSub, session }) {
  const [content, setContent] = useState(null);
  const [loadError, setLoadError] = useState(false);
  useEffect(() => {
    let mounted = true;
    supabaseFetchContent("CONCEPTION")
      .then((data) => { if (mounted) setContent(data); })
      .catch(() => { if (mounted) setLoadError(true); });
    return () => { mounted = false; };
  }, []);

  // Même mécanique que "Ma grossesse" : permet d'arriver directement sur un sous-onglet précis
  // depuis le menu de navigation déplié, et se resynchronise si on clique un autre sous-onglet
  // alors que le composant est déjà monté.
  const [activeSub, setActiveSub] = useState(initialSub || null);
  const meta = SECTION_META.conception;

  useEffect(() => {
    setActiveSub(initialSub || null);
  }, [initialSub]);

  if (!content) {
    return (
      <div style={{ padding: "60px 20px", textAlign: "center", color: COLORS.muted }}>
        {loadError
          ? (lang === "fr" ? "Impossible de charger le contenu pour le moment. Vérifiez votre connexion et réessayez." : lang === "es" ? "No se pudo cargar el contenido por ahora. Verifica tu conexión e inténtalo de nuevo." : "Couldn't load the content right now. Check your connection and try again.")
          : (lang === "fr" ? "Chargement…" : lang === "es" ? "Cargando…" : "Loading…")}
      </div>
    );
  }

  // « Conception » (l'onglet lui-même) a déjà sa propre page d'aperçu — le calculateur
  // d'ovulation et le suivi de cycle — donc elle ne retombe plus automatiquement sur le premier
  // sous-onglet : ce contenu n'apparaît que si un sous-onglet précis est choisi via le menu.
  const currentSub = activeSub && content[activeSub] ? activeSub : null;
  return (
    <div>
      <SectionHero sectionKey="conception" lang={lang} />
      <ToyDivider />
      {currentSub ? (
        <>
          <SubtabBody data={content[currentSub]} lang={lang} accent={meta.color} Icon={meta.icon} isMember={isMember} goTo={goTo} />
          {isMember && currentSub === "prepCorps" && (
            <>
              <ToyDivider />
              <FoodsCard lang={lang} />
              <FertilityFoodsToAvoidCard lang={lang} />
              <SupplementsCard lang={lang} />
              <TeaInfoCard lang={lang} />
              <TeaRecipesCard lang={lang} />
            </>
          )}
        </>
      ) : (
        <>
          <OvulationCalculator lang={lang} />
          <OvulationExample lang={lang} />
          {isMember ? (
            <CycleTracker lang={lang} session={session} />
          ) : (
            <LockedContent lang={lang} goTo={goTo} />
          )}
        </>
      )}
      <ToyDivider />
    </div>
  );
}

/* ---------------- SHARE BUTTON ---------------- */
function ShareButton({ lang }) {
  const [copied, setCopied] = useState(false);
  const [showManual, setShowManual] = useState(false);

  const L = lang === "fr"
    ? {
        label: "Partager avec une amie / une maman",
        copied: "Lien copié !",
        text: "Je viens de découvrir Me My Baby, une application complète pour la grossesse et le développement de bébé jusqu'à 5 ans. Regarde !",
        manualHint: "Le partage automatique n'est pas disponible ici. Copiez le texte ci-dessous :",
      }
    : lang === "es"
    ? {
        label: "Compartir con una amiga / una mamá",
        copied: "¡Enlace copiado!",
        text: "Acabo de descubrir Me My Baby, una aplicación completa para el embarazo y el desarrollo del bebé hasta los 5 años. ¡Échale un vistazo!",
        manualHint: "El uso compartido automático no está disponible aquí. Copia el texto a continuación:",
      }
    : {
        label: "Share with a friend / a mom",
        copied: "Link copied!",
        text: "I just found Me My Baby, a complete app for pregnancy and baby development up to age 5. Check it out!",
        manualHint: "Automatic sharing isn't available here. Copy the text below:",
      };

  const shareText = `${L.text} ${typeof window !== "undefined" ? window.location.href : ""}`;

  const handleShare = async () => {
    const shareData = { title: "Me My Baby", text: L.text, url: window.location.href };
    // Essaie d'abord le vrai menu de partage natif du téléphone (mobile).
    if (navigator.share) {
      try {
        await navigator.share(shareData);
        return;
      } catch (e) {
        // La personne a simplement annulé/fermé le menu de partage — c'est un choix volontaire,
        // pas une erreur. On ne fait rien de plus, surtout pas afficher la boîte de repli.
        if (e && e.name === "AbortError") return;
        // Sinon (le partage natif n'est vraiment pas disponible ici), on tente le copier-coller.
      }
    }
    // Try copying to clipboard
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        await navigator.clipboard.writeText(shareText);
        setCopied(true);
        setTimeout(() => setCopied(false), 2500);
        return;
      } catch (e) {
        // clipboard permission blocked — fall through to manual box
      }
    }
    // Last resort: show the text so it can be copied by hand
    setShowManual(true);
  };

  return (
    <div style={{ display: "inline-flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
      <button onClick={handleShare} style={{
        display: "inline-flex", alignItems: "center", gap: 9, background: COLORS.card,
        border: `1.5px solid ${COLORS.pink}`, color: COLORS.pink, padding: "11px 20px",
        borderRadius: 999, fontSize: 14, fontWeight: 700, cursor: "pointer",
      }}>
        <Share2 size={16} />
        {copied ? L.copied : L.label}
      </button>
      {showManual && (
        <div style={{ maxWidth: 420, textAlign: "center" }}>
          <p style={{ fontSize: 12, color: COLORS.muted, margin: "0 0 6px" }}>{L.manualHint}</p>
          <input
            readOnly
            value={shareText}
            onFocus={(e) => e.target.select()}
            style={{
              width: "100%", padding: "9px 12px", borderRadius: 10, border: `1px solid ${COLORS.line}`,
              fontSize: 12.5, color: COLORS.text, boxSizing: "border-box", textAlign: "center",
            }}
          />
        </div>
      )}
    </div>
  );
}

