// Date de lancement du déblocage progressif des articles : à partir de cette date, seul un
// sous-ensemble d'ARTICLES est visible (voir getUnlockedArticlesCount), et 4 nouveaux articles
// se débloquent automatiquement chaque semaine qui suit — plutôt que de montrer les 200+ articles
// déjà écrits dès le premier jour. Le tableau ARTICLES lui-même reste trié dans l'ordre où les
// articles doivent apparaître (ordre de déblocage), donc getPublishedArticles se contente de
// prendre les N premiers.
const ARTICLES_LAUNCH_DATE = new Date("2026-09-25T00:00:00Z");
const ARTICLES_INITIAL_COUNT = 8;
const ARTICLES_WEEKLY_COUNT = 4;

// Nombre de semaines complètes écoulées depuis le lancement (0 la première semaine).
function getArticlesWeeksSinceLaunch() {
  const MS_PER_DAY = 24 * 60 * 60 * 1000;
  const daysSince = Math.floor((Date.now() - ARTICLES_LAUNCH_DATE.getTime()) / MS_PER_DAY);
  return Math.max(0, Math.floor(daysSince / 7));
}

// Nombre total d'articles débloqués à ce jour : 8 au lancement, +4 par semaine écoulée, plafonné
// à la taille réelle du bassin (utile si le bassin est plus petit que ce que le calendrier
// donnerait, ou tant qu'on n'a pas encore écrit tous les articles prévus).
function getUnlockedArticlesCount(pool = ARTICLES) {
  const count = ARTICLES_INITIAL_COUNT + getArticlesWeeksSinceLaunch() * ARTICLES_WEEKLY_COUNT;
  return Math.min(count, pool.length);
}

// La liste réellement visible dans l'appli — toujours les N premiers du bassin, où N vient de
// getUnlockedArticlesCount. C'est CETTE liste (et non ARTICLES brut) qui doit être utilisée
// partout où on affiche/compte/recherche des articles.
function getPublishedArticles(pool = ARTICLES) {
  return pool.slice(0, getUnlockedArticlesCount(pool));
}

// Les articles ajoutés cette semaine précisément (la tranche entre le déblocage de la semaine
// précédente et celui de cette semaine) — utilisés pour la section "Nouveautés" en haut de la
// page Articles. À la semaine de lancement (weeksSinceLaunch === 0), "cette semaine" désigne les
// ARTICLES_INITIAL_COUNT premiers articles (il n'y a pas de semaine précédente à comparer).
function getThisWeeksNewArticles(pool = ARTICLES) {
  const weeksSinceLaunch = getArticlesWeeksSinceLaunch();
  const unlocked = getUnlockedArticlesCount(pool);
  const previousUnlocked = weeksSinceLaunch === 0
    ? 0
    : Math.min(ARTICLES_INITIAL_COUNT + (weeksSinceLaunch - 1) * ARTICLES_WEEKLY_COUNT, pool.length);
  return pool.slice(previousUnlocked, unlocked);
}

// Clé localStorage utilisée pour retenir le nombre d'articles débloqués que la personne a déjà
// vus dans la section Articles — comparé au nombre débloqué actuel pour savoir si on doit
// afficher la pastille "nouveauté" dans QuickAccessBar et sur la bannière d'accueil.
const ARTICLES_LAST_SEEN_COUNT_KEY = "articlesLastSeenCount";

function hasUnseenWeeklyArticles() {
  try {
    const seen = window.localStorage.getItem(ARTICLES_LAST_SEEN_COUNT_KEY);
    return seen === null || Number(seen) !== getUnlockedArticlesCount();
  } catch {
    // localStorage indisponible (navigation privée, permissions bloquées, etc.) — on n'affiche
    // simplement pas la pastille plutôt que de faire planter l'appli.
    return false;
  }
}

function markWeeklyArticlesSeen() {
  try {
    window.localStorage.setItem(ARTICLES_LAST_SEEN_COUNT_KEY, String(getUnlockedArticlesCount()));
  } catch {
    // Idem : on ignore silencieusement si l'écriture échoue.
  }
}

function ArticlesSection({ lang }) {
  const [openId, setOpenId] = useState(null);
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState(null); // null = toutes les catégories
  const L = lang === "fr"
    ? {
        title: "Articles", subtitle: "Des réponses claires aux questions que les parents recherchent le plus souvent — sources incluses au bas de chaque article.",
        searchPh: "Rechercher un article (ex. sommeil, nausées...)", newSection: "Nouveautés cette semaine", allArticles: "Tous les articles", allCats: "Tous",
        readMore: "Lire l'article", close: "Réduire", sourcesLabel: "Sources", minRead: (n) => `${n} min de lecture`,
        noResults: "Aucun article ne correspond à votre recherche.",
        rolloutTitle: "De nouveaux articles chaque semaine",
        rolloutDesc: (n) => `${n} nouveaux articles s'ajoutent automatiquement à cette section chaque semaine — revenez régulièrement pour découvrir les derniers.`,
      }
    : lang === "es"
    ? {
        title: "Artículos", subtitle: "Respuestas claras a las preguntas que más buscan los padres — con las fuentes al final de cada artículo.",
        searchPh: "Buscar un artículo (ej. sueño, náuseas...)", newSection: "Novedades de esta semana", allArticles: "Todos los artículos", allCats: "Todos",
        readMore: "Leer el artículo", close: "Reducir", sourcesLabel: "Fuentes", minRead: (n) => `${n} min de lectura`,
        noResults: "Ningún artículo coincide con tu búsqueda.",
        rolloutTitle: "Nuevos artículos cada semana",
        rolloutDesc: (n) => `Cada semana se agregan automáticamente ${n} artículos nuevos a esta sección — vuelve seguido para ver los más recientes.`,
      }
    : {
        title: "Articles", subtitle: "Clear answers to the questions parents search for most — sources included at the bottom of every article.",
        searchPh: "Search articles (e.g. sleep, nausea...)", newSection: "New this week", allArticles: "All articles", allCats: "All",
        readMore: "Read the article", close: "Collapse", sourcesLabel: "Sources", minRead: (n) => `${n} min read`,
        noResults: "No articles match your search.",
        rolloutTitle: "New articles every week",
        rolloutDesc: (n) => `${n} new articles are automatically added to this section every week — check back often to see the latest ones.`,
      };

  const query = search.trim().toLowerCase();
  const matchesQuery = (a) => !query || a.title[lang].toLowerCase().includes(query) || a.excerpt[lang].toLowerCase().includes(query);

  // Déblocage progressif — voir getPublishedArticles/getThisWeeksNewArticles plus haut : seul un
  // sous-ensemble d'ARTICLES est visible (8 au lancement, +4 chaque semaine qui suit), plutôt que
  // le bassin complet d'un coup. "Nouveautés" montre précisément la tranche débloquée cette semaine.
  const published = useMemo(() => getPublishedArticles(), []);
  const featured = useMemo(() => getThisWeeksNewArticles(), []);
  const featuredIds = new Set(featured.map((a) => a.id));

  // Dès que la personne consulte la section Articles, on retient le nombre débloqué actuel
  // pour ne plus afficher la pastille "nouveauté" (barre du bas / bannière d'accueil) jusqu'au
  // prochain déblocage hebdomadaire.
  useEffect(() => {
    markWeeklyArticlesSeen();
  }, []);
  const showFeatured = !query && !activeCategory;
  // Quand la section "Nouveautés" est affichée, la liste du dessous ne répète pas les mêmes
  // articles — elle montre le reste (déjà débloqués auparavant) en format compact.
  const filtered = published.filter((a) => matchesQuery(a) && (!activeCategory || a.category === activeCategory) && (!showFeatured || !featuredIds.has(a.id)));

  const ArticleRow = ({ a, compact }) => {
    const isOpen = openId === a.id;
    const Icon = a.icon;
    const wordCount = a.body[lang].join(" ").split(/\s+/).length;
    const minutes = Math.max(2, Math.round(wordCount / 200));
    return (
      <Card
        style={{
          padding: 0, overflow: "hidden", border: `1px solid ${COLORS.line}`, cursor: "pointer",
          boxShadow: isOpen ? `0 14px 34px ${a.color}30` : "0 2px 8px rgba(91,58,36,0.06)",
          marginBottom: compact ? 0 : 10,
        }}
        onClick={() => setOpenId(isOpen ? null : a.id)}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 14px" }}>
          <div style={{ width: 54, height: 54, borderRadius: 12, flexShrink: 0, overflow: "hidden", position: "relative" }}>
            <img src={a.image.url} alt={a.image.alt[lang]} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 2 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", background: a.color, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                <Icon size={9} color="#fff" strokeWidth={3} />
              </div>
              <span style={{ fontSize: 11, color: COLORS.muted, fontWeight: 600 }}>{L.minRead(minutes)}</span>
            </div>
            <div style={{
              fontFamily: "Fraunces, Georgia, serif", fontSize: 14.5, fontWeight: 700, color: COLORS.teal, lineHeight: 1.3,
              display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden",
            }}>{a.title[lang]}</div>
          </div>
          <ChevronRight size={18} color={a.color} style={{ transform: isOpen ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.2s", flexShrink: 0 }} />
        </div>

        {isOpen && (
          <div style={{ padding: "0 18px 18px" }} onClick={(e) => e.stopPropagation()}>
            <div style={{ paddingTop: 14, borderTop: `1px solid ${COLORS.line}`, cursor: "default", maxWidth: 640 }}>
              <p style={{ fontSize: 13.5, color: COLORS.muted, margin: "0 0 12px", fontStyle: "italic" }}>{a.excerpt[lang]}</p>
              {a.body[lang].map((p, i) => (
                <p key={i} style={{ fontSize: 15, color: COLORS.text, lineHeight: 1.75, margin: "0 0 15px" }}>{p}</p>
              ))}
              <div style={{ marginTop: 4, paddingTop: 14, borderTop: `1px dashed ${COLORS.line}` }}>
                <p style={{ fontSize: 11, fontWeight: 800, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.04em", margin: "0 0 8px" }}>{L.sourcesLabel}</p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {a.sources.map((s, i) => (
                    <a key={i} href={s.url} target="_blank" rel="noopener noreferrer" style={{
                      fontSize: 12, color: a.color, textDecoration: "none", fontWeight: 700,
                      background: `${a.color}14`, border: `1px solid ${a.color}30`, borderRadius: 999, padding: "5px 12px",
                    }}>{s.name}</a>
                  ))}
                </div>
                <p style={{ fontSize: 10.5, color: COLORS.muted, margin: "12px 0 0" }}>
                  {lang === "fr" ? "Photo : Unsplash" : lang === "es" ? "Foto: Unsplash" : "Photo: Unsplash"}
                </p>
              </div>
            </div>
          </div>
        )}
      </Card>
    );
  };

  // Grande carte "vedette" — l'ancien format complet (grande photo, résumé visible) — utilisée
  // uniquement pour la section "Nouveautés" en haut de page. Le reste de la liste (recherche/
  // catégories) reste en format compact, mais les vedettes gardent le look d'origine que Marilyne aime.
  const FeaturedCard = ({ a }) => {
    const isOpen = openId === a.id;
    const Icon = a.icon;
    const wordCount = a.body[lang].join(" ").split(/\s+/).length;
    const minutes = Math.max(2, Math.round(wordCount / 200));
    return (
      <Card
        style={{
          padding: 0, overflow: "hidden", border: `1px solid ${COLORS.line}`, cursor: "pointer",
          gridColumn: isOpen ? "1 / -1" : "auto",
          boxShadow: isOpen ? `0 14px 34px ${a.color}30` : "0 3px 12px rgba(91,58,36,0.07)",
        }}
        onClick={() => setOpenId(isOpen ? null : a.id)}
      >
        <div style={{ position: "relative", height: isOpen ? 220 : 150 }}>
          <img src={a.image.url} alt={a.image.alt[lang]} loading="lazy" style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
          <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(0,0,0,0) 55%, rgba(0,0,0,0.45) 100%)" }} />
          <div style={{
            position: "absolute", bottom: 10, left: 12, display: "flex", alignItems: "center", gap: 6,
            background: "rgba(255,255,255,0.92)", borderRadius: 999, padding: "5px 11px 5px 6px",
          }}>
            <div style={{ width: 22, height: 22, borderRadius: "50%", background: a.color, display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Icon size={12} color="#fff" strokeWidth={2.5} />
            </div>
            <span style={{ fontSize: 11.5, fontWeight: 700, color: COLORS.teal }}>{L.minRead(minutes)}</span>
          </div>
        </div>

        <div style={{ padding: "16px 18px 18px" }}>
          <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
            <div style={{ flex: 1 }}>
              <div style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 18, fontWeight: 700, color: COLORS.teal, marginBottom: 5, lineHeight: 1.3 }}>{a.title[lang]}</div>
              {!isOpen && <p style={{ fontSize: 13.5, color: COLORS.muted, margin: 0, lineHeight: 1.55 }}>{a.excerpt[lang]}</p>}
            </div>
            <ChevronRight size={20} color={a.color} style={{ transform: isOpen ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.2s", flexShrink: 0, marginTop: 3 }} />
          </div>

          {!isOpen && (
            <div style={{ marginTop: 12, fontSize: 13, fontWeight: 700, color: a.color, display: "flex", alignItems: "center", gap: 4 }}>
              {L.readMore} <ChevronRight size={14} />
            </div>
          )}

          {isOpen && (
            <div style={{ marginTop: 14, paddingTop: 16, borderTop: `1px solid ${COLORS.line}`, cursor: "default", maxWidth: 640 }} onClick={(e) => e.stopPropagation()}>
              {a.body[lang].map((p, i) => (
                <p key={i} style={{ fontSize: 15, color: COLORS.text, lineHeight: 1.75, margin: "0 0 15px" }}>{p}</p>
              ))}
              <div style={{ marginTop: 4, paddingTop: 14, borderTop: `1px dashed ${COLORS.line}` }}>
                <p style={{ fontSize: 11, fontWeight: 800, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.04em", margin: "0 0 8px" }}>{L.sourcesLabel}</p>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                  {a.sources.map((s, i) => (
                    <a key={i} href={s.url} target="_blank" rel="noopener noreferrer" style={{
                      fontSize: 12, color: a.color, textDecoration: "none", fontWeight: 700,
                      background: `${a.color}14`, border: `1px solid ${a.color}30`, borderRadius: 999, padding: "5px 12px",
                    }}>{s.name}</a>
                  ))}
                </div>
                <p style={{ fontSize: 10.5, color: COLORS.muted, margin: "12px 0 0" }}>
                  {lang === "fr" ? "Photo : Unsplash" : lang === "es" ? "Foto: Unsplash" : "Photo: Unsplash"}
                </p>
              </div>
            </div>
          )}
        </div>
      </Card>
    );
  };

  return (
    <div>
      {/* En-tête moderne, dans le même langage visuel (dégradé doux + bulle décorative) que le
          reste de l'appli, avec sa propre couleur pour rester cohérente sans dupliquer les autres. */}
      <div style={{
        position: "relative", overflow: "hidden",
        background: `linear-gradient(135deg, ${COLORS.slate}22 0%, ${COLORS.cream} 58%, ${COLORS.slate}14 100%)`,
        border: `1px solid ${COLORS.slate}30`, borderRadius: 22, padding: "26px 28px", marginBottom: 18,
        boxShadow: `0 12px 30px ${COLORS.slate}26`, display: "flex", alignItems: "center", gap: 18,
      }}>
        <div style={{ position: "absolute", top: -34, right: -22, width: 130, height: 130, borderRadius: "50%", background: COLORS.slate, opacity: 0.1, pointerEvents: "none" }} />
        <div style={{
          position: "relative", zIndex: 1, width: 68, height: 68, borderRadius: 20, flexShrink: 0,
          background: `linear-gradient(135deg, ${COLORS.slate} 0%, ${COLORS.slate}CC 100%)`,
          display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 8px 18px ${COLORS.slate}45`,
        }}>
          <ClipboardList size={28} color="#fff" />
        </div>
        <div style={{ position: "relative", zIndex: 1 }}>
          <h2 style={{ margin: "0 0 5px", fontFamily: "Fraunces, Georgia, serif", fontSize: 25, color: COLORS.teal, letterSpacing: "-0.01em" }}>{L.title}</h2>
          <p style={{ margin: 0, color: COLORS.text, opacity: 0.82, fontSize: 14.5, lineHeight: 1.55, maxWidth: 540 }}>{L.subtitle}</p>
        </div>
      </div>

      {/* Bannière mettant en valeur le déblocage progressif : 8 articles au lancement, +4 chaque
          semaine — pour que ce soit bien clair que la bibliothèque grandit plutôt que d'être déjà
          complète, et que la personne comprenne pourquoi elle ne voit pas encore tous les sujets. */}
      <div style={{
        display: "flex", alignItems: "center", gap: 14,
        background: "#FBF1E3",
        border: `1.5px solid ${COLORS.ochre}55`, borderRadius: 18, padding: "16px 20px", marginBottom: 18,
      }}>
        <div style={{
          width: 42, height: 42, borderRadius: 14, flexShrink: 0,
          background: COLORS.ochre, display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          <Sparkles size={20} color="#fff" />
        </div>
        <div>
          <p style={{ margin: "0 0 2px", fontWeight: 800, fontSize: 14.5, color: COLORS.teal, fontFamily: "Fraunces, Georgia, serif" }}>{L.rolloutTitle}</p>
          <p style={{ margin: 0, fontSize: 13, color: COLORS.text, opacity: 0.85, lineHeight: 1.5 }}>{L.rolloutDesc(ARTICLES_WEEKLY_COUNT)}</p>
        </div>
      </div>

      {/* Recherche par mots-clés du titre/résumé */}
      <div style={{ position: "relative", marginBottom: 16 }}>
        <Search size={17} color={COLORS.muted} style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)" }} />
        <input
          value={search} onChange={(e) => setSearch(e.target.value)} placeholder={L.searchPh}
          style={{
            width: "100%", padding: "12px 14px 12px 40px", borderRadius: 14, border: `1px solid ${COLORS.line}`,
            fontSize: 14, boxSizing: "border-box", background: "#fff",
          }}
        />
      </div>

      {/* Filtres par sujet — permet de retrouver rapidement une catégorie sans faire défiler toute la liste */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 20 }}>
        <button
          onClick={() => setActiveCategory(null)}
          style={{
            padding: "7px 15px", borderRadius: 999, border: `1px solid ${!activeCategory ? COLORS.teal : COLORS.line}`,
            background: !activeCategory ? COLORS.teal : "#fff", color: !activeCategory ? "#fff" : COLORS.text,
            fontSize: 12.5, fontWeight: 700, cursor: "pointer",
          }}
        >{L.allCats}</button>
        {ARTICLE_CATEGORIES.map((c) => (
          <button
            key={c.id}
            onClick={() => setActiveCategory(activeCategory === c.id ? null : c.id)}
            style={{
              padding: "7px 15px", borderRadius: 999, border: `1px solid ${activeCategory === c.id ? c.color : COLORS.line}`,
              background: activeCategory === c.id ? c.color : "#fff", color: activeCategory === c.id ? "#fff" : COLORS.text,
              fontSize: 12.5, fontWeight: 700, cursor: "pointer",
            }}
          >{c.label[lang]}</button>
        ))}
      </div>

      {/* Nouveautés — les articles les plus récemment ajoutés, en format compact "vedette" —
          l'idée étant que de nouveaux articles s'ajoutent chaque semaine à cette liste. */}
      {showFeatured && (
        <div style={{ marginBottom: 28 }}>
          <h3 style={{ fontSize: 13, fontWeight: 800, color: COLORS.slate, textTransform: "uppercase", letterSpacing: "0.04em", margin: "0 0 10px" }}>
            ✨ {L.newSection}
          </h3>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 16 }}>
            {featured.map((a) => <FeaturedCard key={a.id} a={a} />)}
          </div>
        </div>
      )}

      {filtered.length === 0 ? (
        <p style={{ textAlign: "center", color: COLORS.muted, fontSize: 14, padding: "30px 0" }}>{L.noResults}</p>
      ) : (
        <div>
          {showFeatured && (
            <h3 style={{ fontSize: 13, fontWeight: 800, color: COLORS.muted, textTransform: "uppercase", letterSpacing: "0.04em", margin: "0 0 10px" }}>
              {L.allArticles}
            </h3>
          )}
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {filtered.map((a) => <ArticleRow key={a.id} a={a} compact />)}
          </div>
        </div>
      )}
    </div>
  );
}

