function MenuMealCell({ meal, lang, color, onSelect }) {
  return (
    <div
      onClick={() => onSelect(meal)}
      style={{ display: "flex", flexDirection: "column", alignItems: "center", flex: 1, minWidth: 0, cursor: "pointer" }}
    >
      <div style={{
        width: 44, height: 44, borderRadius: 12, background: "#fff", marginBottom: 3,
        display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 1px 4px rgba(91,58,36,0.10)",
      }}>
        <Illustration type={meal.icon} size={32} />
      </div>
      <div style={{ fontSize: 8.5, color: COLORS.text, lineHeight: 1.2, textAlign: "center" }}>{meal[lang]}</div>
      <div style={{ fontSize: 7, color: color, fontWeight: 700, textDecoration: "underline", marginTop: 1 }}>
        {lang === "fr" ? "Voir la recette" : lang === "es" ? "Ver la receta" : "View recipe"}
      </div>
    </div>
  );
}

function RecipeDetailView({ meal, lang, color, onBack, servings }) {
  const L = lang === "fr"
    ? { back: "← Retour au menu", ingredients: "Ingrédients", steps: "Préparation", method: "Mode de cuisson", forPeople: (n) => `Pour ${n} personne${n > 1 ? "s" : ""}` }
    : lang === "es"
    ? { back: "← Volver al menú", ingredients: "Ingredientes", steps: "Preparación", method: "Modo de cocción", forPeople: (n) => `Para ${n} persona${n > 1 ? "s" : ""}` }
    : { back: "← Back to menu", ingredients: "Ingredients", steps: "Method", method: "Cooking method", forPeople: (n) => `For ${n} ${n > 1 ? "people" : "person"}` };

  const recipe = meal.recipe;
  const hasStructuredData = Array.isArray(recipe?.ingredients);
  const base = recipe?.baseServings || 2;
  const ratio = (servings || base) / base;

  // Arrondit intelligemment : entiers pour les unités comptables, dixièmes sinon.
  const scaleAmount = (amount, unit) => {
    const scaled = amount * ratio;
    if (unit === "unité" || unit === "mesure") return Math.max(1, Math.round(scaled));
    return scaled % 1 === 0 ? scaled : Math.round(scaled * 10) / 10;
  };

  return (
    <Card style={{ marginBottom: 18, border: "none", background: "#fff" }}>
      <button onClick={onBack} style={{
        background: "none", border: "none", color: color, fontSize: 13, fontWeight: 700,
        cursor: "pointer", padding: 0, marginBottom: 16,
      }}>{L.back}</button>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 10 }}>
        <div style={{
          width: 72, height: 72, borderRadius: 18, background: `${color}1F`, flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "center",
        }}>
          <Illustration type={meal.icon} size={54} />
        </div>
        <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, lineHeight: 1.2 }}>{meal[lang]}</h2>
      </div>

      {hasStructuredData && (
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 18 }}>
          <span style={{ background: `${color}1F`, color, borderRadius: 999, padding: "5px 12px", fontSize: 12, fontWeight: 700 }}>{L.forPeople(servings || base)}</span>
          {recipe.method?.[lang] && <span style={{ background: COLORS.cream, color: COLORS.muted, borderRadius: 999, padding: "5px 12px", fontSize: 12, fontWeight: 600 }}>🍳 {recipe.method[lang]}</span>}
          {recipe.tempC && <span style={{ background: COLORS.cream, color: COLORS.muted, borderRadius: 999, padding: "5px 12px", fontSize: 12, fontWeight: 600 }}>🌡️ {recipe.tempC} °C</span>}
          {recipe.durationMin && <span style={{ background: COLORS.cream, color: COLORS.muted, borderRadius: 999, padding: "5px 12px", fontSize: 12, fontWeight: 600 }}>⏱️ {recipe.durationMin} min</span>}
        </div>
      )}

      <div style={{ marginBottom: 16 }}>
        <h3 style={{ margin: "0 0 8px", fontSize: 12, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.03em", color: color }}>{L.ingredients}</h3>
        {hasStructuredData ? (
          <ul style={{ margin: 0, listStyle: "none", background: `${color}14`, borderRadius: 12, padding: "12px 14px" }}>
            {recipe.ingredients.map((ing, i) => (
              <li key={i} style={{ fontSize: 14, color: COLORS.text, lineHeight: 1.8, display: "flex", justifyContent: "space-between", gap: 10 }}>
                <span>{ing[lang]}</span>
                <span style={{ fontWeight: 700, color: color, flexShrink: 0 }}>{scaleAmount(ing.amount, ing.unit)} {ing.unit === "unité" ? "" : ing.unit === "mesure" ? (lang === "fr" ? "mesure(s)" : lang === "es" ? "medida(s)" : "scoop(s)") : ing.unit}</span>
              </li>
            ))}
          </ul>
        ) : (
          <p style={{ margin: 0, fontSize: 14, color: COLORS.text, lineHeight: 1.6, background: `${color}14`, borderRadius: 12, padding: "12px 14px" }}>
            {recipe.ing?.[lang]}
          </p>
        )}
      </div>
      <div>
        <h3 style={{ margin: "0 0 8px", fontSize: 12, fontWeight: 800, textTransform: "uppercase", letterSpacing: "0.03em", color: color }}>{L.steps}</h3>
        {hasStructuredData ? (
          <ol style={{ margin: 0, padding: "0 0 0 20px" }}>
            {recipe.steps.map((s, i) => (
              <li key={i} style={{ fontSize: 14, color: COLORS.text, lineHeight: 1.7, marginBottom: 8 }}>{s[lang]}</li>
            ))}
          </ol>
        ) : (
          <p style={{ margin: 0, fontSize: 14, color: COLORS.text, lineHeight: 1.7 }}>
            {recipe.steps?.[lang]}
          </p>
        )}
      </div>
    </Card>
  );
}

// Nettoie un nom d'ingrédient pour la liste d'épicerie en retirant les précisions de coupe/
// préparation ("en dés", "tranché", "grillée", "(conserve)"...) qui font en sorte que le même
// ingrédient de base apparaît en plusieurs lignes distinctes selon la recette (ex. "Concombre en
// dés" et "Concombre tranché" restaient 2 lignes séparées alors qu'on achète le même concombre).
// On garde volontairement les mots qui désignent un produit vraiment différent (ex. "cerises",
// "grec", "noir", "de cidre") — seules les précisions de coupe/cuisson sont retirées.
function cleanGroceryIngredientName(raw, lang) {
  if (!raw) return raw;
  let s = raw.trim();
  // NB : on utilise (?=\s|$) plutôt que \b comme frontière de fin — après une lettre accentuée
  // (é, à...), \b ne se comporte pas de façon fiable en JavaScript (les accents ne sont pas
  // reconnus comme des caractères "de mot"), ce qui empêchait certains mots comme "tranché" de
  // se faire retirer correctement.
  if (lang === "fr") {
    s = s.replace(/\s*\((conserve|frais|fraîche|surgelé|surgelée|congelé|congelée)\)\s*/gi, "");
    s = s.replace(/\s+coupée?s?\s+en\s+(deux|dés|tranches|quartiers|lanières|morceaux|cubes|rondelles)(?=\s|$)/gi, "");
    s = s.replace(/\s+en\s+(dés|tranches|quartiers|lanières|morceaux|cubes|rondelles)(?=\s|$)/gi, "");
    s = s.replace(/\s+(tranchée?s?|râpée?s?|grillée?s?|hachée?s?|émincée?s?|effilée?s?)(?=\s|$)/gi, "");
    s = s.replace(/^Poitrines(?=\s|$)/i, "Poitrine");
    s = s.replace(/^Cuisses(?=\s|$)/i, "Cuisse");
    s = s.replace(/^Filets(?=\s|$)/i, "Filet");
  } else if (lang === "es") {
    s = s.replace(/\s*\((enlatad[oa]s?|fresc[oa]s?|congelad[oa]s?)\)\s*/gi, "");
    s = s.replace(/\s+cortad[oa]s?\s+en\s+(dos|cubos|rodajas|cuartos|tiras|trozos)(?=\s|$)/gi, "");
    s = s.replace(/\s+en\s+(cubos|rodajas|cuartos|tiras|trozos)(?=\s|$)/gi, "");
    s = s.replace(/\s+(rebanad[oa]s?|rallad[oa]s?|a la parrilla|picad[oa]s?|trocead[oa]s?)(?=\s|$)/gi, "");
    s = s.replace(/^Pechugas(?=\s|$)/i, "Pechuga");
    s = s.replace(/^Muslos(?=\s|$)/i, "Muslo");
  } else {
    s = s.replace(/\s*\((canned|fresh|frozen)\)\s*/gi, "");
    s = s.replace(/\s+cut\s+in\s+(half|halves|quarters|cubes|strips)(?=\s|$)/gi, "");
    s = s.replace(/\s+(diced|sliced|grated|chopped|cubed|julienned|shredded|minced|grilled)(?=\s|$)/gi, "");
    s = s.replace(/^Breasts(?=\s|$)/i, "Breast");
    s = s.replace(/^Thighs(?=\s|$)/i, "Thigh");
  }
  s = s.replace(/\s{2,}/g, " ").trim();
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function WeeklyMenuTable({ menuKey, lang, onSelectRecipe }) {
  const menu = WEEKLY_MENUS[menuKey];
  const days = MENU_DAYS[lang];
  const mealLabels = lang === "fr" ? { b: "Déj.", l: "Dîn.", d: "Sou." } : lang === "es" ? { b: "Des.", l: "Alm.", d: "Cen." } : { b: "Br.", l: "Lu.", d: "Di." };
  const [servings, setServings] = useState(2);
  const pick = (meal) => onSelectRecipe({ meal, color: menu.color, servings });
  const [showGrocery, setShowGrocery] = useState(false);
  const [checkedItems, setCheckedItems] = useState(new Set());
  const [showOnlySelected, setShowOnlySelected] = useState(false);
  const [showShareOptions, setShowShareOptions] = useState(false);
  const [shareCopied, setShareCopied] = useState(false);

  const L = lang === "fr"
    ? { grocery: "🛒 Générer ma liste d'épicerie", groceryTitle: "Liste d'épicerie de la semaine", close: "Fermer", servingsLabel: "Portions",
        showSelected: "Afficher seulement ma sélection", showAll: "Afficher tout", noneSelected: "Aucun article sélectionné pour l'instant.",
        share: "📤 Partager", shareEmail: "📧 Courriel", shareSms: "💬 Texto", shareOther: "🔗 Autre", copied: "Copié !" }
    : lang === "es"
    ? { grocery: "🛒 Generar mi lista de compras", groceryTitle: "Lista de compras de la semana", close: "Cerrar", servingsLabel: "Porciones",
        showSelected: "Mostrar solo mi selección", showAll: "Mostrar todo", noneSelected: "Ningún artículo seleccionado todavía.",
        share: "📤 Compartir", shareEmail: "📧 Correo", shareSms: "💬 SMS", shareOther: "🔗 Otro", copied: "¡Copiado!" }
    : { grocery: "🛒 Generate my grocery list", groceryTitle: "This week's grocery list", close: "Close", servingsLabel: "Servings",
        showSelected: "Show only my selection", showAll: "Show all", noneSelected: "No items selected yet.",
        share: "📤 Share", shareEmail: "📧 Email", shareSms: "💬 Text", shareOther: "🔗 Other", copied: "Copied!" };

  // La rotation change automatiquement le point de départ du menu chaque semaine calendaire
  const weekDates = getCurrentWeekDates();
  const weekNumber = getISOWeekNumber(weekDates[0]);
  const offset = weekNumber % menu.days.length;
  const rangeLabel = lang === "fr"
    ? `Semaine du ${formatShortDate(weekDates[0], lang)} au ${formatShortDate(weekDates[6], lang)}`
    : lang === "es"
    ? `Semana del ${formatShortDate(weekDates[0], lang)} al ${formatShortDate(weekDates[6], lang)}`
    : `Week of ${formatShortDate(weekDates[0], lang)} – ${formatShortDate(weekDates[6], lang)}`;

  const groceryItems = useMemo(() => {
    // Additionne les quantités du même ingrédient au lieu de créer une ligne distincte par
    // quantité rencontrée (ex. "Huile d'olive" apparaissait en 10 ml, 15 ml, 20 ml et 30 ml comme
    // 4 lignes séparées) — la clé de regroupement est le nom + l'unité, jamais la quantité.
    const totals = new Map();
    const legacySet = new Set();
    for (let i = 0; i < days.length; i++) {
      const day = menu.days[(offset + i) % menu.days.length];
      [day.b, day.l, day.d].forEach((meal) => {
        const r = meal?.recipe;
        if (!r) return;
        // Format structuré (avec quantités) — le nom + la quantité ajustée selon le nombre de portions.
        if (Array.isArray(r.ingredients)) {
          const ratio = servings / (r.baseServings || 2);
          r.ingredients.forEach((ing) => {
            const isCount = ing.unit === "unité" || ing.unit === "mesure";
            const amt = ing.amount * ratio;
            const unitLabel = ing.unit === "unité" ? "" : ing.unit === "mesure" ? (lang === "fr" ? "mesure(s)" : lang === "es" ? "medida(s)" : "scoop(s)") : ing.unit;
            const name = cleanGroceryIngredientName(ing[lang], lang);
            const key = `${name}|${unitLabel}`;
            const existing = totals.get(key);
            if (existing) existing.amount += amt;
            else totals.set(key, { name, unitLabel, amount: amt, isCount });
          });
          return;
        }
        // Ancien format (texte libre, sans quantités) — conservé le temps que tous les menus soient migrés.
        const ing = r.ing?.[lang];
        if (!ing) return;
        ing.split(",").forEach((part) => {
          const clean = part.trim().replace(/^et\s+/i, "").replace(/^and\s+/i, "");
          if (clean) legacySet.add(cleanGroceryIngredientName(clean, lang));
        });
      });
    }
    const structured = Array.from(totals.values()).map(({ name, unitLabel, amount, isCount }) => {
      const finalAmt = isCount ? Math.max(1, Math.round(amount)) : Math.round(amount * 10) / 10;
      return `${name} — ${finalAmt}${unitLabel ? " " + unitLabel : ""}`.trim();
    });
    return [...structured, ...legacySet].sort((a, b) => a.localeCompare(b));
  }, [menu, offset, lang, days.length, servings]);

  return (
    <Card style={{ marginBottom: 18, border: "none", background: "#fff" }}>
      <h3 style={{ margin: "0 0 2px", fontFamily: "Fraunces, Georgia, serif", fontSize: 21, fontWeight: 700, color: menu.color }}>{menu.title[lang]}</h3>
      <p style={{ margin: "0 0 12px", fontSize: 12.5, fontWeight: 600, color: COLORS.muted }}>{rangeLabel}</p>

      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
        <span style={{ fontSize: 11.5, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase" }}>{L.servingsLabel}</span>
        {[1, 2, 4].map((n) => (
          <button
            key={n} onClick={() => setServings(n)}
            style={{
              width: 30, height: 30, borderRadius: "50%", border: `1px solid ${servings === n ? menu.color : COLORS.line}`,
              background: servings === n ? menu.color : "#fff", color: servings === n ? "#fff" : COLORS.text,
              fontWeight: 700, fontSize: 13, cursor: "pointer",
            }}
          >{n}</button>
        ))}
      </div>

      <div style={{ display: "flex", gap: 14, marginBottom: 12, fontSize: 10, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase", paddingLeft: 58 }}>
        <span style={{ flex: 1, textAlign: "center" }}>{mealLabels.b}</span>
        <span style={{ flex: 1, textAlign: "center" }}>{mealLabels.l}</span>
        <span style={{ flex: 1, textAlign: "center" }}>{mealLabels.d}</span>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 14 }}>
        {days.map((_, i) => {
          const day = menu.days[(offset + i) % menu.days.length];
          return (
            <div key={i} style={{
              display: "flex", alignItems: "center", gap: 8, background: `${menu.color}1F`,
              borderRadius: 14, padding: "8px 8px", borderLeft: `4px solid ${menu.color}`,
            }}>
              <span style={{
                width: 50, flexShrink: 0, fontSize: 10.5, fontWeight: 800, color: "#fff",
                background: menu.color, borderRadius: 999, padding: "4px 2px", textAlign: "center", lineHeight: 1.3,
              }}>{days[i].slice(0, 3)}<br /><span style={{ fontWeight: 600, opacity: 0.85 }}>{formatShortDate(weekDates[i], lang)}</span></span>
              <MenuMealCell meal={day.b} lang={lang} color={menu.color} onSelect={pick} />
              <MenuMealCell meal={day.l} lang={lang} color={menu.color} onSelect={pick} />
              <MenuMealCell meal={day.d} lang={lang} color={menu.color} onSelect={pick} />
            </div>
          );
        })}
      </div>

      <button onClick={() => setShowGrocery((s) => !s)} style={{
        width: "100%", padding: "11px", borderRadius: 12, border: `1px solid ${menu.color}`, background: showGrocery ? menu.color : "#fff",
        color: showGrocery ? "#fff" : menu.color, fontWeight: 700, fontSize: 13.5, cursor: "pointer",
      }}>{showGrocery ? L.close : L.grocery}</button>

      {showGrocery && (
        <div style={{ marginTop: 14, background: COLORS.cream, borderRadius: 14, padding: "14px 16px" }}>
          <h4 style={{ margin: "0 0 10px", fontSize: 13.5, fontWeight: 800, color: COLORS.teal }}>{L.groceryTitle}</h4>

          {(() => {
            const visibleItems = showOnlySelected ? groceryItems.filter((item) => checkedItems.has(item)) : groceryItems;
            if (showOnlySelected && visibleItems.length === 0) {
              return <p style={{ fontSize: 12.5, color: COLORS.muted, fontStyle: "italic", margin: "4px 0 10px" }}>{L.noneSelected}</p>;
            }
            return (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))", gap: "4px 10px", marginBottom: 14 }}>
                {visibleItems.map((item, i) => (
                  <label key={i} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 12.5, color: COLORS.text, padding: "3px 0" }}>
                    <input
                      type="checkbox" style={{ accentColor: menu.color }}
                      checked={checkedItems.has(item)}
                      onChange={(e) => setCheckedItems((prev) => {
                        const next = new Set(prev);
                        if (e.target.checked) next.add(item); else next.delete(item);
                        return next;
                      })}
                    />
                    {item}
                  </label>
                ))}
              </div>
            );
          })()}

          {(() => {
            const itemsToShare = checkedItems.size > 0 ? groceryItems.filter((item) => checkedItems.has(item)) : groceryItems;
            const shareText = `${L.groceryTitle} — ${menu.title[lang]}\n\n${itemsToShare.map((i) => `• ${i}`).join("\n")}`;
            const shareNative = async () => {
              if (navigator.share) {
                try {
                  await navigator.share({ title: L.groceryTitle, text: shareText });
                  return;
                } catch (e) {
                  if (e && e.name === "AbortError") return; // annulé volontairement, on ne fait rien de plus
                }
              }
              if (navigator.clipboard?.writeText) {
                try { await navigator.clipboard.writeText(shareText); setShareCopied(true); setTimeout(() => setShareCopied(false), 2500); } catch (e) { /* rien à faire de plus */ }
              }
            };
            return (
              <div style={{ borderTop: `1px solid ${COLORS.line}`, paddingTop: 12 }}>
                <button
                  onClick={() => setShowShareOptions((v) => !v)}
                  style={{ background: menu.color, border: "none", color: "#fff", borderRadius: 999, padding: "8px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}
                >{L.share}</button>
                {showShareOptions && (
                  <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10 }}>
                    <a
                      href={`mailto:?subject=${encodeURIComponent(L.groceryTitle)}&body=${encodeURIComponent(shareText)}`}
                      style={{ textDecoration: "none", background: "#fff", border: `1px solid ${COLORS.line}`, color: COLORS.text, borderRadius: 999, padding: "7px 13px", fontSize: 12, fontWeight: 700 }}
                    >{L.shareEmail}</a>
                    <a
                      href={`sms:?body=${encodeURIComponent(shareText)}`}
                      style={{ textDecoration: "none", background: "#fff", border: `1px solid ${COLORS.line}`, color: COLORS.text, borderRadius: 999, padding: "7px 13px", fontSize: 12, fontWeight: 700 }}
                    >{L.shareSms}</a>
                    <button
                      onClick={shareNative}
                      style={{ background: "#fff", border: `1px solid ${COLORS.line}`, color: COLORS.text, borderRadius: 999, padding: "7px 13px", fontSize: 12, fontWeight: 700, cursor: "pointer" }}
                    >{shareCopied ? L.copied : L.shareOther}</button>
                  </div>
                )}
              </div>
            );
          })()}

          <div style={{ display: "flex", justifyContent: "center", marginTop: 14, paddingTop: 12, borderTop: `1px solid ${COLORS.line}` }}>
            <button
              onClick={() => setShowOnlySelected((v) => !v)}
              style={{ background: "none", border: `1px solid ${menu.color}`, color: menu.color, borderRadius: 999, padding: "4px 12px", fontSize: 11.5, fontWeight: 700, cursor: "pointer" }}
            >{showOnlySelected ? L.showAll : L.showSelected}</button>
          </div>
        </div>
      )}
    </Card>
  );
}

const DIETITIAN_SYSTEM_PROMPT = {
  fr: `Tu es Léa, la diététicienne virtuelle de l'application Me My Baby (grossesse, post-partum, et développement de l'enfant jusqu'à 5 ans). Tu aides les parents à choisir un plan alimentaire général adapté à leurs besoins (grossesse, allaitement ou non, diversification alimentaire du bébé, allergies courantes, objectifs personnels). Ton ton est chaleureux, concret et sans jugement. Donne des orientations générales, des idées de menus et des repères nutritionnels reconnus. Tu n'es pas un substitut à un vrai professionnel de la santé : pour toute question médicale précise (dosage de suppléments, condition médicale diagnostiquée, allergie sévère, perte de poids, trouble alimentaire), invite clairement la personne à consulter un diététicien ou un médecin. Ne donne jamais de diagnostic ni de posologie précise. Reste concise (quelques paragraphes maximum).`,
  en: `You are Léa, the virtual dietitian of the Me My Baby app (pregnancy, postpartum, and child development up to age 5). You help parents choose a general food plan suited to their needs (pregnancy, breastfeeding or not, starting solids, common allergies, personal goals). Your tone is warm, practical, and judgment-free. Give general guidance, menu ideas, and recognized nutrition benchmarks. You are not a substitute for a real healthcare professional: for any precise medical question (supplement dosage, a diagnosed medical condition, severe allergy, weight loss, eating disorder), clearly invite the person to consult a dietitian or doctor. Never give a diagnosis or a precise dosage. Keep answers concise (a few short paragraphs at most).`,
  es: `Eres Léa, la nutricionista virtual de la aplicación Me My Baby (embarazo, posparto y desarrollo infantil hasta los 5 años). Ayudas a los padres a elegir un plan alimentario general adaptado a sus necesidades (embarazo, lactancia o no, alimentación complementaria del bebé, alergias comunes, objetivos personales). Tu tono es cálido, concreto y sin juicios. Da orientaciones generales, ideas de menús y referencias nutricionales reconocidas. No eres un sustituto de un verdadero profesional de la salud: para cualquier pregunta médica precisa (dosis de suplementos, una condición médica diagnosticada, alergia grave, pérdida de peso, trastorno alimentario), invita claramente a la persona a consultar a un nutricionista o médico. Nunca des un diagnóstico ni una dosis precisa. Mantén las respuestas concisas (unos pocos párrafos como máximo).`,
};

// Prompt système dédié à la génération du menu personnalisé (envoyé par courriel) — séparé du
// prompt général de Léa ci-dessus, qui demande volontairement des réponses concises : ici on veut
// l'inverse, un menu complet et détaillé pour 7 jours, rendu en JSON strict pour permettre un
// courriel HTML coloré plutôt qu'un simple bloc de texte brut.
// Note historique : on générait autrefois les 7 jours en un seul appel au modèle, mais avec des
// recettes aussi détaillées (tous les ingrédients quantifiés, épices incluses, étapes numérotées),
// le contenu dépasse facilement la limite de tokens en une seule réponse — le JSON se retrouvait
// tronqué en plein milieu, ne laissait souvent qu'un seul jour utilisable, et l'aperçu texte de
// secours affichait un JSON coupé plutôt qu'un vrai menu. On génère donc maintenant CHAQUE JOUR
// séparément (voir generateAndSendMenu, un appel par jour, tous en parallèle) puis on les assemble
// — chaque appel individuel tient facilement dans sa limite de tokens.
const MENU_JSON_SYSTEM_PROMPT = {
  fr: `Tu es Léa, la diététicienne virtuelle de l'application Me My Baby. Tu génères le menu personnalisé détaillé d'UNE SEULE JOURNÉE à la fois. Réponds TOUJOURS avec UNIQUEMENT un objet JSON valide, sans aucun texte avant ou après, sans balises markdown ni bloc de code, exactement dans cette forme :
{"tips": ["conseil général 1"], "date": "Lundi 21 septembre 2026", "meals": [{"slot": "breakfast", "title": "Nom de la recette", "prep": 10, "cook": 5, "ingredients": ["Ingrédient — quantité précise", "..."], "steps": ["Étape 1 détaillée", "..."]}, {"slot": "lunch", ...}, {"slot": "dinner", ...}]}
"slot" doit toujours être exactement "breakfast", "lunch", "dinner" ou "snack" (en anglais, peu importe la langue du menu) — utilise "snack" pour toute collation ou petit repas additionnel demandé, et respecte EXACTEMENT le nombre et l'ordre de repas indiqués dans la consigne de l'utilisateur (ex. si on te demande "breakfast, snack, lunch, snack, dinner", produis ces 5 repas dans cet ordre, pas seulement 3). "prep" et "cook" sont des nombres de minutes (0 si non applicable). Chaque recette doit inclure TOUS ses ingrédients avec une quantité précise — y compris le sel, le poivre et les épices (ex. "Sel — 1 pincée", "Poivre noir moulu — 1 ml", "Paprika — 5 ml"), jamais juste "au goût" sans repère de quantité. Les étapes doivent être numérotées dans l'ordre, détaillées (température, durée, technique), et inclure explicitement le moment d'assaisonner. "tips" contient au plus 1 conseil général court lié à cette journée (peut être un tableau vide).`,
  en: `You are Léa, the virtual dietitian of the Me My Baby app. You generate the detailed personalized menu for ONE SINGLE DAY at a time. ALWAYS respond with ONLY a valid JSON object, no text before or after, no markdown fences or code blocks, in exactly this shape:
{"tips": ["general tip 1"], "date": "Monday, September 21, 2026", "meals": [{"slot": "breakfast", "title": "Recipe name", "prep": 10, "cook": 5, "ingredients": ["Ingredient — precise amount", "..."], "steps": ["Detailed step 1", "..."]}, {"slot": "lunch", ...}, {"slot": "dinner", ...}]}
"slot" must always be exactly "breakfast", "lunch", "dinner" or "snack" (in English, regardless of the menu's language) — use "snack" for any requested snack or extra small meal, and match EXACTLY the number and order of meals given in the user's instruction (e.g. if asked for "breakfast, snack, lunch, snack, dinner", produce those 5 meals in that order, not just 3). "prep" and "cook" are numbers of minutes (0 if not applicable). Every recipe must list ALL its ingredients with a precise amount — including salt, pepper and spices (e.g. "Salt — 1 pinch", "Black pepper — 1 ml", "Paprika — 5 ml"), never just "to taste" with no quantity cue. Steps must be numbered in order, detailed (temperature, duration, technique), and explicitly include the seasoning moment. "tips" holds at most 1 short general tip tied to this day (can be an empty array).`,
  es: `Eres Léa, la nutricionista virtual de la aplicación Me My Baby. Generas el menú personalizado detallado de UN SOLO DÍA a la vez. Responde SIEMPRE con ÚNICAMENTE un objeto JSON válido, sin texto antes ni después, sin etiquetas markdown ni bloques de código, exactamente en esta forma:
{"tips": ["consejo general 1"], "date": "Lunes 21 de septiembre de 2026", "meals": [{"slot": "breakfast", "title": "Nombre de la receta", "prep": 10, "cook": 5, "ingredients": ["Ingrediente — cantidad precisa", "..."], "steps": ["Paso 1 detallado", "..."]}, {"slot": "lunch", ...}, {"slot": "dinner", ...}]}
"slot" siempre debe ser exactamente "breakfast", "lunch", "dinner" o "snack" (en inglés, sin importar el idioma del menú) — usa "snack" para cualquier merienda o comida pequeña adicional solicitada, y respeta EXACTAMENTE el número y el orden de comidas indicados en la instrucción del usuario (ej. si se te pide "breakfast, snack, lunch, snack, dinner", produce esas 5 comidas en ese orden, no solo 3). "prep" y "cook" son números de minutos (0 si no aplica). Cada receta debe incluir TODOS sus ingredientes con una cantidad precisa — incluyendo sal, pimienta y especias (ej. "Sal — 1 pizca", "Pimienta negra — 1 ml", "Paprika — 5 ml"), nunca solo "al gusto" sin una referencia de cantidad. Los pasos deben estar numerados en orden, detallados (temperatura, duración, técnica), e incluir explícitamente el momento de sazonar. "tips" contiene como máximo 1 consejo general corto relacionado con este día (puede ser un arreglo vacío).`,
};

function DietitianChat({ lang, isMember, goTo, userEmail, userFirstName, lastMenuRequestAt, session, onUpdateProfile }) {
  const [error, setError] = useState(null);
  const [selectedRecipe, setSelectedRecipe] = useState(null);

  // Parcours entièrement dirigé par boutons — Léa pose les questions, la personne clique une réponse.
  // Étapes : 0=accueil, 1=objectifs (choix multiples), 2=allergies (oui/non + texte si oui),
  // 3=nombre de personnes, 4=temps de préparation, 5=niveau d'activité, 6=structure des repas,
  // 7=aliments à éviter par préférence (oui/non + texte si oui), 8=résumé et envoi.
  const [intakeMode, setIntakeMode] = useState(false);
  const [intakeStep, setIntakeStep] = useState(0);
  const [intakeGoals, setIntakeGoals] = useState([]); // choix multiples
  const [hasRestrictions, setHasRestrictions] = useState(null); // null | true | false
  const [intakeRestrictions, setIntakeRestrictions] = useState("");
  const [intakeServings, setIntakeServings] = useState(2);
  const [intakeTimePref, setIntakeTimePref] = useState("");
  const [intakeActivityLevel, setIntakeActivityLevel] = useState("");
  const [intakeMealsStructure, setIntakeMealsStructure] = useState("");
  const [hasDislikes, setHasDislikes] = useState(null); // null | true | false
  const [intakeDislikes, setIntakeDislikes] = useState("");
  const [sendingMenu, setSendingMenu] = useState(false);
  const [menuSentAt, setMenuSentAt] = useState(null);

  const MENU_LOCK_DAYS = 7;
  const lastRequestDate = lastMenuRequestAt ? new Date(lastMenuRequestAt) : null;
  const nextAvailableDate = lastRequestDate ? new Date(lastRequestDate.getTime() + MENU_LOCK_DAYS * 86400000) : null;
  const isLocked = !!(nextAvailableDate && nextAvailableDate > new Date());
  const fmtDate = (d) => d.toLocaleDateString(lang === "fr" ? "fr-CA" : lang === "es" ? "es-MX" : "en-CA", { day: "numeric", month: "long", year: "numeric" });

  // Le menu couvre toujours les 7 prochains jours à partir d'aujourd'hui, peu importe le jour de la semaine.
  const menuStartDate = new Date();
  const menuEndDate = new Date(menuStartDate.getTime() + 6 * 86400000);

  const L = lang === "fr"
    ? {
        title: "Léa, votre diététicienne virtuelle",
        badge: "Fonctionnalité Premium",
        greeting: (name) => `Bonjour${name ? " " + name : ""}, je suis Léa, votre diététicienne. Je vais vous poser quelques questions pour pouvoir composer votre menu.`,
        startBtn: "Débutons", cancelBtn: "Annuler",
        errorMsg: "Une erreur est survenue. Réessayez dans un instant.",
        disclaimer: "Léa donne des conseils généraux et ne remplace pas une consultation avec un professionnel de la santé.",
        personalizedCta: "✨ Obtenir mon menu personnalisé",
        intakeTitle: "Votre menu personnalisé",
        goalQ: "Quel est votre objectif ? (Vous pouvez en choisir plus d'un.)",
        goals: ["Perte de poids", "Ajouter plus de protéines", "Menu végétarien", "Améliorer la production de lait", "Retrouver de l'énergie"],
        restrictionsQ: "Avez-vous des allergies ou restrictions alimentaires ?",
        yes: "Oui", no: "Non",
        restrictionsWhichQ: "Lesquelles ? Nous les exclurons complètement du menu.",
        restrictionsPlaceholder: "Ex. intolérance au lactose, arachides, végétarienne…",
        servingsQ: "Pour combien de personnes voulez-vous ce menu ?",
        timePrefQ: "Préférez-vous des recettes rapides ?",
        timePrefFast: "Rapide (moins de 20 minutes)", timePrefAny: "Peu importe",
        next: "Suivant", back: "Retour", generate: "Générer mon menu",
        noEmail: "Aucun courriel n'est associé à votre profil — impossible d'envoyer le menu. Vérifiez votre profil.",
        sending: "Léa prépare votre menu et vous l'envoie…",
        sentTitle: "C'est envoyé ! 📬",
        sentDesc: (email, mealsCountLabel) => `Un seul courriel a été envoyé à ${email}. Il contient votre menu personnalisé qui couvre les 7 prochains jours : pour chacun de ces 7 jours, vous trouverez ${mealsCountLabel}. Revenez faire une nouvelle demande dans une semaine — Léa se fera un plaisir de vous préparer un nouveau menu !`,
        mealsCountLabels: ["3 repas (déjeuner, dîner et souper)", "3 repas et 2 collations", "5 à 6 petits repas"],
        close: "Fermer",
        activityQ: "Quel est votre niveau d'activité physique ?",
        activityOptions: ["Sédentaire (peu ou pas d'exercice)", "Légèrement actif (1 à 3 fois/semaine)", "Modérément actif (3 à 5 fois/semaine)", "Très actif (6 à 7 fois/semaine)"],
        mealsQ: "Combien de repas préférez-vous par jour ?",
        mealsOptions: ["3 repas seulement", "3 repas + collations", "5 à 6 petits repas"],
        dislikesQ: "Y a-t-il des aliments que vous n'aimez pas, sans être des allergies ?",
        dislikesWhichQ: "Lesquels ? Nous éviterons de les inclure dans votre menu.",
        dislikesPlaceholder: "Ex. champignons, poisson, coriandre…",
        summaryTitle: "Voici ce que j'ai compris",
        summaryDateRange: (start, end) => `Menu de 7 jours, du ${start} au ${end}`,
        summaryGoals: (g) => `Vos objectifs : ${g}`,
        summaryRestrictions: (r) => `À exclure complètement : ${r}`,
        summaryRestrictionsNone: "Aucune allergie ni restriction.",
        summaryServings: (n) => `Menu pour ${n} personne${n > 1 ? "s" : ""}`,
        summaryTimePref: (fast) => fast ? "Recettes rapides (moins de 20 minutes)" : "Peu importe le temps de préparation",
        summaryActivity: (a) => `Niveau d'activité : ${a}`,
        summaryMeals: (m) => `Structure des repas : ${m}`,
        summaryDislikes: (d) => `Aliments à éviter par préférence : ${d}`,
        summaryDislikesNone: "Aucun aliment à éviter par préférence.",
        summarySendBtn: (email) => `Cliquer ici pour l'envoi de votre menu personnalisé par courriel à ${email}`,
        lockedTitle: "Une demande à la fois 🙂",
        lockedMsg: (date) => `Vous avez déjà demandé un menu personnalisé cette semaine. Vous pourrez en redemander un nouveau à partir du ${date}.`,
      }
    : lang === "es"
    ? {
        title: "Léa, tu nutricionista virtual",
        badge: "Función Premium",
        greeting: (name) => `Hola${name ? " " + name : ""}, soy Léa, tu nutricionista. Te haré algunas preguntas para poder armar tu menú.`,
        startBtn: "Empecemos", cancelBtn: "Cancelar",
        errorMsg: "Ocurrió un error. Inténtalo de nuevo en un momento.",
        disclaimer: "Léa ofrece consejos generales y no reemplaza una consulta con un profesional de la salud.",
        personalizedCta: "✨ Obtener mi menú personalizado",
        intakeTitle: "Tu menú personalizado",
        goalQ: "¿Cuál es tu objetivo? (Puedes elegir más de uno.)",
        goals: ["Pérdida de peso", "Agregar más proteínas", "Menú vegetariano", "Mejorar la producción de leche", "Recuperar energía"],
        restrictionsQ: "¿Tienes alergias o restricciones alimentarias?",
        yes: "Sí", no: "No",
        restrictionsWhichQ: "¿Cuáles? Las excluiremos por completo del menú.",
        restrictionsPlaceholder: "Ej. intolerancia a la lactosa, maní, vegetariana…",
        servingsQ: "¿Para cuántas personas quieres este menú?",
        timePrefQ: "¿Prefieres recetas rápidas?",
        timePrefFast: "Rápidas (menos de 20 minutos)", timePrefAny: "No importa",
        next: "Siguiente", back: "Atrás", generate: "Generar mi menú",
        noEmail: "Ningún correo electrónico está asociado a tu perfil — no se puede enviar el menú. Verifica tu perfil.",
        sending: "Léa está preparando tu menú y enviándolo…",
        sentTitle: "¡Enviado! 📬",
        sentDesc: (email, mealsCountLabel) => `Se envió un solo correo a ${email}. Contiene tu menú personalizado que cubre los próximos 7 días: para cada uno de esos 7 días encontrarás ${mealsCountLabel}. Vuelve a hacer una nueva solicitud en una semana — ¡Léa estará encantada de prepararte un nuevo menú!`,
        mealsCountLabels: ["3 comidas (desayuno, almuerzo y cena)", "3 comidas y 2 meriendas", "5 a 6 comidas pequeñas"],
        close: "Cerrar",
        activityQ: "¿Cuál es tu nivel de actividad física?",
        activityOptions: ["Sedentario (poco o nada de ejercicio)", "Ligeramente activo (1 a 3 veces/semana)", "Moderadamente activo (3 a 5 veces/semana)", "Muy activo (6 a 7 veces/semana)"],
        mealsQ: "¿Cuántas comidas prefieres al día?",
        mealsOptions: ["Solo 3 comidas", "3 comidas + meriendas", "5 a 6 comidas pequeñas"],
        dislikesQ: "¿Hay alimentos que no te gustan, sin ser alergias?",
        dislikesWhichQ: "¿Cuáles? Evitaremos incluirlos en tu menú.",
        dislikesPlaceholder: "Ej. champiñones, pescado, cilantro…",
        summaryTitle: "Esto es lo que entendí",
        summaryDateRange: (start, end) => `Menú de 7 días, del ${start} al ${end}`,
        summaryGoals: (g) => `Tus objetivos: ${g}`,
        summaryRestrictions: (r) => `A excluir por completo: ${r}`,
        summaryRestrictionsNone: "Sin alergias ni restricciones.",
        summaryServings: (n) => `Menú para ${n} persona${n > 1 ? "s" : ""}`,
        summaryTimePref: (fast) => fast ? "Recetas rápidas (menos de 20 minutos)" : "El tiempo de preparación no importa",
        summaryActivity: (a) => `Nivel de actividad: ${a}`,
        summaryMeals: (m) => `Estructura de comidas: ${m}`,
        summaryDislikes: (d) => `Alimentos a evitar por preferencia: ${d}`,
        summaryDislikesNone: "Ningún alimento a evitar por preferencia.",
        summarySendBtn: (email) => `Haz clic aquí para el envío de tu menú personalizado por correo a ${email}`,
        lockedTitle: "Una solicitud a la vez 🙂",
        lockedMsg: (date) => `Ya solicitaste un menú personalizado esta semana. Podrás solicitar uno nuevo a partir del ${date}.`,
      }
    : {
        title: "Léa, your virtual dietitian",
        badge: "Premium feature",
        greeting: (name) => `Hi${name ? " " + name : ""}, I'm Léa, your dietitian. I'll ask you a few questions to put together your menu.`,
        startBtn: "Let's start", cancelBtn: "Cancel",
        errorMsg: "Something went wrong. Please try again in a moment.",
        disclaimer: "Léa offers general guidance and doesn't replace a consultation with a healthcare professional.",
        personalizedCta: "✨ Get my personalized menu",
        intakeTitle: "Your personalized menu",
        goalQ: "What's your goal? (You can pick more than one.)",
        goals: ["Weight loss", "Add more protein", "Vegetarian menu", "Improve milk supply", "Getting energy back"],
        restrictionsQ: "Do you have any allergies or dietary restrictions?",
        yes: "Yes", no: "No",
        restrictionsWhichQ: "Which ones? We'll exclude them completely from the menu.",
        restrictionsPlaceholder: "E.g. lactose intolerant, peanuts, vegetarian…",
        servingsQ: "How many people is this menu for?",
        timePrefQ: "Do you prefer quick recipes?",
        timePrefFast: "Quick (under 20 minutes)", timePrefAny: "No preference",
        next: "Next", back: "Back", generate: "Generate my menu",
        noEmail: "No email is linked to your profile — the menu can't be sent. Please check your profile.",
        sending: "Léa is preparing your menu and sending it over…",
        sentTitle: "It's sent! 📬",
        sentDesc: (email, mealsCountLabel) => `A single email was sent to ${email}. It contains your personalized menu covering the next 7 days: for each of those 7 days, you'll find ${mealsCountLabel}. Come back in a week to make a new request — Léa will be happy to put together a fresh menu!`,
        mealsCountLabels: ["3 meals (breakfast, lunch and dinner)", "3 meals and 2 snacks", "5-6 small meals"],
        close: "Close",
        activityQ: "What's your physical activity level?",
        activityOptions: ["Sedentary (little to no exercise)", "Lightly active (1-3 times/week)", "Moderately active (3-5 times/week)", "Very active (6-7 times/week)"],
        mealsQ: "How many meals do you prefer per day?",
        mealsOptions: ["3 meals only", "3 meals + snacks", "5-6 small meals"],
        dislikesQ: "Are there any foods you dislike, without being allergies?",
        dislikesWhichQ: "Which ones? We'll avoid including them in your menu.",
        dislikesPlaceholder: "E.g. mushrooms, fish, cilantro…",
        summaryTitle: "Here's what I understood",
        summaryDateRange: (start, end) => `7-day menu, from ${start} to ${end}`,
        summaryGoals: (g) => `Your goals: ${g}`,
        summaryRestrictions: (r) => `To exclude completely: ${r}`,
        summaryRestrictionsNone: "No allergies or restrictions.",
        summaryServings: (n) => `Menu for ${n} ${n > 1 ? "people" : "person"}`,
        summaryTimePref: (fast) => fast ? "Quick recipes (under 20 minutes)" : "No preference on prep time",
        summaryActivity: (a) => `Activity level: ${a}`,
        summaryMeals: (m) => `Meal structure: ${m}`,
        summaryDislikes: (d) => `Foods to avoid by preference: ${d}`,
        summaryDislikesNone: "No foods to avoid by preference.",
        summarySendBtn: (email) => `Click here to send your personalized menu by email to ${email}`,
        lockedTitle: "One request at a time 🙂",
        lockedMsg: (date) => `You've already requested a personalized menu this week. You'll be able to request a new one starting ${date}.`,
      };

  const toggleGoal = (g) => setIntakeGoals((prev) => prev.includes(g) ? prev.filter((x) => x !== g) : [...prev, g]);

  const resetIntake = () => {
    setIntakeMode(false); setIntakeStep(0); setIntakeGoals([]); setHasRestrictions(null);
    setIntakeRestrictions(""); setIntakeServings(2); setIntakeTimePref("");
    setIntakeActivityLevel(""); setIntakeMealsStructure(""); setHasDislikes(null); setIntakeDislikes("");
    setMenuSentAt(null);
  };

  const generateAndSendMenu = async () => {
    if (!userEmail) { setError(L.noEmail); return; }
    setSendingMenu(true);
    setError(null);
    try {
      const goalsText = intakeGoals.join(", ");
      const restrictionsText = hasRestrictions ? intakeRestrictions : "";
      const dislikesText = hasDislikes ? intakeDislikes : "";
      const fastPref = intakeTimePref === "fast";
      const startLabel = fmtDate(menuStartDate);
      const endLabel = fmtDate(menuEndDate);

      // Un menu de 7 jours avec des recettes complètes (tous les ingrédients quantifiés, épices
      // incluses, étapes détaillées) dépasse facilement ce qu'un seul appel au modèle peut produire
      // sans se faire couper en plein milieu — ce qui donnait un JSON tronqué et, dans les faits,
      // un courriel avec un seul jour utilisable. On génère donc chaque jour séparément, tous les
      // appels en parallèle, puis on assemble les 7 réponses avant de construire le courriel.
      const dayLabels = Array.from({ length: 7 }, (_, i) => fmtDate(new Date(menuStartDate.getTime() + i * 86400000)));

      // La structure de repas choisie à l'étape "Combien de repas préférez-vous par jour ?" doit
      // vraiment changer ce qui est généré — sinon la question ne servirait à rien. On traduit le
      // choix (index dans L.mealsOptions, indépendant de la langue) en une liste exacte de slots
      // ("breakfast"/"snack"/"lunch"/"snack"/"dinner"/...) qu'on donne au modèle mot pour mot, plutôt
      // que de lui laisser interpréter le texte librement.
      const mealsStructureIndex = Math.max(0, L.mealsOptions.indexOf(intakeMealsStructure));
      const MEALS_STRUCTURE_SLOTS = [
        ["breakfast", "lunch", "dinner"],
        ["breakfast", "snack", "lunch", "snack", "dinner"],
        ["breakfast", "snack", "lunch", "snack", "dinner", "snack"],
      ];
      const mealSlots = MEALS_STRUCTURE_SLOTS[mealsStructureIndex] || MEALS_STRUCTURE_SLOTS[0];
      const mealSlotsList = mealSlots.join(", ");

      const dayPrompt = (dayLabel) => lang === "fr"
        ? `Génère le menu personnalisé complet d'UNE SEULE JOURNÉE : ${dayLabel}, pour une utilisatrice avec les objectifs suivants : "${goalsText}". IMPORTANT — produis EXACTEMENT ces ${mealSlots.length} repas, dans cet ordre, avec ces valeurs exactes de "slot" : ${mealSlotsList} (chaque "snack" est une collation légère, distincte des autres repas de la journée). Niveau d'activité physique : "${intakeActivityLevel}". Allergies/restrictions à EXCLURE COMPLÈTEMENT du menu (ne doivent apparaître nulle part, y compris comme ingrédient secondaire) : "${restrictionsText || "aucune"}". Aliments à éviter par préférence (pas des allergies, mais à éviter si possible) : "${dislikesText || "aucun"}". ${fastPref ? "Privilégier des recettes rapides, moins de 20 minutes de préparation." : ""} Le menu doit être calculé pour ${intakeServings} personne${intakeServings > 1 ? "s" : ""}. Utilise "${dayLabel}" comme valeur exacte du champ "date". Varie les recettes par rapport à un menu typique de semaine — évite de répéter toujours les mêmes plats.`
        : lang === "es"
        ? `Genera el menú personalizado completo de UN SOLO DÍA: ${dayLabel}, para una usuaria con los siguientes objetivos: "${goalsText}". IMPORTANTE — produce EXACTAMENTE estas ${mealSlots.length} comidas, en este orden, con estos valores exactos de "slot": ${mealSlotsList} (cada "snack" es una merienda ligera, distinta de las demás comidas del día). Nivel de actividad física: "${intakeActivityLevel}". Alergias/restricciones a EXCLUIR POR COMPLETO del menú (no deben aparecer en ningún lugar, ni siquiera como ingrediente secundario): "${restrictionsText || "ninguna"}". Alimentos a evitar por preferencia (no son alergias, pero evitar si es posible): "${dislikesText || "ninguno"}". ${fastPref ? "Priorizar recetas rápidas, menos de 20 minutos de preparación." : ""} El menú debe calcularse para ${intakeServings} persona${intakeServings > 1 ? "s" : ""}. Usa "${dayLabel}" como valor exacto del campo "date". Varía las recetas respecto a un menú semanal típico — evita repetir siempre los mismos platos.`
        : `Generate the complete personalized menu for ONE SINGLE DAY: ${dayLabel}, for a user with the following goals: "${goalsText}". IMPORTANT — produce EXACTLY these ${mealSlots.length} meals, in this order, with these exact "slot" values: ${mealSlotsList} (each "snack" is a light snack, distinct from the day's other meals). Physical activity level: "${intakeActivityLevel}". Allergies/restrictions to COMPLETELY EXCLUDE from the menu (must not appear anywhere, including as a minor ingredient): "${restrictionsText || "none"}". Foods to avoid by preference (not allergies, but avoid if possible): "${dislikesText || "none"}". ${fastPref ? "Favor quick recipes, under 20 minutes of prep." : ""} The menu should be sized for ${intakeServings} ${intakeServings > 1 ? "people" : "person"}. Use "${dayLabel}" as the exact value of the "date" field. Vary the recipes from a typical week's menu — avoid always repeating the same dishes.`;

      const fetchDay = async (dayLabel) => {
        const response = await fetch("/api/chat", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            model: "claude-sonnet-4-6",
            max_tokens: mealSlots.length > 3 ? 4200 : 3000,
            system: MENU_JSON_SYSTEM_PROMPT[lang],
            messages: [{ role: "user", content: dayPrompt(dayLabel) }],
          }),
        });
        const data = await response.json();
        const rawText = (data.content || []).map((b) => b.text || "").join("\n").trim();
        // Le modèle répond en JSON strict (voir MENU_JSON_SYSTEM_PROMPT) — on retire malgré tout les
        // ```json ... ``` que le modèle ajoute parfois par habitude avant de parser.
        const jsonMatch = rawText.match(/\{[\s\S]*\}/);
        let dayData = null;
        try { dayData = JSON.parse(jsonMatch ? jsonMatch[0] : rawText); } catch (e) { dayData = null; }
        return { dayLabel, dayData, rawText };
      };

      const results = await Promise.all(dayLabels.map(fetchDay));

      // Assemble les 7 réponses en un seul objet menuData ({ tips, days: [...] }), dans l'ordre —
      // un jour qui n'a pas pu être analysé (rare, mais possible si l'appel échoue) est remplacé par
      // un jour minimal indiquant qu'il faudra régénérer, plutôt que de faire échouer tout le courriel.
      const allTips = [];
      const days = results.map(({ dayLabel, dayData }) => {
        if (dayData && Array.isArray(dayData.meals)) {
          if (Array.isArray(dayData.tips)) allTips.push(...dayData.tips);
          return { date: dayData.date || dayLabel, meals: dayData.meals };
        }
        return { date: dayLabel, meals: [] };
      });
      const menuData = { tips: allTips.slice(0, 3), days };
      const rawText = results.map((r) => r.rawText).join("\n\n");

      await sendPersonalizedMenuEmail(userEmail, menuData, rawText, lang);
      const now = new Date();
      setMenuSentAt(now);
      // Enregistre la date de la demande pour appliquer la limite d'une demande par semaine — sans
      // ça, la limite serait oubliée dès qu'on quitte la page ou qu'on se reconnecte.
      onUpdateProfile && onUpdateProfile({ lastMenuRequestAt: now.toISOString() });
      if (session) {
        supabaseUpdateProfile(session.user.id, { last_menu_request_at: now.toISOString() }, session.access_token).catch(() => { /* pas grave si ça échoue, la limite reste appliquée localement pour cette session */ });
      }
    } catch (e) {
      setError(L.errorMsg);
    } finally {
      setSendingMenu(false);
    }
  };

  const btnStyle = (active) => ({
    textAlign: "left", background: active ? COLORS.teal : COLORS.cream,
    color: active ? "#fff" : COLORS.text, border: `1px solid ${COLORS.line}`,
    borderRadius: 12, padding: "11px 14px", fontSize: 14, fontWeight: 600, cursor: "pointer",
  });
  const navRow = (children) => <div style={{ display: "flex", gap: 10 }}>{children}</div>;
  const backBtn = (onClick) => <button onClick={onClick} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 18px", borderRadius: 10, fontWeight: 600, fontSize: 13.5, cursor: "pointer" }}>{L.back}</button>;
  const nextBtn = (onClick, disabled) => <button onClick={onClick} disabled={disabled} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "10px 18px", borderRadius: 10, fontWeight: 700, fontSize: 13.5, cursor: disabled ? "default" : "pointer", opacity: disabled ? 0.5 : 1 }}>{L.next}</button>;

  return (
    <div>
      <Card style={{ position: "relative", overflow: "hidden", background: "#E4EFDF", border: "none", padding: "16px", marginBottom: 18 }}>
        <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 0 }}>
          {LEA_FOOD_PATTERN.map((it, idx) => (
            <span key={idx} style={{ position: "absolute", top: it.top, left: it.left, fontSize: it.size, opacity: 0.18, transform: `rotate(${it.rotate}deg)` }}>
              {it.emoji}
            </span>
          ))}
        </div>
        <div style={{
          position: "relative", zIndex: 1, background: "#fff", borderRadius: 14,
          padding: "18px 20px", display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap",
          boxShadow: "0 4px 16px rgba(91,58,36,0.08)",
        }}>
          <div style={{ background: "#fff", borderRadius: "50%", padding: 3, boxShadow: "0 2px 8px rgba(91,58,36,0.12)", flexShrink: 0 }}>
            <LeaPhoto size={56} />
          </div>
          <div>
            <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 21, color: COLORS.teal }}>{L.title}</h2>
          </div>
        </div>
      </Card>

      {!isMember ? (
        <LockedContent lang={lang} goTo={goTo} />
      ) : intakeMode ? (
        <Card>
          {menuSentAt ? (
            <div style={{ textAlign: "center", padding: "10px 4px" }}>
              <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 10px" }}>{L.sentTitle}</h3>
              <p style={{ color: COLORS.text, fontSize: 14, lineHeight: 1.6, margin: "0 0 20px" }}>{L.sentDesc(userEmail, L.mealsCountLabels[Math.max(0, L.mealsOptions.indexOf(intakeMealsStructure))])}</p>
              <button onClick={resetIntake} style={{
                background: COLORS.teal, color: "#fff", border: "none", borderRadius: 12,
                padding: "11px 22px", fontWeight: 700, fontSize: 14, cursor: "pointer",
              }}>{L.close}</button>
            </div>
          ) : sendingMenu ? (
            <div style={{ textAlign: "center", padding: "24px 4px" }}>
              <p style={{ color: COLORS.muted, fontSize: 14.5, fontStyle: "italic" }}>{L.sending}</p>
            </div>
          ) : (
            <div>
              <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 19, color: COLORS.teal, margin: "0 0 16px" }}>{L.intakeTitle}</h3>

              {intakeStep === 0 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, lineHeight: 1.6, marginBottom: 20 }}>{L.greeting(userFirstName)}</p>
                  {navRow(<>
                    <button onClick={() => setIntakeStep(1)} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "10px 20px", borderRadius: 10, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{L.startBtn}</button>
                    <button onClick={resetIntake} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 20px", borderRadius: 10, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{L.cancelBtn}</button>
                  </>)}
                </div>
              )}

              {intakeStep === 1 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.goalQ}</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
                    {L.goals.map((g) => (
                      <button key={g} onClick={() => toggleGoal(g)} style={btnStyle(intakeGoals.includes(g))}>
                        {intakeGoals.includes(g) ? "✓ " : ""}{g}
                      </button>
                    ))}
                  </div>
                  {navRow(<>{backBtn(resetIntake)}{nextBtn(() => setIntakeStep(2), intakeGoals.length === 0)}</>)}
                </div>
              )}

              {intakeStep === 2 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.restrictionsQ}</p>
                  <div style={{ display: "flex", gap: 10, marginBottom: hasRestrictions ? 14 : 18 }}>
                    <button onClick={() => setHasRestrictions(true)} style={{ ...btnStyle(hasRestrictions === true), flex: 1, textAlign: "center" }}>{L.yes}</button>
                    <button onClick={() => { setHasRestrictions(false); setIntakeRestrictions(""); }} style={{ ...btnStyle(hasRestrictions === false), flex: 1, textAlign: "center" }}>{L.no}</button>
                  </div>
                  {hasRestrictions === true && (
                    <div style={{ marginBottom: 18 }}>
                      <p style={{ fontSize: 13, color: COLORS.muted, marginBottom: 8 }}>{L.restrictionsWhichQ}</p>
                      <input placeholder={L.restrictionsPlaceholder} value={intakeRestrictions} onChange={(e) => setIntakeRestrictions(e.target.value)}
                        style={{ width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, fontFamily: "inherit", boxSizing: "border-box" }} />
                    </div>
                  )}
                  {navRow(<>{backBtn(() => setIntakeStep(1))}{nextBtn(() => setIntakeStep(3), hasRestrictions === null || (hasRestrictions === true && !intakeRestrictions.trim()))}</>)}
                </div>
              )}

              {intakeStep === 3 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.servingsQ}</p>
                  <div style={{ display: "flex", gap: 10, marginBottom: 18 }}>
                    {[1, 2, 4].map((n) => (
                      <button key={n} onClick={() => setIntakeServings(n)} style={{ ...btnStyle(intakeServings === n), flex: 1, textAlign: "center" }}>{n}</button>
                    ))}
                  </div>
                  {navRow(<>{backBtn(() => setIntakeStep(2))}{nextBtn(() => setIntakeStep(4), false)}</>)}
                </div>
              )}

              {intakeStep === 4 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.timePrefQ}</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
                    <button onClick={() => setIntakeTimePref("fast")} style={btnStyle(intakeTimePref === "fast")}>{L.timePrefFast}</button>
                    <button onClick={() => setIntakeTimePref("any")} style={btnStyle(intakeTimePref === "any")}>{L.timePrefAny}</button>
                  </div>
                  {navRow(<>{backBtn(() => setIntakeStep(3))}{nextBtn(() => setIntakeStep(5), !intakeTimePref)}</>)}
                </div>
              )}

              {intakeStep === 5 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.activityQ}</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
                    {L.activityOptions.map((a) => (
                      <button key={a} onClick={() => setIntakeActivityLevel(a)} style={btnStyle(intakeActivityLevel === a)}>{a}</button>
                    ))}
                  </div>
                  {navRow(<>{backBtn(() => setIntakeStep(4))}{nextBtn(() => setIntakeStep(6), !intakeActivityLevel)}</>)}
                </div>
              )}

              {intakeStep === 6 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.mealsQ}</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
                    {L.mealsOptions.map((m) => (
                      <button key={m} onClick={() => setIntakeMealsStructure(m)} style={btnStyle(intakeMealsStructure === m)}>{m}</button>
                    ))}
                  </div>
                  {navRow(<>{backBtn(() => setIntakeStep(5))}{nextBtn(() => setIntakeStep(7), !intakeMealsStructure)}</>)}
                </div>
              )}

              {intakeStep === 7 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 600, marginBottom: 12 }}>{L.dislikesQ}</p>
                  <div style={{ display: "flex", gap: 10, marginBottom: hasDislikes ? 14 : 18 }}>
                    <button onClick={() => setHasDislikes(true)} style={{ ...btnStyle(hasDislikes === true), flex: 1, textAlign: "center" }}>{L.yes}</button>
                    <button onClick={() => { setHasDislikes(false); setIntakeDislikes(""); }} style={{ ...btnStyle(hasDislikes === false), flex: 1, textAlign: "center" }}>{L.no}</button>
                  </div>
                  {hasDislikes === true && (
                    <div style={{ marginBottom: 18 }}>
                      <p style={{ fontSize: 13, color: COLORS.muted, marginBottom: 8 }}>{L.dislikesWhichQ}</p>
                      <input placeholder={L.dislikesPlaceholder} value={intakeDislikes} onChange={(e) => setIntakeDislikes(e.target.value)}
                        style={{ width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, fontFamily: "inherit", boxSizing: "border-box" }} />
                    </div>
                  )}
                  {navRow(<>{backBtn(() => setIntakeStep(6))}{nextBtn(() => setIntakeStep(8), hasDislikes === null || (hasDislikes === true && !intakeDislikes.trim()))}</>)}
                </div>
              )}

              {intakeStep === 8 && (
                <div>
                  <p style={{ fontSize: 14, color: COLORS.text, fontWeight: 700, marginBottom: 12 }}>{L.summaryTitle}</p>
                  <div style={{ background: COLORS.cream, borderRadius: 12, padding: "13px 15px", marginBottom: 18, display: "flex", flexDirection: "column", gap: 8 }}>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5, fontWeight: 700 }}>📅 {L.summaryDateRange(fmtDate(menuStartDate), fmtDate(menuEndDate))}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>🎯 {L.summaryGoals(intakeGoals.join(", "))}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>⚠️ {hasRestrictions && intakeRestrictions.trim() ? L.summaryRestrictions(intakeRestrictions) : L.summaryRestrictionsNone}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>🍽️ {L.summaryServings(intakeServings)}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>⏱️ {L.summaryTimePref(intakeTimePref === "fast")}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>🏃 {L.summaryActivity(intakeActivityLevel)}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>🍴 {L.summaryMeals(intakeMealsStructure)}</p>
                    <p style={{ margin: 0, fontSize: 13.5, color: COLORS.text, lineHeight: 1.5 }}>🙅 {hasDislikes && intakeDislikes.trim() ? L.summaryDislikes(intakeDislikes) : L.summaryDislikesNone}</p>
                  </div>
                  {error && <p style={{ color: "#B5533C", fontSize: 13, marginBottom: 10 }}>{error}</p>}
                  <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                    <button onClick={generateAndSendMenu} style={{ background: COLORS.ochre, color: "#fff", border: "none", padding: "12px 18px", borderRadius: 10, fontWeight: 700, fontSize: 13.5, cursor: "pointer" }}>
                      {L.summarySendBtn(userEmail)}
                    </button>
                    <button onClick={() => setIntakeStep(7)} style={{ background: "transparent", color: COLORS.muted, border: `1px solid ${COLORS.line}`, padding: "10px 18px", borderRadius: 10, fontWeight: 600, fontSize: 13.5, cursor: "pointer", alignSelf: "flex-start" }}>{L.back}</button>
                  </div>
                </div>
              )}
            </div>
          )}
        </Card>
      ) : (
        <Card>
          {isLocked ? (
            <div style={{ background: COLORS.cream, borderRadius: 12, padding: "13px 15px" }}>
              <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 700, color: COLORS.teal }}>{L.lockedTitle}</p>
              <p style={{ margin: 0, fontSize: 13, color: COLORS.text, lineHeight: 1.5 }}>{L.lockedMsg(fmtDate(nextAvailableDate))}</p>
            </div>
          ) : (
            <button onClick={() => setIntakeMode(true)} style={{
              background: COLORS.ochre, border: "none", borderRadius: 999,
              padding: "10px 18px", fontSize: 13.5, color: "#fff", cursor: "pointer", fontWeight: 700,
            }}>{L.personalizedCta}</button>
          )}
        </Card>
      )}
      {isMember && <p style={{ fontSize: 12, color: COLORS.muted, marginTop: 12, textAlign: "center" }}>{L.disclaimer}</p>}

      {isMember && (
        <div style={{ marginTop: 28 }}>
          {selectedRecipe ? (
            <RecipeDetailView
              meal={selectedRecipe.meal}
              lang={lang}
              color={selectedRecipe.color}
              servings={selectedRecipe.servings}
              onBack={() => setSelectedRecipe(null)}
            />
          ) : (
            <>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, marginBottom: 4 }}>
                {lang === "fr" ? "Menus visuels de la semaine" : "This week's visual menus"}
              </h2>
              <p style={{ color: COLORS.muted, fontSize: 13.5, marginBottom: 18 }}>
                {lang === "fr" ? "Du lundi au dimanche, déjeuner, dîner et souper — renouvelés chaque semaine." : "Monday to Sunday, breakfast, lunch and dinner — refreshed every week."}
              </p>
              <WeeklyMenuTable menuKey="weightLoss" lang={lang} onSelectRecipe={setSelectedRecipe} />
              <WeeklyMenuTable menuKey="protein" lang={lang} onSelectRecipe={setSelectedRecipe} />
              <WeeklyMenuTable menuKey="breastfeeding" lang={lang} onSelectRecipe={setSelectedRecipe} />
            </>
          )}
        </div>
      )}
    </div>
  );
}

function ChatBubble({ role, content, muted }) {
  const isUser = role === "user";
  return (
    <div style={{ display: "flex", justifyContent: isUser ? "flex-end" : "flex-start", marginBottom: 14 }}>
      <div style={{
        maxWidth: "78%", padding: "10px 14px", borderRadius: isUser ? "14px 14px 3px 14px" : "14px 14px 14px 3px",
        background: isUser ? COLORS.teal : COLORS.cream,
        color: isUser ? "#fff" : COLORS.text,
        fontSize: 14, lineHeight: 1.55, fontStyle: muted ? "italic" : "normal",
        opacity: muted ? 0.75 : 1, whiteSpace: "pre-wrap",
      }}>
        {content}
      </div>
    </div>
  );
}

/* ---------------- GENERAL AI ASSISTANT (Novaris) ---------------- */
const ASSISTANT_SYSTEM_PROMPT = {
  fr: `Tu es Novaris, l'assistante virtuelle de l'application Me My Baby (conception, grossesse, post-partum, développement de l'enfant jusqu'à 5 ans). Tu réponds à toutes sortes de questions que se posent les parents et futurs parents, avec la même largeur d'information générale qu'on trouverait en cherchant sur le web, mais présentée de façon claire, organisée et fiable. Ton esprit est compatissant, aidant, respectueux et amical — jamais condescendant, jamais alarmiste. Quand c'est pertinent, oriente la personne vers des ressources reconnues et fiables (par exemple une société de pédiatrie, un organisme de santé publique reconnu, ou un site gouvernemental de santé) sans jamais inventer de lien précis, de statistique ou de citation que tu ne peux pas garantir exacte. Tu n'es pas un moteur de recherche en temps réel et tu ne remplaces pas un professionnel de la santé : pour toute question médicale précise, urgente, ou touchant un diagnostic, invite clairement la personne à consulter un professionnel ou les services d'urgence. Reste concise et chaleureuse. IMPORTANT — mise en forme : structure toujours tes réponses en plusieurs courts paragraphes (2 à 4 phrases chacun), séparés par un saut de ligne, plutôt qu'un seul bloc de texte dense. Comme dans une vraie conversation : une idée à la fois, aérée et facile à lire sur un téléphone. Utilise des tirets pour une courte liste si utile, mais évite les longs paragraphes uniques.`,
  en: `You are Novaris, the virtual assistant of the Me My Baby app (conception, pregnancy, postpartum, child development up to age 5). You answer all kinds of questions parents and parents-to-be might have, with the same breadth of general information you'd find searching the web, presented clearly, organized, and reliably. Your spirit is compassionate, helpful, respectful, and friendly — never condescending, never alarmist. When relevant, point the person toward recognized, reliable resources (for example a pediatric society, a recognized public health body, or a government health site) without ever inventing a specific link, statistic, or quote you can't guarantee is accurate. You are not a real-time search engine and you don't replace a healthcare professional: for any precise, urgent, or diagnostic medical question, clearly invite the person to consult a professional or emergency services. Stay concise and warm. IMPORTANT — formatting: always structure your answers into several short paragraphs (2-4 sentences each), separated by a line break, rather than one dense block of text. Like a real conversation: one idea at a time, airy and easy to read on a phone. Use short bullet points if helpful, but avoid long single paragraphs.`,
  es: `Eres Novaris, la asistente virtual de la aplicación Me My Baby (concepción, embarazo, posparto, desarrollo infantil hasta los 5 años). Respondes a todo tipo de preguntas que puedan tener los padres y futuros padres, con la misma amplitud de información general que se encontraría buscando en la web, pero presentada de forma clara, organizada y confiable. Tu espíritu es compasivo, útil, respetuoso y amigable — nunca condescendiente, nunca alarmista. Cuando sea pertinente, orienta a la persona hacia recursos reconocidos y confiables (por ejemplo, una sociedad de pediatría, un organismo de salud pública reconocido o un sitio gubernamental de salud) sin inventar nunca un enlace, estadística o cita específica que no puedas garantizar como exacta. No eres un motor de búsqueda en tiempo real y no reemplazas a un profesional de la salud: para cualquier pregunta médica precisa, urgente o relacionada con un diagnóstico, invita claramente a la persona a consultar a un profesional o a los servicios de urgencia. Mantente concisa y cálida. IMPORTANTE — formato: estructura siempre tus respuestas en varios párrafos cortos (2 a 4 frases cada uno), separados por un salto de línea, en lugar de un solo bloque denso de texto. Como en una conversación real: una idea a la vez, ligera y fácil de leer en un teléfono. Usa viñetas cortas si resulta útil, pero evita los párrafos largos y únicos.`,
};

function AIAssistant({ lang, isMember, goTo }) {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, loading]);

  const L = lang === "fr"
    ? {
        title: "Novaris, votre assistante virtuelle",
        callout: "Vous ne trouvez pas l'information que vous cherchez ? Demandez à notre assistant virtuel, il vous aidera dans votre recherche.",
        intro: "Bonjour, je suis Novaris 👋 Posez-moi à peu près n'importe quelle question liée à la grossesse, l'accouchement, le post-partum ou le développement de votre enfant. Je fais de mon mieux pour vous aider avec des réponses claires et fiables.",
        placeholder: "Écrivez votre question…", send: "Envoyer", thinking: "Novaris réfléchit…",
        errorMsg: "Une erreur est survenue. Réessayez dans un instant.",
        disclaimer: "Novaris donne de l'information générale et peut orienter vers des ressources fiables, mais ne remplace pas une consultation avec un professionnel de la santé.",
        suggestions: ["Comment soulager le mal de dos enceinte ?", "Mon bébé de 2 ans fait des crises, est-ce normal ?", "Quels sont les signes du travail ?", "Comment aider mon enfant à mieux dormir ?"],
      }
    : lang === "es"
    ? {
        title: "Novaris, tu asistente virtual",
        callout: "¿No encuentras la información que buscas? Pregúntale a nuestra asistente virtual, te ayudará en tu búsqueda.",
        intro: "Hola, soy Novaris 👋 Pregúntame casi cualquier cosa relacionada con el embarazo, el parto, el posparto o el desarrollo de tu hijo. Hago todo lo posible para ayudarte con respuestas claras y confiables.",
        placeholder: "Escribe tu pregunta…", send: "Enviar", thinking: "Novaris está pensando…",
        errorMsg: "Ocurrió un error. Inténtalo de nuevo en un momento.",
        disclaimer: "Novaris ofrece información general y puede orientarte hacia recursos confiables, pero no reemplaza una consulta con un profesional de la salud.",
        suggestions: ["¿Cómo alivio el dolor de espalda en el embarazo?", "Mi bebé de 2 años tiene rabietas, ¿es normal?", "¿Cuáles son las señales de trabajo de parto?", "¿Cómo ayudo a mi hijo a dormir mejor?"],
      }
    : {
        title: "Novaris, your virtual assistant",
        callout: "Can't find the information you're looking for? Ask our virtual assistant, and it will help you find it.",
        intro: "Hi, I'm Novaris 👋 Ask me pretty much anything about pregnancy, birth, postpartum, or your child's development. I'll do my best to help with clear, reliable answers.",
        placeholder: "Type your question…", send: "Send", thinking: "Novaris is thinking…",
        errorMsg: "Something went wrong. Please try again in a moment.",
        disclaimer: "Novaris gives general information and can point you to reliable resources, but doesn't replace a consultation with a healthcare professional.",
        suggestions: ["How do I ease back pain during pregnancy?", "My 2-year-old has meltdowns, is that normal?", "What are the signs of labor?", "How can I help my child sleep better?"],
      };

  const send = async (text) => {
    const content = (text ?? input).trim();
    if (!content || loading) return;
    const userMsg = { role: "user", content };
    const history = [...messages, userMsg];
    setMessages(history);
    setInput("");
    setLoading(true);
    setError(null);

    // On ajoute tout de suite une bulle vide pour Novaris, qu'on remplit morceau par morceau au fur et
    // à mesure que le texte arrive — c'est ce qui donne l'effet "en train de répondre" plutôt qu'un
    // seul gros bloc qui apparaît d'un coup à la fin.
    const assistantIndex = history.length;
    setMessages([...history, { role: "assistant", content: "" }]);
    let fullText = "";

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 800,
          system: ASSISTANT_SYSTEM_PROMPT[lang],
          messages: history.map((m) => ({ role: m.role, content: m.content })),
          stream: true,
        }),
      });

      if (!response.ok || !response.body) throw new Error("stream failed");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() ?? ""; // garder la ligne incomplète pour le prochain morceau reçu
        for (const line of lines) {
          if (!line.startsWith("data: ")) continue;
          const jsonStr = line.slice(6).trim();
          if (!jsonStr) continue;
          try {
            const evt = JSON.parse(jsonStr);
            if (evt.type === "content_block_delta" && evt.delta?.text) {
              fullText += evt.delta.text;
              const snapshot = fullText;
              setMessages((prev) => {
                const next = [...prev];
                next[assistantIndex] = { role: "assistant", content: snapshot };
                return next;
              });
            }
          } catch (parseErr) { /* ligne SSE partielle ou non reconnue, on l'ignore */ }
        }
      }

      if (!fullText.trim()) {
        const fallback = lang === "fr" ? "Désolée, je n'ai pas pu répondre. Réessayez." : lang === "es" ? "Lo siento, no pude responder. Inténtalo de nuevo." : "Sorry, I couldn't answer. Please try again.";
        setMessages((prev) => {
          const next = [...prev];
          next[assistantIndex] = { role: "assistant", content: fallback };
          return next;
        });
      }
    } catch (e) {
      setError(L.errorMsg);
      setMessages((prev) => prev.slice(0, assistantIndex)); // retire la bulle vide si ça échoue
    } finally {
      setLoading(false);
    }
  };

  // Novaris est un outil réservé aux membres — on garde l'en-tête visible (pour donner envie),
  // mais la conversation elle-même est verrouillée pour les non-membres, comme pour les autres
  // outils membres (Forum, etc.), avec le même composant LockedContent.
  if (!isMember) {
    return (
      <div>
        <Card style={{ padding: 0, overflow: "hidden" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 20px 10px" }}>
            <div style={{ background: COLORS.cream, borderRadius: 14, padding: 4, flexShrink: 0 }}>
              <Illustration type="assistantBot" size={40} />
            </div>
            <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal }}>{L.title}</h2>
          </div>
          <div style={{ padding: "0 20px 20px" }}>
            <LockedContent lang={lang} goTo={goTo} />
          </div>
        </Card>
        <p style={{ fontSize: 12, color: COLORS.muted, marginTop: 12, textAlign: "center" }}>{L.disclaimer}</p>
      </div>
    );
  }

  return (
    <div>
      <Card style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 20px 10px" }}>
          <div style={{ background: COLORS.cream, borderRadius: 14, padding: 4, flexShrink: 0 }}>
            <Illustration type="assistantBot" size={40} />
          </div>
          <h2 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 18, color: COLORS.teal }}>{L.title}</h2>
        </div>
        <div ref={scrollRef} style={{ maxHeight: 420, minHeight: 260, overflowY: "auto", padding: "6px 20px 4px" }}>
          <ChatBubble role="assistant" content={L.intro} lang={lang} />
          {messages.map((m, i) => {
            const isEmptyStreamingBubble = loading && i === messages.length - 1 && m.role === "assistant" && !m.content;
            if (isEmptyStreamingBubble) return <ChatBubble key={i} role="assistant" content={L.thinking} lang={lang} muted />;
            return <ChatBubble key={i} role={m.role} content={m.content} lang={lang} />;
          })}
        </div>

        {messages.length === 0 && (
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", padding: "0 20px 14px" }}>
            {L.suggestions.map((s, i) => (
              <button key={i} onClick={() => send(s)} style={{
                background: COLORS.cream, border: `1px solid ${COLORS.line}`, borderRadius: 999,
                padding: "7px 13px", fontSize: 12.5, color: COLORS.teal, cursor: "pointer", fontWeight: 600,
              }}>{s}</button>
            ))}
          </div>
        )}

        {error && <p style={{ color: "#B5533C", fontSize: 13, padding: "0 20px 10px" }}>{error}</p>}

        <div style={{ display: "flex", gap: 8, borderTop: `1px solid ${COLORS.line}`, padding: 14 }}>
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") send(); }}
            placeholder={L.placeholder}
            style={{ flex: 1, padding: "11px 14px", borderRadius: 12, border: `1px solid ${COLORS.line}`, fontSize: 14, fontFamily: "inherit" }}
          />
          <button onClick={() => send()} disabled={loading} style={{
            background: COLORS.teal, color: "#fff", border: "none", borderRadius: 12, padding: "0 18px",
            display: "flex", alignItems: "center", justifyContent: "center", cursor: loading ? "default" : "pointer",
            opacity: loading ? 0.6 : 1,
          }}>
            <Send size={17} />
          </button>
        </div>
      </Card>
      <p style={{ fontSize: 12, color: COLORS.muted, marginTop: 12, textAlign: "center" }}>{L.disclaimer}</p>
    </div>
  );
}

const NAV_ITEMS = [
  { id: "accueil", icon: Sun },
  { id: "profil", icon: User },
  { id: "conception", icon: Heart },
  { id: "grossesse", icon: Calendar },
  { id: "postpartum", icon: Baby },
  { id: "dev01", icon: Sparkles },
  { id: "alimentation", icon: Apple },
  { id: "soins", icon: Bath },
  { id: "sante", icon: Stethoscope },
  { id: "famille", icon: Coffee },
  { id: "mission", icon: BookOpen },
  { id: "abonnement", icon: ShieldAlert },
  { id: "contact", icon: MessageCircle },
];

// Chaque item du menu déroulant a sa propre teinte douce quand il est actif — un ton clair
// (pastille légère), jamais un aplat brun foncé qui alourdit visuellement le menu.
const NAV_COLORS = {
  accueil: COLORS.slate, profil: COLORS.sand, conception: COLORS.ochre, grossesse: COLORS.pink,
  postpartum: COLORS.blue, dev01: COLORS.coral, alimentation: COLORS.sage, soins: COLORS.plum,
  sante: COLORS.mint, famille: COLORS.lavender, dietitian: COLORS.berry, mission: COLORS.sky,
  abonnement: COLORS.yellow, contact: COLORS.blue,
};

const UI_FONT = "'Inter','SF Pro Text',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

// Sections dont le menu de navigation peut se déplier pour montrer directement les sous-onglets
// (clic sur le nom = page d'aperçu de la section; clic sur un sous-onglet = cette page précise).
// Chaque entrée dit quelle(s) clé(s) Supabase charger (dev01 en combine deux) et dans quel ordre
// afficher les sous-onglets. Toutes les sections suivent maintenant le même principe que "Ma
// grossesse" (première page validée avec ce fonctionnement).
const NAV_EXPANDABLE = {
  conception: { contentKeys: ["CONCEPTION"], order: CONCEPTION_TAB_ORDER },
  grossesse: { contentKeys: ["PREGNANCY"], order: PREGNANCY_TAB_ORDER },
  postpartum: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.postpartum, order: GENERIC_SECTION_TAB_ORDER.postpartum },
  dev01: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.dev01, order: GENERIC_SECTION_TAB_ORDER.dev01 },
  alimentation: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.alimentation, order: GENERIC_SECTION_TAB_ORDER.alimentation },
  soins: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.soins, order: GENERIC_SECTION_TAB_ORDER.soins },
  sante: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.sante, order: GENERIC_SECTION_TAB_ORDER.sante },
  famille: { contentKeys: GENERIC_SECTION_CONTENT_KEYS.famille, order: GENERIC_SECTION_TAB_ORDER.famille },
};

/* ---------------- SIDEBAR ---------------- */
function NavDropdown({ open, active, goTo, lang, onClose, onLogout }) {
  const nav = T[lang].nav;
  const [expandedNav, setExpandedNav] = useState(null);
  const [subContentCache, setSubContentCache] = useState({}); // { [navId]: data | "loading" | "error" }

  const toggleExpand = (id) => {
    setExpandedNav((prev) => (prev === id ? null : id));
    const conf = NAV_EXPANDABLE[id];
    if (conf && !subContentCache[id]) {
      setSubContentCache((c) => ({ ...c, [id]: "loading" }));
      Promise.all(conf.contentKeys.map((k) => supabaseFetchContent(k)))
        .then((parts) => setSubContentCache((c) => ({ ...c, [id]: Object.assign({}, ...parts) })))
        .catch(() => setSubContentCache((c) => ({ ...c, [id]: "error" })));
    }
  };

  if (!open) return null;
  return (
    <>
      <div onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 35, background: "rgba(91,58,36,0.15)" }} />
      <div style={{
        position: "absolute", top: "calc(100% + 10px)", left: 0, width: 280, maxHeight: "72vh", overflowY: "auto",
        background: COLORS.card, border: `1px solid ${COLORS.line}`, borderRadius: 16,
        boxShadow: "0 14px 34px rgba(91,58,36,0.2)", padding: 8, zIndex: 36,
      }}>
        {NAV_ITEMS.map(({ id, icon: Icon }) => {
          const isActive = active === id;
          const accent = NAV_COLORS[id] || COLORS.teal;
          const conf = NAV_EXPANDABLE[id];
          const isExpanded = expandedNav === id;
          const subData = subContentCache[id];
          return (
            <div key={id}>
              <div style={{ display: "flex", alignItems: "center", gap: 2 }}>
                <button
                  type="button"
                  onClick={() => goTo(id)}
                  style={{
                    display: "flex", alignItems: "center", gap: 11, padding: "11px 14px", borderRadius: 10,
                    flex: 1, minWidth: 0, border: "none", textAlign: "left", cursor: "pointer",
                    background: isActive ? `${accent}1E` : "transparent",
                    color: isActive ? accent : COLORS.teal,
                    fontSize: 15, fontWeight: 700,
                  }}
                >
                  <Icon size={18} strokeWidth={2.2} />
                  <span>{nav[id]}</span>
                </button>
                {conf && (
                  <button
                    type="button"
                    onClick={() => toggleExpand(id)}
                    aria-label={nav[id]}
                    style={{
                      display: "flex", alignItems: "center", justifyContent: "center",
                      width: 32, height: 32, borderRadius: "50%", border: "none",
                      background: `${accent}20`, color: accent, cursor: "pointer", flexShrink: 0,
                    }}
                  >
                    <ChevronDown size={20} strokeWidth={2.6} style={{ transform: isExpanded ? "rotate(180deg)" : "none", transition: "transform 0.2s ease" }} />
                  </button>
                )}
              </div>
              {isExpanded && conf && (
                <div style={{ margin: "2px 0 4px 30px", display: "flex", flexDirection: "column", gap: 1 }}>
                  {subData === "loading" && (
                    <p style={{ fontSize: 12, color: COLORS.muted, padding: "6px 10px", margin: 0 }}>
                      {lang === "fr" ? "Chargement…" : lang === "es" ? "Cargando…" : "Loading…"}
                    </p>
                  )}
                  {subData === "error" && (
                    <p style={{ fontSize: 12, color: COLORS.muted, padding: "6px 10px", margin: 0 }}>
                      {lang === "fr" ? "Impossible de charger." : lang === "es" ? "No se pudo cargar." : "Couldn't load."}
                    </p>
                  )}
                  {subData && subData !== "loading" && subData !== "error" &&
                    conf.order.filter((subId) => subData[subId]).map((subId) => (
                      <button
                        key={subId}
                        type="button"
                        onClick={() => goTo(id, subId)}
                        style={{
                          display: "block", width: "100%", textAlign: "left", border: "none", background: "transparent",
                          borderRadius: 8, padding: "7px 10px", fontSize: 12.5, fontWeight: 500, color: COLORS.teal, opacity: 0.75, cursor: "pointer",
                        }}
                      >
                        {subData[subId].title[lang]}
                      </button>
                    ))}
                </div>
              )}
            </div>
          );
        })}
        {onLogout && (
          <>
            <div style={{ height: 1, background: COLORS.line, margin: "6px 4px" }} />
            <button
              type="button"
              onClick={() => { onClose && onClose(); onLogout(); }}
              style={{
                display: "flex", alignItems: "center", gap: 11, padding: "10px 14px", borderRadius: 10,
                width: "100%", border: "none", textAlign: "left", cursor: "pointer",
                background: "transparent", color: "#B3261E", fontSize: 14, fontWeight: 600,
              }}
            >
              <LogOut size={17} strokeWidth={2} />
              <span>{nav.logout}</span>
            </button>
          </>
        )}
      </div>
    </>
  );
}

/* ---------------- APP ---------------- */
/* ---------------- PROFILE GATE (mandatory on first launch) ---------------- */
function ResetPasswordScreen({ lang, session, onDone }) {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [done, setDone] = useState(false);

  const L = lang === "fr"
    ? {
        title: "Choisissez un nouveau mot de passe", subtitle: "Ce mot de passe remplacera l'ancien pour votre compte.",
        password: "Nouveau mot de passe", confirm: "Confirmez le mot de passe", submit: "Enregistrer le nouveau mot de passe",
        mismatch: "Les deux mots de passe ne correspondent pas.", tooShort: "Le mot de passe doit contenir au moins 6 caractères.",
        doneTitle: "Mot de passe mis à jour !", doneText: "Vous pouvez maintenant continuer vers l'application.", continueBtn: "Continuer",
      }
    : lang === "es"
    ? {
        title: "Elige una nueva contraseña", subtitle: "Esta contraseña reemplazará la anterior de tu cuenta.",
        password: "Nueva contraseña", confirm: "Confirma la contraseña", submit: "Guardar la nueva contraseña",
        mismatch: "Las contraseñas no coinciden.", tooShort: "La contraseña debe tener al menos 6 caracteres.",
        doneTitle: "¡Contraseña actualizada!", doneText: "Ahora puedes continuar hacia la aplicación.", continueBtn: "Continuar",
      }
    : {
        title: "Choose a new password", subtitle: "This password will replace the old one for your account.",
        password: "New password", confirm: "Confirm password", submit: "Save new password",
        mismatch: "The two passwords don't match.", tooShort: "The password must be at least 6 characters long.",
        doneTitle: "Password updated!", doneText: "You can now continue to the app.", continueBtn: "Continue",
      };

  const submit = async () => {
    setErrorMsg("");
    if (password.length < 6) { setErrorMsg(L.tooShort); return; }
    if (password !== confirm) { setErrorMsg(L.mismatch); return; }
    setLoading(true);
    try {
      await supabaseUpdatePassword(password, session.access_token);
      setDone(true);
    } catch (err) {
      setErrorMsg(err.message);
    }
    setLoading(false);
  };

  const inputStyle = { width: "100%", padding: "12px 14px", borderRadius: 12, border: `1px solid ${COLORS.line}`, fontSize: 14.5, boxSizing: "border-box" };
  const labelStyle = { display: "block", fontSize: 13, fontWeight: 700, color: COLORS.text, marginBottom: 16 };

  return (
    <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", padding: "24px 16px", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ maxWidth: 420, width: "100%", background: "#fff", borderRadius: 20, padding: "30px 26px", boxShadow: "0 4px 20px rgba(91,58,36,0.08)" }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}><Logo height={30} /></div>
        {done ? (
          <div style={{ textAlign: "center" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>✅</div>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 8px" }}>{L.doneTitle}</h2>
            <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 22px" }}>{L.doneText}</p>
            <button onClick={onDone} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "12px 26px", borderRadius: 999, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{L.continueBtn}</button>
          </div>
        ) : (
          <>
            <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{L.title}</h2>
            <p style={{ color: COLORS.muted, fontSize: 13, textAlign: "center", margin: "0 0 20px" }}>{L.subtitle}</p>
            <label style={labelStyle}>{L.password}
              <input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} />
            </label>
            <label style={labelStyle}>{L.confirm}
              <input type="password" style={inputStyle} value={confirm} onChange={(e) => setConfirm(e.target.value)} />
            </label>
            {errorMsg && <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>}
            <button
              disabled={loading} onClick={submit}
              style={{
                width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1,
              }}
            >{loading ? "…" : L.submit}</button>
          </>
        )}
      </div>
    </div>
  );
}

function PartnerSharing({ lang, session, userProfile, ownerLink, setOwnerLink, partnerLink, setPartnerLink, isMember, goTo }) {
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [codeInput, setCodeInput] = useState("");
  const [confirmRevoke, setConfirmRevoke] = useState(false);
  // Section compressée par défaut (repliée) — ne prend qu'une seule ligne tant qu'on ne clique pas
  // pour l'ouvrir, plutôt que d'occuper tout cet espace en permanence sur la page profil.
  const [expanded, setExpanded] = useState(false);

  const L = lang === "fr"
    ? {
        title: "Partager mon compte", subtitle: "Invitez votre partenaire à consulter vos données (rendez-vous, tâches, suivis, documents, croissance) en lecture seule. Il ou elle ne pourra rien modifier — sauf dans l'outil « Idées de prénoms », où il ou elle pourra ajouter ses propres suggestions. Il ou elle n'aura jamais accès à votre abonnement ni à vos informations de paiement. Limité à une seule personne à la fois.",
        generate: "Générer une invitation", codeLabel: "Code d'invitation", sendEmail: "📧 Envoyer par courriel",
        emailPh: "Courriel de votre partenaire (optionnel, pour personnaliser le message)",
        cancelInvite: "Annuler l'invitation", pendingNote: "En attente — votre partenaire n'a pas encore entré ce code.",
        sharedWith: "Vous partagez votre compte en lecture seule.", revoke: "Retirer l'accès",
        revokeConfirm: "Retirer l'accès de votre partenaire ? Il ou elle ne pourra plus consulter vos données.",
        confirmBtn: "Oui, retirer", cancelBtn: "Annuler",
        joinTitle: "J'ai reçu un code d'invitation", joinSubtitle: "Entrez le code reçu pour consulter les données de votre partenaire (rendez-vous, tâches, suivis, documents, croissance) en lecture seule.",
        codeInputPh: "Ex. AB3D9F2K", join: "Rejoindre", alreadyPartner: (name) => `Vous consultez actuellement le compte de ${name || "votre partenaire"} en lecture seule.`,
        leaveLink: "Quitter ce partage",
        errInvalid: "Ce code n'est pas valide ou a déjà été utilisé.", errOwn: "Vous ne pouvez pas utiliser votre propre code.",
        emailSubject: "Invitation à consulter mes données sur Me My Baby",
        emailBody: (code, name) => `Bonjour,\n\n${name ? name + " vous invite" : "Vous êtes invité·e"} à consulter en lecture seule ses données de suivi de bébé sur l'application Me My Baby (rendez-vous, tâches familiales, allaitement, sommeil, couches, croissance, documents).\n\nVous ne pourrez rien modifier ni supprimer, à une seule exception : l'outil « Idées de prénoms », où vous pourrez ajouter vos propres suggestions de prénoms. Partout ailleurs, c'est un accès pour consulter seulement. Vous n'aurez jamais accès aux informations de paiement ou d'abonnement.\n\n📱 Accédez à l'application ici : ${APP_URL}\n\nPour vous connecter :\n1. Ouvrez le lien ci-dessus, puis créez votre propre compte gratuit (votre propre courriel et mot de passe).\n2. Une fois connecté·e, allez dans votre profil, section « J'ai reçu un code d'invitation ».\n3. Entrez ce code : ${code}\n\nÀ bientôt !`,
      }
    : lang === "es"
    ? {
        title: "Compartir mi cuenta", subtitle: "Invita a tu pareja a consultar tus datos (citas, tareas, seguimientos, documentos, crecimiento) en modo de solo lectura. No podrá modificar nada — excepto en la herramienta «Ideas de nombres», donde podrá agregar sus propias sugerencias. Nunca tendrá acceso a tu suscripción ni a tu información de pago. Limitado a una sola persona a la vez.",
        generate: "Generar una invitación", codeLabel: "Código de invitación", sendEmail: "📧 Enviar por correo",
        emailPh: "Correo de tu pareja (opcional, para personalizar el mensaje)",
        cancelInvite: "Cancelar la invitación", pendingNote: "Pendiente — tu pareja aún no ha ingresado este código.",
        sharedWith: "Estás compartiendo tu cuenta en modo de solo lectura.", revoke: "Retirar el acceso",
        revokeConfirm: "¿Retirar el acceso de tu pareja? Ya no podrá consultar tus datos.",
        confirmBtn: "Sí, retirar", cancelBtn: "Cancelar",
        joinTitle: "Recibí un código de invitación", joinSubtitle: "Ingresa el código recibido para consultar los datos de tu pareja (citas, tareas, seguimientos, documentos, crecimiento) en modo de solo lectura.",
        codeInputPh: "Ej. AB3D9F2K", join: "Unirme", alreadyPartner: (name) => `Actualmente estás consultando la cuenta de ${name || "tu pareja"} en modo de solo lectura.`,
        leaveLink: "Salir de este acceso compartido",
        errInvalid: "Este código no es válido o ya fue usado.", errOwn: "No puedes usar tu propio código.",
        emailSubject: "Invitación para consultar mis datos en Me My Baby",
        emailBody: (code, name) => `Hola,\n\n${name ? name + " te invita" : "Estás invitado/a"} a consultar en modo de solo lectura sus datos de seguimiento del bebé en la aplicación Me My Baby (citas, tareas familiares, lactancia, sueño, pañales, crecimiento, documentos).\n\nNo podrás modificar ni eliminar nada, con una sola excepción: la herramienta «Ideas de nombres», donde podrás agregar tus propias sugerencias de nombres. En todo lo demás, es un acceso solo para consultar. Nunca tendrás acceso a la información de pago o suscripción.\n\n📱 Accede a la aplicación aquí: ${APP_URL}\n\nPara conectarte:\n1. Abre el enlace de arriba, luego crea tu propia cuenta gratuita (tu propio correo y contraseña).\n2. Una vez conectado/a, ve a tu perfil, sección «Recibí un código de invitación».\n3. Ingresa este código: ${code}\n\n¡Hasta pronto!`,
      }
    : {
        title: "Share my account", subtitle: "Invite your partner to view your data (appointments, tasks, tracking, documents, growth) in read-only mode. They won't be able to change anything — except in the \"Baby name ideas\" tool, where they can add their own suggestions. They will never have access to your subscription or payment information. Limited to one person at a time.",
        generate: "Generate an invite", codeLabel: "Invite code", sendEmail: "📧 Send by email",
        emailPh: "Your partner's email (optional, to personalize the message)",
        cancelInvite: "Cancel the invite", pendingNote: "Pending — your partner hasn't entered this code yet.",
        sharedWith: "You're sharing your account in read-only mode.", revoke: "Remove access",
        revokeConfirm: "Remove your partner's access? They'll no longer be able to view your data.",
        confirmBtn: "Yes, remove", cancelBtn: "Cancel",
        joinTitle: "I received an invite code", joinSubtitle: "Enter the code you received to view your partner's data (appointments, tasks, tracking, documents, growth) in read-only mode.",
        codeInputPh: "E.g. AB3D9F2K", join: "Join", alreadyPartner: (name) => `You're currently viewing ${name || "your partner"}'s account in read-only mode.`,
        leaveLink: "Leave this shared access",
        errInvalid: "This code isn't valid or has already been used.", errOwn: "You can't use your own code.",
        emailSubject: "Invitation to view my data on Me My Baby",
        emailBody: (code, name) => `Hi,\n\n${name ? name + " is inviting you" : "You're invited"} to view, in read-only mode, their baby tracking data on the Me My Baby app (appointments, family tasks, feeding, sleep, diapers, growth, documents).\n\nYou won't be able to change or delete anything, with one exception: the "Baby name ideas" tool, where you can add your own name suggestions. Everywhere else, it's view-only access. You'll never have access to payment or subscription information.\n\n📱 Access the app here: ${APP_URL}\n\nTo connect:\n1. Open the link above, then create your own free account (your own email and password).\n2. Once logged in, go to your profile, "I received an invite code" section.\n3. Enter this code: ${code}\n\nSee you soon!`,
      };

  const hasSession = !!(session?.access_token && session?.user?.id);

  const createInvite = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      const link = await supabaseCreatePartnerInvite(session.user.id, session.access_token);
      setOwnerLink(link);
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };
  const revokeInvite = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      await supabaseRevokePartnerLink(ownerLink.id, session.access_token);
      setOwnerLink(null);
      setConfirmRevoke(false);
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };
  const sendInviteEmail = () => {
    const body = L.emailBody(ownerLink.invite_code, userProfile?.firstName);
    window.open(`mailto:?subject=${encodeURIComponent(L.emailSubject)}&body=${encodeURIComponent(body)}`, "_blank");
  };
  const joinWithCode = async () => {
    if (!codeInput.trim()) return;
    setErrorMsg(""); setLoading(true);
    try {
      const link = await supabaseRedeemInviteCode(codeInput.trim().toUpperCase(), session.user.id, session.access_token);
      setPartnerLink(link);
      setCodeInput("");
      // Un code vient d'être accepté : le profil, les enfants et le statut membre affichés partout
      // ailleurs dans l'appli sont encore ceux de CE compte (chargés avant qu'il y ait un lien
      // partenaire), pas ceux du compte partagé — sans rechargement, l'appli continuait d'afficher
      // le nom, les enfants et les données vides de la personne qui vient d'entrer le code plutôt
      // que celles de son ou sa partenaire, jusqu'à la prochaine connexion. Un rechargement complet
      // refait tourner la même logique qui charge correctement le bon compte au démarrage.
      window.location.reload();
      return;
    } catch (err) {
      setErrorMsg(err.message === "CODE_INVALIDE" ? L.errInvalid : err.message === "CODE_PROPRE_COMPTE" ? L.errOwn : err.message);
    }
    setLoading(false);
  };
  const leaveShare = async () => {
    setErrorMsg(""); setLoading(true);
    try {
      await supabaseRevokePartnerLink(partnerLink.id, session.access_token);
      setPartnerLink(null);
      // Même raison qu'à la jonction : sans rechargement, l'appli continuerait d'afficher le
      // profil et les enfants du compte qu'on vient de quitter au lieu de revenir aux nôtres.
      window.location.reload();
      return;
    } catch (err) { setErrorMsg(err.message); }
    setLoading(false);
  };

  if (!hasSession) return null;

  // Petit résumé d'un coup d'œil, visible même repliée, pour qu'on sache si le partage est actif
  // sans avoir à ouvrir la section.
  const statusLine = partnerLink
    ? `👁️ ${L.alreadyPartner(userProfile?.firstName)}`
    : ownerLink
    ? (ownerLink.status === "accepted" ? `✅ ${L.sharedWith}` : `🔑 ${L.pendingNote}`)
    : null;

  return (
    <Card style={{ padding: 0, overflow: "hidden" }}>
      <div
        onClick={() => setExpanded((v) => !v)}
        role="button" tabIndex={0}
        style={{ display: "flex", alignItems: "center", gap: 12, padding: "18px 20px", cursor: "pointer" }}
      >
        <div style={{ width: 38, height: 38, borderRadius: 12, background: `${COLORS.blue}18`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
          <Users size={18} color={COLORS.blue} />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <h3 style={{ margin: 0, fontFamily: "Fraunces, Georgia, serif", fontSize: 16, color: COLORS.teal }}>{L.title}</h3>
          {!expanded && (
            <p style={{ margin: "2px 0 0", fontSize: 12, color: COLORS.muted, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {statusLine || L.subtitle}
            </p>
          )}
        </div>
        <ChevronRight size={19} color={COLORS.muted} style={{ transform: expanded ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.2s", flexShrink: 0 }} />
      </div>

      {/* Le bloc "code d'invitation reçu" reste toujours visible (pas replié dans l'accordéon) —
          c'est le seul moyen pour un·e partenaire non-membre d'accéder aux données sans payer, donc
          il ne doit jamais être caché derrière un clic supplémentaire. */}
      {!ownerLink && !partnerLink && (
        <div style={{ padding: "0 20px 20px" }} onClick={(e) => e.stopPropagation()}>
          <div style={{ borderTop: `1px solid ${COLORS.line}`, paddingTop: 18 }}>
            <p style={{ margin: "0 0 4px", fontSize: 13.5, fontWeight: 700, color: COLORS.text }}>{L.joinTitle}</p>
            <p style={{ margin: "0 0 12px", fontSize: 12, color: COLORS.muted, lineHeight: 1.5 }}>{L.joinSubtitle}</p>
            <div style={{ display: "flex", gap: 8 }}>
              <input
                value={codeInput} onChange={(e) => setCodeInput(e.target.value)} placeholder={L.codeInputPh}
                style={{ flex: 1, padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14, letterSpacing: 1, textTransform: "uppercase", boxSizing: "border-box" }}
              />
              <button onClick={joinWithCode} disabled={loading} style={{ padding: "10px 18px", borderRadius: 10, border: "none", background: COLORS.ochre, color: "#fff", fontWeight: 700, fontSize: 13, cursor: loading ? "default" : "pointer" }}>{loading ? "…" : L.join}</button>
            </div>
            {errorMsg && <p style={{ fontSize: 11.5, color: "#B3261E", marginTop: 10 }}>{errorMsg}</p>}
          </div>
        </div>
      )}

      {expanded && (
      <div style={{ padding: "0 20px 20px" }} onClick={(e) => e.stopPropagation()}>
      <p style={{ margin: "0 0 16px", fontSize: 12.5, color: COLORS.muted, lineHeight: 1.55 }}>{L.subtitle}</p>

      {partnerLink ? (
        <div style={{ background: "#F0F5EC", borderRadius: 12, padding: "12px 14px", marginBottom: 18 }}>
          <p style={{ margin: "0 0 10px", fontSize: 13, color: COLORS.text, fontWeight: 600 }}>👁️ {L.alreadyPartner(userProfile?.firstName)}</p>
          <button onClick={leaveShare} disabled={loading} style={{ background: "none", border: "none", color: "#B3261E", fontSize: 12.5, fontWeight: 700, cursor: "pointer", padding: 0, textDecoration: "underline" }}>{L.leaveLink}</button>
        </div>
      ) : ownerLink ? (
        <div style={{ background: ownerLink.status === "accepted" ? "#F0F5EC" : COLORS.cream, borderRadius: 12, padding: "14px 16px", marginBottom: 18 }}>
          {ownerLink.status === "accepted" ? (
            <p style={{ margin: "0 0 10px", fontSize: 13, color: COLORS.text, fontWeight: 600 }}>✅ {L.sharedWith}</p>
          ) : (
            <>
              <p style={{ margin: "0 0 4px", fontSize: 11, fontWeight: 700, color: COLORS.muted, textTransform: "uppercase" }}>{L.codeLabel}</p>
              <p style={{ margin: "0 0 10px", fontSize: 22, fontWeight: 800, color: COLORS.teal, letterSpacing: 2 }}>{ownerLink.invite_code}</p>
              <button onClick={sendInviteEmail} style={{ background: COLORS.teal, color: "#fff", border: "none", padding: "9px 16px", borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", marginBottom: 10 }}>{L.sendEmail}</button>
              <p style={{ margin: "0 0 10px", fontSize: 11.5, color: COLORS.muted, fontStyle: "italic" }}>{L.pendingNote}</p>
            </>
          )}
          <div>
            <button onClick={() => setConfirmRevoke(true)} disabled={loading} style={{ background: "none", border: "none", color: "#B3261E", fontSize: 12.5, fontWeight: 700, cursor: "pointer", padding: 0, textDecoration: "underline" }}>
              {ownerLink.status === "accepted" ? L.revoke : L.cancelInvite}
            </button>
          </div>
        </div>
      ) : isMember ? (
        <button onClick={createInvite} disabled={loading} style={{
          width: "100%", padding: "12px", borderRadius: 12, border: "none", background: COLORS.teal, color: "#fff",
          fontWeight: 700, fontSize: 13.5, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1, marginBottom: 22,
        }}>{loading ? "…" : L.generate}</button>
      ) : (
        <div style={{ marginBottom: 22 }}>
          <LockedContent lang={lang} goTo={goTo} />
        </div>
      )}

      {errorMsg && <p style={{ fontSize: 11.5, color: "#B3261E", marginBottom: 14 }}>{errorMsg}</p>}

      {confirmRevoke && (
        <div onClick={() => setConfirmRevoke(false)} style={{
          position: "fixed", inset: 0, zIndex: 300, background: "rgba(91,58,36,0.5)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        }}>
          <div onClick={(ev) => ev.stopPropagation()} style={{ background: "#fff", borderRadius: 20, maxWidth: 380, width: "100%", padding: "26px 24px", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.3)" }}>
            <p style={{ fontSize: 14, color: COLORS.text, lineHeight: 1.55, margin: "0 0 22px" }}>{L.revokeConfirm}</p>
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button onClick={() => setConfirmRevoke(false)} style={{ background: "none", border: `1px solid ${COLORS.line}`, color: COLORS.muted, padding: "10px 20px", borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{L.cancelBtn}</button>
              <button onClick={revokeInvite} style={{ background: "#B3261E", color: "#fff", border: "none", padding: "10px 20px", borderRadius: 999, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{L.confirmBtn}</button>
            </div>
          </div>
        </div>
      )}
      </div>
      )}
    </Card>
  );
}

function ProfileGate({ lang, onComplete }) {
  const [mode, setMode] = useState("signup"); // "signup" | "login"
  const [step, setStep] = useState("welcome"); // "welcome" | "form" | "verify" | "forgot" | "forgotSent"
  const [forgotEmail, setForgotEmail] = useState("");
  const [form, setForm] = useState({ firstName: "", lastName: "", email: "", password: "" });
  const [loginForm, setLoginForm] = useState({ email: "", password: "" });
  const [resendMsg, setResendMsg] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [legalDoc, setLegalDoc] = useState(null); // "privacy" | "terms" | null

  const handleSubmit = async () => {
    if (!(form.firstName.trim() && form.email.trim() && form.password.length >= 8 && acceptedTerms)) return;
    setLoading(true);
    setErrorMsg("");

    try {
      const result = await supabaseSignUp(form.email.trim(), form.password, {
        first_name: form.firstName.trim(),
        last_name: form.lastName.trim(),
      });

      setLoading(false);
      if (result?.access_token) {
        // On enregistre la preuve de consentement (date + heure) ET la langue choisie au moment de
        // l'inscription (le sélecteur de langue en haut de l'écran est déjà disponible ici) — sans ça,
        // le profil retombait toujours sur le français par défaut à la prochaine connexion, peu importe
        // la langue choisie pendant l'inscription.
        try {
          await supabaseUpdateProfile(result.user.id, {
            terms_accepted: true, terms_accepted_at: new Date().toISOString(), language: lang,
          }, result.access_token);
        } catch (e) { /* n'empêche pas la création du compte si cette mise à jour échoue */ }
        // La confirmation par courriel n'est pas activée côté Supabase : on entre directement.
        onComplete(form, result, true);
      } else {
        // Un code à 6 chiffres vient d'être envoyé par courriel.
        setStep("verify");
      }
    } catch (err) {
      setErrorMsg(err.message === "EMAIL_ALREADY_REGISTERED" ? L.emailExists : err.message);
      setLoading(false);
    }
  };

  const handleResend = async () => {
    setErrorMsg("");
    setResendMsg("");
    try {
      await supabaseResendOtp(form.email.trim(), "signup");
      setResendMsg(lang === "fr" ? "Le courriel a été renvoyé." : lang === "es" ? "El correo fue reenviado." : "The email has been resent.");
    } catch (err) {
      setErrorMsg(err.message);
    }
  };

  const handleLogin = async () => {
    if (!(loginForm.email.trim() && loginForm.password)) return;
    setLoading(true);
    setErrorMsg("");
    try {
      const session = await supabaseSignIn(loginForm.email.trim(), loginForm.password);
      setLoading(false);
      onComplete(null, session, false);
    } catch (err) {
      setErrorMsg(err.message);
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!forgotEmail.trim()) return;
    setLoading(true);
    setErrorMsg("");
    try {
      await supabaseRequestPasswordReset(forgotEmail.trim(), window.location.origin + window.location.pathname);
      setStep("forgotSent");
    } catch (err) {
      setErrorMsg(err.message);
    }
    setLoading(false);
  };

  const L = lang === "fr"
    ? {
        title: "Bienvenue dans Me My Baby", subtitle: "Créez votre compte gratuit pour commencer à explorer l'application.",
        welcomeEyebrow: "💛 Pensée avec amour, pour vous et votre bébé",
        welcomeTagline: "Un accompagnement doux et chaleureux à chaque étape de votre grossesse et des premières années de votre enfant — parce que chaque maman mérite de se sentir soutenue, entourée et jamais seule.",
        welcomeCreateBtn: "Créer mon compte", welcomeSignInBtn: "Se connecter",
        welcomeNote: "✨ Essai gratuit de 5 jours inclus — sans engagement.",
        backToWelcome: "← Retour",
        firstName: "Nom", email: "Courriel", password: "Mot de passe", passwordHint: "8 caractères minimum",
        submit: "Créer mon compte gratuit",
        note: "La création d'un compte est requise pour utiliser l'application. Vous pourrez ensuite explorer librement — le contenu détaillé est réservé aux membres.",
        acceptTermsPrefix: "J'accepte les ", termsLabel: "conditions d'utilisation", acceptTermsMiddle: " et la ", privacyLabel: "politique de confidentialité",
        acceptTermsRequired: "Vous devez accepter les conditions d'utilisation et la politique de confidentialité pour créer un compte.",
        emailExists: "Ce courriel existe déjà dans notre base de données. Veuillez vous connecter ou utiliser une autre adresse.",
        medicalReminder: "⚠️ Le contenu de l'application est informatif et ne remplace pas l'avis d'un professionnel de la santé.",
        loginTitle: "Content de vous revoir", loginSubtitle: "Connectez-vous pour retrouver votre profil.",
        loginSubmit: "Se connecter", switchToLogin: "Déjà membre ? Se connecter",
        forgotLink: "Mot de passe oublié ?", forgotTitle: "Mot de passe oublié", forgotSubtitle: "Entrez votre courriel — on vous enverra un lien pour en choisir un nouveau.",
        forgotSubmit: "Envoyer le lien", backToLogin: "← Retour à la connexion",
        forgotSentTitle: "Courriel envoyé !", forgotSentText: "Si un compte existe avec cette adresse, un lien pour réinitialiser votre mot de passe vient d'être envoyé. Vérifiez aussi vos courriels indésirables.",
        switchToSignup: "Pas encore de compte ? Créer un profil",
        verifyTitle: "Vérifiez votre courriel",
        verifySubtitle: (email) => `Nous avons envoyé un courriel de confirmation à ${email}. Cliquez sur le lien qu'il contient pour activer votre compte — vous serez automatiquement dirigé·e vers l'application.`,
        resend: "Renvoyer le courriel", changeEmail: "Modifier mon courriel",
      }
    : lang === "es"
    ? {
        title: "Bienvenida a Me My Baby", subtitle: "Crea tu cuenta gratuita para empezar a explorar la aplicación.",
        welcomeEyebrow: "💛 Pensada con amor, para ti y tu bebé",
        welcomeTagline: "Un acompañamiento cálido y cercano en cada etapa de tu embarazo y los primeros años de tu hijo — porque toda mamá merece sentirse apoyada, acompañada y nunca sola.",
        welcomeCreateBtn: "Crear mi cuenta", welcomeSignInBtn: "Iniciar sesión",
        welcomeNote: "✨ Prueba gratuita de 5 días incluida — sin compromiso.",
        backToWelcome: "← Volver",
        firstName: "Nombre", email: "Correo electrónico", password: "Contraseña", passwordHint: "Mínimo 8 caracteres",
        submit: "Crear mi cuenta gratuita",
        note: "Se requiere crear una cuenta para usar la aplicación. Después podrás explorar libremente — el contenido detallado está reservado para miembros.",
        acceptTermsPrefix: "Acepto los ", termsLabel: "términos de uso", acceptTermsMiddle: " y la ", privacyLabel: "política de privacidad",
        acceptTermsRequired: "Debes aceptar los términos de uso y la política de privacidad para crear una cuenta.",
        emailExists: "Este correo ya existe en nuestra base de datos. Inicia sesión o usa otra dirección.",
        medicalReminder: "⚠️ El contenido de la aplicación es informativo y no sustituye el consejo de un profesional de la salud.",
        designerSkip: "Vista previa de diseñadora — acceso completo, sin crear perfil",
        loginTitle: "Qué bueno verte de nuevo", loginSubtitle: "Inicia sesión para recuperar tu perfil.",
        loginSubmit: "Iniciar sesión", switchToLogin: "¿Ya eres miembro? Inicia sesión",
        forgotLink: "¿Olvidaste tu contraseña?", forgotTitle: "Contraseña olvidada", forgotSubtitle: "Ingresa tu correo — te enviaremos un enlace para elegir una nueva.",
        forgotSubmit: "Enviar el enlace", backToLogin: "← Volver a iniciar sesión",
        forgotSentTitle: "¡Correo enviado!", forgotSentText: "Si existe una cuenta con esta dirección, se acaba de enviar un enlace para restablecer tu contraseña. Revisa también tu carpeta de correo no deseado.",
        switchToSignup: "¿Aún no tienes cuenta? Crea un perfil",
        verifyTitle: "Verifica tu correo electrónico",
        verifySubtitle: (email) => `Enviamos un correo de confirmación a ${email}. Haz clic en el enlace que contiene para activar tu cuenta — serás dirigido automáticamente a la aplicación.`,
        resend: "Reenviar el correo", changeEmail: "Cambiar mi correo",
      }
    : {
        title: "Welcome to Me My Baby", subtitle: "Create your free account to start exploring the app.",
        welcomeEyebrow: "💛 Made with love, for you and your baby",
        welcomeTagline: "A warm, gentle companion for every step of your pregnancy and your child's first years — because every mom deserves to feel supported, understood, and never alone.",
        welcomeCreateBtn: "Create my account", welcomeSignInBtn: "Sign in",
        welcomeNote: "✨ 5-day free trial included — no commitment.",
        backToWelcome: "← Back",
        firstName: "Name", email: "Email", password: "Password", passwordHint: "8 characters minimum",
        submit: "Create my free account",
        note: "Creating an account is required to use the app. After that you can browse freely — detailed content is reserved for members.",
        acceptTermsPrefix: "I agree to the ", termsLabel: "Terms of Use", acceptTermsMiddle: " and ", privacyLabel: "Privacy Policy",
        acceptTermsRequired: "You must agree to the Terms of Use and Privacy Policy to create an account.",
        emailExists: "This email already exists in our database. Please log in or use a different address.",
        medicalReminder: "⚠️ The app's content is informational and does not replace advice from a healthcare professional.",
        designerSkip: "Designer preview — full access, no profile needed",
        loginTitle: "Good to see you again", loginSubtitle: "Log in to pick up right where you left off.",
        loginSubmit: "Log in", switchToLogin: "Already a member? Log in",
        forgotLink: "Forgot password?", forgotTitle: "Forgot password", forgotSubtitle: "Enter your email — we'll send you a link to choose a new one.",
        forgotSubmit: "Send the link", backToLogin: "← Back to login",
        forgotSentTitle: "Email sent!", forgotSentText: "If an account exists with this address, a password reset link was just sent. Check your spam folder too.",
        switchToSignup: "No account yet? Create a profile",
        verifyTitle: "Verify your email",
        verifySubtitle: (email) => `We sent a confirmation email to ${email}. Click the link inside it to activate your account — you'll be taken straight into the app.`,
        resend: "Resend email", changeEmail: "Change my email",
      };

  const inputStyle = { width: "100%", padding: "10px 13px", borderRadius: 10, border: `1px solid ${COLORS.line}`, fontSize: 14.5, boxSizing: "border-box", fontFamily: "inherit" };
  const labelStyle = { display: "flex", flexDirection: "column", gap: 6, fontSize: 13.5, color: COLORS.muted, fontWeight: 600, marginBottom: 14 };

  if (step === "welcome") {
    return (
      <div style={{
        fontFamily: UI_FONT, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        position: "relative", overflow: "hidden",
        background: `radial-gradient(circle at 12% 4%, ${COLORS.pink}3D, transparent 42%), radial-gradient(circle at 92% 14%, ${COLORS.ochre}38, transparent 40%), radial-gradient(circle at 88% 96%, ${COLORS.blue}30, transparent 42%), radial-gradient(circle at 6% 92%, ${COLORS.sage}30, transparent 42%), ${COLORS.cream}`,
      }}>
        <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap'); * { box-sizing: border-box; }
          @keyframes mmbFloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }`}</style>
        {/* soft decorative blobs for extra color "pop" behind the card */}
        <div style={{ position: "absolute", top: "8%", left: "8%", width: 90, height: 90, borderRadius: "50%", background: COLORS.pink, opacity: 0.16, filter: "blur(2px)" }} />
        <div style={{ position: "absolute", bottom: "10%", right: "10%", width: 120, height: 120, borderRadius: "50%", background: COLORS.blue, opacity: 0.14, filter: "blur(2px)" }} />
        <div style={{ position: "absolute", top: "58%", left: "4%", width: 46, height: 46, borderRadius: "50%", background: COLORS.ochre, opacity: 0.22 }} />

        <div style={{ width: "100%", maxWidth: 440, textAlign: "center", position: "relative" }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 8, animation: "mmbFloat 4.5s ease-in-out infinite", position: "relative" }}>
            {/* Le logo contient sa propre forme "éclaboussure" pêche opaque (le dessin de
                Marilyne) — pour qu'elle se fonde dans la page peu importe le dégradé de fond à
                cet endroit précis, on met derrière elle une lueur radiale de LA MÊME teinte
                exacte que cette forme, qui s'estompe ensuite vers le crème de l'appli. Le bord
                du logo touche donc toujours une zone de couleur identique, jamais un contraste. */}
            <div style={{
              position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)",
              width: 300, height: 232, borderRadius: "50%",
              background: "radial-gradient(circle, #F7E4D6 0%, #F7E4D6 38%, transparent 72%)",
              filter: "blur(4px)", zIndex: 0,
            }} />
            <div style={{ position: "relative", zIndex: 1 }}>
              <Logo height={205} />
            </div>
          </div>
          <span style={{
            display: "inline-block", background: "#fff", color: COLORS.ochre, fontSize: 12, fontWeight: 800,
            padding: "6px 14px", borderRadius: 999, marginBottom: 16, boxShadow: "0 3px 10px rgba(212,165,74,0.22)",
          }}>{L.welcomeEyebrow}</span>
          <p style={{
            fontFamily: "Fraunces, Georgia, serif", fontSize: 17, color: COLORS.text, lineHeight: 1.6,
            margin: "0 auto 28px", maxWidth: 370,
          }}>{L.welcomeTagline}</p>
          <Card style={{ padding: "30px 26px", boxShadow: "0 16px 40px rgba(217,139,164,0.22)", border: `1px solid ${COLORS.pink}25` }}>
            <button
              onClick={() => { setMode("signup"); setStep("form"); setErrorMsg(""); }}
              style={{
                width: "100%", background: `linear-gradient(120deg, ${COLORS.pink} 0%, ${COLORS.ochre} 100%)`, color: "#fff", border: "none", padding: "16px",
                borderRadius: 14, fontSize: 16, fontWeight: 800, cursor: "pointer", marginBottom: 12,
                boxShadow: "0 8px 20px rgba(217,139,164,0.35)", letterSpacing: "0.01em",
              }}
            >{L.welcomeCreateBtn} 🤍</button>
            <button
              onClick={() => { setMode("login"); setStep("form"); setErrorMsg(""); }}
              style={{
                width: "100%", background: "#fff", color: COLORS.teal, border: `2px solid ${COLORS.teal}`, padding: "15px",
                borderRadius: 14, fontSize: 15.5, fontWeight: 700, cursor: "pointer",
              }}
            >{L.welcomeSignInBtn}</button>
            <p style={{ fontSize: 12.5, color: COLORS.muted, margin: "16px 0 0", fontWeight: 600 }}>{L.welcomeNote}</p>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div style={{
      fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh",
      display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
    }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap'); * { box-sizing: border-box; }`}</style>
      <div style={{ width: "100%", maxWidth: 440 }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
          <Logo height={100} />
        </div>
        {step === "form" && (
          <button
            onClick={() => { setStep("welcome"); setErrorMsg(""); }}
            style={{ display: "block", background: "none", border: "none", color: COLORS.muted, fontSize: 12.5, fontWeight: 600, cursor: "pointer", margin: "0 0 10px" }}
          >{L.backToWelcome}</button>
        )}
        <Card>
          {step === "forgot" ? (
            <div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{L.forgotTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13, textAlign: "center", margin: "0 0 20px" }}>{L.forgotSubtitle}</p>
              <label style={labelStyle}>{L.email}
                <input required type="email" style={inputStyle} value={forgotEmail} onChange={(e) => setForgotEmail(e.target.value)} />
              </label>
              {errorMsg && <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>}
              <button
                type="button" disabled={loading} onClick={handleForgotPassword}
                style={{
                  width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                  borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer", opacity: loading ? 0.7 : 1, marginBottom: 14,
                }}>{loading ? "…" : L.forgotSubmit}</button>
              <div style={{ textAlign: "center" }}>
                <button onClick={() => { setStep("form"); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 12.5, textDecoration: "underline", cursor: "pointer" }}>{L.backToLogin}</button>
              </div>
            </div>
          ) : step === "forgotSent" ? (
            <div style={{ textAlign: "center" }}>
              <div style={{
                width: 64, height: 64, borderRadius: "50%", background: "#EAF2F8", display: "flex",
                alignItems: "center", justifyContent: "center", margin: "0 auto 16px",
              }}>
                <Mail size={28} color={COLORS.blue} />
              </div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 20, color: COLORS.teal, margin: "0 0 8px" }}>{L.forgotSentTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 20px", lineHeight: 1.5 }}>{L.forgotSentText}</p>
              <button onClick={() => { setStep("form"); setMode("login"); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 12.5, fontWeight: 700, textDecoration: "underline", cursor: "pointer" }}>{L.backToLogin}</button>
            </div>
          ) : step === "verify" ? (
            <div style={{ textAlign: "center" }}>
              <div style={{
                width: 64, height: 64, borderRadius: "50%", background: "#EAF2F8", display: "flex",
                alignItems: "center", justifyContent: "center", margin: "0 auto 16px",
              }}>
                <Mail size={28} color={COLORS.blue} />
              </div>
              <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, margin: "0 0 8px" }}>{L.verifyTitle}</h2>
              <p style={{ color: COLORS.muted, fontSize: 13.5, margin: "0 0 20px", lineHeight: 1.5 }}>{L.verifySubtitle(form.email.trim())}</p>
              {errorMsg && (
                <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
              )}
              {resendMsg && (
                <p style={{ color: COLORS.sage, fontSize: 13, marginBottom: 12, fontWeight: 600 }}>{resendMsg}</p>
              )}
              <div style={{ display: "flex", justifyContent: "center", gap: 18 }}>
                <button onClick={handleResend} style={{ background: "none", border: "none", color: COLORS.teal, fontSize: 12.5, fontWeight: 700, textDecoration: "underline", cursor: "pointer" }}>{L.resend}</button>
                <button onClick={() => { setStep("form"); setErrorMsg(""); setResendMsg(""); }} style={{ background: "none", border: "none", color: COLORS.muted, fontSize: 12.5, textDecoration: "underline", cursor: "pointer" }}>{L.changeEmail}</button>
              </div>
            </div>
          ) : (
          <>
          <h2 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 22, color: COLORS.teal, margin: "0 0 4px", textAlign: "center" }}>{mode === "login" ? L.loginTitle : L.title}</h2>
          <p style={{ color: COLORS.muted, fontSize: 13.5, textAlign: "center", margin: "0 0 20px" }}>{mode === "login" ? L.loginSubtitle : L.subtitle}</p>

          {mode === "login" ? (
            <div>
              <label style={labelStyle}>{L.email}
                <input required type="email" style={inputStyle} value={loginForm.email} onChange={(e) => setLoginForm({ ...loginForm, email: e.target.value })} />
              </label>
              <label style={labelStyle}>{L.password}
                <input required type="password" style={inputStyle} value={loginForm.password} onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })} />
              </label>
              <div style={{ textAlign: "right", marginBottom: 12, marginTop: -8 }}>
                <button type="button" onClick={() => { setStep("forgot"); setForgotEmail(loginForm.email); setErrorMsg(""); }} style={{ background: "none", border: "none", color: COLORS.blue, fontSize: 12, fontWeight: 600, textDecoration: "underline", cursor: "pointer", padding: 0 }}>{L.forgotLink}</button>
              </div>
              {errorMsg && (
                <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
              )}
              <button
                type="button"
                disabled={loading}
                onClick={handleLogin}
                style={{
                  width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                  borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: loading ? "default" : "pointer",
                  opacity: loading ? 0.7 : 1,
                }}>{loading ? "..." : L.loginSubmit}</button>
            </div>
          ) : (
          <div>
            <label style={labelStyle}>{L.firstName}
              <input required style={inputStyle} value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} />
            </label>
            <label style={labelStyle}>{L.email}
              <input required type="email" style={inputStyle} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
            </label>
            <label style={labelStyle}>{L.password}
              <input required type="password" minLength={8} style={inputStyle} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
              <span style={{ fontWeight: 400, fontSize: 11.5, color: COLORS.muted }}>{L.passwordHint}</span>
            </label>
            {errorMsg && (
              <p style={{ color: "#B3261E", fontSize: 13, marginBottom: 12 }}>{errorMsg}</p>
            )}
            <label style={{ display: "flex", alignItems: "flex-start", gap: 9, fontSize: 12.5, color: COLORS.muted, marginBottom: 14, cursor: "pointer", lineHeight: 1.5 }}>
              <input type="checkbox" checked={acceptedTerms} onChange={(e) => setAcceptedTerms(e.target.checked)} style={{ marginTop: 2, flexShrink: 0 }} />
              <span>
                {L.acceptTermsPrefix}
                <button type="button" onClick={(e) => { e.preventDefault(); setLegalDoc("terms"); }} style={{ background: "none", border: "none", padding: 0, color: COLORS.teal, textDecoration: "underline", cursor: "pointer", font: "inherit" }}>{L.termsLabel}</button>
                {L.acceptTermsMiddle}
                <button type="button" onClick={(e) => { e.preventDefault(); setLegalDoc("privacy"); }} style={{ background: "none", border: "none", padding: 0, color: COLORS.teal, textDecoration: "underline", cursor: "pointer", font: "inherit" }}>{L.privacyLabel}</button>
              </span>
            </label>
            <button
              type="button"
              disabled={loading || !acceptedTerms}
              onClick={handleSubmit}
              style={{
                width: "100%", background: COLORS.teal, color: "#fff", border: "none", padding: "13px",
                borderRadius: 12, fontSize: 15, fontWeight: 700, cursor: (loading || !acceptedTerms) ? "default" : "pointer",
                opacity: (loading || !acceptedTerms) ? 0.5 : 1,
              }}>{loading ? "..." : L.submit}</button>
          </div>
          )}
          </>
          )}
        </Card>
        {legalDoc && <LegalModal lang={lang} doc={legalDoc} onClose={() => setLegalDoc(null)} />}
        {step === "form" && mode === "signup" && (
          <>
            <p style={{
              fontSize: 11.5, color: COLORS.teal, textAlign: "center", marginTop: 14, lineHeight: 1.5,
              background: "#EAF2F8", borderRadius: 10, padding: "8px 12px", fontWeight: 600,
            }}>{L.medicalReminder}</p>
            <p style={{ fontSize: 12, color: COLORS.muted, textAlign: "center", marginTop: 10, lineHeight: 1.5 }}>{L.note}</p>
          </>
        )}
        {step === "form" && (
        <>
        <button
          onClick={() => { setMode(mode === "login" ? "signup" : "login"); setErrorMsg(""); }}
          style={{
            display: "block", margin: "16px auto 0", background: "none", border: "none",
            color: COLORS.teal, fontSize: 13, fontWeight: 700, textDecoration: "underline", cursor: "pointer",
          }}
        >
          {mode === "login" ? L.switchToSignup : L.switchToLogin}
        </button>
        </>
        )}
      </div>
    </div>
  );
}

// Alerte automatique par courriel en cas d'erreur JavaScript imprévue dans l'app — plafonnée à un envoi
// par type d'erreur par heure (via sessionStorage) pour éviter d'inonder ta boîte de courriel si la
// même erreur se répète en boucle.
function reportAppError(message, extra) {
  try {
    const key = `err-report-${message}`.slice(0, 100);
    const last = Number(sessionStorage.getItem(key) || 0);
    if (Date.now() - last < 60 * 60 * 1000) return; // déjà signalée dans la dernière heure
    sessionStorage.setItem(key, String(Date.now()));
  } catch { /* sessionStorage indisponible — on tente quand même l'envoi */ }
  const html = `<div style="font-family:Georgia,serif;color:#3A3833;max-width:560px;margin:0 auto;line-height:1.5;font-size:13px;">
    <p><strong>Erreur :</strong> ${String(message).slice(0, 500)}</p>
    <p><strong>Page :</strong> ${window.location?.href || ""}</p>
    <p><strong>Heure :</strong> ${new Date().toISOString()}</p>
    <p><strong>Navigateur :</strong> ${navigator.userAgent}</p>
    ${extra ? `<p><strong>Détail :</strong> ${String(extra).slice(0, 1000)}</p>` : ""}
  </div>`;
  sendAppEmail("Memybaby.app@gmail.com", "⚠️ Erreur détectée sur Me My Baby", html).catch(() => { /* si même le rapport d'erreur échoue, on abandonne silencieusement */ });
}

// Détecte la langue préférée du téléphone/navigateur au tout premier chargement (avant toute
// connexion) — utilisée seulement tant qu'aucune langue n'a été choisie ou sauvegardée dans un
// profil ; une fois connectée, la langue du profil ou un choix manuel prend toujours le dessus.
// Fonctionne aussi bien sur le web que dans une future version empaquetée pour l'App Store/Google
// Play (Capacitor), puisque navigator.language reflète la langue de l'appareil dans les deux cas.
function detectInitialLang() {
  // Repli sur l'anglais (plutôt que le français) quand la langue de l'appareil ne correspond à
  // aucune des 3 langues supportées — l'anglais étant la langue la plus "internationale", c'est
  // le choix le plus sûr pour une personne dont on ne reconnaît pas la langue.
  if (typeof navigator === "undefined") return "en";
  const candidates = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "en"];
  for (const l of candidates) {
    const base = String(l).toLowerCase().slice(0, 2);
    if (base === "es") return "es";
    if (base === "en") return "en";
    if (base === "fr") return "fr";
  }
  return "en";
}

// Bande de raccourcis fixe, toujours visible en bas de l'écran, séparée de la grille "Vos outils" —
// donne un accès direct en un tap à Novaris, au Forum, à Léa (diététicienne) et aux Articles,
// peu importe la page où l'on se trouve, sans jamais se déplacer avec le défilement.
function QuickAccessBar({ lang, active, goTo, isMember }) {
  const L = lang === "fr"
    ? { novaris: "Novaris", forum: "Forum", dietitian: "Léa", articles: "Articles" }
    : lang === "es"
    ? { novaris: "Novaris", forum: "Foro", dietitian: "Léa", articles: "Artículos" }
    : { novaris: "Novaris", forum: "Forum", dietitian: "Léa", articles: "Articles" };

  // Le Forum reste un outil réservé aux membres — retiré de cette bande pour les non-membres,
  // pour ne pas mener vers une page verrouillée depuis l'accueil non-membre.
  const items = [
    { key: "novaris", label: L.novaris, icon: MessageSquare, color: COLORS.blue, customIcon: "assistantBot" },
    ...(isMember ? [{ key: "forum", label: L.forum, icon: MessageCircle, color: COLORS.pink }] : []),
    { key: "dietitian", label: L.dietitian, icon: UtensilsCrossed, color: COLORS.ochre },
    { key: "articles", label: L.articles, icon: ClipboardList, color: COLORS.slate },
  ];

  // Pastille "nouveauté" sur l'icône Articles : affichée quand le déblocage hebdomadaire actuel
  // (voir getUnlockedArticlesCount/getThisWeeksNewArticles plus haut) n'a pas encore été consulté.
  // Recalculé à chaque rendu de la barre (donc à chaque navigation), ce qui est suffisant puisque
  // ArticlesSection appelle markWeeklyArticlesSeen() dès qu'on ouvre la page Articles.
  const showArticlesBadge = hasUnseenWeeklyArticles();

  return (
    <div style={{
      position: "fixed", left: 0, right: 0, bottom: 0, zIndex: 40,
      background: `linear-gradient(180deg, ${COLORS.cream}F2 0%, ${COLORS.cream} 100%)`,
      backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)",
      borderTop: `1px solid ${COLORS.ochre}30`, boxShadow: "0 -6px 20px rgba(91,58,36,0.10)",
      paddingBottom: "env(safe-area-inset-bottom, 0px)",
    }}>
      <div style={{ maxWidth: 560, margin: "0 auto", display: "flex", justifyContent: "space-around", padding: "8px 6px" }}>
        {items.map(({ key, label, icon: Icon, color, customIcon }) => {
          const isActive = active === key;
          return (
            <button
              key={key}
              type="button"
              onClick={() => goTo(key)}
              style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 3,
                background: "none", border: "none", cursor: "pointer", padding: "4px 10px", flex: 1,
                color: isActive ? color : COLORS.text,
              }}
            >
              <div style={{
                position: "relative", width: 34, height: 34, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center",
                background: isActive ? color : `${color}22`, transition: "background 0.15s",
              }}>
                {customIcon ? (
                  <Illustration type={customIcon} size={26} />
                ) : (
                  <Icon size={18} color={isActive ? "#fff" : color} strokeWidth={2.2} />
                )}
                {key === "articles" && showArticlesBadge && (
                  <span style={{
                    position: "absolute", top: -2, right: -2, width: 9, height: 9, borderRadius: "50%",
                    background: COLORS.coral, border: `1.5px solid ${COLORS.cream}`,
                  }} />
                )}
              </div>
              <span style={{ fontSize: 10.5, fontWeight: 700 }}>{label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

export default function App() {
  const [lang, setLang] = useState(detectInitialLang);
  const [active, setActive] = useState("accueil");
  const [navOpen, setNavOpen] = useState(false);
  const [hasProfile, setHasProfile] = useState(false);
  const [userProfile, setUserProfile] = useState(null);
  const [isMember, setIsMember] = useState(false);
  const [ownerLink, setOwnerLink] = useState(null); // invitation créée par CE compte pour inviter un·e partenaire
  const [partnerLink, setPartnerLink] = useState(null); // lien où CE compte est le/la partenaire (lecture seule du compte d'un·e autre)
  // L'accès au contenu réservé aux membres tient compte aussi du statut d'abonnement :
  // - un compte bloqué pour échec de paiement perd l'accès immédiatement, jusqu'à mise à jour du paiement.
  // - un abonnement annulé garde l'accès jusqu'à la fin de la période déjà payée (subscriptionAccessUntil),
  //   puis le perd automatiquement une fois cette date passée — sans qu'aucune action supplémentaire soit requise.
  // - un·e partenaire lié·e (partnerLink actif) a accès en lecture seule sans avoir besoin de son propre abonnement,
  //   puisque c'est le compte titulaire (maman) qui paie.
  const cancelledAndExpired = userProfile?.subscriptionStatus === "cancelled"
    && userProfile?.subscriptionAccessUntil
    && new Date(userProfile.subscriptionAccessUntil + "T23:59:59") < new Date();
  // isAdmin ne débloque PAS l'accès membre (le compte admin doit pouvoir tester le vrai cheminement
  // non-membre → abonnement → membre) — il sert uniquement à révéler, plus tard, des sections/outils
  // réservés à ce compte (gestion des promotions, codes, etc.), séparément du statut membre.
  const isAdmin = isAdminEmail(userProfile?.email);
  const isMemberActive = isMember && userProfile?.subscriptionStatus !== "payment_failed" && !cancelledAndExpired;
  // Quand on consulte le compte d'un·e partenaire : les appels aux données doivent cibler SON id à elle/lui
  // (le compte titulaire), pas le nôtre — et toute action d'ajout/modification/suppression doit rester bloquée.
  const isReadOnlyPartner = !!partnerLink;
  const [children, setChildren] = useState([]);
  const [activeChildId, setActiveChildId] = useState(null);
  const [session, setSession] = useState(null); // { access_token, refresh_token, user, isMember }
  const [justSignedUp, setJustSignedUp] = useState(false);
  const [justBecameMember, setJustBecameMember] = useState(false);
  // Si le webhook Stripe n'a pas encore mis à jour le profil après ~9 secondes d'attente au retour
  // du paiement, on le signale à la personne au lieu de la laisser sans aucune confirmation.
  const [checkoutDelayed, setCheckoutDelayed] = useState(false);
  const [checkingSession, setCheckingSession] = useState(true);
  const [needsPasswordReset, setNeedsPasswordReset] = useState(false);
  const effectiveUserId = partnerLink ? partnerLink.owner_user_id : session?.user?.id;
  // "Session miroir" : même jeton d'authentification (donc toute tentative d'écriture reste bloquée
  // côté base de données, puisque le jeton réel de papa ne correspond pas à l'id de maman), mais avec
  // l'id du compte titulaire pour que toutes les lectures de données pointent vers son compte à elle.
  const effectiveSession = (partnerLink && session) ? { ...session, user: { ...session.user, id: effectiveUserId } } : session;

  // Écoute globale des erreurs JavaScript imprévues (bug non géré, requête qui plante, etc.) pour
  // t'envoyer un courriel automatique — voir reportAppError plus haut.
  useEffect(() => {
    const onError = (event) => reportAppError(event.message || "Erreur inconnue", event.error?.stack);
    const onRejection = (event) => reportAppError("Promesse rejetée non gérée", String(event.reason));
    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onRejection);
    return () => {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onRejection);
    };
  }, []);

  const [pendingSubtab, setPendingSubtab] = useState(null); // sous-onglet précis à ouvrir dès l'arrivée sur une section

  // Pile de navigation : garde l'onglet précédent à chaque déplacement, pour permettre un vrai
  // bouton "Retour" partout dans l'app plutôt que de dépendre du bouton retour du navigateur.
  const [navStack, setNavStack] = useState([]);

  const goTo = (id, subtab) => {
    setNavStack((stack) => (active && active !== id ? [...stack, active] : stack));
    setActive(id);
    setPendingSubtab(subtab || null);
    setNavOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const goBack = () => {
    setNavStack((stack) => {
      if (stack.length === 0) { setActive("accueil"); return stack; }
      const prev = stack[stack.length - 1];
      setActive(prev);
      setPendingSubtab(null);
      return stack.slice(0, -1);
    });
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const mapProfileRow = (row) => ({
    firstName: row.first_name || "", lastName: row.last_name || "", email: row.email || "",
    username: row.username || "", country: row.country || "", language: row.language || "fr",
    motherAge: row.mother_age || "", motherBirthdate: row.mother_birthdate || "", children: row.children ?? "0",
    childrenAgesArr: (row.children_ages || "").split(",").map((s) => s.trim()).filter(Boolean),
    dueDate: row.due_date || "", pregnancyProfile: row.pregnancy_profile || [], newsletter: row.newsletter ?? true,
    photoUrl: row.photo_url || null,
    birthAnnouncementPending: row.birth_announcement_pending || false,
    birthAnnouncementName: row.birth_announcement_name || "",
    billingCycle: row.billing_cycle || "monthly",
    billingAnchorDate: row.billing_anchor_date || "",
    subscriptionStatus: row.subscription_status || "active",
    subscriptionAccessUntil: row.subscription_access_until || "",
    lastMenuRequestAt: row.last_menu_request_at || "",
    preferredCurrency: row.preferred_currency || "",
  });

  // Détecte si la date prévue d'accouchement est maintenant dans le passé : dans ce cas, on considère
  // que bébé est né (l'enfant "à venir" est déjà compté comme un enfant actuel dès que sa date de
  // naissance est passée — voir le filtre utilisé partout ailleurs). On vide alors la DPA (le champ
  // redevient gris, comme non répondu) et on active un message de bienvenue à afficher une seule fois
  // à la prochaine visite de la page d'accueil.
  const checkDueDateTransition = async (sess, profile) => {
    if (!profile?.dueDate) return profile;
    const due = new Date(profile.dueDate + "T00:00:00");
    const todayStart = new Date(new Date().toDateString());
    if (isNaN(due.getTime()) || due >= todayStart) return profile; // pas encore passée
    let childName = "";
    try {
      const rows = await supabaseFetchChildren(sess.user.id, sess.access_token);
      const match = rows.find((r) => r.birthdate === profile.dueDate);
      childName = match?.name || "";
    } catch (e) { /* pas grave si on ne trouve pas le nom, le message restera générique */ }
    try {
      await supabaseUpdateProfile(sess.user.id, {
        due_date: null, birth_announcement_pending: true, birth_announcement_name: childName || null,
      }, sess.access_token);
    } catch (e) { return profile; } // si la mise à jour échoue, on ne change rien localement non plus
    return { ...profile, dueDate: "", birthAnnouncementPending: true, birthAnnouncementName: childName };
  };

  // Recharge le profil depuis Supabase et met à jour l'état userProfile de l'app. Nécessaire après
  // l'enregistrement du profil d'onboarding (composant standalone) car la page "Mon profil" qui
  // s'affiche ensuite est une AUTRE instance du composant, qui repart de userProfile — sans ce
  // rechargement, elle affichait des champs vides même si tout avait bien été sauvegardé côté serveur.
  // Efface le message de félicitations de naissance après son premier affichage, pour qu'il
  // n'apparaisse plus à la prochaine connexion.
  const dismissBirthAnnouncement = async () => {
    setUserProfile((p) => (p ? { ...p, birthAnnouncementPending: false } : p));
    if (!session) return;
    try {
      await supabaseUpdateProfile(session.user.id, { birth_announcement_pending: false }, session.access_token);
    } catch (e) { /* pas grave si ça échoue, ça reste réglé localement pour cette session */ }
  };

  const refreshUserProfile = async () => {
    if (!session) return;
    try {
      const row = await supabaseFetchProfile(session.user.id, session.access_token);
      if (row) {
        let mapped = mapProfileRow(row);
        mapped = await checkDueDateTransition(session, mapped);
        setUserProfile(mapped);
      }
    } catch (e) { /* on garde le profil actuel si le rechargement échoue */ }
  };

  const applySession = async (sess, profileRow) => {
    setSession(sess);
    setHasProfile(true);
    // Le statut membre est déterminé à partir du profil Supabase (présence d'une date d'ancrage de
    // facturation, fixée une seule fois par becomeMember() et jamais effacée ensuite), pas d'un
    // simple indicateur de session — sinon le statut membre se perdait à chaque nouvelle connexion
    // (session locale toute neuve, sans l'indicateur), obligeant la personne à tout ressaisir.
    // Le compte admin n'a PAS d'accès membre forcé — il suit exactement le même cheminement que
    // n'importe quel compte (non-membre → abonnement → membre) pour pouvoir tester ce parcours.
    setIsMember(!!profileRow?.billing_anchor_date);

    let link = null;
    try { link = await supabaseGetPartnerLink(sess.user.id, sess.access_token); } catch { /* pas de lien, on continue normalement */ }
    setPartnerLink(link);
    supabaseGetOwnerLink(sess.user.id, sess.access_token).then(setOwnerLink).catch(() => {});

    const dataOwnerId = link ? link.owner_user_id : sess.user.id;

    if (link) {
      // On consulte le compte d'un·e partenaire en lecture seule : on va chercher SON profil (grossesse,
      // enfants, etc.) plutôt que le nôtre, qui serait vide puisqu'on n'a pas créé nos propres données.
      try {
        const ownerProfileRow = await supabaseFetchProfile(dataOwnerId, sess.access_token);
        if (ownerProfileRow) setUserProfile(mapProfileRow(ownerProfileRow));
      } catch { /* on garde le profil vide plutôt que de bloquer l'app */ }
    } else if (profileRow) {
      const mapped = mapProfileRow(profileRow);
      setUserProfile(mapped);
      if (profileRow.language) setLang(profileRow.language);
      checkDueDateTransition(sess, mapped).then((updated) => {
        if (updated.birthAnnouncementPending) setUserProfile(updated);
      });
    }

    supabaseFetchChildren(dataOwnerId, sess.access_token)
      .then((rows) => setChildren(rows.map(mapChildRow)))
      .catch(() => {}); // en cas d'échec, on garde la liste vide plutôt que de bloquer l'app
  };

  // Analyse l'URL pour voir si on arrive via le lien de confirmation envoyé par courriel
  // (Supabase ajoute access_token/refresh_token/type dans le fragment #... de l'adresse)
  const parseHashSession = () => {
    if (typeof window === "undefined") return null;
    const hash = window.location.hash;
    if (!hash || !hash.includes("access_token")) return null;
    const params = new URLSearchParams(hash.slice(1));
    const access_token = params.get("access_token");
    const refresh_token = params.get("refresh_token");
    const type = params.get("type");
    if (!access_token) return null;
    return { access_token, refresh_token, type };
  };

  // Au chargement de l'app : on regarde d'abord si on arrive via un lien de confirmation de courriel,
  // sinon on tente de restaurer la session déjà ouverte (localStorage)
  useEffect(() => {
    (async () => {
      const fromLink = parseHashSession();
      if (fromLink) {
        try {
          const user = await supabaseGetUser(fromLink.access_token);
          const sessionToStore = { access_token: fromLink.access_token, refresh_token: fromLink.refresh_token, user, isMember: false };
          saveLocalSession(sessionToStore);
          window.history.replaceState(null, "", window.location.pathname + window.location.search); // nettoie l'adresse
          if (fromLink.type === "signup") { setJustSignedUp(true); setActive("profil"); }
          if (fromLink.type === "recovery") { setNeedsPasswordReset(true); }
          const profileRow = await supabaseFetchProfile(user.id, fromLink.access_token).catch(() => null);
          await applySession(sessionToStore, profileRow);
          setCheckingSession(false);
          return;
        } catch (e) {
          window.history.replaceState(null, "", window.location.pathname + window.location.search);
          // on retombe sur la restauration normale ci-dessous si le lien est invalide/expiré
        }
      }

      const stored = loadLocalSession();
      if (!stored?.access_token) { setCheckingSession(false); return; }
      // Reste connectée avec les jetons déjà en mémoire, sans vider quoi que ce soit — utilisé quand
      // un problème réseau (pas un rejet du serveur) empêche de vérifier la session au retour sur
      // l'appli. On réessaiera silencieusement une fois le réseau revenu (voir plus bas).
      const keepSessionOptimistically = () => {
        setSession(stored);
        setIsMember(!!stored.isMember);
        setHasProfile(true);
      };
      try {
        const user = await supabaseGetUser(stored.access_token);
        const profileRow = await supabaseFetchProfile(user.id, stored.access_token).catch(() => null);
        await applySession(stored, profileRow);
      } catch (e) {
        if (isNetworkError(e)) {
          // Pas de vrai rejet du serveur ici — juste pas de réseau au moment de la vérification (ex.
          // le téléphone vient de se réveiller après avoir changé d'appli). On ne déconnecte JAMAIS
          // pour ça : la personne garde son accès et ses outils, et on retentera dès que le réseau
          // sera revenu plutôt que de la renvoyer à l'écran de connexion pour rien.
          keepSessionOptimistically();
        } else if (stored.refresh_token) {
          // Le jeton d'accès a probablement expiré : on tente un rafraîchissement silencieux
          try {
            const refreshed = await supabaseRefreshSession(stored.refresh_token);
            const merged = { access_token: refreshed.access_token, refresh_token: refreshed.refresh_token, user: refreshed.user, isMember: stored.isMember };
            saveLocalSession(merged);
            const profileRow = await supabaseFetchProfile(refreshed.user.id, refreshed.access_token).catch(() => null);
            await applySession(merged, profileRow);
          } catch (e2) {
            if (isNetworkError(e2)) keepSessionOptimistically();
            else clearLocalSession(); // ici, le serveur a bien répondu et a refusé le jeton — la session est vraiment invalide
          }
        } else {
          clearLocalSession();
        }
      }
      setCheckingSession(false);
    })();

    // Si le réseau n'était pas disponible au chargement, on retente une seule fois dès qu'il revient —
    // pour aller chercher le vrai profil à jour plutôt que de rester indéfiniment sur les données
    // optimistes locales.
    const onOnline = () => {
      const stored = loadLocalSession();
      if (!stored?.access_token) return;
      (async () => {
        try {
          const user = await supabaseGetUser(stored.access_token);
          const profileRow = await supabaseFetchProfile(user.id, stored.access_token).catch(() => null);
          await applySession(stored, profileRow);
        } catch (e) { /* on retentera à la prochaine reconnexion réseau ou au prochain chargement */ }
      })();
    };
    window.addEventListener("online", onOnline);
    return () => window.removeEventListener("online", onOnline);
  }, []);

  // Au retour depuis Stripe Checkout (après paiement ou annulation) : l'adresse contient
  // ?checkout=success ou ?checkout=cancelled. Le webhook Stripe a déjà mis à jour le profil Supabase
  // à ce moment-là (ou est sur le point de le faire) — on relit donc le profil quelques fois avec un
  // court délai, le temps que billing_anchor_date apparaisse, plutôt que de se fier à un état local.
  // Même chose au retour du Customer Portal (?portal=return) : la personne peut y avoir annulé,
  // réactivé ou changé de carte — sans ce rafraîchissement, l'app continuerait d'afficher son
  // ancien statut en mémoire et le bandeau d'annulation n'apparaîtrait jamais.
  const checkoutReturnHandled = useRef(false);
  useEffect(() => {
    if (checkingSession || checkoutReturnHandled.current) return;
    if (typeof window === "undefined") return;
    const params = new URLSearchParams(window.location.search);
    const checkoutResult = params.get("checkout");
    const portalResult = params.get("portal");
    if (!checkoutResult && !portalResult) return;
    checkoutReturnHandled.current = true;
    window.history.replaceState(null, "", window.location.pathname);

    if (!session?.access_token) return;

    if (portalResult) {
      // Simple relecture du profil — pas besoin d'attendre billing_anchor_date puisqu'il existait
      // déjà avant d'aller sur le portail ; on veut juste le statut/la date d'accès à jour.
      (async () => {
        for (let attempt = 0; attempt < 4; attempt++) {
          try {
            const profileRow = await supabaseFetchProfile(session.user.id, session.access_token);
            if (profileRow) { await applySession(session, profileRow); return; }
          } catch (e) { /* on retente, le webhook peut prendre un instant */ }
          await new Promise((r) => setTimeout(r, 1200));
        }
      })();
      return;
    }

    if (checkoutResult !== "success") return;

    (async () => {
      for (let attempt = 0; attempt < 6; attempt++) {
        try {
          const profileRow = await supabaseFetchProfile(session.user.id, session.access_token);
          if (profileRow?.billing_anchor_date) {
            await applySession(session, profileRow);
            setJustBecameMember(true);
            setActive("abonnement");
            return;
          }
        } catch (e) { /* on retente, le webhook peut prendre un instant */ }
        await new Promise((r) => setTimeout(r, 1500));
      }
      // Après ~9 secondes, le webhook n'a toujours pas confirmé le paiement. On ne sait pas si
      // c'est juste lent ou si quelque chose a échoué : plutôt que de laisser la personne sans
      // nouvelle après avoir payé, on l'avertit et on lui propose de vérifier à nouveau.
      setCheckoutDelayed(true);
    })();
  }, [checkingSession, session]);

  // Relance manuelle depuis le message "activation en cours" : relit le profil une fois: si le
  // webhook a fini par passer, on ferme le message et on affiche la confirmation normale; sinon on
  // laisse le message affiché pour que la personne puisse réessayer ou nous écrire.
  const retryCheckoutStatus = async () => {
    if (!session?.access_token) return;
    try {
      const profileRow = await supabaseFetchProfile(session.user.id, session.access_token);
      if (profileRow?.billing_anchor_date) {
        await applySession(session, profileRow);
        setCheckoutDelayed(false);
        setJustBecameMember(true);
        setActive("abonnement");
      }
    } catch (e) { /* on laisse la personne réessayer */ }
  };

  // Appelé après une inscription ou une connexion réussie. Passe par applySession — la même logique
  // que la restauration de session au chargement de l'app — pour que la connexion via le formulaire
  // de connexion recharge elle aussi correctement le statut membre, le partage partenaire et le
  // profil complet, plutôt qu'une version incomplète qui laissait tout ça vide/à zéro.
  const handleAuthComplete = async (profileForm, authSession, isFreshSignup) => {
    if (authSession?.access_token) {
      const sessionToStore = { access_token: authSession.access_token, refresh_token: authSession.refresh_token, user: authSession.user };
      saveLocalSession(sessionToStore);
      if (isFreshSignup) { setJustSignedUp(true); setActive("profil"); }
      let profileRow = null;
      try {
        profileRow = await supabaseFetchProfile(authSession.user.id, authSession.access_token);
      } catch (e) { /* on retombe sur le formulaire saisi localement si la lecture échoue */ }
      await applySession(sessionToStore, profileRow);
      if (profileRow) return;
    }
    if (profileForm) setUserProfile(profileForm);
  };

  const becomeMember = (billingCycle, preferredCurrency) => {
    setIsMember(true);
    setJustBecameMember(true);
    setSession((prev) => {
      if (!prev) return prev;
      const updated = { ...prev, isMember: true };
      saveLocalSession(updated);
      return updated;
    });
    // La date d'ancrage (premier paiement, à la fin de l'essai gratuit) est fixée une seule fois ici —
    // toutes les dates de renouvellement futures se calculent ensuite à partir de cette date précise,
    // plutôt que de recalculer "aujourd'hui + 30 jours" à chaque visite (ce qui donnerait une date qui
    // change tout le temps au lieu de rester fixe).
    const anchorDate = new Date();
    anchorDate.setDate(anchorDate.getDate() + TRIAL_DAYS);
    const anchorDateStr = anchorDate.toISOString().slice(0, 10);
    setUserProfile((p) => (p ? {
      ...p,
      ...(billingCycle ? { billingCycle } : {}),
      ...(preferredCurrency ? { preferredCurrency } : {}),
      billingAnchorDate: anchorDateStr,
    } : p));
    if (session) {
      const updates = { billing_anchor_date: anchorDateStr };
      if (billingCycle) updates.billing_cycle = billingCycle;
      if (preferredCurrency) updates.preferred_currency = preferredCurrency;
      supabaseUpdateProfile(session.user.id, updates, session.access_token).catch(() => { /* pas grave si ça échoue, l'état local reste correct pour cette session */ });
    }
  };

  const logout = async () => {
    if (session?.access_token) await supabaseSignOut(session.access_token);
    clearLocalSession();
    setSession(null);
    setHasProfile(false);
    setIsMember(false);
    setUserProfile(null);
    setChildren([]);
    setActive("accueil");
  };

  if (checkingSession) {
    return (
      <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Logo height={34} />
      </div>
    );
  }

  if (needsPasswordReset) {
    return <ResetPasswordScreen lang={lang} session={session} onDone={() => setNeedsPasswordReset(false)} />;
  }

  if (!hasProfile) {
    return <ProfileGate lang={lang} onComplete={handleAuthComplete} />;
  }

  if (justSignedUp) {
    return (
      <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", padding: "24px 16px" }}>
        <div style={{ maxWidth: 560, margin: "0 auto" }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
            <Logo height={34} />
          </div>
          <ProfileSection
            lang={lang} setLang={setLang} children={children} setChildren={setChildren} userProfile={userProfile}
            session={session} justSignedUp={true} onOnboardingDone={async () => { await refreshUserProfile(); setJustSignedUp(false); setActive("profil"); }}
            standalone
          />
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (active) {
      case "accueil": return <Home lang={lang} goTo={goTo} isMember={isMemberActive} userProfile={userProfile} children={children} session={effectiveSession} onDismissBirthAnnouncement={dismissBirthAnnouncement} isReadOnlyPartner={isReadOnlyPartner} />;
      case "conception": return <ConceptionSection lang={lang} isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} session={session} />;
      case "grossesse": return <PregnancySection lang={lang} isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} userProfile={userProfile} session={effectiveSession} />;
      case "postpartum": return <GenericSection lang={lang} sectionKey="postpartum" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} />;
      case "dev01": return <GenericSection lang={lang} sectionKey="dev01" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} children={children} session={session} />;
      case "alimentation": return <GenericSection lang={lang} sectionKey="alimentation" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} />;
      case "soins": return <GenericSection lang={lang} sectionKey="soins" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} />;
      case "sante": return <GenericSection lang={lang} sectionKey="sante" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} />;
      case "famille": return <GenericSection lang={lang} sectionKey="famille" isMember={isMemberActive} goTo={goTo} initialSub={pendingSubtab} />;
      case "mission": return <MissionSection lang={lang} />;
      case "abonnement": return <AbonnementUnified lang={lang} isMember={isMember} goTo={goTo} onBecomeMember={becomeMember} userProfile={userProfile} session={session} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} isReadOnlyPartner={isReadOnlyPartner} partnerLink={partnerLink} setPartnerLink={setPartnerLink} />;
      case "profil": return <ProfileSection lang={lang} setLang={setLang} children={children} setChildren={setChildren} userProfile={userProfile} onLogout={logout} session={session} justSignedUp={justSignedUp} onOnboardingDone={async () => { await refreshUserProfile(); setJustSignedUp(false); }} isMember={isMember} onBecomeMember={isMember ? () => setIsMember(false) : becomeMember} goTo={goTo} ownerLink={ownerLink} setOwnerLink={setOwnerLink} partnerLink={partnerLink} setPartnerLink={setPartnerLink} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} />;
      case "dietitian": return <DietitianChat lang={lang} isMember={isMemberActive} goTo={goTo} userEmail={userProfile?.email} userFirstName={userProfile?.firstName} lastMenuRequestAt={userProfile?.lastMenuRequestAt} session={session} onUpdateProfile={(updates) => setUserProfile((p) => (p ? { ...p, ...updates } : p))} />;
      case "contact": return <ContactSection lang={lang} />;
      // Novaris, le Forum et les Articles sont accessibles depuis la bande de raccourcis fixe
      // (QuickAccessBar) — ce sont des pages normales comme les autres, pas une superposition.
      case "novaris": return <AIAssistant lang={lang} isMember={isMemberActive} goTo={goTo} />;
      case "forum": return <ForumSection lang={lang} isMember={isMemberActive} goTo={goTo} userProfile={userProfile} />;
      case "articles": return <ArticlesSection lang={lang} />;
      default: return null;
    }
  };

  return (
    <div style={{ fontFamily: UI_FONT, background: COLORS.cream, minHeight: "100vh", color: COLORS.text, paddingBottom: 76 }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; -webkit-font-smoothing: antialiased; }
        body { margin: 0; }
        ::-webkit-scrollbar { height: 6px; width: 6px; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.line}; border-radius: 10px; }
        button { font-family: inherit; }
        button:focus-visible, input:focus-visible { outline: 2px solid ${COLORS.ochre}; outline-offset: 2px; }

        .page-shell { max-width: 880px; margin: 0 auto; padding: 28px 24px 64px; }

        @media (max-width: 900px) {
          .page-shell { padding: 16px 16px 48px; }
        }
        @media (max-width: 560px) {
          .hero-illu { display: none; }
        }
      `}</style>

      {/* Header */}
      <header style={{
        background: "rgba(247,244,238,0.82)", backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)",
        borderBottom: `1px solid ${COLORS.line}`, position: "sticky", top: 0, zIndex: 30,
      }}>
        <div style={{ maxWidth: 1180, margin: "0 auto", padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setNavOpen((v) => !v)}
              style={{
                background: COLORS.line, border: "none", cursor: "pointer",
                padding: "8px 14px", borderRadius: 14, display: "flex", alignItems: "center", gap: 8,
              }}
              aria-label="Me My Baby menu"
            >
              <Logo height={30} />
            </button>
            <NavDropdown open={navOpen} active={active} goTo={goTo} lang={lang} onClose={() => setNavOpen(false)} onLogout={session ? logout : null} />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <GlobalSearch lang={lang} goTo={goTo} compact />
            {/* Indicateur de langue — purement informatif, se change dans Mon profil */}
            <div style={{
              display: "flex", alignItems: "center", gap: 6, background: COLORS.card,
              border: `1px solid ${COLORS.line}`, borderRadius: 999, padding: "7px 14px",
              fontSize: 13, fontWeight: 600, color: COLORS.muted,
            }}>
              <Globe size={15} />
              {lang === "fr" ? "FR" : lang === "en" ? "EN" : "ES"}
            </div>
          </div>
        </div>
      </header>

      {session && userProfile?.subscriptionStatus === "payment_failed" && (
        <div style={{
          background: "#B3261E", color: "#fff", padding: "12px 20px", display: "flex",
          alignItems: "center", justifyContent: "center", gap: 12, flexWrap: "wrap", textAlign: "center",
        }}>
          <span style={{ fontSize: 13.5, fontWeight: 600 }}>
            {lang === "fr"
              ? "⚠️ Votre compte est bloqué — votre dernier paiement n'a pas fonctionné. Mettez à jour votre mode de paiement pour retrouver l'accès."
              : lang === "es"
              ? "⚠️ Tu cuenta está bloqueada — tu último pago no funcionó. Actualiza tu método de pago para recuperar el acceso."
              : "⚠️ Your account is blocked — your last payment didn't go through. Update your payment method to regain access."}
          </span>
          <button onClick={() => goTo("abonnement")} style={{
            background: "#fff", color: "#B3261E", border: "none", padding: "6px 16px",
            borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", flexShrink: 0,
          }}>
            {lang === "fr" ? "Mettre à jour le paiement" : lang === "es" ? "Actualizar el pago" : "Update payment"}
          </button>
        </div>
      )}

      {session && userProfile?.subscriptionStatus === "cancelled" && (
        <div style={{
          background: "#B3261E", color: "#fff", padding: "12px 20px", display: "flex",
          alignItems: "center", justifyContent: "center", gap: 12, flexWrap: "wrap", textAlign: "center",
        }}>
          <span style={{ fontSize: 13.5, fontWeight: 600 }}>
            {cancelledAndExpired
              ? (lang === "fr"
                  ? "⚠️ Votre compte est annulé — vous n'avez plus accès aux fonctionnalités. Remettez votre abonnement en vigueur pour y accéder à nouveau."
                  : lang === "es"
                  ? "⚠️ Tu cuenta está cancelada — ya no tienes acceso a las funciones. Reactiva tu suscripción para volver a acceder."
                  : "⚠️ Your account is cancelled — you no longer have access to the features. Reactivate your subscription to regain access.")
              : (lang === "fr"
                  ? `⚠️ Demande d'annulation en cours — votre compte sera annulé le ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("fr-CA", { day: "numeric", month: "long", year: "numeric" })}. Vous perdrez alors l'accès à toutes les fonctionnalités. Remettez votre abonnement en vigueur pour l'annuler.`
                  : lang === "es"
                  ? `⚠️ Solicitud de cancelación en curso — tu cuenta se cancelará el ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("es-MX", { day: "numeric", month: "long", year: "numeric" })}. Perderás entonces el acceso a todas las funciones. Reactiva tu suscripción para cancelar esto.`
                  : `⚠️ Cancellation request in progress — your account will be cancelled on ${new Date(userProfile.subscriptionAccessUntil + "T00:00:00").toLocaleDateString("en-CA", { day: "numeric", month: "long", year: "numeric" })}. You will then lose access to all features. Reactivate your subscription to undo this.`)}
          </span>
          <button onClick={() => goTo("abonnement")} style={{
            background: "#fff", color: "#B3261E", border: "none", padding: "6px 16px",
            borderRadius: 999, fontWeight: 700, fontSize: 12.5, cursor: "pointer", flexShrink: 0,
          }}>
            {lang === "fr" ? "Remettre en vigueur" : lang === "es" ? "Reactivar" : "Reactivate"}
          </button>
        </div>
      )}

      <div className="page-shell">
        {active !== "accueil" && active !== "abonnement" && (
          <button
            onClick={goBack}
            aria-label={lang === "fr" ? "Retour" : lang === "es" ? "Volver" : "Back"}
            style={{
              display: "inline-flex", alignItems: "center", gap: 6, background: "none", border: "none",
              cursor: "pointer", padding: "6px 0", marginBottom: 14, color: COLORS.teal,
              fontFamily: UI_FONT, fontSize: 14, fontWeight: 700,
            }}
          >
            <ArrowLeft size={18} />
            {lang === "fr" ? "Retour" : lang === "es" ? "Volver" : "Back"}
          </button>
        )}
        {renderContent()}
      </div>

      <footer style={{ borderTop: `1px solid ${COLORS.line}`, padding: "24px 20px", textAlign: "center" }}>
        <div style={{ marginBottom: 8, display: "flex", justifyContent: "center" }}>
          <Logo height={26} />
        </div>
        <p style={{ fontSize: 12.5, color: COLORS.muted, margin: 0 }}>
          {lang === "fr"
            ? "Me My Baby — de la conception à 5 ans. Le contenu de cette application est informatif et ne remplace pas l'avis d'un professionnel de la santé."
            : lang === "es"
            ? "Me My Baby — de la concepción a los 5 años. El contenido de esta aplicación es informativo y no sustituye el consejo de un profesional de la salud."
            : "Me My Baby — from conception to age 5. Content in this app is informational and does not replace advice from a healthcare professional."}
        </p>
      </footer>

      <QuickAccessBar lang={lang} active={active} goTo={goTo} isMember={isMemberActive} />

      {justBecameMember && (
        <div onClick={() => { setJustBecameMember(false); setActive("accueil"); }} style={{
          position: "fixed", inset: 0, zIndex: 300, background: "rgba(91,58,36,0.5)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        }}>
          <div onClick={(e) => e.stopPropagation()} style={{
            background: "#fff", borderRadius: 20, maxWidth: 400, width: "100%",
            padding: "30px 26px", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
          }}>
            <div style={{ fontSize: 42, marginBottom: 10 }}>🎉</div>
            <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 21, color: COLORS.teal, margin: "0 0 10px" }}>
              {lang === "fr" ? "Bienvenue dans la communauté !" : lang === "es" ? "¡Bienvenida a la comunidad!" : "Welcome to the community!"}
            </h3>
            <p style={{ fontSize: 13.5, color: COLORS.text, lineHeight: 1.6, margin: "0 0 6px" }}>
              {lang === "fr" ? "Vous êtes maintenant membre de Me My Baby." : lang === "es" ? "Ahora eres miembro de Me My Baby." : "You're now a Me My Baby member."}
            </p>
            <p style={{ fontSize: 12.5, color: COLORS.muted, lineHeight: 1.6, margin: "0 0 24px" }}>
              {lang === "fr" ? "Vous avez maintenant accès à toutes les fonctionnalités." : lang === "es" ? "Ahora tienes acceso a todas las funcionalidades." : "You now have access to all features."}
            </p>
            <button onClick={() => { setJustBecameMember(false); setActive("accueil"); }} style={{
              background: COLORS.teal, color: "#fff", border: "none", padding: "12px 26px", borderRadius: 999,
              fontWeight: 700, fontSize: 14, cursor: "pointer",
            }}>
              {lang === "fr" ? "Commencer à naviguer" : lang === "es" ? "Empezar a explorar" : "Start browsing"}
            </button>
          </div>
        </div>
      )}

      {checkoutDelayed && (
        <div style={{
          position: "fixed", inset: 0, zIndex: 300, background: "rgba(91,58,36,0.5)",
          display: "flex", alignItems: "center", justifyContent: "center", padding: 20,
        }}>
          <div style={{
            background: "#fff", borderRadius: 20, maxWidth: 400, width: "100%",
            padding: "30px 26px", textAlign: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.3)",
          }}>
            <div style={{ fontSize: 42, marginBottom: 10 }}>⏳</div>
            <h3 style={{ fontFamily: "Fraunces, Georgia, serif", fontSize: 21, color: COLORS.teal, margin: "0 0 10px" }}>
              {lang === "fr" ? "Paiement reçu — activation en cours" : lang === "es" ? "Pago recibido — activación en curso" : "Payment received — activating"}
            </h3>
            <p style={{ fontSize: 13.5, color: COLORS.text, lineHeight: 1.6, margin: "0 0 6px" }}>
              {lang === "fr"
                ? "Votre paiement a été envoyé à Stripe, mais l'activation de votre compte prend un peu plus de temps que prévu."
                : lang === "es"
                ? "Tu pago fue enviado a Stripe, pero la activación de tu cuenta está tardando un poco más de lo previsto."
                : "Your payment was sent to Stripe, but activating your account is taking a little longer than expected."}
            </p>
            <p style={{ fontSize: 12.5, color: COLORS.muted, lineHeight: 1.6, margin: "0 0 24px" }}>
              {lang === "fr"
                ? "Réessayez dans un instant. Si l'accès n'apparaît toujours pas après quelques minutes, écrivez-nous — votre paiement est en sécurité chez Stripe."
                : lang === "es"
                ? "Vuelve a intentarlo en un momento. Si el acceso sigue sin aparecer después de unos minutos, escríbenos — tu pago está seguro con Stripe."
                : "Try again in a moment. If access still hasn't appeared after a few minutes, contact us — your payment is safe with Stripe."}
            </p>
            <button onClick={retryCheckoutStatus} style={{
              background: COLORS.teal, color: "#fff", border: "none", padding: "12px 26px", borderRadius: 999,
              fontWeight: 700, fontSize: 14, cursor: "pointer", marginRight: 10,
            }}>
              {lang === "fr" ? "Vérifier à nouveau" : lang === "es" ? "Volver a comprobar" : "Check again"}
            </button>
            <button onClick={() => setCheckoutDelayed(false)} style={{
              background: "transparent", color: COLORS.muted, border: "none", padding: "12px 10px",
              fontWeight: 600, fontSize: 13, cursor: "pointer",
            }}>
              {lang === "fr" ? "Fermer" : lang === "es" ? "Cerrar" : "Close"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
